window.MT_DATA['hi'] = [{"id":1,"name":"Niveau 1","freeLessonsPerModule":{"1":10,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours en Inde, en route et à la maison.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Delhi","phrases":[{"fr":"Je suis à Delhi.","tgt":"मैं दिल्ली में हूँ।","ro":"Maiṃ Dillī meṃ hūṃ.","lit":"je · Delhi · [dans] · suis"},{"fr":"Je viens de Paris.","tgt":"मैं पेरिस से हूँ।","ro":"Maiṃ Peris se hūṃ.","lit":"je · Paris · [depuis] · suis"},{"fr":"Je bois du chai.","tgt":"मैं चाय पीता हूँ।","ro":"Maiṃ chāy pītā hūṃ.","lit":"je · chai · buvant · suis"},{"fr":"Je parle français.","tgt":"मैं फ़्रांसीसी बोलता हूँ।","ro":"Maiṃ frānsīsī boltā hūṃ.","lit":"je · français · parlant · suis"},{"fr":"Je parle un peu hindi.","tgt":"मैं थोड़ी हिंदी बोलता हूँ।","ro":"Maiṃ thoṛī hindī boltā hūṃ.","lit":"je · un peu · hindi · parlant · suis"},{"fr":"Delhi est très grande.","tgt":"दिल्ली बहुत बड़ी है।","ro":"Dillī bahut baṛī hai.","lit":"Delhi · très · grande · est"},{"fr":"L'hôtel est à Connaught Place.","tgt":"होटल कनॉट प्लेस में है।","ro":"Hoṭal Kanoṭ Ples meṃ hai.","lit":"hôtel · Connaught Place · [dans] · est"},{"fr":"J'aime beaucoup Delhi.","tgt":"मुझे दिल्ली बहुत पसंद है।","ro":"Mujhe Dillī bahut pasand hai.","lit":"à moi · Delhi · très · plaisante · est"},{"fr":"Mon ami habite à Delhi.","tgt":"मेरा दोस्त दिल्ली में रहता है।","ro":"Merā dost Dillī meṃ rahtā hai.","lit":"mon · ami · Delhi · [dans] · habitant · est"},{"fr":"Je travaille ici.","tgt":"मैं यहाँ काम करता हूँ।","ro":"Maiṃ yahāṃ kām kartā hūṃ.","lit":"je · ici · travail · faisant · suis"}],"tip":{"title":"L'ordre des mots : le verbe à la fin","example":"Je bois du chai. — मैं चाय <b>पीता</b> <b>हूँ</b>।","body":"En hindi, le verbe se place tout à la fin de la phrase, comme une signature. Là où le français dit « je bois du chai », le hindi dit « Maiṃ chāy pītā hūṃ », c'est-à-dire mot à mot « je, chai, buvant, suis ». On pose d'abord qui agit, puis ce dont on parle, et seulement à la fin l'action. C'est la même chose dans « Maiṃ hindī boltā hūṃ », je parle hindi, et dans « Maiṃ yahāṃ kām kartā hūṃ », je travaille ici. Les indications de lieu viennent elles aussi avant le verbe : « Maiṃ Dillī meṃ hūṃ », je suis à Delhi. Pour retenir, pensez à une rame de métro : le sujet est la locomotive, le verbe est toujours le dernier wagon. Quand vous parlez, gardez votre verbe en réserve et prononcez-le en dernier, sans hésiter.","exampleRo":"Maiṃ chāy pītā hūṃ.","lit":"je · chai · buvant · suis","say":{"Maiṃ chāy pītā hūṃ":"मैं चाय पीता हूँ","Maiṃ hindī boltā hūṃ":"मैं हिंदी बोलता हूँ","Maiṃ yahāṃ kām kartā hūṃ":"मैं यहाँ काम करता हूँ","Maiṃ Dillī meṃ hūṃ":"मैं दिल्ली में हूँ"}}},{"title":"Mon appartement à Delhi","phrases":[{"fr":"Voici mon appartement à Delhi.","tgt":"यह दिल्ली में मेरा फ़्लैट है।","ro":"Yah Dillī meṃ merā flaiṭ hai.","lit":"ceci · Delhi · [dans] · mon · appartement · est"},{"fr":"L'appartement est petit.","tgt":"फ़्लैट छोटा है।","ro":"Flaiṭ chhoṭā hai.","lit":"appartement · petit · est"},{"fr":"La cuisine est propre.","tgt":"रसोई साफ़ है।","ro":"Rasoī sāf hai.","lit":"cuisine · propre · est"},{"fr":"La chambre est grande.","tgt":"कमरा बड़ा है।","ro":"Kamrā baṛā hai.","lit":"chambre · grande · est"},{"fr":"Aujourd'hui, il fait chaud dans l'appartement.","tgt":"आज फ़्लैट में गर्मी है।","ro":"Āj flaiṭ meṃ garmī hai.","lit":"aujourd'hui · appartement · [dans] · chaleur · est"},{"fr":"Le ventilateur est neuf.","tgt":"पंखा नया है।","ro":"Pankhā nayā hai.","lit":"ventilateur · neuf · est"},{"fr":"Le loyer est cher.","tgt":"किराया महँगा है।","ro":"Kirāyā mahaṃgā hai.","lit":"loyer · cher · est"},{"fr":"Nous sommes contents ici.","tgt":"हम यहाँ ख़ुश हैं।","ro":"Ham yahāṃ khush haiṃ.","lit":"nous · ici · contents · sommes"},{"fr":"Le quartier est calme.","tgt":"मोहल्ला शांत है।","ro":"Mohallā shānt hai.","lit":"quartier · calme · est"},{"fr":"Je suis chez moi.","tgt":"मैं घर पर हूँ।","ro":"Maiṃ ghar par hūṃ.","lit":"je · maison · [sur] · suis"}],"tip":{"title":"« Hai » : être, à la fin de la phrase","example":"L'appartement est petit. — फ़्लैट छोटा <b>है</b>।","body":"Le verbe être, en hindi, se dit « hai » pour « il est » ou « elle est », et il se place toujours à la toute fin. Pour dire « l'appartement est petit », on dit « Flaiṭ chhoṭā hai », mot à mot « appartement, petit, est ». Le français met le verbe au milieu, le hindi le garde pour la fin, comme un point final que l'on prononce. Avec « je », le verbe devient « hūṃ » : « Maiṃ ghar par hūṃ », je suis chez moi. Avec « nous » ou « vous », il devient « haiṃ », avec un son nasal comme dans le mot français « hein » : « Ham khush haiṃ », nous sommes contents. Pour retenir, dites-vous que « hai » est un petit soupir de satisfaction à la fin de chaque description : « Kamrā baṛā hai », la chambre est grande. Ne l'oubliez jamais, sans lui la phrase sonne inachevée.","exampleRo":"Flaiṭ chhoṭā hai.","lit":"appartement · petit · est","say":{"Hai":"है","hai":"है","Flaiṭ chhoṭā hai":"फ़्लैट छोटा है","hūṃ":"हूँ","Maiṃ ghar par hūṃ":"मैं घर पर हूँ","haiṃ":"हैं","Ham khush haiṃ":"हम ख़ुश हैं","Kamrā baṛā hai":"कमरा बड़ा है"}}},{"title":"Un chai à Chandni Chowk","phrases":[{"fr":"Il y a beaucoup de monde à Chandni Chowk.","tgt":"चाँदनी चौक में बहुत भीड़ है।","ro":"Chāṃdnī Chauk meṃ bahut bhīṛ hai.","lit":"Chandni Chowk · [dans] · beaucoup · foule · est"},{"fr":"Un chai, s'il vous plaît.","tgt":"एक चाय दीजिए।","ro":"Ek chāy dījie.","lit":"un · chai · donnez"},{"fr":"Le chai est brûlant.","tgt":"चाय बहुत गरम है।","ro":"Chāy bahut garam hai.","lit":"chai · très · chaude · est"},{"fr":"L'eau est froide.","tgt":"पानी ठंडा है।","ro":"Pānī ṭhaṇḍā hai.","lit":"eau · froide · est"},{"fr":"Il y a du lait dans le chai.","tgt":"चाय में दूध है।","ro":"Chāy meṃ dūdh hai.","lit":"chai · [dans] · lait · est"},{"fr":"Tout va bien.","tgt":"सब ठीक है।","ro":"Sab ṭhīk hai.","lit":"tout · bien · est"},{"fr":"Cette ruelle est étroite.","tgt":"यह गली पतली है।","ro":"Yah galī patlī hai.","lit":"cette · ruelle · étroite · est"},{"fr":"Le samosa est très croustillant.","tgt":"समोसा बहुत कुरकुरा है।","ro":"Samosā bahut kurkurā hai.","lit":"samosa · très · croustillant · est"},{"fr":"La boutique est fermée.","tgt":"दुकान बंद है।","ro":"Dukān band hai.","lit":"boutique · fermée · est"},{"fr":"Ce chai est très sucré.","tgt":"यह चाय बहुत मीठी है।","ro":"Yah chāy bahut mīṭhī hai.","lit":"ce · chai · très · sucrée · est"}],"tip":{"title":"Les sons du hindi : les consonnes aspirées et rétroflexes","example":"L'eau est froide. — पानी <b>ठंडा</b> है।","body":"Le hindi possède deux familles de sons qui n'existent pas en français. D'abord les consonnes aspirées, notées avec un « h » : on les prononce avec un petit souffle, comme si on soufflait sur une bougie. « Dūdh », le lait, se termine par un « d » suivi d'un souffle, et « bhīṛ », la foule, commence par un « b » soufflé. Ensuite les consonnes rétroflexes, qu'on prononce en recourbant le bout de la langue vers le palais, un peu en arrière des dents. Dans « ṭhaṇḍā », froid, les deux consonnes sont rétroflexes et la première est en plus aspirée : « ṭh », langue recourbée et souffle. Comparez avec « dūdh », où le « d » se fait langue contre les dents, à plat. Écoutez aussi « ṭhīk », bien, et « baṛā », grand, avec ce « ṛ » où la langue claque vers l'avant. Pour vous entraîner, mettez la main devant la bouche : sur les sons aspirés, vous devez sentir l'air passer.","exampleRo":"Pānī ṭhaṇḍā hai.","lit":"eau · froide · est","say":{"Dūdh":"दूध","bhīṛ":"भीड़","ṭhaṇḍā":"ठंडा","dūdh":"दूध","ṭhīk":"ठीक","baṛā":"बड़ा"}}},{"title":"Dans le métro de Delhi","phrases":[{"fr":"Est-ce que c'est la ligne jaune ?","tgt":"क्या यह पीली लाइन है?","ro":"Kyā yah pīlī lāin hai?","lit":"[question] · ceci · jaune · ligne · est ?"},{"fr":"Ce métro va-t-il à Chandni Chowk ?","tgt":"क्या यह मेट्रो चाँदनी चौक जाती है?","ro":"Kyā yah meṭro Chāṃdnī Chauk jātī hai?","lit":"[question] · ce · métro · Chandni Chowk · allant · est ?"},{"fr":"Le métro est-il rapide ?","tgt":"क्या मेट्रो तेज़ है?","ro":"Kyā meṭro tez hai?","lit":"[question] · métro · rapide · est ?"},{"fr":"Oui, il est très rapide.","tgt":"हाँ, बहुत तेज़ है।","ro":"Hāṃ, bahut tez hai.","lit":"oui · très · rapide · est"},{"fr":"Cette place est-elle libre ?","tgt":"क्या यह सीट ख़ाली है?","ro":"Kyā yah sīṭ khālī hai?","lit":"[question] · ce · siège · libre · est ?"},{"fr":"Le wagon est plein.","tgt":"डिब्बा भरा हुआ है।","ro":"Ḍibbā bharā huā hai.","lit":"wagon · rempli · devenu · est"},{"fr":"Est-ce que vous êtes de Delhi ?","tgt":"क्या आप दिल्ली से हैं?","ro":"Kyā āp Dillī se haiṃ?","lit":"[question] · vous · Delhi · [depuis] · êtes ?"},{"fr":"Oui, je suis d'ici.","tgt":"हाँ, मैं यहीं से हूँ।","ro":"Hāṃ, maiṃ yahīṃ se hūṃ.","lit":"oui · je · ici même · [depuis] · suis"},{"fr":"Est-ce que la station est loin ?","tgt":"क्या स्टेशन दूर है?","ro":"Kyā sṭeshan dūr hai?","lit":"[question] · station · loin · est ?"},{"fr":"Non, elle est tout près.","tgt":"नहीं, बहुत पास है।","ro":"Nahīṃ, bahut pās hai.","lit":"non · très · près · est"}],"tip":{"title":"« Kyā » : transformer une phrase en question","example":"Le métro est-il rapide ? — <b>क्या</b> मेट्रो तेज़ है?","body":"Poser une question fermée en hindi est d'une simplicité étonnante. On prend une phrase affirmative et on place simplement « kyā » au tout début, comme un « est-ce que » français. « Meṭro tez hai » veut dire le métro est rapide ; « Kyā meṭro tez hai ? » veut dire est-ce que le métro est rapide ? L'ordre des mots ne bouge pas du tout, le verbe reste à la fin. De même, « Kyā sṭeshan dūr hai ? », est-ce que la station est loin, et « Kyā āp Dillī se haiṃ ? », est-ce que vous êtes de Delhi. Faites monter légèrement la voix sur la fin de la phrase, comme en français. Dans la conversation rapide, on omet même souvent « kyā » et la seule intonation suffit. Pour retenir : « kyā » est la clé qui ouvre la question, posez-la devant la porte.","exampleRo":"Kyā meṭro tez hai?","lit":"[question] · métro · rapide · est ?","say":{"Kyā":"क्या","kyā":"क्या","Meṭro tez hai":"मेट्रो तेज़ है","Kyā meṭro tez hai ?":"क्या मेट्रो तेज़ है?","Kyā sṭeshan dūr hai ?":"क्या स्टेशन दूर है?","Kyā āp Dillī se haiṃ ?":"क्या आप दिल्ली से हैं?"}}},{"title":"Trouver un rickshaw","phrases":[{"fr":"Le rickshaw n'est pas là.","tgt":"रिक्शा यहाँ नहीं है।","ro":"Rikshā yahāṃ nahīṃ hai.","lit":"rickshaw · ici · pas · est"},{"fr":"Ce n'est pas loin.","tgt":"दूर नहीं है।","ro":"Dūr nahīṃ hai.","lit":"loin · pas · est"},{"fr":"Ce n'est pas cher.","tgt":"यह महँगा नहीं है।","ro":"Yah mahaṃgā nahīṃ hai.","lit":"ceci · cher · pas · est"},{"fr":"Le compteur ne marche pas.","tgt":"मीटर नहीं चलता।","ro":"Mīṭar nahīṃ chaltā.","lit":"compteur · pas · marchant"},{"fr":"Je ne connais pas la route.","tgt":"मुझे रास्ता नहीं पता।","ro":"Mujhe rāstā nahīṃ patā.","lit":"à moi · route · pas · connue"},{"fr":"Je ne suis pas pressé.","tgt":"मैं जल्दी में नहीं हूँ।","ro":"Maiṃ jaldī meṃ nahīṃ hūṃ.","lit":"je · hâte · [dans] · pas · suis"},{"fr":"Cent roupies, c'est trop.","tgt":"सौ रुपये बहुत ज़्यादा हैं।","ro":"Sau rupaye bahut zyādā haiṃ.","lit":"cent · roupies · très · trop · sont"},{"fr":"Le chauffeur ne parle pas français.","tgt":"ड्राइवर फ़्रांसीसी नहीं बोलता।","ro":"Ḍrāivar frānsīsī nahīṃ boltā.","lit":"chauffeur · français · pas · parlant"},{"fr":"Il ne fait pas froid.","tgt":"ठंड नहीं है।","ro":"Ṭhaṇḍ nahīṃ hai.","lit":"froid · pas · est"},{"fr":"Pas de problème.","tgt":"कोई बात नहीं।","ro":"Koī bāt nahīṃ.","lit":"aucune · chose · pas"}],"tip":{"title":"« Nahīṃ » : la négation","example":"Le rickshaw n'est pas là. — रिक्शा यहाँ <b>नहीं</b> है।","body":"Pour dire non en hindi, un seul mot suffit : « nahīṃ ». Il sert à la fois de « non » tout seul et de « ne... pas » dans une phrase. Là où le français entoure le verbe avec « ne » et « pas », le hindi place simplement « nahīṃ » juste avant le verbe. « Rikshā yahāṃ hai » signifie le rickshaw est là ; « Rikshā yahāṃ nahīṃ hai » signifie il n'est pas là, mot à mot « rickshaw, ici, pas, est ». Avec un verbe d'action, on laisse même tomber le petit « hai » final : « Ḍrāivar frānsīsī nahīṃ boltā », le chauffeur ne parle pas français. Prononcez bien la nasale finale, comme « nahin » dit avec le nez, et allongez le « ī ». Retenez aussi la formule « Koī bāt nahīṃ », pas de problème, que vous entendrez partout à Delhi.","exampleRo":"Rikshā yahāṃ nahīṃ hai.","lit":"rickshaw · ici · pas · est","say":{"Nahīṃ":"नहीं","nahīṃ":"नहीं","Rikshā yahāṃ hai":"रिक्शा यहाँ है","Rikshā yahāṃ nahīṃ hai":"रिक्शा यहाँ नहीं है","hai":"है","Ḍrāivar frānsīsī nahīṃ boltā":"ड्राइवर फ़्रांसीसी नहीं बोलता","nahin":"नहीं","Koī bāt nahīṃ":"कोई बात नहीं"}}},{"title":"Les voisins de l'immeuble","phrases":[{"fr":"Je suis votre voisin.","tgt":"मैं आपका पड़ोसी हूँ।","ro":"Maiṃ āpkā paṛosī hūṃ.","lit":"je · votre · voisin · suis"},{"fr":"Vous êtes nouveau ici ?","tgt":"क्या आप यहाँ नए हैं?","ro":"Kyā āp yahāṃ nae haiṃ?","lit":"[question] · vous · ici · nouveau · êtes ?"},{"fr":"Il est très drôle.","tgt":"वह बहुत मज़ेदार है।","ro":"Vah bahut mazedār hai.","lit":"il · très · drôle · est"},{"fr":"Elle est étudiante.","tgt":"वह छात्रा है।","ro":"Vah chhātrā hai.","lit":"elle · étudiante · est"},{"fr":"Tu es mon ami.","tgt":"तुम मेरे दोस्त हो।","ro":"Tum mere dost ho.","lit":"tu · mon · ami · es"},{"fr":"Il habite au deuxième étage.","tgt":"वह दूसरी मंज़िल पर रहता है।","ro":"Vah dūsrī manzil par rahtā hai.","lit":"il · deuxième · étage · [sur] · habitant · est"},{"fr":"Elle habite seule.","tgt":"वह अकेली रहती है।","ro":"Vah akelī rahtī hai.","lit":"elle · seule · habitant · est"},{"fr":"Vous habitez dans cet immeuble ?","tgt":"क्या आप इस बिल्डिंग में रहते हैं?","ro":"Kyā āp is bilḍing meṃ rahte haiṃ?","lit":"[question] · vous · cet · immeuble · [dans] · habitant · êtes ?"},{"fr":"Tu es fatigué aujourd'hui ?","tgt":"क्या तुम आज थके हुए हो?","ro":"Kyā tum āj thake hue ho?","lit":"[question] · tu · aujourd'hui · fatigué · devenu · es ?"},{"fr":"Nous sommes voisins.","tgt":"हम पड़ोसी हैं।","ro":"Ham paṛosī haiṃ.","lit":"nous · voisins · sommes"}],"tip":{"title":"Les pronoms : « maiṃ, āp, tum, vah »","example":"Je suis votre voisin. — <b>मैं</b> आपका पड़ोसी हूँ।","body":"Voici les quatre pronoms dont vous aurez besoin tous les jours. « Maiṃ » veut dire je, avec un son nasal à la fin, comme « mèn » dit du nez. « Āp » veut dire vous, « tum » veut dire tu, et « vah » veut dire à la fois il et elle : le hindi ne fait pas la différence dans le pronom. Chaque pronom appelle sa propre forme du verbe être : « maiṃ hūṃ », je suis, « āp haiṃ », vous êtes, « tum ho », tu es, et « vah hai », il ou elle est. Décomposons « Maiṃ āpkā paṛosī hūṃ » : je, votre, voisin, suis. Dans la conversation, « vah » se prononce très souvent « vo », ne soyez pas surpris. Pour savoir si « vah » parle d'un homme ou d'une femme, écoutez la fin des mots : « Vah akelī rahtī hai », elle habite seule, avec des « ī » féminins. Astuce : apprenez chaque pronom collé à son verbe, comme un duo indissociable.","exampleRo":"Maiṃ āpkā paṛosī hūṃ.","lit":"je · votre · voisin · suis","say":{"Maiṃ":"मैं","Āp":"आप","tum":"तुम","vah":"वह","maiṃ hūṃ":"मैं हूँ","āp haiṃ":"आप हैं","tum ho":"तुम हो","vah hai":"वह है","Maiṃ āpkā paṛosī hūṃ":"मैं आपका पड़ोसी हूँ","vo":"वो","Vah akelī rahtī hai":"वह अकेली रहती है","maiṃ, āp, tum, vah":"मैं, आप, तुम, वह"}}},{"title":"Un collègue et un ami","phrases":[{"fr":"Bonjour, monsieur Sharma, comment allez-vous ?","tgt":"नमस्ते शर्मा जी, आप कैसे हैं?","ro":"Namaste Sharmā jī, āp kaise haiṃ?","lit":"bonjour · Sharma · [respect] · vous · comment · êtes ?"},{"fr":"Je vais bien, et vous ?","tgt":"मैं ठीक हूँ, और आप?","ro":"Maiṃ ṭhīk hūṃ, aur āp?","lit":"je · bien · suis · et · vous ?"},{"fr":"Salut Ravi, ça va ?","tgt":"अरे रवि, तुम कैसे हो?","ro":"Are Ravi, tum kaise ho?","lit":"hé · Ravi · tu · comment · es ?"},{"fr":"Moi, ça va, et toi, raconte !","tgt":"मैं ठीक हूँ, तुम बताओ!","ro":"Maiṃ ṭhīk hūṃ, tum batāo!","lit":"je · bien · suis · toi · dis"},{"fr":"Vous êtes très occupé aujourd'hui ?","tgt":"क्या आप आज बहुत व्यस्त हैं?","ro":"Kyā āp āj bahut vyast haiṃ?","lit":"[question] · vous · aujourd'hui · très · occupé · êtes ?"},{"fr":"Tu es libre ce soir ?","tgt":"क्या तुम आज शाम ख़ाली हो?","ro":"Kyā tum āj shām khālī ho?","lit":"[question] · tu · aujourd'hui · soir · libre · es ?"},{"fr":"Vous habitez près du bureau ?","tgt":"क्या आप दफ़्तर के पास रहते हैं?","ro":"Kyā āp daftar ke pās rahte haiṃ?","lit":"[question] · vous · bureau · [de] · près · habitant · êtes ?"},{"fr":"Tu habites à Noida ?","tgt":"क्या तुम नोएडा में रहते हो?","ro":"Kyā tum Noeḍā meṃ rahte ho?","lit":"[question] · tu · Noida · [dans] · habitant · es ?"},{"fr":"Tu es mon meilleur ami.","tgt":"तुम मेरे सबसे अच्छे दोस्त हो।","ro":"Tum mere sabse achchhe dost ho.","lit":"tu · mon · le plus · bon · ami · es"},{"fr":"Monsieur Sharma travaille avec moi.","tgt":"शर्मा जी मेरे साथ काम करते हैं।","ro":"Sharmā jī mere sāth kām karte haiṃ.","lit":"Sharma · [respect] · moi · avec · travail · faisant · sont"}],"tip":{"title":"« Āp » et « tum » : vouvoyer et tutoyer","example":"Salut Ravi, ça va ? — अरे रवि, <b>तुम</b> कैसे <b>हो</b>?","body":"Comme le français, le hindi distingue le vouvoiement et le tutoiement. « Āp » correspond à notre vous de politesse : on l'utilise avec un collègue, un aîné, un commerçant ou toute personne que l'on ne connaît pas. « Tum » correspond à tu : on le réserve aux amis, aux gens de son âge, à la famille proche. Chacun entraîne sa forme de verbe : « Āp kaise haiṃ ? », comment allez-vous, mais « Tum kaise ho ? », comment vas-tu. Décomposons « Are Ravi, tum kaise ho » : hé, Ravi, tu, comment, es. Pour parler respectueusement de quelqu'un, on ajoute « jī » après son nom et on met le verbe au pluriel : « Sharmā jī mere sāth kām karte haiṃ ». Dans le doute, choisissez toujours « āp » : personne ne vous reprochera d'être poli. Astuce : « āp » est long et posé comme le respect, « tum » est court et vif comme l'amitié.","exampleRo":"Are Ravi, tum kaise ho?","lit":"hé · Ravi · tu · comment · es ?","say":{"Āp":"आप","tum":"तुम","Tum":"तुम","Āp kaise haiṃ ?":"आप कैसे हैं?","Tum kaise ho ?":"तुम कैसे हो?","Are Ravi, tum kaise ho":"अरे रवि, तुम कैसे हो","jī":"जी","Sharmā jī mere sāth kām karte haiṃ":"शर्मा जी मेरे साथ काम करते हैं","āp":"आप"}}},{"title":"Dal et roti au restaurant","phrases":[{"fr":"Le dal est très bon.","tgt":"दाल बहुत अच्छी है।","ro":"Dāl bahut achchhī hai.","lit":"dal · très · bonne · est"},{"fr":"Le samosa est bon.","tgt":"समोसा अच्छा है।","ro":"Samosā achchhā hai.","lit":"samosa · bon · est"},{"fr":"La roti est fraîche.","tgt":"रोटी ताज़ी है।","ro":"Roṭī tāzī hai.","lit":"roti · fraîche · est"},{"fr":"Ce dhaba est bon.","tgt":"यह ढाबा अच्छा है।","ro":"Yah ḍhābā achchhā hai.","lit":"ce · dhaba · bon · est"},{"fr":"Le chai est bon ici.","tgt":"यहाँ की चाय अच्छी है।","ro":"Yahāṃ kī chāy achchhī hai.","lit":"ici · [de] · chai · bonne · est"},{"fr":"La nourriture est très épicée.","tgt":"खाना बहुत तीखा है।","ro":"Khānā bahut tīkhā hai.","lit":"nourriture · très · piquante · est"},{"fr":"Le chutney vert est très piquant.","tgt":"हरी चटनी बहुत तीखी है।","ro":"Harī chaṭnī bahut tīkhī hai.","lit":"verte · chutney · très · piquante · est"},{"fr":"Le lassi est-il sucré ?","tgt":"क्या लस्सी मीठी है?","ro":"Kyā lassī mīṭhī hai?","lit":"[question] · lassi · sucrée · est ?"},{"fr":"Le paneer est très frais.","tgt":"पनीर बहुत ताज़ा है।","ro":"Panīr bahut tāzā hai.","lit":"paneer · très · frais · est"},{"fr":"C'est une très bonne adresse.","tgt":"यह बहुत अच्छी जगह है।","ro":"Yah bahut achchhī jagah hai.","lit":"ceci · très · bon · endroit · est"}],"tip":{"title":"Masculin et féminin : « achchhā, achchhī »","example":"Le dal est très bon. — दाल बहुत <b>अच्छी</b> है।","body":"En hindi, chaque nom est masculin ou féminin, comme en français, mais les genres ne tombent pas toujours au même endroit. Beaucoup d'adjectifs changent leur dernière voyelle pour s'accorder : « ā » pour le masculin, « ī » pour le féminin. Ainsi, « achchhā » veut dire bon et « achchhī » veut dire bonne. On dit « Samosā achchhā hai », le samosa est bon, mais « Dāl bahut achchhī hai », mot à mot « dal, très, bonne, est », car le dal est féminin en hindi. Même chose avec « tāzā » et « tāzī », frais et fraîche : « Panīr tāzā hai », mais « Roṭī tāzī hai ». Un indice pratique : un nom qui se termine par « ā », comme « khānā » ou « samosā », est souvent masculin, et un nom en « ī », comme « roṭī » ou « chaṭnī », est souvent féminin. Attention, certains adjectifs comme « garam », chaud, ne changent jamais. Pour retenir, pensez à « ā » grand ouvert pour le masculin, et « ī » fin et souriant pour le féminin.","exampleRo":"Dāl bahut achchhī hai.","lit":"dal · très · bonne · est","say":{"achchhā":"अच्छा","achchhī":"अच्छी","Samosā achchhā hai":"समोसा अच्छा है","Dāl bahut achchhī hai":"दाल बहुत अच्छी है","tāzā":"ताज़ा","tāzī":"ताज़ी","Panīr tāzā hai":"पनीर ताज़ा है","Roṭī tāzī hai":"रोटी ताज़ी है","khānā":"खाना","samosā":"समोसा","roṭī":"रोटी","chaṭnī":"चटनी","garam":"गरम","achchhā, achchhī":"अच्छा, अच्छी"}}},{"title":"Au marché de Chandni Chowk","phrases":[{"fr":"Ce kurta est beau.","tgt":"यह कुर्ता सुंदर है।","ro":"Yah kurtā sundar hai.","lit":"ce · kurta · beau · est"},{"fr":"Ce kurta-là est bleu.","tgt":"वह कुर्ता नीला है।","ro":"Vah kurtā nīlā hai.","lit":"ce-là · kurta · bleu · est"},{"fr":"Et ça, c'est quoi ?","tgt":"और यह क्या है?","ro":"Aur yah kyā hai?","lit":"et · ceci · quoi · est ?"},{"fr":"Cette boutique-là est très ancienne.","tgt":"वह दुकान बहुत पुरानी है।","ro":"Vah dukān bahut purānī hai.","lit":"cette-là · boutique · très · ancienne · est"},{"fr":"Ce foulard est en soie.","tgt":"यह दुपट्टा रेशम का है।","ro":"Yah dupaṭṭā resham kā hai.","lit":"ce · foulard · soie · [de] · est"},{"fr":"Celui-là est très petit.","tgt":"वह बहुत छोटा है।","ro":"Vah bahut chhoṭā hai.","lit":"celui-là · très · petit · est"},{"fr":"Ceci est pour vous.","tgt":"यह आपके लिए है।","ro":"Yah āpke lie hai.","lit":"ceci · vous · [pour] · est"},{"fr":"Cet homme-là est le marchand.","tgt":"वह आदमी दुकानदार है।","ro":"Vah ādmī dukāndār hai.","lit":"cet-là · homme · marchand · est"},{"fr":"Ce sac est lourd.","tgt":"यह थैला भारी है।","ro":"Yah thailā bhārī hai.","lit":"ce · sac · lourd · est"},{"fr":"Cette couleur est très belle.","tgt":"यह रंग बहुत सुंदर है।","ro":"Yah rang bahut sundar hai.","lit":"cette · couleur · très · belle · est"}],"tip":{"title":"« Yah » et « vah » : ceci et cela","example":"Ce kurta-là est bleu. — <b>वह</b> कुर्ता नीला है।","body":"Pour montrer quelque chose, le hindi utilise deux petits mots. « Yah » désigne ce qui est proche de vous, comme ceci ou ce... ci : « Yah kurtā sundar hai », ce kurta est beau, celui que vous tenez en main. « Vah » désigne ce qui est plus loin, comme cela ou ce... là : « Vah kurtā nīlā hai », mot à mot « ce-là, kurta, bleu, est », celui accroché au fond de la boutique. Ces mots s'utilisent aussi tout seuls : « Yah kyā hai ? », c'est quoi, ça ? Ils ne changent pas selon le masculin ou le féminin : « vah dukān », cette boutique-là, et « vah ādmī », cet homme-là. À l'oral, à Delhi, vous entendrez presque toujours « ye » pour « yah » et « vo » pour « vah ». Astuce : « yah » commence comme « y » de « ici », et « vah » sonne comme un « voilà » lancé au loin.","exampleRo":"Vah kurtā nīlā hai.","lit":"ce-là · kurta · bleu · est","say":{"Yah":"यह","vah":"वह","Yah kurtā sundar hai":"यह कुर्ता सुंदर है","Vah":"वह","Vah kurtā nīlā hai":"वह कुर्ता नीला है","Yah kyā hai ?":"यह क्या है?","vah dukān":"वह दुकान","vah ādmī":"वह आदमी","ye":"ये","yah":"यह","vo":"वो"}}},{"title":"La famille de Priya","phrases":[{"fr":"C'est la maison de Priya.","tgt":"यह प्रिया का घर है।","ro":"Yah Priyā kā ghar hai.","lit":"ceci · Priya · [de] · maison · est"},{"fr":"La sœur de Rahul habite à Delhi.","tgt":"राहुल की बहन दिल्ली में रहती है।","ro":"Rāhul kī bahan Dillī meṃ rahtī hai.","lit":"Rahul · [de] · sœur · Delhi · [dans] · habitant · est"},{"fr":"Les parents de Priya sont très gentils.","tgt":"प्रिया के माता-पिता बहुत अच्छे हैं।","ro":"Priyā ke mātā-pitā bahut achchhe haiṃ.","lit":"Priya · [de] · mère-père · très · bons · sont"},{"fr":"Le frère de Priya est étudiant.","tgt":"प्रिया का भाई छात्र है।","ro":"Priyā kā bhāī chhātr hai.","lit":"Priya · [de] · frère · étudiant · est"},{"fr":"La cuisine de la mère de Priya est délicieuse.","tgt":"प्रिया की माँ का खाना बहुत अच्छा है।","ro":"Priyā kī māṃ kā khānā bahut achchhā hai.","lit":"Priya · [de] · mère · [de] · nourriture · très · bonne · est"},{"fr":"C'est le téléphone de Rahul.","tgt":"यह राहुल का फ़ोन है।","ro":"Yah Rāhul kā fon hai.","lit":"ceci · Rahul · [de] · téléphone · est"},{"fr":"La chambre de Priya est petite.","tgt":"प्रिया का कमरा छोटा है।","ro":"Priyā kā kamrā chhoṭā hai.","lit":"Priya · [de] · chambre · petite · est"},{"fr":"Les enfants de Rahul sont à l'école.","tgt":"राहुल के बच्चे स्कूल में हैं।","ro":"Rāhul ke bachche skūl meṃ haiṃ.","lit":"Rahul · [de] · enfants · école · [dans] · sont"},{"fr":"La chaleur de Delhi est terrible.","tgt":"दिल्ली की गर्मी बहुत तेज़ है।","ro":"Dillī kī garmī bahut tez hai.","lit":"Delhi · [de] · chaleur · très · forte · est"},{"fr":"Le père de Priya s'appelle Anil.","tgt":"प्रिया के पिताजी का नाम अनिल है।","ro":"Priyā ke pitājī kā nām Anil hai.","lit":"Priya · [de] · père · [de] · nom · Anil · est"}],"tip":{"title":"« Kā, kī, ke » : le possessif qui s'accorde","example":"La sœur de Rahul habite à Delhi. — राहुल <b>की</b> बहन दिल्ली में रहती है।","body":"Pour dire « de » au sens de l'appartenance, le hindi inverse l'ordre français. On dit d'abord le propriétaire, puis le petit mot « kā », puis la chose possédée. « Priyā kā ghar » signifie la maison de Priya, mot à mot « Priya, de, maison ». La subtilité, c'est que ce petit mot s'accorde avec la chose possédée, pas avec le propriétaire. Devant un nom masculin, on dit « kā » : « Rāhul kā fon », le téléphone de Rahul. Devant un nom féminin, on dit « kī » : « Rāhul kī bahan », la sœur de Rahul. Devant un pluriel ou une personne respectée, on dit « ke » : « Rāhul ke bachche », les enfants de Rahul, ou « Priyā ke pitājī », le père de Priya. On retrouve donc les terminaisons « ā » et « ī » de « achchhā » et « achchhī ». Astuce : regardez toujours vers la droite, c'est le mot qui suit qui choisit entre « kā », « kī » et « ke ».","exampleRo":"Rāhul kī bahan Dillī meṃ rahtī hai.","lit":"Rahul · [de] · sœur · Delhi · [dans] · habitant · est","say":{"Kā, kī, ke":"का, की, के","kā":"का","Priyā kā ghar":"प्रिया का घर","Rāhul kā fon":"राहुल का फ़ोन","kī":"की","Rāhul kī bahan":"राहुल की बहन","ke":"के","Rāhul ke bachche":"राहुल के बच्चे","Priyā ke pitājī":"प्रिया के पिताजी","achchhā":"अच्छा","achchhī":"अच्छी"}}},{"title":"Compter au marché","phrases":[{"fr":"Un chai et deux samosas.","tgt":"एक चाय और दो समोसे।","ro":"Ek chāy aur do samose.","lit":"un · chai · et · deux · samosas"},{"fr":"Trois rotis, s'il vous plaît.","tgt":"तीन रोटियाँ दीजिए।","ro":"Tīn roṭiyāṃ dījie.","lit":"trois · rotis · donnez"},{"fr":"Quatre bananes, c'est vingt roupies.","tgt":"चार केले बीस रुपये के हैं।","ro":"Chār kele bīs rupaye ke haiṃ.","lit":"quatre · bananes · vingt · roupies · [de] · sont"},{"fr":"Seulement cinq roupies.","tgt":"सिर्फ़ पाँच रुपये।","ro":"Sirf pāṃch rupaye.","lit":"seulement · cinq · roupies"},{"fr":"J'ai deux frères.","tgt":"मेरे दो भाई हैं।","ro":"Mere do bhāī haiṃ.","lit":"mes · deux · frères · sont"},{"fr":"Une mangue coûte trente roupies.","tgt":"एक आम तीस रुपये का है।","ro":"Ek ām tīs rupaye kā hai.","lit":"une · mangue · trente · roupies · [de] · est"},{"fr":"Sept, huit, neuf et dix.","tgt":"सात, आठ, नौ और दस।","ro":"Sāt, āṭh, nau aur das.","lit":"sept · huit · neuf · et · dix"},{"fr":"Nous sommes six.","tgt":"हम छह लोग हैं।","ro":"Ham chhah log haiṃ.","lit":"nous · six · personnes · sommes"},{"fr":"Les deux pour cent roupies.","tgt":"दोनों के सौ रुपये।","ro":"Donoṃ ke sau rupaye.","lit":"les deux · [de] · cent · roupies"},{"fr":"Les tomates sont à quarante roupies le kilo.","tgt":"टमाटर चालीस रुपये किलो हैं।","ro":"Ṭamāṭar chālīs rupaye kilo haiṃ.","lit":"tomates · quarante · roupies · kilo · sont"}],"tip":{"title":"Compter : « ek, do, tīn »","example":"Un chai et deux samosas. — <b>एक</b> चाय और <b>दो</b> समोसे।","body":"Les premiers nombres du hindi sont courts et faciles à dire. Un se dit « ek », deux « do », trois « tīn », quatre « chār » et cinq « pāṃch », avec un « ā » nasal. Viennent ensuite six « chhah », sept « sāt », huit « āṭh », neuf « nau » et dix « das ». Comme en français, le nombre se place devant le nom : « Ek chāy aur do samose », mot à mot « un, chai, et, deux, samosas ». Remarquez que le nom se met au pluriel après deux : « samosā » devient « samose », et « roṭī » devient « roṭiyāṃ ». Pour les prix, retenez « bīs », vingt, « tīs », trente, « chālīs », quarante, et « sau », cent, suivis de « rupaye », roupies. Au marché, entraînez-vous à compter à voix haute vos achats, un, « ek », deux, « do », trois, « tīn » : les marchands apprécient beaucoup l'effort.","exampleRo":"Ek chāy aur do samose.","lit":"un · chai · et · deux · samosas","say":{"ek":"एक","do":"दो","tīn":"तीन","chār":"चार","pāṃch":"पाँच","chhah":"छह","sāt":"सात","āṭh":"आठ","nau":"नौ","das":"दस","Ek chāy aur do samose":"एक चाय और दो समोसे","samosā":"समोसा","samose":"समोसे","roṭī":"रोटी","roṭiyāṃ":"रोटियाँ","bīs":"बीस","tīs":"तीस","chālīs":"चालीस","sau":"सौ","rupaye":"रुपये","ek, do, tīn":"एक, दो, तीन"}}},{"title":"Où est mon téléphone ?","phrases":[{"fr":"Le téléphone est sur la table.","tgt":"फ़ोन मेज़ पर है।","ro":"Fon mez par hai.","lit":"téléphone · table · [sur] · est"},{"fr":"Les clés sont dans le sac.","tgt":"चाबियाँ थैले में हैं।","ro":"Chābiyāṃ thaile meṃ haiṃ.","lit":"clés · sac · [dans] · sont"},{"fr":"Le portefeuille est dans la poche.","tgt":"बटुआ जेब में है।","ro":"Baṭuā jeb meṃ hai.","lit":"portefeuille · poche · [dans] · est"},{"fr":"Le chargeur est sur le lit.","tgt":"चार्जर बिस्तर पर है।","ro":"Chārjar bistar par hai.","lit":"chargeur · lit · [sur] · est"},{"fr":"Le métro part d'ici.","tgt":"मेट्रो यहाँ से चलती है।","ro":"Meṭro yahāṃ se chaltī hai.","lit":"métro · ici · [depuis] · partant · est"},{"fr":"Mon ami est à la maison.","tgt":"मेरा दोस्त घर पर है।","ro":"Merā dost ghar par hai.","lit":"mon · ami · maison · [sur] · est"},{"fr":"Il y a du chai dans la tasse.","tgt":"कप में चाय है।","ro":"Kap meṃ chāy hai.","lit":"tasse · [dans] · chai · est"},{"fr":"La station est loin d'ici.","tgt":"स्टेशन यहाँ से दूर है।","ro":"Sṭeshan yahāṃ se dūr hai.","lit":"station · ici · [depuis] · loin · est"},{"fr":"Le téléphone est dans la cuisine.","tgt":"फ़ोन रसोई में है।","ro":"Fon rasoī meṃ hai.","lit":"téléphone · cuisine · [dans] · est"},{"fr":"Je suis de Marseille.","tgt":"मैं मार्सेल से हूँ।","ro":"Maiṃ Mārsel se hūṃ.","lit":"je · Marseille · [depuis] · suis"}],"tip":{"title":"« Meṃ, par, se » : les petits mots placés après le nom","example":"Le téléphone est sur la table. — फ़ोन मेज़ <b>पर</b> है।","body":"En français, on dit « sur la table » : le petit mot vient avant le nom. En hindi, c'est l'inverse, il vient après, on l'appelle donc une postposition. « Fon mez par hai » se décompose en « téléphone, table, sur, est ». Les trois postpositions les plus utiles sont « meṃ », dans, « par », sur, et « se », depuis ou de. On dit ainsi « Chābiyāṃ thaile meṃ haiṃ », les clés sont dans le sac, et « Maiṃ Mārsel se hūṃ », je suis de Marseille, c'est-à-dire je viens depuis Marseille. Notez l'expression « ghar par », à la maison, mot à mot sur la maison. Le nom peut légèrement changer devant une postposition : « thailā », le sac, devient « thaile meṃ », dans le sac. Astuce : imaginez que la postposition est une étiquette collée au dos du nom, elle le suit partout.","exampleRo":"Fon mez par hai.","lit":"téléphone · table · [sur] · est","say":{"Meṃ, par, se":"में, पर, से","Fon mez par hai":"फ़ोन मेज़ पर है","meṃ":"में","par":"पर","se":"से","Chābiyāṃ thaile meṃ haiṃ":"चाबियाँ थैले में हैं","Maiṃ Mārsel se hūṃ":"मैं मार्सेल से हूँ","ghar par":"घर पर","thailā":"थैला","thaile meṃ":"थैले में"}}},{"title":"Ce que j'ai dans mon sac","phrases":[{"fr":"J'ai un parapluie.","tgt":"मेरे पास छाता है।","ro":"Mere pās chhātā hai.","lit":"mon · [près] · parapluie · est"},{"fr":"J'ai une carte de métro.","tgt":"मेरे पास मेट्रो कार्ड है।","ro":"Mere pās meṭro kārḍ hai.","lit":"mon · [près] · métro · carte · est"},{"fr":"Je n'ai pas de monnaie.","tgt":"मेरे पास खुले पैसे नहीं हैं।","ro":"Mere pās khule paise nahīṃ haiṃ.","lit":"mon · [près] · détaché · argent · pas · sont"},{"fr":"Avez-vous de la monnaie ?","tgt":"क्या आपके पास खुले पैसे हैं?","ro":"Kyā āpke pās khule paise haiṃ?","lit":"[question] · votre · [près] · détaché · argent · sont ?"},{"fr":"J'ai cinq cents roupies.","tgt":"मेरे पास पाँच सौ रुपये हैं।","ro":"Mere pās pāṃch sau rupaye haiṃ.","lit":"mon · [près] · cinq · cents · roupies · sont"},{"fr":"Elle a un nouveau kurta.","tgt":"उसके पास नया कुर्ता है।","ro":"Uske pās nayā kurtā hai.","lit":"son · [près] · nouveau · kurta · est"},{"fr":"Vous avez un stylo ?","tgt":"क्या आपके पास पेन है?","ro":"Kyā āpke pās pen hai?","lit":"[question] · votre · [près] · stylo · est ?"},{"fr":"Je n'ai pas le temps aujourd'hui.","tgt":"आज मेरे पास समय नहीं है।","ro":"Āj mere pās samay nahīṃ hai.","lit":"aujourd'hui · mon · [près] · temps · pas · est"},{"fr":"J'ai une bouteille d'eau.","tgt":"मेरे पास पानी की बोतल है।","ro":"Mere pās pānī kī botal hai.","lit":"mon · [près] · eau · [de] · bouteille · est"},{"fr":"Tu as un chargeur ?","tgt":"क्या तुम्हारे पास चार्जर है?","ro":"Kyā tumhāre pās chārjar hai?","lit":"[question] · ton · [près] · chargeur · est ?"}],"tip":{"title":"« Mere pās... hai » : avoir","example":"J'ai un parapluie. — <b>मेरे</b> <b>पास</b> छाता है।","body":"Le hindi n'a pas de verbe avoir comme le nôtre. Pour dire que l'on possède un objet, on dit qu'il est près de soi. « Mere pās chhātā hai » signifie j'ai un parapluie, mot à mot « mon près, parapluie, est », autrement dit un parapluie est près de moi. On change simplement le premier mot selon la personne : « mere pās » pour moi, « āpke pās » pour vous, « tumhāre pās » pour toi, et « uske pās » pour lui ou elle. Pour poser la question, on ajoute « kyā » devant : « Kyā āpke pās pen hai ? », vous avez un stylo ? Pour dire que l'on n'a pas, on glisse « nahīṃ » avant le verbe : « Mere pās samay nahīṃ hai », je n'ai pas le temps. Si l'objet est au pluriel, « hai » devient « haiṃ ». Astuce : imaginez que vous tapotez votre sac en disant « mere pās », c'est près de moi, donc c'est à moi.","exampleRo":"Mere pās chhātā hai.","lit":"mon · [près] · parapluie · est","say":{"Mere pās chhātā hai":"मेरे पास छाता है","mere pās":"मेरे पास","āpke pās":"आपके पास","tumhāre pās":"तुम्हारे पास","uske pās":"उसके पास","kyā":"क्या","Kyā āpke pās pen hai ?":"क्या आपके पास पेन है?","nahīṃ":"नहीं","Mere pās samay nahīṃ hai":"मेरे पास समय नहीं है","hai":"है","haiṃ":"हैं"}}},{"title":"La routine du matin","phrases":[{"fr":"Je me lève tôt.","tgt":"मैं जल्दी उठता हूँ।","ro":"Maiṃ jaldī uṭhtā hūṃ.","lit":"je · tôt · levant · suis"},{"fr":"Le matin, je bois du chai.","tgt":"मैं सुबह चाय पीता हूँ।","ro":"Maiṃ subah chāy pītā hūṃ.","lit":"je · matin · chai · buvant · suis"},{"fr":"Je mange deux rotis.","tgt":"मैं दो रोटियाँ खाता हूँ।","ro":"Maiṃ do roṭiyāṃ khātā hūṃ.","lit":"je · deux · rotis · mangeant · suis"},{"fr":"Je vais au bureau en métro.","tgt":"मैं मेट्रो से दफ़्तर जाता हूँ।","ro":"Maiṃ meṭro se daftar jātā hūṃ.","lit":"je · métro · [depuis] · bureau · allant · suis"},{"fr":"Ma femme lit le journal.","tgt":"मेरी पत्नी अख़बार पढ़ती है।","ro":"Merī patnī akhbār paṛhtī hai.","lit":"ma · femme · journal · lisant · est"},{"fr":"Les enfants vont à l'école.","tgt":"बच्चे स्कूल जाते हैं।","ro":"Bachche skūl jāte haiṃ.","lit":"enfants · école · allant · sont"},{"fr":"Je travaille toute la journée.","tgt":"मैं पूरे दिन काम करता हूँ।","ro":"Maiṃ pūre din kām kartā hūṃ.","lit":"je · entier · jour · travail · faisant · suis"},{"fr":"Le soir, nous mangeons ensemble.","tgt":"शाम को हम साथ खाना खाते हैं।","ro":"Shām ko ham sāth khānā khāte haiṃ.","lit":"soir · [à] · nous · ensemble · repas · mangeant · sommes"},{"fr":"Je ne mange pas de viande.","tgt":"मैं मांस नहीं खाता।","ro":"Maiṃ māṃs nahīṃ khātā.","lit":"je · viande · pas · mangeant"},{"fr":"Ma sœur se lève très tôt.","tgt":"मेरी बहन बहुत जल्दी उठती है।","ro":"Merī bahan bahut jaldī uṭhtī hai.","lit":"ma · sœur · très · tôt · levant · est"}],"tip":{"title":"Le présent habituel : « maiṃ jātā hūṃ »","example":"Je vais au bureau en métro. — मैं मेट्रो से दफ़्तर <b>जाता</b> <b>हूँ</b>।","body":"Pour parler de ce que l'on fait d'habitude, le hindi utilise une construction en deux morceaux. On prend la racine du verbe, on ajoute une terminaison, puis on termine par le verbe être. « Jā » veut dire aller, et « Maiṃ jātā hūṃ » veut dire je vais, mot à mot « je, allant, suis ». La terminaison s'accorde avec la personne qui parle : « tā » pour un homme, « tī » pour une femme, « te » pour le pluriel ou le vouvoiement. Un homme dit « Maiṃ jaldī uṭhtā hūṃ », je me lève tôt, une femme dit « Maiṃ jaldī uṭhtī hūṃ », et l'on dit « Bachche skūl jāte haiṃ », les enfants vont à l'école. À la forme négative, on laisse souvent tomber le verbe être : « Maiṃ māṃs nahīṃ khātā ». C'est la forme idéale pour raconter votre routine à Delhi. Astuce : retenez le refrain « tā hūṃ, tī hūṃ, te haiṃ », il vous servira avec tous les verbes.","exampleRo":"Maiṃ meṭro se daftar jātā hūṃ.","lit":"je · métro · [depuis] · bureau · allant · suis","say":{"Jā":"जा","Maiṃ jātā hūṃ":"मैं जाता हूँ","Maiṃ jaldī uṭhtā hūṃ":"मैं जल्दी उठता हूँ","Maiṃ jaldī uṭhtī hūṃ":"मैं जल्दी उठती हूँ","Bachche skūl jāte haiṃ":"बच्चे स्कूल जाते हैं","Maiṃ māṃs nahīṃ khātā":"मैं मांस नहीं खाता","maiṃ jātā hūṃ":"मैं जाता हूँ","tā":"ता","tī":"ती","te":"ते","tā hūṃ, tī hūṃ, te haiṃ":"ता हूँ, ती हूँ, ते हैं"}}},{"title":"Demander son chemin","phrases":[{"fr":"Où est la station de métro ?","tgt":"मेट्रो स्टेशन कहाँ है?","ro":"Meṭro sṭeshan kahāṃ hai?","lit":"métro · station · où · est ?"},{"fr":"Qui est cet homme ?","tgt":"वह आदमी कौन है?","ro":"Vah ādmī kaun hai?","lit":"cet-là · homme · qui · est ?"},{"fr":"Combien coûte ce kurta ?","tgt":"यह कुर्ता कितने का है?","ro":"Yah kurtā kitne kā hai?","lit":"ce · kurta · combien · [de] · est ?"},{"fr":"Quand passe le prochain métro ?","tgt":"अगली मेट्रो कब है?","ro":"Aglī meṭro kab hai?","lit":"prochain · métro · quand · est ?"},{"fr":"Chandni Chowk, c'est à quelle distance ?","tgt":"चाँदनी चौक कितनी दूर है?","ro":"Chāṃdnī Chauk kitnī dūr hai?","lit":"Chandni Chowk · combien · loin · est ?"},{"fr":"Le marché aux épices, c'est où ?","tgt":"मसाला बाज़ार कहाँ है?","ro":"Masālā bāzār kahāṃ hai?","lit":"épices · marché · où · est ?"},{"fr":"Quel est le nom de cette rue ?","tgt":"इस गली का नाम क्या है?","ro":"Is galī kā nām kyā hai?","lit":"cette · ruelle · [de] · nom · quoi · est ?"},{"fr":"Qui parle français ici ?","tgt":"यहाँ फ़्रांसीसी कौन बोलता है?","ro":"Yahāṃ frānsīsī kaun boltā hai?","lit":"ici · français · qui · parlant · est ?"},{"fr":"Le musée ouvre à quelle heure ?","tgt":"म्यूज़ियम कब खुलता है?","ro":"Myūziyam kab khultā hai?","lit":"musée · quand · ouvrant · est ?"},{"fr":"Il faut combien de temps à pied ?","tgt":"पैदल कितना समय लगता है?","ro":"Paidal kitnā samay lagtā hai?","lit":"à pied · combien · temps · prenant · est ?"}],"tip":{"title":"Les mots interrogatifs : « kyā, kahāṃ, kaun, kab, kitnā »","example":"Où est la station de métro ? — मेट्रो स्टेशन <b>कहाँ</b> है?","body":"Les mots interrogatifs du hindi commencent presque tous par le son « k », ce qui les rend faciles à repérer. « Kyā » veut dire quoi, « kahāṃ » où, « kaun » qui, « kab » quand, et « kitnā » combien. Contrairement au français, on ne les met pas en tête de phrase : on les place juste avant le verbe, à l'endroit où se trouverait la réponse. « Meṭro sṭeshan kahāṃ hai ? » se décompose en « métro, station, où, est ? ». La réponse aura exactement la même forme : « Meṭro sṭeshan vahāṃ hai », la station est là-bas. De même, « Vah ādmī kaun hai ? », qui est cet homme, et « Aglī meṭro kab hai ? », quand passe le prochain métro. « Kitnā » s'accorde comme un adjectif : « kitnā samay », combien de temps, mais « kitnī dūr », à quelle distance. Astuce : remplacez la réponse par le mot en « k », sans rien déplacer d'autre.","exampleRo":"Meṭro sṭeshan kahāṃ hai?","lit":"métro · station · où · est ?","say":{"Kyā":"क्या","kahāṃ":"कहाँ","kaun":"कौन","kab":"कब","kitnā":"कितना","Meṭro sṭeshan kahāṃ hai ?":"मेट्रो स्टेशन कहाँ है?","Meṭro sṭeshan vahāṃ hai":"मेट्रो स्टेशन वहाँ है","Vah ādmī kaun hai ?":"वह आदमी कौन है?","Aglī meṭro kab hai ?":"अगली मेट्रो कब है?","Kitnā":"कितना","kitnā samay":"कितना समय","kitnī dūr":"कितनी दूर","kyā, kahāṃ, kaun, kab, kitnā":"क्या, कहाँ, कौन, कब, कितना"}}},{"title":"La mousson à Delhi","phrases":[{"fr":"Aujourd'hui aussi, il pleut.","tgt":"आज भी बारिश है।","ro":"Āj bhī bārish hai.","lit":"aujourd'hui · aussi · pluie · est"},{"fr":"Il fait chaud, et c'est humide aussi.","tgt":"गर्मी भी है और उमस भी।","ro":"Garmī bhī hai aur umas bhī.","lit":"chaleur · aussi · est · et · moiteur · aussi"},{"fr":"Moi aussi, j'aime la pluie.","tgt":"मुझे भी बारिश पसंद है।","ro":"Mujhe bhī bārish pasand hai.","lit":"à moi · aussi · pluie · plaisante · est"},{"fr":"Il y a des nuages dans le ciel.","tgt":"आसमान में बादल हैं।","ro":"Āsmān meṃ bādal haiṃ.","lit":"ciel · [dans] · nuages · sont"},{"fr":"La mousson arrive en juillet.","tgt":"मानसून जुलाई में आता है।","ro":"Mānsūn julāī meṃ ātā hai.","lit":"mousson · juillet · [dans] · venant · est"},{"fr":"Il y a de l'eau sur la route.","tgt":"सड़क पर पानी है।","ro":"Saṛak par pānī hai.","lit":"route · [sur] · eau · est"},{"fr":"Mes chaussures aussi sont mouillées.","tgt":"मेरे जूते भी गीले हैं।","ro":"Mere jūte bhī gīle haiṃ.","lit":"mes · chaussures · aussi · mouillées · sont"},{"fr":"Le soir aussi, il fait chaud.","tgt":"शाम को भी गर्मी होती है।","ro":"Shām ko bhī garmī hotī hai.","lit":"soir · [à] · aussi · chaleur · étant · est"},{"fr":"J'ai aussi un parapluie.","tgt":"मेरे पास छाता भी है।","ro":"Mere pās chhātā bhī hai.","lit":"mon · [près] · parapluie · aussi · est"},{"fr":"Des pakoras aussi, s'il vous plaît.","tgt":"पकौड़े भी दीजिए।","ro":"Pakauṛe bhī dījie.","lit":"pakoras · aussi · donnez"}],"tip":{"title":"« Bhī » : aussi","example":"Moi aussi, j'aime la pluie. — मुझे <b>भी</b> बारिश पसंद है।","body":"Le mot « bhī » veut dire aussi, et il se place toujours juste après le mot qu'il concerne. C'est très précis : en déplaçant « bhī », on change le sens de la phrase. « Mujhe bhī bārish pasand hai » signifie moi aussi, j'aime la pluie, mot à mot « à moi, aussi, pluie, plaisante, est ». Mais « Āj bhī bārish hai » signifie aujourd'hui aussi, il pleut : c'est le jour qui est concerné. Et « Pakauṛe bhī dījie » veut dire donnez aussi des pakoras. On peut même le répéter pour dire et... et : « Garmī bhī hai aur umas bhī », il fait chaud et humide à la fois. Prononcez bien le « bh » avec un petit souffle, sinon on entend « bī ». Astuce : pensez à « bhī » comme à un petit drapeau que vous plantez juste derrière le mot important.","exampleRo":"Mujhe bhī bārish pasand hai.","lit":"à moi · aussi · pluie · plaisante · est","say":{"Bhī":"भी","bhī":"भी","Mujhe bhī bārish pasand hai":"मुझे भी बारिश पसंद है","Āj bhī bārish hai":"आज भी बारिश है","Pakauṛe bhī dījie":"पकौड़े भी दीजिए","Garmī bhī hai aur umas bhī":"गर्मी भी है और उमस भी"}}},{"title":"Quelle heure est-il ?","phrases":[{"fr":"Il est quelle heure, s'il vous plaît ?","tgt":"कितने बजे हैं?","ro":"Kitne baje haiṃ?","lit":"combien · sonnés · sont ?"},{"fr":"Il est deux heures.","tgt":"दो बजे हैं।","ro":"Do baje haiṃ.","lit":"deux · sonnés · sont"},{"fr":"Il est une heure.","tgt":"एक बजा है।","ro":"Ek bajā hai.","lit":"une · sonnée · est"},{"fr":"Le cours commence à dix heures.","tgt":"क्लास दस बजे शुरू होती है।","ro":"Klās das baje shurū hotī hai.","lit":"cours · dix · sonnés · début · étant · est"},{"fr":"Il est quatre heures et demie.","tgt":"साढ़े चार बजे हैं।","ro":"Sāṛhe chār baje haiṃ.","lit":"et demie · quatre · sonnés · sont"},{"fr":"Je déjeune à une heure.","tgt":"मैं एक बजे खाना खाता हूँ।","ro":"Maiṃ ek baje khānā khātā hūṃ.","lit":"je · une · sonnée · repas · mangeant · suis"},{"fr":"La boutique ouvre à neuf heures.","tgt":"दुकान नौ बजे खुलती है।","ro":"Dukān nau baje khultī hai.","lit":"boutique · neuf · sonnés · ouvrant · est"},{"fr":"Il est presque midi.","tgt":"लगभग बारह बजे हैं।","ro":"Lagbhag bārah baje haiṃ.","lit":"presque · douze · sonnés · sont"},{"fr":"Je rentre à sept heures du soir.","tgt":"मैं शाम सात बजे घर आता हूँ।","ro":"Maiṃ shām sāt baje ghar ātā hūṃ.","lit":"je · soir · sept · sonnés · maison · venant · suis"},{"fr":"À six heures, à Connaught Place.","tgt":"छह बजे, कनॉट प्लेस में।","ro":"Chhah baje, Kanoṭ Ples meṃ.","lit":"six · sonnés · Connaught Place · [dans]"}],"tip":{"title":"L'heure : « baje »","example":"Il est deux heures. — दो <b>बजे</b> हैं।","body":"Pour donner l'heure, le hindi utilise le mot « baje », qui vient d'un verbe signifiant sonner, comme une cloche. « Do baje haiṃ » veut dire il est deux heures, mot à mot « deux, sonnés, sont », c'est-à-dire deux coups ont sonné. Pour une heure seulement, on passe au singulier : « Ek bajā hai ». Pour demander l'heure, on remplace le nombre par « kitne », combien : « Kitne baje haiṃ ? ». Pour dire à quelle heure se passe quelque chose, on garde simplement « baje » sans verbe être : « Dukān nau baje khultī hai », la boutique ouvre à neuf heures. Pour la demie, on ajoute « sāṛhe » devant : « sāṛhe chār baje », quatre heures et demie. En Inde, on compte sur douze heures et l'on précise « subah », le matin, ou « shām », le soir. Astuce : imaginez une horloge qui sonne, et dites « baje » à chaque coup.","exampleRo":"Do baje haiṃ.","lit":"deux · sonnés · sont","say":{"baje":"बजे","Do baje haiṃ":"दो बजे हैं","Ek bajā hai":"एक बजा है","kitne":"कितने","Kitne baje haiṃ ?":"कितने बजे हैं?","Dukān nau baje khultī hai":"दुकान नौ बजे खुलती है","sāṛhe":"साढ़े","sāṛhe chār baje":"साढ़े चार बजे","subah":"सुबह","shām":"शाम"}}},{"title":"Acheter un kurta","phrases":[{"fr":"Je voudrais un kurta.","tgt":"मुझे एक कुर्ता चाहिए।","ro":"Mujhe ek kurtā chāhie.","lit":"à moi · un · kurta · nécessaire"},{"fr":"Il me faut une taille plus grande.","tgt":"मुझे बड़ा साइज़ चाहिए।","ro":"Mujhe baṛā sāiz chāhie.","lit":"à moi · grande · taille · nécessaire"},{"fr":"Je cherche un kurta en coton.","tgt":"मुझे सूती कुर्ता चाहिए।","ro":"Mujhe sūtī kurtā chāhie.","lit":"à moi · en coton · kurta · nécessaire"},{"fr":"Avez-vous besoin d'un sac ?","tgt":"क्या आपको थैला चाहिए?","ro":"Kyā āpko thailā chāhie?","lit":"[question] · vous · [à] · sac · nécessaire ?"},{"fr":"Non, je n'ai pas besoin de sac.","tgt":"नहीं, मुझे थैला नहीं चाहिए।","ro":"Nahīṃ, mujhe thailā nahīṃ chāhie.","lit":"non · à moi · sac · pas · nécessaire"},{"fr":"Il me faut aussi un pantalon blanc.","tgt":"मुझे सफ़ेद पजामा भी चाहिए।","ro":"Mujhe safed pajāmā bhī chāhie.","lit":"à moi · blanc · pantalon · aussi · nécessaire"},{"fr":"Ma femme voudrait un sari.","tgt":"मेरी पत्नी को साड़ी चाहिए।","ro":"Merī patnī ko sāṛī chāhie.","lit":"ma · femme · [à] · sari · nécessaire"},{"fr":"Je voudrais une autre couleur.","tgt":"मुझे दूसरा रंग चाहिए।","ro":"Mujhe dūsrā rang chāhie.","lit":"à moi · autre · couleur · nécessaire"},{"fr":"Combien de kurtas vous faut-il ?","tgt":"आपको कितने कुर्ते चाहिए?","ro":"Āpko kitne kurte chāhie?","lit":"vous · [à] · combien · kurtas · nécessaire ?"},{"fr":"Il m'en faut deux.","tgt":"मुझे दो चाहिए।","ro":"Mujhe do chāhie.","lit":"à moi · deux · nécessaire"}],"tip":{"title":"« Chāhie » : il me faut, je voudrais","example":"Je voudrais un kurta. — मुझे एक कुर्ता <b>चाहिए</b>।","body":"Pour demander quelque chose dans une boutique, le mot magique est « chāhie », qui veut dire nécessaire, souhaité. La construction ressemble à notre « il me faut » : on ne dit pas je veux, mais à moi, cela est nécessaire. « Mujhe ek kurtā chāhie » se décompose en « à moi, un, kurta, nécessaire », c'est-à-dire je voudrais un kurta. « Mujhe » veut dire à moi, et pour vous on dit « āpko » : « Kyā āpko thailā chāhie ? », avez-vous besoin d'un sac ? Pour une autre personne, on ajoute « ko » après son nom : « Merī patnī ko sāṛī chāhie », ma femme voudrait un sari. Bonne nouvelle, « chāhie » ne change jamais de forme. Pour refuser, on glisse « nahīṃ » devant : « Mujhe thailā nahīṃ chāhie ». Astuce : retenez la petite chanson « mujhe... chāhie », et remplissez le milieu avec tout ce dont vous avez besoin à Delhi.","exampleRo":"Mujhe ek kurtā chāhie.","lit":"à moi · un · kurta · nécessaire","say":{"Chāhie":"चाहिए","chāhie":"चाहिए","Mujhe ek kurtā chāhie":"मुझे एक कुर्ता चाहिए","Mujhe":"मुझे","āpko":"आपको","Kyā āpko thailā chāhie ?":"क्या आपको थैला चाहिए?","ko":"को","Merī patnī ko sāṛī chāhie":"मेरी पत्नी को साड़ी चाहिए","nahīṃ":"नहीं","Mujhe thailā nahīṃ chāhie":"मुझे थैला नहीं चाहिए"}}},{"title":"Une sortie à Connaught Place","phrases":[{"fr":"Allons-y !","tgt":"चलिए!","ro":"Chalie!","lit":"allons"},{"fr":"Allez, on va à Connaught Place.","tgt":"चलो, कनॉट प्लेस चलते हैं।","ro":"Chalo, Kanoṭ Ples chalte haiṃ.","lit":"allons · Connaught Place · allant · sommes"},{"fr":"Viens, on boit un chai.","tgt":"चलो, चाय पीते हैं।","ro":"Chalo, chāy pīte haiṃ.","lit":"allons · chai · buvant · sommes"},{"fr":"Venez, allons-y ensemble.","tgt":"चलिए, साथ चलते हैं।","ro":"Chalie, sāth chalte haiṃ.","lit":"allons · ensemble · allant · sommes"},{"fr":"On prend un rickshaw ?","tgt":"रिक्शा लेते हैं?","ro":"Rikshā lete haiṃ?","lit":"rickshaw · prenant · sommes ?"},{"fr":"Non, allons-y à pied.","tgt":"नहीं, पैदल चलते हैं।","ro":"Nahīṃ, paidal chalte haiṃ.","lit":"non · à pied · allant · sommes"},{"fr":"Allez, on mange des samosas !","tgt":"चलो, समोसे खाते हैं!","ro":"Chalo, samose khāte haiṃ!","lit":"allons · samosas · mangeant · sommes"},{"fr":"Allez, ce soir on regarde un film.","tgt":"चलो, आज शाम फ़िल्म देखते हैं।","ro":"Chalo, āj shām film dekhte haiṃ.","lit":"allons · aujourd'hui · soir · film · regardant · sommes"},{"fr":"Super idée !","tgt":"बहुत बढ़िया!","ro":"Bahut baṛhiyā!","lit":"très · excellent"},{"fr":"Venez, c'est par ici.","tgt":"आइए, इधर चलिए।","ro":"Āie, idhar chalie.","lit":"venez · par ici · allez"}],"tip":{"title":"« Chalie » et « chalo » : allons-y, proposer","example":"Allez, on va à Connaught Place. — <b>चलो</b>, कनॉट प्लेस चलते हैं।","body":"Le verbe « chalnā » veut dire marcher, avancer, et il sert à proposer de faire quelque chose ensemble. « Chalo » est la forme familière, qu'on lance entre amis, et « chalie » est la forme polie, pour quelqu'un que l'on vouvoie. Tout seul, il veut dire allons-y : « Chalie ! ». Suivi d'une phrase au présent avec « nous », il devient une proposition, comme notre « allez, on... ». « Chalo, Kanoṭ Ples chalte haiṃ » se décompose en « allons, Connaught Place, allant, sommes », c'est-à-dire allez, on va à Connaught Place. On peut proposer n'importe quoi de la même façon : « Chalo, chāy pīte haiṃ », viens, on boit un chai, ou « Chalo, samose khāte haiṃ ». Vous entendrez aussi « chalo » pour dire bon, d'accord, à la fin d'une discussion. Astuce : « chalo » claque comme un geste de la main qui invite à avancer, « chalie » est le même geste, fait avec un sourire poli.","exampleRo":"Chalo, Kanoṭ Ples chalte haiṃ.","lit":"allons · Connaught Place · allant · sommes","say":{"Chalie":"चलिए","chalo":"चलो","chalnā":"चलना","Chalo":"चलो","chalie":"चलिए","Chalie !":"चलिए!","Chalo, Kanoṭ Ples chalte haiṃ":"चलो, कनॉट प्लेस चलते हैं","Chalo, chāy pīte haiṃ":"चलो, चाय पीते हैं","Chalo, samose khāte haiṃ":"चलो, समोसे खाते हैं"}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Namaste à tous !","tgt":"सबको नमस्ते!","ro":"Sabko namaste!","lit":"tous · [à] · namaste"},{"fr":"Merci beaucoup pour tout.","tgt":"हर चीज़ के लिए बहुत धन्यवाद।","ro":"Har chīz ke lie bahut dhanyavād.","lit":"chaque · chose · [pour] · beaucoup · merci"},{"fr":"Merci, mon ami !","tgt":"शुक्रिया, दोस्त!","ro":"Shukriyā, dost!","lit":"merci · ami"},{"fr":"Excusez-moi, une minute.","tgt":"माफ़ कीजिए, एक मिनट।","ro":"Māf kījie, ek minaṭ.","lit":"pardon · faites · une · minute"},{"fr":"Le hindi est une très belle langue.","tgt":"हिंदी बहुत सुंदर भाषा है।","ro":"Hindī bahut sundar bhāshā hai.","lit":"hindi · très · belle · langue · est"},{"fr":"Maintenant, je parle un peu mieux le hindi.","tgt":"अब मैं थोड़ी बेहतर हिंदी बोलता हूँ।","ro":"Ab maiṃ thoṛī behtar hindī boltā hūṃ.","lit":"maintenant · je · un peu · meilleur · hindi · parlant · suis"},{"fr":"La première partie est terminée.","tgt":"पहला हिस्सा पूरा हुआ।","ro":"Pahlā hissā pūrā huā.","lit":"première · partie · complète · devenue"},{"fr":"Je parle hindi tous les jours.","tgt":"मैं हर दिन हिंदी बोलता हूँ।","ro":"Maiṃ har din hindī boltā hūṃ.","lit":"je · chaque · jour · hindi · parlant · suis"},{"fr":"Pardon, encore une fois, s'il vous plaît.","tgt":"माफ़ कीजिए, एक बार फिर से।","ro":"Māf kījie, ek bār phir se.","lit":"pardon · faites · une · fois · encore · [depuis]"},{"fr":"Merci et à bientôt !","tgt":"धन्यवाद, फिर मिलेंगे!","ro":"Dhanyavād, phir milenge!","lit":"merci · encore · nous verrons"}],"tip":{"title":"Les formules magiques : « namaste, dhanyavād, shukriyā, māf kījie »","example":"Excusez-moi, une minute. — <b>माफ़</b> <b>कीजिए</b>, एक मिनट।","body":"Pour terminer ce module, voici les formules qui ouvrent toutes les portes à Delhi. « Namaste » sert à la fois de bonjour et d'au revoir, à toute heure, souvent accompagné des mains jointes devant la poitrine. Pour remercier, vous avez le choix entre « dhanyavād », un peu plus soutenu, et « shukriyā », plus courant dans la rue et entre amis. Pour vous excuser ou attirer l'attention de quelqu'un, dites « māf kījie », mot à mot « pardon, faites », c'est-à-dire faites-moi grâce, ou plus simplement excusez-moi. « Māf kījie, ek minaṭ » veut dire excusez-moi, une minute. Retenez aussi « phir milenge », on se reverra, pour quitter quelqu'un chaleureusement. Prononcez « dhanyavād » avec un petit souffle sur le « dh », et appuyez sur le « ā » de « shukriyā ». Astuce : utilisez ces quatre formules le plus souvent possible, ce sont elles qui feront sourire vos interlocuteurs dès le premier jour.","exampleRo":"Māf kījie, ek minaṭ.","lit":"pardon · faites · une · minute","say":{"Namaste":"नमस्ते","dhanyavād":"धन्यवाद","shukriyā":"शुक्रिया","māf kījie":"माफ़ कीजिए","Māf kījie, ek minaṭ":"माफ़ कीजिए, एक मिनट","phir milenge":"फिर मिलेंगे","namaste, dhanyavād, shukriyā, māf kījie":"नमस्ते, धन्यवाद, शुक्रिया, माफ़ कीजिए"}}}]},{"id":2,"name":"En voyage","desc":"Se déplacer, découvrir et gérer les imprévus en Inde.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à la gare de Delhi","phrases":[{"fr":"La gare est très grande.","tgt":"स्टेशन बहुत बड़ा है।","ro":"Sṭeshan bahut baṛā hai.","lit":"gare · très · grand · est"},{"fr":"Où est le quai numéro cinq ?","tgt":"प्लेटफ़ार्म नंबर पाँच कहाँ है?","ro":"Pleṭfārm nambar pāṃch kahāṃ hai?","lit":"quai · numéro · cinq · où · est ?"},{"fr":"Mon train est en retard.","tgt":"मेरी ट्रेन लेट है।","ro":"Merī ṭren leṭ hai.","lit":"mon · train · en retard · est"},{"fr":"J'ai un gros sac.","tgt":"मेरे पास एक बड़ा थैला है।","ro":"Mere pās ek baṛā thailā hai.","lit":"moi · [chez] · un · gros · sac · est"},{"fr":"Le taxi attend dehors.","tgt":"टैक्सी बाहर खड़ी है।","ro":"Ṭaiksī bāhar khaṛī hai.","lit":"taxi · dehors · debout · est"},{"fr":"Je dois aller à l'hôtel.","tgt":"मुझे होटल जाना है।","ro":"Mujhe hoṭal jānā hai.","lit":"à moi · hôtel · aller · est"},{"fr":"Les toilettes sont là-bas.","tgt":"बाथरूम वहाँ है।","ro":"Bāthrūm vahāṃ hai.","lit":"toilettes · là-bas · est"},{"fr":"Avez-vous de l'eau ?","tgt":"क्या आपके पास पानी है?","ro":"Kyā āpke pās pānī hai?","lit":"[question] · vous · [chez] · eau · est ?"},{"fr":"Il fait très chaud ici.","tgt":"यहाँ बहुत गर्मी है।","ro":"Yahāṃ bahut garmī hai.","lit":"ici · très · chaleur · est"},{"fr":"Bienvenue en Inde !","tgt":"भारत में आपका स्वागत है!","ro":"Bhārat meṃ āpkā svāgat hai!","lit":"Inde · [dans] · votre · accueil · est !"}]},{"title":"Organiser le séjour à Agra","phrases":[{"fr":"Aujourd'hui, je suis à Delhi.","tgt":"आज मैं दिल्ली में हूँ।","ro":"Āj maiṃ Dillī meṃ hūṃ.","lit":"aujourd'hui · je · Delhi · [dans] · suis"},{"fr":"Demain, je pars pour Agra.","tgt":"कल मैं आगरा जा रहा हूँ।","ro":"Kal maiṃ Āgrā jā rahā hūṃ.","lit":"demain · je · Agra · aller · [en cours] · suis"},{"fr":"Hier, j'étais très fatigué.","tgt":"कल मैं बहुत थका हुआ था।","ro":"Kal maiṃ bahut thakā huā thā.","lit":"hier · je · très · fatigué · devenu · étais"},{"fr":"Après-demain, nous sommes à Jaipur.","tgt":"परसों हम जयपुर में हैं।","ro":"Parsoṃ ham Jaypur meṃ haiṃ.","lit":"après-demain · nous · Jaipur · [dans] · sommes"},{"fr":"Le Taj Mahal est fermé aujourd'hui ?","tgt":"क्या आज ताजमहल बंद है?","ro":"Kyā āj Tājmahal band hai?","lit":"[question] · aujourd'hui · Taj Mahal · fermé · est ?"},{"fr":"Non, il est fermé le vendredi.","tgt":"नहीं, शुक्रवार को बंद है।","ro":"Nahīṃ, shukravār ko band hai.","lit":"non · vendredi · [à] · fermé · est"},{"fr":"Hier, c'était dimanche.","tgt":"कल रविवार था।","ro":"Kal ravivār thā.","lit":"hier · dimanche · était"},{"fr":"Et demain, c'est lundi.","tgt":"और कल सोमवार है।","ro":"Aur kal somvār hai.","lit":"et · demain · lundi · est"},{"fr":"Aujourd'hui, le temps est agréable.","tgt":"आज मौसम अच्छा है।","ro":"Āj mausam achchhā hai.","lit":"aujourd'hui · temps · bon · est"},{"fr":"Mon train est après-demain.","tgt":"मेरी ट्रेन परसों है।","ro":"Merī ṭren parsoṃ hai.","lit":"mon · train · après-demain · est"}],"tip":{"title":"« Āj, kal, parsoṃ » : « kal » veut dire hier ET demain","example":"Hier, c'était dimanche. — <b>कल</b> रविवार था।","body":"En hindi, le mot « kal » est une petite surprise pour un francophone : il veut dire à la fois hier et demain. En fait, « kal » signifie simplement « à un jour d'aujourd'hui », dans un sens ou dans l'autre. C'est le verbe qui vous dit de quel côté on se trouve. « Kal ravivār thā » se décompose en « kal », hier, « ravivār », dimanche, et « thā », était : le verbe au passé montre qu'on parle d'hier. À l'inverse, « kal somvār hai », avec « hai », est, veut dire demain c'est lundi. Même logique pour « parsoṃ », à deux jours d'aujourd'hui : après-demain, ou avant-hier. Et pour aujourd'hui, on dit « āj », comme dans « āj mausam achchhā hai », aujourd'hui il fait beau. Pour retenir, imaginez « āj » au centre, « kal » à un pas de chaque côté, et « parsoṃ » à deux pas.","exampleRo":"Kal ravivār thā.","lit":"hier · dimanche · était","say":{"Āj, kal, parsoṃ":"आज, कल, परसों","kal":"कल","Kal ravivār thā":"कल रविवार था","ravivār":"रविवार","thā":"था","kal somvār hai":"कल सोमवार है","hai":"है","parsoṃ":"परसों","āj":"आज","āj mausam achchhā hai":"आज मौसम अच्छा है"}}},{"title":"Le Taj Mahal","phrases":[{"fr":"Le Taj Mahal est vraiment beau.","tgt":"ताजमहल बहुत सुंदर है।","ro":"Tājmahal bahut sundar hai.","lit":"Taj Mahal · très · beau · est"},{"fr":"Il est en marbre blanc.","tgt":"यह सफ़ेद संगमरमर का है।","ro":"Yah safed sangmarmar kā hai.","lit":"ceci · blanc · marbre · [de] · est"},{"fr":"Où est la porte principale ?","tgt":"मुख्य द्वार कहाँ है?","ro":"Mukhya dvār kahāṃ hai?","lit":"principale · porte · où · est ?"},{"fr":"Il y a énormément de monde.","tgt":"बहुत भीड़ है।","ro":"Bahut bhīṛ hai.","lit":"beaucoup · foule · est"},{"fr":"Le matin, il y a moins de monde.","tgt":"सुबह कम भीड़ होती है।","ro":"Subah kam bhīṛ hotī hai.","lit":"matin · moins · foule · devenir · est"},{"fr":"Le jardin est immense.","tgt":"बगीचा बहुत बड़ा है।","ro":"Bagīchā bahut baṛā hai.","lit":"jardin · très · grand · est"},{"fr":"Allez, prenons une photo ici.","tgt":"चलो, यहाँ फ़ोटो लेते हैं।","ro":"Chalo, yahāṃ foṭo lete haiṃ.","lit":"allons · ici · photo · prendre · sommes"},{"fr":"Le fleuve est derrière le monument.","tgt":"नदी स्मारक के पीछे है।","ro":"Nadī smārak ke pīchhe hai.","lit":"fleuve · monument · [de] · derrière · est"},{"fr":"C'est mon premier voyage en Inde.","tgt":"यह मेरी पहली भारत यात्रा है।","ro":"Yah merī pahlī Bhārat yātrā hai.","lit":"ceci · mon · premier · Inde · voyage · est"},{"fr":"Le soir, la vue est superbe.","tgt":"शाम का नज़ारा बहुत सुंदर है।","ro":"Shām kā nazārā bahut sundar hai.","lit":"soir · [de] · vue · très · beau · est"}]},{"title":"À l'hôtel","phrases":[{"fr":"J'ai une réservation chez vous.","tgt":"यहाँ मेरी बुकिंग है।","ro":"Yahāṃ merī buking hai.","lit":"ici · ma · réservation · est"},{"fr":"Dites-moi votre nom, s'il vous plaît.","tgt":"कृपया अपना नाम बताइए।","ro":"Kṛpayā apnā nām batāie.","lit":"s'il vous plaît · votre · nom · dites"},{"fr":"Il me faut une chambre pour deux nuits.","tgt":"दो रातों के लिए एक कमरा चाहिए।","ro":"Do rātoṃ ke lie ek kamrā chāhie.","lit":"deux · nuits · [pour] · une · chambre · faut"},{"fr":"Attendez un instant, s'il vous plaît.","tgt":"ज़रा रुकिए।","ro":"Zarā rukie.","lit":"un peu · attendez"},{"fr":"Voici votre clé.","tgt":"यह आपकी चाबी है।","ro":"Yah āpkī chābī hai.","lit":"ceci · votre · clé · est"},{"fr":"La chambre est au deuxième étage.","tgt":"कमरा दूसरी मंज़िल पर है।","ro":"Kamrā dūsrī manzil par hai.","lit":"chambre · deuxième · étage · [sur] · est"},{"fr":"Montrez-moi la chambre, s'il vous plaît.","tgt":"ज़रा कमरा दिखाइए।","ro":"Zarā kamrā dikhāie.","lit":"un peu · chambre · montrez"},{"fr":"Fermez la fenêtre, s'il vous plaît.","tgt":"कृपया खिड़की बंद कीजिए।","ro":"Kṛpayā khiṛkī band kījie.","lit":"s'il vous plaît · fenêtre · fermé · faites"},{"fr":"Le petit-déjeuner est à quelle heure ?","tgt":"नाश्ता कितने बजे है?","ro":"Nāshtā kitne baje hai?","lit":"petit-déjeuner · combien · heures · est ?"},{"fr":"Un peu d'eau chaude, s'il vous plaît.","tgt":"ज़रा गरम पानी दीजिए।","ro":"Zarā garam pānī dījie.","lit":"un peu · chaude · eau · donnez"}],"tip":{"title":"« Kṛpayā » et « zarā » : s'il vous plaît","example":"Attendez un instant, s'il vous plaît. — <b>ज़रा</b> रुकिए।","body":"Pour demander poliment, le hindi a deux petits mots très utiles. « Kṛpayā » correspond à s'il vous plaît, mais il sonne un peu soutenu : on l'entend surtout dans les annonces, à l'hôtel ou au guichet. Au quotidien, on préfère souvent « zarā », qui veut dire un peu, et qui adoucit la demande, comme notre « vous pourriez juste ». « Zarā rukie » se décompose en « zarā », un peu, et « rukie », attendez : mot à mot, attendez un peu. Le vrai secret de la politesse se cache dans la fin du verbe, en « -ie » ou « -ijie », la forme de respect qui va avec « āp », vous. Ainsi « dījie » veut dire donnez, et « kījie » veut dire faites. Essayez « zarā pānī dījie », un peu d'eau s'il vous plaît, ou « kṛpayā baiṭhie », asseyez-vous je vous en prie. Pour retenir : « zarā » pour adoucir, la fin en « -ie » pour respecter.","exampleRo":"Zarā rukie.","lit":"un peu · attendez","say":{"Kṛpayā":"कृपया","zarā":"ज़रा","Zarā rukie":"ज़रा रुकिए","rukie":"रुकिए","āp":"आप","dījie":"दीजिए","kījie":"कीजिए","zarā pānī dījie":"ज़रा पानी दीजिए","kṛpayā baiṭhie":"कृपया बैठिए","-ie":"इए"}}},{"title":"Acheter un billet de train","phrases":[{"fr":"Où se trouve le guichet des billets ?","tgt":"टिकट खिड़की कहाँ है?","ro":"Ṭikaṭ khiṛkī kahāṃ hai?","lit":"billet · guichet · où · est ?"},{"fr":"Il me faut un billet pour Jaipur.","tgt":"जयपुर का एक टिकट चाहिए।","ro":"Jaypur kā ek ṭikaṭ chāhie.","lit":"Jaipur · [de] · un · billet · faut"},{"fr":"Le train part à quelle heure ?","tgt":"ट्रेन कितने बजे चलती है?","ro":"Ṭren kitne baje chaltī hai?","lit":"train · combien · heures · partir · est ?"},{"fr":"À six heures du matin.","tgt":"सुबह छह बजे।","ro":"Subah chhah baje.","lit":"matin · six · heures"},{"fr":"Il me faut une couchette.","tgt":"मुझे एक बर्थ चाहिए।","ro":"Mujhe ek barth chāhie.","lit":"à moi · une · couchette · faut"},{"fr":"Je préfère la place côté fenêtre.","tgt":"मुझे खिड़की वाली सीट पसंद है।","ro":"Mujhe khiṛkī vālī sīṭ pasand hai.","lit":"à moi · fenêtre · [côté] · place · plaisir · est"},{"fr":"Il n'y a plus de place dans le train.","tgt":"ट्रेन में जगह नहीं है।","ro":"Ṭren meṃ jagah nahīṃ hai.","lit":"train · [dans] · place · pas · est"},{"fr":"Tenez, c'est mon passeport.","tgt":"यह मेरा पासपोर्ट है।","ro":"Yah merā pāsporṭ hai.","lit":"ceci · mon · passeport · est"},{"fr":"C'est un train rapide ?","tgt":"क्या यह तेज़ ट्रेन है?","ro":"Kyā yah tez ṭren hai?","lit":"[question] · ceci · rapide · train · est ?"},{"fr":"Le voyage dure cinq heures.","tgt":"सफ़र पाँच घंटे का है।","ro":"Safar pāṃch ghanṭe kā hai.","lit":"voyage · cinq · heures · [de] · est"}]},{"title":"Au bazar de Jaipur","phrases":[{"fr":"Ça coûte combien ?","tgt":"यह कितने का है?","ro":"Yah kitne kā hai?","lit":"ceci · combien · [de] · est ?"},{"fr":"Cent roupies.","tgt":"सौ रुपये।","ro":"Sau rupaye.","lit":"cent · roupies"},{"fr":"Oh, c'est vraiment cher !","tgt":"यह बहुत महँगा है!","ro":"Yah bahut mahaṃgā hai!","lit":"ceci · très · cher · est !"},{"fr":"Combien coûte ce foulard ?","tgt":"यह दुपट्टा कितने का है?","ro":"Yah dupaṭṭā kitne kā hai?","lit":"ce · foulard · combien · [de] · est ?"},{"fr":"Deux cents roupies, monsieur.","tgt":"दो सौ रुपये, साहब।","ro":"Do sau rupaye, sāhab.","lit":"deux · cents · roupies · monsieur"},{"fr":"Faites-moi un petit prix.","tgt":"थोड़ा कम कीजिए।","ro":"Thoṛā kam kījie.","lit":"un peu · moins · faites"},{"fr":"Cent cinquante, d'accord ?","tgt":"डेढ़ सौ ठीक है?","ro":"Ḍeṛh sau ṭhīk hai?","lit":"un et demi · cent · bien · est ?"},{"fr":"Ces bracelets coûtent combien ?","tgt":"ये चूड़ियाँ कितने की हैं?","ro":"Ye chūṛiyāṃ kitne kī haiṃ?","lit":"ces · bracelets · combien · [de] · sont ?"},{"fr":"Les deux pour trois cents roupies.","tgt":"दोनों तीन सौ रुपये में।","ro":"Donoṃ tīn sau rupaye meṃ.","lit":"les deux · trois · cents · roupies · [dans]"},{"fr":"Bon, d'accord, je les prends.","tgt":"ठीक है, मैं लेता हूँ।","ro":"Ṭhīk hai, maiṃ letā hūṃ.","lit":"bien · est · je · prendre · suis"}],"tip":{"title":"« Kitne kā hai ? » : demander un prix, les roupies","example":"Ça coûte combien ? — यह <b>कितने का</b> है?","body":"Pour demander un prix, la formule magique est « kitne kā hai ? ». On la décompose ainsi : « kitne », combien, « kā », de, et « hai », est : mot à mot, de combien est-ce ? Placez simplement l'objet devant : « yah dupaṭṭā kitne kā hai ? », combien coûte ce foulard ? Pour plusieurs objets féminins, comme des bracelets, « kā hai » devient « kī haiṃ » : « ye chūṛiyāṃ kitne kī haiṃ ? ». La monnaie, c'est la roupie, « rupayā » pour une seule et « rupaye » pour plusieurs. Retenez aussi « sau », cent, et l'adorable « ḍeṛh sau », un et demi cent, c'est-à-dire cent cinquante. Au marché, marchander est tout à fait normal : dites en souriant « thoṛā kam kījie », faites un peu moins. Astuce : la question tient en trois syllabes rapides, « kit-ne-kā », répétez-la comme un refrain.","exampleRo":"Yah kitne kā hai?","lit":"ceci · combien · [de] · est ?","say":{"Kitne kā hai ?":"कितने का है?","kitne kā hai ?":"कितने का है?","kitne":"कितने","kā":"का","hai":"है","yah dupaṭṭā kitne kā hai ?":"यह दुपट्टा कितने का है?","kā hai":"का है","kī haiṃ":"की हैं","ye chūṛiyāṃ kitne kī haiṃ ?":"ये चूड़ियाँ कितने की हैं?","rupayā":"रुपया","rupaye":"रुपये","sau":"सौ","ḍeṛh sau":"डेढ़ सौ","thoṛā kam kījie":"थोड़ा कम कीजिए"}}},{"title":"Le palais des vents","phrases":[{"fr":"Voici le palais des vents.","tgt":"यह हवा महल है।","ro":"Yah Havā Mahal hai.","lit":"ceci · vent · palais · est"},{"fr":"Le palais est rose.","tgt":"महल गुलाबी है।","ro":"Mahal gulābī hai.","lit":"palais · rose · est"},{"fr":"Il y a énormément de fenêtres.","tgt":"इसमें बहुत सारी खिड़कियाँ हैं।","ro":"Ismeṃ bahut sārī khiṛkiyāṃ haiṃ.","lit":"ceci-[dans] · très · nombreuses · fenêtres · sont"},{"fr":"Jaipur est la ville rose.","tgt":"जयपुर गुलाबी शहर है।","ro":"Jaypur gulābī shahar hai.","lit":"Jaipur · rose · ville · est"},{"fr":"Ici, le vent est frais.","tgt":"यहाँ हवा ठंडी है।","ro":"Yahāṃ havā ṭhanḍī hai.","lit":"ici · vent · frais · est"},{"fr":"Le marché est juste en face.","tgt":"बाज़ार ठीक सामने है।","ro":"Bāzār ṭhīk sāmne hai.","lit":"marché · juste · en face · est"},{"fr":"On monte tout en haut ?","tgt":"क्या ऊपर चलें?","ro":"Kyā ūpar chaleṃ?","lit":"[question] · en haut · allions ?"},{"fr":"La vue est magnifique.","tgt":"नज़ारा शानदार है।","ro":"Nazārā shāndār hai.","lit":"vue · magnifique · est"},{"fr":"Le palais est vieux ?","tgt":"क्या महल पुराना है?","ro":"Kyā mahal purānā hai?","lit":"[question] · palais · vieux · est ?"},{"fr":"Oui, il est très ancien.","tgt":"हाँ, यह बहुत पुराना है।","ro":"Hāṃ, yah bahut purānā hai.","lit":"oui · ceci · très · vieux · est"}]},{"title":"De Jaipur à Jodhpur","phrases":[{"fr":"Je dois aller de Jaipur à Jodhpur.","tgt":"मुझे जयपुर से जोधपुर जाना है।","ro":"Mujhe Jaypur se Jodhpur jānā hai.","lit":"à moi · Jaipur · [depuis] · Jodhpur · aller · est"},{"fr":"Le bus va de la gare jusqu'au fort.","tgt":"बस स्टेशन से किले तक जाती है।","ro":"Bas sṭeshan se kile tak jātī hai.","lit":"bus · gare · [depuis] · fort · [jusqu'à] · aller · est"},{"fr":"De Jaipur à Jodhpur, il faut six heures.","tgt":"जयपुर से जोधपुर तक छह घंटे लगते हैं।","ro":"Jaypur se Jodhpur tak chhah ghanṭe lagte haiṃ.","lit":"Jaipur · [depuis] · Jodhpur · [jusqu'à] · six · heures · prendre · sont"},{"fr":"La boutique est ouverte de neuf à six heures.","tgt":"दुकान नौ से छह बजे तक खुली है।","ro":"Dukān nau se chhah baje tak khulī hai.","lit":"boutique · neuf · [depuis] · six · heures · [jusqu'à] · ouverte · est"},{"fr":"Du lundi au vendredi.","tgt":"सोमवार से शुक्रवार तक।","ro":"Somvār se shukravār tak.","lit":"lundi · [depuis] · vendredi · [jusqu'à]"},{"fr":"On trouve du thé dans le train ?","tgt":"क्या ट्रेन में चाय मिलती है?","ro":"Kyā ṭren meṃ chāy miltī hai?","lit":"[question] · train · [dans] · thé · se trouver · est ?"},{"fr":"Le désert commence à partir d'ici.","tgt":"यहाँ से रेगिस्तान शुरू होता है।","ro":"Yahāṃ se registān shurū hotā hai.","lit":"ici · [depuis] · désert · début · devenir · est"},{"fr":"Par la fenêtre, on voit des chameaux.","tgt":"खिड़की से ऊँट दिखते हैं।","ro":"Khiṛkī se ūṃṭ dikhte haiṃ.","lit":"fenêtre · [depuis] · chameaux · se voir · sont"},{"fr":"Jusqu'à quand restez-vous à Jodhpur ?","tgt":"आप जोधपुर में कब तक हैं?","ro":"Āp Jodhpur meṃ kab tak haiṃ?","lit":"vous · Jodhpur · [dans] · quand · [jusqu'à] · êtes ?"},{"fr":"Jusqu'à dimanche soir.","tgt":"रविवार शाम तक।","ro":"Ravivār shām tak.","lit":"dimanche · soir · [jusqu'à]"}],"tip":{"title":"« Se... tak » : de... à...","example":"Du lundi au vendredi. — सोमवार <b>से</b> शुक्रवार <b>तक</b>।","body":"Pour dire de... à..., le hindi utilise deux petits mots placés après les noms, comme des étiquettes. « Se » veut dire de ou depuis, et « tak » veut dire jusqu'à. Contrairement au français, ils viennent après le mot : on dit « Jaypur se », Jaipur depuis, et « Jodhpur tak », Jodhpur jusqu'à. Ainsi « somvār se shukravār tak » se lit mot à mot lundi depuis, vendredi jusqu'à, c'est-à-dire du lundi au vendredi. Cela marche aussi pour les heures : « nau se chhah baje tak », de neuf à six heures. Et pour demander jusqu'à quand, on dit simplement « kab tak ? ». Astuce pour retenir : « se » marque la ligne de départ, « tak » la ligne d'arrivée, et les deux suivent toujours le nom.","exampleRo":"Somvār se shukravār tak.","lit":"lundi · [depuis] · vendredi · [jusqu'à]","say":{"Se":"से","tak":"तक","Jaypur se":"जयपुर से","Jodhpur tak":"जोधपुर तक","somvār se shukravār tak":"सोमवार से शुक्रवार तक","nau se chhah baje tak":"नौ से छह बजे तक","kab tak ?":"कब तक?","se":"से"}}},{"title":"Jodhpur, la ville bleue","phrases":[{"fr":"Jodhpur est la ville bleue.","tgt":"जोधपुर नीला शहर है।","ro":"Jodhpur nīlā shahar hai.","lit":"Jodhpur · bleue · ville · est"},{"fr":"Ici, les maisons sont bleues.","tgt":"यहाँ घर नीले हैं।","ro":"Yahāṃ ghar nīle haiṃ.","lit":"ici · maisons · bleues · sont"},{"fr":"Le fort est sur la colline.","tgt":"किला पहाड़ी पर है।","ro":"Kilā pahāṛī par hai.","lit":"fort · colline · [sur] · est"},{"fr":"Les ruelles ici sont très étroites.","tgt":"गलियाँ बहुत तंग हैं।","ro":"Galiyāṃ bahut tang haiṃ.","lit":"ruelles · très · étroites · sont"},{"fr":"Le temps est chaud et sec.","tgt":"मौसम गरम और सूखा है।","ro":"Mausam garam aur sūkhā hai.","lit":"temps · chaud · et · sec · est"},{"fr":"Le restaurant est sur le toit.","tgt":"रेस्टोरेंट छत पर है।","ro":"Resṭorenṭ chhat par hai.","lit":"restaurant · toit · [sur] · est"},{"fr":"Un thé bien chaud, s'il vous plaît.","tgt":"एक गरम चाय दीजिए।","ro":"Ek garam chāy dījie.","lit":"un · chaud · thé · donnez"},{"fr":"D'en haut, la ville est très belle.","tgt":"ऊपर से शहर सुंदर दिखता है।","ro":"Ūpar se shahar sundar dikhtā hai.","lit":"haut · [depuis] · ville · belle · paraître · est"},{"fr":"Pourquoi les maisons sont-elles bleues ?","tgt":"घर नीले क्यों हैं?","ro":"Ghar nīle kyoṃ haiṃ?","lit":"maisons · bleues · pourquoi · sont ?"},{"fr":"Je n'en sais rien du tout.","tgt":"मुझे बिलकुल नहीं पता।","ro":"Mujhe bilkul nahīṃ patā.","lit":"à moi · du tout · pas · connu"}]},{"title":"Hier, au fort de Jodhpur","phrases":[{"fr":"Hier, je suis allé au fort.","tgt":"कल मैं किले गया।","ro":"Kal maiṃ kile gayā.","lit":"hier · je · fort · allé"},{"fr":"Ma femme est allée au marché.","tgt":"मेरी पत्नी बाज़ार गयी।","ro":"Merī patnī bāzār gayī.","lit":"ma · femme · marché · allée"},{"fr":"Nous sommes allés au lac.","tgt":"हम झील पर गये।","ro":"Ham jhīl par gaye.","lit":"nous · lac · [sur] · allés"},{"fr":"Où êtes-vous allé hier ?","tgt":"आप कल कहाँ गये?","ro":"Āp kal kahāṃ gaye?","lit":"vous · hier · où · allé ?"},{"fr":"Moi, je suis allée au palais.","tgt":"मैं महल गयी।","ro":"Maiṃ mahal gayī.","lit":"je · palais · allée"},{"fr":"Le train est parti à l'heure.","tgt":"ट्रेन समय पर चली।","ro":"Ṭren samay par chalī.","lit":"train · heure · [sur] · partie"},{"fr":"Mon ami est venu avec moi.","tgt":"मेरा दोस्त मेरे साथ आया।","ro":"Merā dost mere sāth āyā.","lit":"mon · ami · moi · [avec] · venu"},{"fr":"Il est arrivé tard à l'hôtel.","tgt":"वह देर से होटल पहुँचा।","ro":"Vah der se hoṭal pahuṃchā.","lit":"il · retard · [depuis] · hôtel · arrivé"},{"fr":"Elle est partie tôt ce matin.","tgt":"वह आज सुबह जल्दी गयी।","ro":"Vah āj subah jaldī gayī.","lit":"elle · aujourd'hui · matin · tôt · partie"},{"fr":"Nous sommes rentrés le soir.","tgt":"हम शाम को वापस आये।","ro":"Ham shām ko vāpas āye.","lit":"nous · soir · [à] · retour · venus"}],"tip":{"title":"Le passé : « gayā, gayī »","example":"Ma femme est allée au marché. — मेरी पत्नी बाज़ार <b>गयी</b>।","body":"Pour raconter où l'on est allé, le hindi utilise le passé du verbe aller : « gayā ». Bonne nouvelle, pas besoin d'auxiliaire : « kal maiṃ kile gayā » veut dire mot à mot hier je fort allé, donc hier je suis allé au fort. Comme notre participe allé ou allée, ce mot s'accorde avec la personne qui part. Un homme dit « maiṃ gayā », une femme dit « maiṃ gayī ». Au pluriel, et avec « āp », vous, on dit « gaye » : « ham jhīl par gaye », nous sommes allés au lac. La même logique vaut pour d'autres verbes de mouvement : « āyā », venu, « pahuṃchā », arrivé, ou « chalī », partie, pour le train qui est féminin en hindi. Astuce : « gayā » finit en « ā » comme beaucoup de mots masculins, et « gayī » en « ī » comme beaucoup de mots féminins.","exampleRo":"Merī patnī bāzār gayī.","lit":"ma · femme · marché · allée","say":{"gayā":"गया","kal maiṃ kile gayā":"कल मैं क़िले गया","maiṃ gayā":"मैं गया","maiṃ gayī":"मैं गयी","āp":"आप","gaye":"गये","ham jhīl par gaye":"हम झील पर गये","āyā":"आया","pahuṃchā":"पहुँचा","chalī":"चली","gayī":"गयी","gayā, gayī":"गया, गयी"}}},{"title":"Mes bagages","phrases":[{"fr":"Voici ma grosse valise.","tgt":"यह मेरा बड़ा सूटकेस है।","ro":"Yah merā baṛā sūṭkes hai.","lit":"ceci · ma · grosse · valise · est"},{"fr":"Elle est très lourde.","tgt":"यह बहुत भारी है।","ro":"Yah bahut bhārī hai.","lit":"ceci · très · lourd · est"},{"fr":"J'ai deux sacs.","tgt":"मेरे पास दो बैग हैं।","ro":"Mere pās do baig haiṃ.","lit":"moi · [chez] · deux · sacs · sont"},{"fr":"Où est mon sac noir ?","tgt":"मेरा काला बैग कहाँ है?","ro":"Merā kālā baig kahāṃ hai?","lit":"mon · noir · sac · où · est ?"},{"fr":"Il est sous le siège.","tgt":"वह सीट के नीचे है।","ro":"Vah sīṭ ke nīche hai.","lit":"il · siège · [de] · dessous · est"},{"fr":"Le porteur soulève les bagages.","tgt":"कुली सामान उठाता है।","ro":"Kulī sāmān uṭhātā hai.","lit":"porteur · bagages · soulever · est"},{"fr":"C'est combien pour les bagages ?","tgt":"सामान के कितने पैसे?","ro":"Sāmān ke kitne paise?","lit":"bagages · [de] · combien · argent ?"},{"fr":"Doucement, c'est fragile.","tgt":"ध्यान से, यह नाज़ुक है।","ro":"Dhyān se, yah nāzuk hai.","lit":"attention · [avec] · ceci · fragile · est"},{"fr":"Mon sac est ouvert.","tgt":"मेरा बैग खुला है।","ro":"Merā baig khulā hai.","lit":"mon · sac · ouvert · est"},{"fr":"Tous les bagages sont là.","tgt":"सब सामान यहाँ है।","ro":"Sab sāmān yahāṃ hai.","lit":"tous · bagages · ici · est"}]},{"title":"Demander son chemin","phrases":[{"fr":"Comment aller à la gare ?","tgt":"स्टेशन कैसे जाएँ?","ro":"Sṭeshan kaise jāeṃ?","lit":"gare · comment · allions ?"},{"fr":"Continuez tout droit.","tgt":"सीधे जाइए।","ro":"Sīdhe jāie.","lit":"droit · allez"},{"fr":"Puis prenez à gauche.","tgt":"फिर बाएँ मुड़िए।","ro":"Phir bāeṃ muṛie.","lit":"ensuite · gauche · tournez"},{"fr":"Comment est l'hôtel ?","tgt":"होटल कैसा है?","ro":"Hoṭal kaisā hai?","lit":"hôtel · comment · est ?"},{"fr":"Il est propre et calme.","tgt":"साफ़ और शांत है।","ro":"Sāf aur shānt hai.","lit":"propre · et · calme · est"},{"fr":"Comment arriver jusqu'au fort ?","tgt":"किले तक कैसे पहुँचें?","ro":"Kile tak kaise pahuṃcheṃ?","lit":"fort · [jusqu'à] · comment · arrivions ?"},{"fr":"À droite, après le pont.","tgt":"पुल के बाद दाएँ।","ro":"Pul ke bād dāeṃ.","lit":"pont · [de] · après · droite"},{"fr":"Comment est le thé ici ?","tgt":"यहाँ चाय कैसी है?","ro":"Yahāṃ chāy kaisī hai?","lit":"ici · thé · comment · est ?"},{"fr":"Comment va-t-on au marché ?","tgt":"बाज़ार कैसे जाते हैं?","ro":"Bāzār kaise jāte haiṃ?","lit":"marché · comment · aller · sont ?"},{"fr":"Pardon, je me suis perdu.","tgt":"माफ़ कीजिए, मैं रास्ता भूल गया।","ro":"Māf kījie, maiṃ rāstā bhūl gayā.","lit":"pardon · faites · je · chemin · oublier · allé"}],"tip":{"title":"« Kaise » : comment","example":"Comment aller à la gare ? — स्टेशन <b>कैसे</b> जाएँ?","body":"« Kaise » veut dire comment, et c'est le mot idéal pour demander son chemin. Comme les autres mots interrogatifs du hindi, il ne se met pas au début de la phrase mais juste avant le verbe. « Sṭeshan kaise jāeṃ ? » se décompose en « sṭeshan », la gare, « kaise », comment, et « jāeṃ », allions : comment aller à la gare ? Quand on veut décrire une chose, comment est-elle, le mot s'accorde comme un adjectif : « kaisā » au masculin, « kaisī » au féminin. On dit donc « hoṭal kaisā hai ? », comment est l'hôtel, mais « chāy kaisī hai ? », comment est le thé, car le thé est féminin en hindi. Vous connaissez sans doute déjà « āp kaise haiṃ ? », comment allez-vous. Astuce : pensez « kaise » pour la manière de faire, et « kaisā » ou « kaisī » pour l'allure des choses.","exampleRo":"Sṭeshan kaise jāeṃ?","lit":"gare · comment · allions ?","say":{"Kaise":"कैसे","Sṭeshan kaise jāeṃ ?":"स्टेशन कैसे जाएँ?","sṭeshan":"स्टेशन","kaise":"कैसे","jāeṃ":"जाएँ","kaisā":"कैसा","kaisī":"कैसी","hoṭal kaisā hai ?":"होटल कैसा है?","chāy kaisī hai ?":"चाय कैसी है?","āp kaise haiṃ ?":"आप कैसे हैं?"}}},{"title":"À la pharmacie","phrases":[{"fr":"Il me faut une pharmacie.","tgt":"मुझे दवा की दुकान चाहिए।","ro":"Mujhe davā kī dukān chāhie.","lit":"à moi · médicament · [de] · boutique · faut"},{"fr":"J'ai très mal à la tête.","tgt":"मेरे सिर में बहुत दर्द है।","ro":"Mere sir meṃ bahut dard hai.","lit":"ma · tête · [dans] · très · douleur · est"},{"fr":"J'ai un peu de fièvre.","tgt":"मुझे थोड़ा बुखार है।","ro":"Mujhe thoṛā bukhār hai.","lit":"à moi · un peu · fièvre · est"},{"fr":"J'ai l'estomac dérangé.","tgt":"मेरा पेट खराब है।","ro":"Merā peṭ kharāb hai.","lit":"mon · ventre · mauvais · est"},{"fr":"Vous avez un médicament contre la fièvre ?","tgt":"क्या बुखार की दवा है?","ro":"Kyā bukhār kī davā hai?","lit":"[question] · fièvre · [de] · médicament · est ?"},{"fr":"Prenez-le deux fois par jour.","tgt":"इसे दिन में दो बार लीजिए।","ro":"Ise din meṃ do bār lījie.","lit":"ceci-[à] · jour · [dans] · deux · fois · prenez"},{"fr":"Toujours après le repas.","tgt":"हमेशा खाने के बाद।","ro":"Hameshā khāne ke bād.","lit":"toujours · repas · [de] · après"},{"fr":"Buvez beaucoup d'eau.","tgt":"खूब पानी पीजिए।","ro":"Khūb pānī pījie.","lit":"beaucoup · eau · buvez"},{"fr":"Ça, ce n'est pas grave.","tgt":"यह गंभीर नहीं है।","ro":"Yah gambhīr nahīṃ hai.","lit":"ceci · grave · pas · est"},{"fr":"Maintenant, je vais mieux.","tgt":"अब मैं बेहतर हूँ।","ro":"Ab maiṃ behtar hūṃ.","lit":"maintenant · je · mieux · suis"}]},{"title":"Le train est en retard","phrases":[{"fr":"Le train a deux heures de retard.","tgt":"ट्रेन दो घंटे लेट है।","ro":"Ṭren do ghanṭe leṭ hai.","lit":"train · deux · heures · en retard · est"},{"fr":"Je peux attendre ici ?","tgt":"क्या मैं यहाँ इंतज़ार कर सकता हूँ?","ro":"Kyā maiṃ yahāṃ intazār kar saktā hūṃ?","lit":"[question] · je · ici · attente · faire · pouvant · suis ?"},{"fr":"Oui, vous pouvez vous asseoir là-bas.","tgt":"हाँ, आप वहाँ बैठ सकते हैं।","ro":"Hāṃ, āp vahāṃ baiṭh sakte haiṃ.","lit":"oui · vous · là-bas · asseoir · pouvant · êtes"},{"fr":"Vous pouvez m'aider, s'il vous plaît ?","tgt":"क्या आप मेरी मदद कर सकते हैं?","ro":"Kyā āp merī madad kar sakte haiṃ?","lit":"[question] · vous · mon · aide · faire · pouvant · êtes ?"},{"fr":"Je peux changer mon billet ?","tgt":"क्या मैं टिकट बदल सकता हूँ?","ro":"Kyā maiṃ ṭikaṭ badal saktā hūṃ?","lit":"[question] · je · billet · changer · pouvant · suis ?"},{"fr":"Non, ce n'est pas possible.","tgt":"नहीं, यह नहीं हो सकता।","ro":"Nahīṃ, yah nahīṃ ho saktā.","lit":"non · ceci · pas · être · pouvant"},{"fr":"Je peux prendre le prochain train.","tgt":"मैं अगली ट्रेन ले सकता हूँ।","ro":"Maiṃ aglī ṭren le saktā hūṃ.","lit":"je · prochain · train · prendre · pouvant · suis"},{"fr":"Ma sœur ne peut pas venir.","tgt":"मेरी बहन नहीं आ सकती।","ro":"Merī bahan nahīṃ ā saktī.","lit":"ma · sœur · pas · venir · pouvant"},{"fr":"En attendant, on peut boire un thé.","tgt":"तब तक हम चाय पी सकते हैं।","ro":"Tab tak ham chāy pī sakte haiṃ.","lit":"alors · [jusqu'à] · nous · thé · boire · pouvant · sommes"},{"fr":"Quelle galère !","tgt":"क्या मुसीबत है!","ro":"Kyā musībat hai!","lit":"quel · ennui · est !"}],"tip":{"title":"« Saknā » : pouvoir","example":"Je peux prendre le prochain train. — मैं अगली ट्रेन ले <b>सकता</b> हूँ।","body":"Pour dire pouvoir, le hindi utilise le verbe « saknā ». La construction est très simple : on prend le verbe principal tout nu, sans terminaison, puis on ajoute « saktā hūṃ ». « Maiṃ aglī ṭren le saktā hūṃ » se décompose en je, prochain, train, prendre, pouvant, suis : je peux prendre le prochain train. Une femme dira « saktī hūṃ », et avec « āp », vous, ou « ham », nous, on dit « sakte haiṃ ». Pour poser la question, ajoutez « kyā » devant : « kyā maiṃ yahāṃ baiṭh saktā hūṃ ? », je peux m'asseoir ici ? Pour la négation, glissez « nahīṃ » avant le verbe : « vah nahīṃ ā saktī », elle ne peut pas venir, et dans ce cas on laisse souvent tomber « hai ». Astuce : « saknā » arrive toujours en fin de phrase, juste après le verbe qu'il rend possible.","exampleRo":"Maiṃ aglī ṭren le saktā hūṃ.","lit":"je · prochain · train · prendre · pouvant · suis","say":{"Saknā":"सकना","saknā":"सकना","saktā hūṃ":"सकता हूँ","Maiṃ aglī ṭren le saktā hūṃ":"मैं अगली ट्रेन ले सकता हूँ","saktī hūṃ":"सकती हूँ","āp":"आप","ham":"हम","sakte haiṃ":"सकते हैं","kyā":"क्या","kyā maiṃ yahāṃ baiṭh saktā hūṃ ?":"क्या मैं यहाँ बैठ सकता हूँ?","nahīṃ":"नहीं","vah nahīṃ ā saktī":"वह नहीं आ सकती","hai":"है"}}},{"title":"Udaipur, la ville des lacs","phrases":[{"fr":"À Udaipur, il y a beaucoup de lacs.","tgt":"उदयपुर में बहुत सारी झीलें हैं।","ro":"Udaypur meṃ bahut sārī jhīleṃ haiṃ.","lit":"Udaipur · [dans] · très · nombreux · lacs · sont"},{"fr":"L'eau est très calme.","tgt":"पानी बहुत शांत है।","ro":"Pānī bahut shānt hai.","lit":"eau · très · calme · est"},{"fr":"Le palais est au milieu du lac.","tgt":"महल झील के बीच में है।","ro":"Mahal jhīl ke bīch meṃ hai.","lit":"palais · lac · [de] · milieu · [dans] · est"},{"fr":"Allez, prenons un bateau.","tgt":"चलो, नाव लेते हैं।","ro":"Chalo, nāv lete haiṃ.","lit":"allons · bateau · prendre · sommes"},{"fr":"Le soir, les lumières sont belles.","tgt":"शाम को रोशनी सुंदर होती है।","ro":"Shām ko roshnī sundar hotī hai.","lit":"soir · [à] · lumière · belle · devenir · est"},{"fr":"De cet hôtel, on voit le lac.","tgt":"इस होटल से झील दिखती है।","ro":"Is hoṭal se jhīl dikhtī hai.","lit":"cet · hôtel · [depuis] · lac · se voir · est"},{"fr":"Ici, il fait un peu plus frais.","tgt":"यहाँ थोड़ी ठंडक है।","ro":"Yahāṃ thoṛī ṭhanḍak hai.","lit":"ici · un peu · fraîcheur · est"},{"fr":"C'est une ville très romantique.","tgt":"यह बहुत रोमांटिक शहर है।","ro":"Yah bahut romānṭik shahar hai.","lit":"ceci · très · romantique · ville · est"},{"fr":"Il y a des oiseaux sur l'eau.","tgt":"पानी पर चिड़ियाँ हैं।","ro":"Pānī par chiṛiyāṃ haiṃ.","lit":"eau · [sur] · oiseaux · sont"},{"fr":"J'adore cet endroit.","tgt":"मुझे यह जगह बहुत पसंद है।","ro":"Mujhe yah jagah bahut pasand hai.","lit":"à moi · cet · endroit · très · plaisir · est"}]},{"title":"En bus, en rickshaw","phrases":[{"fr":"J'y vais en taxi.","tgt":"मैं टैक्सी से जाता हूँ।","ro":"Maiṃ ṭaiksī se jātā hūṃ.","lit":"je · taxi · [en] · aller · suis"},{"fr":"On va au palais en rickshaw ?","tgt":"रिक्शा से महल चलें?","ro":"Rikshā se mahal chaleṃ?","lit":"rickshaw · [en] · palais · allions ?"},{"fr":"Le bus part d'ici même.","tgt":"बस यहीं से चलती है।","ro":"Bas yahīṃ se chaltī hai.","lit":"bus · ici même · [depuis] · partir · est"},{"fr":"Je suis en Inde depuis une semaine.","tgt":"मैं एक हफ़्ते से भारत में हूँ।","ro":"Maiṃ ek hafte se Bhārat meṃ hūṃ.","lit":"je · une · semaine · [depuis] · Inde · [dans] · suis"},{"fr":"J'attends depuis une heure.","tgt":"मैं एक घंटे से इंतज़ार कर रहा हूँ।","ro":"Maiṃ ek ghanṭe se intazār kar rahā hūṃ.","lit":"je · une · heure · [depuis] · attente · faire · [en cours] · suis"},{"fr":"Nous venons de Paris.","tgt":"हम पेरिस से हैं।","ro":"Ham Peris se haiṃ.","lit":"nous · Paris · [depuis] · sommes"},{"fr":"En bus, c'est moins cher.","tgt":"बस से सस्ता है।","ro":"Bas se sastā hai.","lit":"bus · [en] · bon marché · est"},{"fr":"Nous allons à Udaipur en bus.","tgt":"हम बस से उदयपुर जा रहे हैं।","ro":"Ham bas se Udaypur jā rahe haiṃ.","lit":"nous · bus · [en] · Udaipur · aller · [en cours] · sommes"},{"fr":"Depuis ce matin, il pleut.","tgt":"सुबह से बारिश हो रही है।","ro":"Subah se bārish ho rahī hai.","lit":"matin · [depuis] · pluie · être · [en cours] · est"},{"fr":"J'aime voyager en train.","tgt":"मुझे ट्रेन से सफ़र करना पसंद है।","ro":"Mujhe ṭren se safar karnā pasand hai.","lit":"à moi · train · [en] · voyage · faire · plaisir · est"}],"tip":{"title":"« Se » : en train, en bus, et depuis","example":"Je suis en Inde depuis une semaine. — मैं एक हफ़्ते <b>से</b> भारत में हूँ।","body":"Le petit mot « se », placé après un nom, a plusieurs sens très pratiques. D'abord, il indique le moyen de transport, comme notre en ou par : « bas se », en bus, « ṭren se », en train, « ṭaiksī se », en taxi. Ensuite, il marque l'origine : « ham Peris se haiṃ », nous sommes de Paris. Enfin, avec une durée, il veut dire depuis. « Maiṃ ek hafte se Bhārat meṃ hūṃ » se décompose en je, une semaine depuis, Inde dans, suis : je suis en Inde depuis une semaine. Remarquez que le hindi garde le présent, exactement comme le français. Et vous pouvez dire de la même façon « subah se », depuis ce matin. Astuce : imaginez que « se » trace toujours un chemin, à partir d'un lieu, à partir d'un moment, ou à travers un moyen de transport.","exampleRo":"Maiṃ ek hafte se Bhārat meṃ hūṃ.","lit":"je · une · semaine · [depuis] · Inde · [dans] · suis","say":{"Se":"से","se":"से","bas se":"बस से","ṭren se":"ट्रेन से","ṭaiksī se":"टैक्सी से","ham Peris se haiṃ":"हम पेरिस से हैं","Maiṃ ek hafte se Bhārat meṃ hūṃ":"मैं एक हफ़्ते से भारत में हूँ","subah se":"सुबह से"}}},{"title":"Un plan de la ville","phrases":[{"fr":"Il me faut un plan d'Udaipur.","tgt":"मुझे उदयपुर का नक्शा चाहिए।","ro":"Mujhe Udaypur kā nakshā chāhie.","lit":"à moi · Udaipur · [de] · plan · faut"},{"fr":"Sur le plan, nous sommes ici.","tgt":"नक्शे पर हम यहाँ हैं।","ro":"Nakshe par ham yahāṃ haiṃ.","lit":"plan · [sur] · nous · ici · sommes"},{"fr":"Le musée est à côté du palais.","tgt":"म्यूज़ियम महल के बगल में है।","ro":"Myūziyam mahal ke bagal meṃ hai.","lit":"musée · palais · [de] · côté · [dans] · est"},{"fr":"Cette rue mène au lac.","tgt":"यह सड़क झील तक जाती है।","ro":"Yah saṛak jhīl tak jātī hai.","lit":"cette · rue · lac · [jusqu'à] · aller · est"},{"fr":"Montrez-moi sur le plan.","tgt":"मुझे नक्शे पर दिखाइए।","ro":"Mujhe nakshe par dikhāie.","lit":"à moi · plan · [sur] · montrez"},{"fr":"Le jardin est au nord.","tgt":"बगीचा उत्तर में है।","ro":"Bagīchā uttar meṃ hai.","lit":"jardin · nord · [dans] · est"},{"fr":"La vieille ville est par là.","tgt":"पुराना शहर उधर है।","ro":"Purānā shahar udhar hai.","lit":"vieille · ville · par là · est"},{"fr":"Le plan est en hindi.","tgt":"नक्शा हिंदी में है।","ro":"Nakshā hindī meṃ hai.","lit":"plan · hindi · [dans] · est"},{"fr":"Je ne trouve pas l'hôtel sur le plan.","tgt":"मुझे नक्शे पर होटल नहीं मिल रहा।","ro":"Mujhe nakshe par hoṭal nahīṃ mil rahā.","lit":"à moi · plan · [sur] · hôtel · pas · trouver · [en cours]"},{"fr":"Le voilà, juste ici.","tgt":"यह रहा, ठीक यहाँ।","ro":"Yah rahā, ṭhīk yahāṃ.","lit":"ceci · voilà · juste · ici"}]},{"title":"Loin ou près ?","phrases":[{"fr":"La gare est loin d'ici ?","tgt":"क्या स्टेशन यहाँ से दूर है?","ro":"Kyā sṭeshan yahāṃ se dūr hai?","lit":"[question] · gare · ici · [depuis] · loin · est ?"},{"fr":"Non, c'est très proche.","tgt":"नहीं, बहुत पास है।","ro":"Nahīṃ, bahut pās hai.","lit":"non · très · près · est"},{"fr":"Le lac est près de l'hôtel.","tgt":"झील होटल के पास है।","ro":"Jhīl hoṭal ke pās hai.","lit":"lac · hôtel · [de] · près · est"},{"fr":"Le fort est loin de la ville.","tgt":"किला शहर से दूर है।","ro":"Kilā shahar se dūr hai.","lit":"fort · ville · [depuis] · loin · est"},{"fr":"C'est à combien de kilomètres ?","tgt":"कितने किलोमीटर दूर है?","ro":"Kitne kilomīṭar dūr hai?","lit":"combien · kilomètres · loin · est ?"},{"fr":"À environ deux kilomètres.","tgt":"लगभग दो किलोमीटर।","ro":"Lagbhag do kilomīṭar.","lit":"environ · deux · kilomètres"},{"fr":"Il y a un restaurant près d'ici ?","tgt":"क्या पास में कोई रेस्टोरेंट है?","ro":"Kyā pās meṃ koī resṭorenṭ hai?","lit":"[question] · près · [dans] · quelque · restaurant · est ?"},{"fr":"Oui, juste à côté.","tgt":"हाँ, बिलकुल पास में।","ro":"Hāṃ, bilkul pās meṃ.","lit":"oui · tout à fait · près · [dans]"},{"fr":"À pied, c'est trop loin.","tgt":"पैदल बहुत दूर है।","ro":"Paidal bahut dūr hai.","lit":"à pied · très · loin · est"},{"fr":"Alors, prenons un rickshaw.","tgt":"तो रिक्शा लेते हैं।","ro":"To rikshā lete haiṃ.","lit":"alors · rickshaw · prendre · sommes"}],"tip":{"title":"« Dūr » et « pās » : loin et près","example":"Le lac est près de l'hôtel. — झील होटल के <b>पास</b> है।","body":"Pour dire loin et près, retenez deux mots : « dūr », loin, et « pās », près. Avec « pās », on relie le lieu par le petit mot « ke » : « hoṭal ke pās », près de l'hôtel. « Jhīl hoṭal ke pās hai » se décompose en lac, hôtel, de, près, est : le lac est près de l'hôtel. Avec « dūr », on utilise plutôt « se », depuis : « shahar se dūr », loin de la ville, littéralement loin à partir de la ville. Pour demander la distance, la question toute faite est « kitne kilomīṭar dūr hai ? », c'est à combien de kilomètres ? Et pour insister, ajoutez « bahut » ou « bilkul » : « bilkul pās meṃ », juste à côté. Astuce : « pās » marche avec « ke », « dūr » avec « se », comme deux couples qui ne se séparent jamais.","exampleRo":"Jhīl hoṭal ke pās hai.","lit":"lac · hôtel · [de] · près · est","say":{"Dūr":"दूर","pās":"पास","dūr":"दूर","ke":"के","hoṭal ke pās":"होटल के पास","Jhīl hoṭal ke pās hai":"झील होटल के पास है","se":"से","shahar se dūr":"शहर से दूर","kitne kilomīṭar dūr hai ?":"कितने किलोमीटर दूर है?","bahut":"बहुत","bilkul":"बिल्कुल","bilkul pās meṃ":"बिल्कुल पास में"}}},{"title":"Petits imprévus","phrases":[{"fr":"Mon téléphone a disparu.","tgt":"मेरा फ़ोन खो गया।","ro":"Merā fon kho gayā.","lit":"mon · téléphone · perdre · allé"},{"fr":"Il était dans ma poche.","tgt":"वह मेरी जेब में था।","ro":"Vah merī jeb meṃ thā.","lit":"il · ma · poche · [dans] · était"},{"fr":"Où est le commissariat ?","tgt":"पुलिस स्टेशन कहाँ है?","ro":"Pulis sṭeshan kahāṃ hai?","lit":"police · poste · où · est ?"},{"fr":"Ne paniquez pas, monsieur.","tgt":"घबराइए मत, साहब।","ro":"Ghabrāie mat, sāhab.","lit":"paniquez · ne pas · monsieur"},{"fr":"Appelez votre propre numéro.","tgt":"अपने नंबर पर फ़ोन कीजिए।","ro":"Apne nambar par fon kījie.","lit":"votre · numéro · [sur] · téléphone · faites"},{"fr":"Le voilà, sous la table !","tgt":"यह रहा, मेज़ के नीचे!","ro":"Yah rahā, mez ke nīche!","lit":"ceci · voilà · table · [de] · dessous !"},{"fr":"Ouf, quelle chance !","tgt":"वाह, क्या किस्मत है!","ro":"Vāh, kyā kismat hai!","lit":"ah · quelle · chance · est !"},{"fr":"Le chauffeur est parti avec mon sac.","tgt":"ड्राइवर मेरा बैग लेकर चला गया।","ro":"Ḍrāivar merā baig lekar chalā gayā.","lit":"chauffeur · mon · sac · ayant pris · partir · allé"},{"fr":"Vous avez son numéro ?","tgt":"क्या आपके पास उसका नंबर है?","ro":"Kyā āpke pās uskā nambar hai?","lit":"[question] · vous · [chez] · son · numéro · est ?"},{"fr":"Il revient dans dix minutes.","tgt":"वह दस मिनट में वापस आ रहा है।","ro":"Vah das minaṭ meṃ vāpas ā rahā hai.","lit":"il · dix · minutes · [dans] · retour · venir · [en cours] · est"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce voyage en hindi était formidable.","tgt":"हिंदी का यह सफ़र बहुत अच्छा था।","ro":"Hindī kā yah safar bahut achchhā thā.","lit":"hindi · [de] · ce · voyage · très · bon · était"},{"fr":"Nous sommes allés à Agra et à Jodhpur.","tgt":"हम आगरा और जोधपुर गये।","ro":"Ham Āgrā aur Jodhpur gaye.","lit":"nous · Agra · et · Jodhpur · allés"},{"fr":"Maintenant, je parle un peu hindi.","tgt":"अब मैं थोड़ी हिंदी बोलता हूँ।","ro":"Ab maiṃ thoṛī hindī boltā hūṃ.","lit":"maintenant · je · un peu · hindi · parler · suis"},{"fr":"Un jour, j'irai à Udaipur.","tgt":"एक दिन मैं उदयपुर जाऊँगा।","ro":"Ek din maiṃ Udaypur jāūṃgā.","lit":"un · jour · je · Udaipur · irai"},{"fr":"Je suis ravie, j'irai à Jaipur !","tgt":"मैं बहुत खुश हूँ, जयपुर जाऊँगी!","ro":"Maiṃ bahut khush hūṃ, Jaypur jāūṃgī!","lit":"je · très · contente · suis · Jaipur · irai !"},{"fr":"Ma fille ira au Taj Mahal.","tgt":"मेरी बेटी ताजमहल जाएगी।","ro":"Merī beṭī Tājmahal jāegī.","lit":"ma · fille · Taj Mahal · ira"},{"fr":"Ensuite, nous parlerons avec les gens.","tgt":"फिर हम लोगों से बात करेंगे।","ro":"Phir ham logoṃ se bāt kareṃge.","lit":"ensuite · nous · gens · [avec] · parole · ferons"},{"fr":"Nous irons plus loin ensemble.","tgt":"हम साथ में आगे जाएँगे।","ro":"Ham sāth meṃ āge jāeṃge.","lit":"nous · ensemble · [dans] · en avant · irons"},{"fr":"Bravo pour tous vos efforts !","tgt":"आपकी मेहनत के लिए शाबाश!","ro":"Āpkī mehnat ke lie shābāsh!","lit":"votre · effort · [de] · [pour] · bravo !"},{"fr":"On se retrouve très vite !","tgt":"फिर मिलेंगे!","ro":"Phir mileṃge!","lit":"encore · nous rencontrerons !"}],"tip":{"title":"Le futur : « jāūṃgā, jāūṃgī »","example":"Un jour, j'irai à Udaipur. — एक दिन मैं उदयपुर <b>जाऊँगा</b>।","body":"Pour parler de l'avenir, le hindi colle une petite terminaison au verbe. Pour aller, « jānā », on obtient « jāūṃgā », j'irai. On peut le découper en trois morceaux : « jā », le radical, « ūṃ », la marque du je, et « gā », qui s'accorde comme un adjectif. Un homme dit donc « maiṃ jāūṃgā », et une femme « maiṃ jāūṃgī ». Pour il ou elle, cela devient « jāegā » ou « jāegī », et pour nous ou vous, « jāeṃge ». « Ek din maiṃ Udaypur jāūṃgā » se lit mot à mot un jour, je, Udaipur, irai. Le même moule marche avec tous les verbes : « āūṃgā », je viendrai, « bolūṃgā », je parlerai. Astuce : écoutez le « gā » final, c'est le son du futur, et il devient « gī » au féminin.","exampleRo":"Ek din maiṃ Udaypur jāūṃgā.","lit":"un · jour · je · Udaipur · irai","say":{"jānā":"जाना","jāūṃgā":"जाऊँगा","jā":"जा","maiṃ jāūṃgā":"मैं जाऊँगा","maiṃ jāūṃgī":"मैं जाऊँगी","jāegā":"जाएगा","jāegī":"जाएगी","jāeṃge":"जाएँगे","Ek din maiṃ Udaypur jāūṃgā":"एक दिन मैं उदयपुर जाऊँगा","āūṃgā":"आऊँगा","bolūṃgā":"बोलूँगा","jāūṃgā, jāūṃgī":"जाऊँगा, जाऊँगी","gā":"गा","gī":"गी"}}}]},{"id":3,"name":"Conversation sociale","desc":"Faire connaissance, se présenter, échanger avec aisance.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Rencontre sur la plage de Juhu","phrases":[{"fr":"Bonjour, cette plage est vraiment belle.","tgt":"नमस्ते, यह बीच बहुत सुंदर है।","ro":"Namaste, yah bīch bahut sundar hai.","lit":"bonjour · cette · plage · très · belle · est"},{"fr":"Tu viens souvent à Juhu ?","tgt":"तुम अक्सर जुहू आते हो?","ro":"Tum aksar Juhū āte ho?","lit":"tu · souvent · Juhu · viens ?"},{"fr":"Oui, tous les dimanches soir.","tgt":"हाँ, हर रविवार शाम को।","ro":"Hāṃ, har ravivār shām ko.","lit":"oui · chaque · dimanche · soir · [à]"},{"fr":"Moi, je suis nouveau dans le coin.","tgt":"मैं यहाँ नया हूँ।","ro":"Maiṃ yahāṃ nayā hūṃ.","lit":"je · ici · nouveau · suis"},{"fr":"Tu viens de France, toi ?","tgt":"तुम फ़्रांस से हो?","ro":"Tum Frāns se ho?","lit":"tu · France · [depuis] · es ?"},{"fr":"Oui, je suis de Paris.","tgt":"हाँ, मैं पेरिस से हूँ।","ro":"Hāṃ, maiṃ Peris se hūṃ.","lit":"oui · je · Paris · [depuis] · suis"},{"fr":"La mer est calme ce soir.","tgt":"आज शाम समुद्र शांत है।","ro":"Āj shām samudra shānt hai.","lit":"aujourd'hui · soir · mer · calme · est"},{"fr":"Il y a beaucoup de monde sur la plage.","tgt":"बीच पर बहुत लोग हैं।","ro":"Bīch par bahut log haiṃ.","lit":"plage · [sur] · beaucoup · gens · sont"},{"fr":"Tu habites près de la plage ?","tgt":"तुम बीच के पास रहते हो?","ro":"Tum bīch ke pās rahte ho?","lit":"tu · plage · [de] · près · habites ?"},{"fr":"Oui, ma maison est tout près d'ici.","tgt":"हाँ, मेरा घर बहुत पास है।","ro":"Hāṃ, merā ghar bahut pās hai.","lit":"oui · ma · maison · très · près · est"}]},{"title":"Se présenter","phrases":[{"fr":"C'est quoi, ton prénom ?","tgt":"तुम्हारा नाम क्या है?","ro":"Tumhārā nām kyā hai?","lit":"ton · nom · quoi · est ?"},{"fr":"Moi, je m'appelle Lucas.","tgt":"मेरा नाम लुकास है।","ro":"Merā nām Lukās hai.","lit":"mon · nom · Lucas · est"},{"fr":"Et ton nom à toi ?","tgt":"और तुम्हारा नाम?","ro":"Aur tumhārā nām?","lit":"et · ton · nom ?"},{"fr":"Moi, c'est Priya.","tgt":"मेरा नाम प्रिया है।","ro":"Merā nām Priyā hai.","lit":"mon · nom · Priya · est"},{"fr":"Enchanté de te rencontrer, Priya.","tgt":"तुमसे मिलकर ख़ुशी हुई, प्रिया।","ro":"Tumse milkar khushī huī, Priyā.","lit":"toi-[depuis] · ayant rencontré · joie · est venue · Priya"},{"fr":"Mon ami s'appelle Rahul.","tgt":"मेरे दोस्त का नाम राहुल है।","ro":"Mere dost kā nām Rāhul hai.","lit":"mon · ami · [de] · nom · Rahul · est"},{"fr":"Ma sœur s'appelle Neha.","tgt":"मेरी बहन का नाम नेहा है।","ro":"Merī bahan kā nām Nehā hai.","lit":"ma · sœur · [de] · nom · Neha · est"},{"fr":"Comment s'appelle ton ami ?","tgt":"तुम्हारे दोस्त का नाम क्या है?","ro":"Tumhāre dost kā nām kyā hai?","lit":"ton · ami · [de] · nom · quoi · est ?"},{"fr":"Moi, je suis français, et toi ?","tgt":"मैं फ़्रांसीसी हूँ, और तुम?","ro":"Maiṃ frānsīsī hūṃ, aur tum?","lit":"je · français · suis · et · toi ?"},{"fr":"Moi, je suis d'ici, de Mumbai.","tgt":"मैं मुंबई से हूँ।","ro":"Maiṃ Mumbaī se hūṃ.","lit":"je · Mumbai · [depuis] · suis"}],"tip":{"title":"Se présenter : « merā nām... hai »","example":"Moi, je m'appelle Lucas. — <b>मेरा</b> <b>नाम</b> लुकास <b>है</b>।","body":"Pour dire comment on s'appelle, le hindi utilise une phrase très simple : « merā nām Lukās hai », mot à mot « mon nom Lucas est ». Le verbe « hai », qui veut dire « est », se place toujours à la fin, comme un point final que l'on prononce. « Merā » veut dire « mon », et il reste « merā » même si c'est une femme qui parle, car il s'accorde avec le mot « nām », le nom, qui est masculin. Une femme dira donc aussi « merā nām Priyā hai ». Pour demander le nom de quelqu'un entre amis, on dit « tumhārā nām kyā hai ? », ton nom quoi est. Avec une personne qu'on vouvoie, on dit plutôt « āpkā nām kyā hai ? ». Et pour parler du nom d'un ami, on ajoute « kā », qui veut dire « de » : « mere dost kā nām Rāhul hai », le nom de mon ami est Rahul. Astuce pour retenir : pensez à une carte de visite lue à voix haute, d'abord mon nom, puis le prénom, et enfin « hai » pour fermer la phrase.","exampleRo":"Merā nām Lukās hai.","lit":"mon · nom · Lucas · est","say":{"merā nām Lukās hai":"मेरा नाम लुकास है","hai":"है","Merā":"मेरा","merā":"मेरा","nām":"नाम","merā nām Priyā hai":"मेरा नाम प्रिया है","tumhārā nām kyā hai ?":"तुम्हारा नाम क्या है?","āpkā nām kyā hai ?":"आपका नाम क्या है?","kā":"का","mere dost kā nām Rāhul hai":"मेरे दोस्त का नाम राहुल है","merā nām... hai":"मेरा नाम… है"}}},{"title":"D'où viens-tu ?","phrases":[{"fr":"Tu es d'où, toi ?","tgt":"तुम कहाँ से हो?","ro":"Tum kahāṃ se ho?","lit":"tu · où · [depuis] · es ?"},{"fr":"Je suis du sud de la France.","tgt":"मैं फ़्रांस के दक्षिण से हूँ।","ro":"Maiṃ Frāns ke dakshiṇ se hūṃ.","lit":"je · France · [de] · sud · [depuis] · suis"},{"fr":"Ma ville natale est toute petite.","tgt":"मेरा शहर छोटा है।","ro":"Merā shahar chhoṭā hai.","lit":"ma · ville · petite · est"},{"fr":"Mumbai est une ville immense.","tgt":"मुंबई बहुत बड़ा शहर है।","ro":"Mumbaī bahut baṛā shahar hai.","lit":"Mumbai · très · grande · ville · est"},{"fr":"Tu habites où à Mumbai ?","tgt":"तुम मुंबई में कहाँ रहते हो?","ro":"Tum Mumbaī meṃ kahāṃ rahte ho?","lit":"tu · Mumbai · [dans] · où · habites ?"},{"fr":"J'habite à Bandra.","tgt":"मैं बांद्रा में रहता हूँ।","ro":"Maiṃ Bāndrā meṃ rahtā hūṃ.","lit":"je · Bandra · [dans] · habite"},{"fr":"C'est loin de Juhu ?","tgt":"क्या वह जुहू से दूर है?","ro":"Kyā vah Juhū se dūr hai?","lit":"[question] · ça · Juhu · [depuis] · loin · est ?"},{"fr":"Non, pas tellement loin.","tgt":"नहीं, ज़्यादा दूर नहीं है।","ro":"Nahīṃ, zyādā dūr nahīṃ hai.","lit":"non · trop · loin · pas · est"},{"fr":"Depuis quand es-tu à Mumbai ?","tgt":"तुम कब से मुंबई में हो?","ro":"Tum kab se Mumbaī meṃ ho?","lit":"tu · quand · [depuis] · Mumbai · [dans] · es ?"},{"fr":"Depuis deux mois seulement.","tgt":"सिर्फ़ दो महीने से।","ro":"Sirf do mahīne se.","lit":"seulement · deux · mois · [depuis]"}]},{"title":"Ce qu'on aime","phrases":[{"fr":"J'aime le vada pav.","tgt":"मुझे वड़ा पाव पसंद है।","ro":"Mujhe vaṛā pāv pasand hai.","lit":"moi-[à] · vada pav · agréable · est"},{"fr":"Tu aimes le cricket ?","tgt":"क्या तुम्हें क्रिकेट पसंद है?","ro":"Kyā tumheṃ krikeṭ pasand hai?","lit":"[question] · toi-[à] · cricket · agréable · est ?"},{"fr":"Oui, j'adore le cricket.","tgt":"हाँ, मुझे क्रिकेट बहुत पसंद है।","ro":"Hāṃ, mujhe krikeṭ bahut pasand hai.","lit":"oui · moi-[à] · cricket · très · agréable · est"},{"fr":"Je n'aime pas le froid.","tgt":"मुझे सर्दी पसंद नहीं है।","ro":"Mujhe sardī pasand nahīṃ hai.","lit":"moi-[à] · froid · agréable · pas · est"},{"fr":"Ma sœur aime les films de Bollywood.","tgt":"मेरी बहन को बॉलीवुड फ़िल्में पसंद हैं।","ro":"Merī bahan ko Bolīvuḍ filmeṃ pasand haiṃ.","lit":"ma · sœur · [à] · Bollywood · films · agréables · sont"},{"fr":"Qu'est-ce que tu aimes manger ?","tgt":"तुम्हें क्या खाना पसंद है?","ro":"Tumheṃ kyā khānā pasand hai?","lit":"toi-[à] · quoi · manger · agréable · est ?"},{"fr":"J'aime la cuisine bien épicée.","tgt":"मुझे तीखा खाना पसंद है।","ro":"Mujhe tīkhā khānā pasand hai.","lit":"moi-[à] · épicée · nourriture · agréable · est"},{"fr":"Mumbai me plaît beaucoup.","tgt":"मुझे मुंबई बहुत पसंद है।","ro":"Mujhe Mumbaī bahut pasand hai.","lit":"moi-[à] · Mumbai · très · agréable · est"},{"fr":"Nous aimons la mer.","tgt":"हमें समुद्र पसंद है।","ro":"Hameṃ samudra pasand hai.","lit":"nous-[à] · mer · agréable · est"},{"fr":"Tu aimes la pluie de Mumbai ?","tgt":"क्या तुम्हें मुंबई की बारिश पसंद है?","ro":"Kyā tumheṃ Mumbaī kī bārish pasand hai?","lit":"[question] · toi-[à] · Mumbai · [de] · pluie · agréable · est ?"}],"tip":{"title":"« Pasand hai » : aimer, littéralement c'est agréable pour moi","example":"J'aime le vada pav. — <b>मुझे</b> वड़ा पाव <b>पसंद</b> <b>है</b>।","body":"En hindi, on ne dit pas vraiment « j'aime », on dit plutôt « pour moi, c'est agréable ». La phrase « mujhe vaṛā pāv pasand hai » se décompose ainsi : « mujhe », à moi, « vaṛā pāv », le vada pav, « pasand », agréable ou préféré, et « hai », est. C'est donc la chose aimée qui est le sujet, un peu comme en français quand on dit « ça me plaît ». Le verbe s'accorde avec cette chose : avec un pluriel, « hai » devient « haiṃ », comme dans « mujhe filmeṃ pasand haiṃ », les films me plaisent. Pour toi, on dit « tumheṃ », et pour vous, « āpko » : « kyā tumheṃ krikeṭ pasand hai ? », tu aimes le cricket ? Pour dire qu'on n'aime pas, il suffit de glisser « nahīṃ » juste avant le verbe : « mujhe sardī pasand nahīṃ hai ». Astuce : chaque fois que vous voulez dire « j'aime », pensez à « ça me plaît », et la phrase hindi vient toute seule.","exampleRo":"Mujhe vaṛā pāv pasand hai.","lit":"moi-[à] · vada pav · agréable · est","say":{"Pasand hai":"पसंद है","mujhe vaṛā pāv pasand hai":"मुझे वड़ा पाव पसंद है","mujhe":"मुझे","vaṛā pāv":"वड़ा पाव","pasand":"पसंद","hai":"है","haiṃ":"हैं","mujhe filmeṃ pasand haiṃ":"मुझे फ़िल्में पसंद हैं","tumheṃ":"तुम्हें","āpko":"आपको","kyā tumheṃ krikeṭ pasand hai ?":"क्या तुम्हें क्रिकेट पसंद है?","nahīṃ":"नहीं","mujhe sardī pasand nahīṃ hai":"मुझे सर्दी पसंद नहीं है"}}},{"title":"Un vada pav au bord de la mer","phrases":[{"fr":"J'ai faim, et toi ?","tgt":"मुझे भूख लगी है, और तुम्हें?","ro":"Mujhe bhūkh lagī hai, aur tumheṃ?","lit":"moi-[à] · faim · attachée · est · et · toi-[à] ?"},{"fr":"Il y a un stand de vada pav là-bas.","tgt":"वहाँ वड़ा पाव का ठेला है।","ro":"Vahāṃ vaṛā pāv kā ṭhelā hai.","lit":"là-bas · vada pav · [de] · charrette · est"},{"fr":"Deux vada pav, s'il vous plaît.","tgt":"दो वड़ा पाव दीजिए।","ro":"Do vaṛā pāv dījie.","lit":"deux · vada pav · donnez"},{"fr":"C'est combien, le vada pav ?","tgt":"वड़ा पाव कितने का है?","ro":"Vaṛā pāv kitne kā hai?","lit":"vada pav · combien · [de] · est ?"},{"fr":"Vingt roupies l'un.","tgt":"बीस रुपये का एक।","ro":"Bīs rupaye kā ek.","lit":"vingt · roupies · [de] · un"},{"fr":"Ouh, c'est très épicé.","tgt":"यह बहुत तीखा है।","ro":"Yah bahut tīkhā hai.","lit":"ceci · très · épicé · est"},{"fr":"Tu veux un peu d'eau ?","tgt":"तुम्हें पानी चाहिए?","ro":"Tumheṃ pānī chāhie?","lit":"toi-[à] · eau · faut ?"},{"fr":"Non, ça va, c'est délicieux.","tgt":"नहीं, ठीक है, बहुत स्वादिष्ट है।","ro":"Nahīṃ, ṭhīk hai, bahut svādishṭ hai.","lit":"non · bien · est · très · délicieux · est"},{"fr":"Le vada pav, c'est le burger de Mumbai.","tgt":"वड़ा पाव मुंबई का बर्गर है।","ro":"Vaṛā pāv Mumbaī kā bargar hai.","lit":"vada pav · Mumbai · [de] · burger · est"},{"fr":"On en reprend un chacun ?","tgt":"एक और लें?","ro":"Ek aur leṃ?","lit":"un · encore · prenons ?"}]},{"title":"Parler de sa famille","phrases":[{"fr":"Tu as des frères ou des sœurs ?","tgt":"तुम्हारे भाई-बहन हैं?","ro":"Tumhāre bhāī-bahan haiṃ?","lit":"tes · frères-sœurs · sont ?"},{"fr":"J'ai un grand frère.","tgt":"मेरा एक बड़ा भाई है।","ro":"Merā ek baṛā bhāī hai.","lit":"mon · un · grand · frère · est"},{"fr":"Ma petite sœur est étudiante.","tgt":"मेरी छोटी बहन छात्रा है।","ro":"Merī chhoṭī bahan chhātrā hai.","lit":"ma · petite · sœur · étudiante · est"},{"fr":"Mes parents habitent en France.","tgt":"मेरे माता-पिता फ़्रांस में रहते हैं।","ro":"Mere mātā-pitā Frāns meṃ rahte haiṃ.","lit":"mes · mère-père · France · [dans] · habitent"},{"fr":"Mon père est professeur.","tgt":"मेरे पिता टीचर हैं।","ro":"Mere pitā ṭīchar haiṃ.","lit":"mon · père · professeur · sont"},{"fr":"Ma mère travaille dans un hôpital.","tgt":"मेरी माँ अस्पताल में काम करती हैं।","ro":"Merī māṃ aspatāl meṃ kām kartī haiṃ.","lit":"ma · maman · hôpital · [dans] · travail · faisant · sont"},{"fr":"Ton frère vit à Mumbai ?","tgt":"क्या तुम्हारा भाई मुंबई में रहता है?","ro":"Kyā tumhārā bhāī Mumbaī meṃ rahtā hai?","lit":"[question] · ton · frère · Mumbai · [dans] · habite ?"},{"fr":"Non, il habite à Pune.","tgt":"नहीं, वह पुणे में रहता है।","ro":"Nahīṃ, vah Puṇe meṃ rahtā hai.","lit":"non · il · Pune · [dans] · habite"},{"fr":"Ma sœur a deux enfants.","tgt":"मेरी बहन के दो बच्चे हैं।","ro":"Merī bahan ke do bachche haiṃ.","lit":"ma · sœur · [de] · deux · enfants · sont"},{"fr":"Ma famille me manque.","tgt":"मुझे अपने परिवार की याद आती है।","ro":"Mujhe apne parivār kī yād ātī hai.","lit":"moi-[à] · ma propre · famille · [de] · souvenir · vient"}],"tip":{"title":"La famille : « mātā-pitā, bhāī, bahan »","example":"Mes parents habitent en France. — मेरे <b>माता-पिता</b> फ़्रांस में रहते हैं।","body":"Pour parler de sa famille, quelques mots suffisent pour commencer. « Bhāī » veut dire frère, « bahan » veut dire sœur, et « mātā-pitā », mot à mot mère-père, désigne les parents. Au quotidien, on appelle souvent sa mère « māṃ » et son père « pitā jī » ou « pāpā ». Pour dire grand frère ou petite sœur, on ajoute simplement « baṛā », grand, ou « chhoṭī », petite : « merā ek baṛā bhāī hai », j'ai un grand frère, mot à mot mon un grand frère est. Remarquez que « merā » devient « merī » devant un mot féminin comme « bahan » : « merī bahan », ma sœur. Pour les parents, on emploie le pluriel de respect : « mere mātā-pitā Frāns meṃ rahte haiṃ », mes parents habitent en France. Astuce : « bhāī » est aussi un mot très amical à Mumbai, on l'entend partout entre copains, un peu comme « frérot » en français.","exampleRo":"Mere mātā-pitā Frāns meṃ rahte haiṃ.","lit":"mes · mère-père · France · [dans] · habitent","say":{"Bhāī":"भाई","bahan":"बहन","mātā-pitā":"माता-पिता","māṃ":"माँ","pitā jī":"पिता जी","pāpā":"पापा","baṛā":"बड़ा","chhoṭī":"छोटी","merā ek baṛā bhāī hai":"मेरा एक बड़ा भाई है","merā":"मेरा","merī":"मेरी","merī bahan":"मेरी बहन","mere mātā-pitā Frāns meṃ rahte haiṃ":"मेरे माता-पिता फ़्रांस में रहते हैं","bhāī":"भाई","mātā-pitā, bhāī, bahan":"माता-पिता, भाई, बहन"}}},{"title":"Parler de son travail","phrases":[{"fr":"Qu'est-ce que tu fais comme boulot ?","tgt":"तुम क्या काम करते हो?","ro":"Tum kyā kām karte ho?","lit":"tu · quel · travail · fais ?"},{"fr":"Je suis ingénieur.","tgt":"मैं इंजीनियर हूँ।","ro":"Maiṃ injīniyar hūṃ.","lit":"je · ingénieur · suis"},{"fr":"Je travaille pour une société française.","tgt":"मैं एक फ़्रांसीसी कंपनी में काम करता हूँ।","ro":"Maiṃ ek frānsīsī kampanī meṃ kām kartā hūṃ.","lit":"je · une · française · société · [dans] · travail · fais"},{"fr":"Mon bureau est à Andheri.","tgt":"मेरा दफ़्तर अंधेरी में है।","ro":"Merā daftar Andherī meṃ hai.","lit":"mon · bureau · Andheri · [dans] · est"},{"fr":"Tu travailles le samedi ?","tgt":"क्या तुम शनिवार को काम करते हो?","ro":"Kyā tum shanivār ko kām karte ho?","lit":"[question] · tu · samedi · [à] · travail · fais ?"},{"fr":"Non, seulement du lundi au vendredi.","tgt":"नहीं, सिर्फ़ सोमवार से शुक्रवार तक।","ro":"Nahīṃ, sirf somvār se shukravār tak.","lit":"non · seulement · lundi · [depuis] · vendredi · jusqu'à"},{"fr":"Je commence à neuf heures.","tgt":"मैं नौ बजे शुरू करता हूँ।","ro":"Maiṃ nau baje shurū kartā hūṃ.","lit":"je · neuf · heures · début · fais"},{"fr":"Mon travail est intéressant.","tgt":"मेरा काम दिलचस्प है।","ro":"Merā kām dilchasp hai.","lit":"mon · travail · intéressant · est"},{"fr":"Et toi, tu es encore étudiante ?","tgt":"और तुम, क्या तुम छात्रा हो?","ro":"Aur tum, kyā tum chhātrā ho?","lit":"et · toi · [question] · tu · étudiante · es ?"},{"fr":"Non, je suis médecin.","tgt":"नहीं, मैं डॉक्टर हूँ।","ro":"Nahīṃ, maiṃ ḍokṭar hūṃ.","lit":"non · je · médecin · suis"}]},{"title":"Au téléphone avec un ami","phrases":[{"fr":"Allô Rahul, tu fais quoi ?","tgt":"हैलो राहुल, क्या कर रहे हो?","ro":"Hailo Rāhul, kyā kar rahe ho?","lit":"allô · Rahul · quoi · faire · en train · es ?"},{"fr":"Je suis en train de manger.","tgt":"मैं खाना खा रहा हूँ।","ro":"Maiṃ khānā khā rahā hūṃ.","lit":"je · repas · manger · en train · suis"},{"fr":"Tu regardes le match ?","tgt":"क्या तुम मैच देख रहे हो?","ro":"Kyā tum maich dekh rahe ho?","lit":"[question] · tu · match · regarder · en train · es ?"},{"fr":"Oui, l'Inde est en train de gagner.","tgt":"हाँ, भारत जीत रहा है।","ro":"Hāṃ, Bhārat jīt rahā hai.","lit":"oui · Inde · gagner · en train · est"},{"fr":"Tu vas où, là, maintenant ?","tgt":"तुम अभी कहाँ जा रहे हो?","ro":"Tum abhī kahāṃ jā rahe ho?","lit":"tu · maintenant · où · aller · en train · es ?"},{"fr":"Je suis en route pour la plage.","tgt":"मैं बीच जा रहा हूँ।","ro":"Maiṃ bīch jā rahā hūṃ.","lit":"je · plage · aller · en train · suis"},{"fr":"Priya est en chemin, elle aussi.","tgt":"प्रिया भी आ रही है।","ro":"Priyā bhī ā rahī hai.","lit":"Priya · aussi · venir · en train · est"},{"fr":"Il pleut fort ici en ce moment.","tgt":"यहाँ बहुत बारिश हो रही है।","ro":"Yahāṃ bahut bārish ho rahī hai.","lit":"ici · beaucoup · pluie · se faire · en train · est"},{"fr":"J'attends à la gare.","tgt":"मैं स्टेशन पर इंतज़ार कर रहा हूँ।","ro":"Maiṃ sṭeshan par intazār kar rahā hūṃ.","lit":"je · gare · [sur] · attente · faire · en train · suis"},{"fr":"D'accord, j'arrive tout de suite.","tgt":"ठीक है, मैं आ रहा हूँ।","ro":"Ṭhīk hai, maiṃ ā rahā hūṃ.","lit":"bien · est · je · venir · en train · suis"}],"tip":{"title":"« Rahā hai » : être en train de","example":"Je suis en train de manger. — मैं खाना खा <b>रहा</b> <b>हूँ</b>।","body":"Pour dire ce qu'on fait en ce moment précis, le hindi ajoute « rahā » après le verbe, puis « hai » ou « hūṃ ». « Maiṃ khānā khā rahā hūṃ » se décompose ainsi : « maiṃ », je, « khānā », le repas, « khā », manger, « rahā », en train, et « hūṃ », suis. C'est exactement l'idée française de « je suis en train de manger ». Le petit mot « rahā » s'accorde comme un adjectif : « rahā » pour un homme, « rahī » pour une femme, et « rahe » avec « tum », « āp » ou un pluriel. On dira ainsi « Priyā ā rahī hai », Priya arrive, et entre amis « kyā kar rahe ho ? », qu'est-ce que tu fais ? Comparez avec « maiṃ khānā khātā hūṃ », qui veut dire je mange en général, par habitude. Astuce : retenez « rahā » comme le mot du direct, celui qu'on utilise au téléphone pour raconter ce qui se passe maintenant.","exampleRo":"Maiṃ khānā khā rahā hūṃ.","lit":"je · repas · manger · en train · suis","say":{"Rahā hai":"रहा है","rahā":"रहा","hai":"है","hūṃ":"हूँ","Maiṃ khānā khā rahā hūṃ":"मैं खाना खा रहा हूँ","maiṃ":"मैं","khānā":"खाना","khā":"खा","rahī":"रही","rahe":"रहे","tum":"तुम","āp":"आप","Priyā ā rahī hai":"प्रिया आ रही है","kyā kar rahe ho ?":"क्या कर रहे हो?","maiṃ khānā khātā hūṃ":"मैं खाना खाता हूँ"}}},{"title":"Les collègues au bureau","phrases":[{"fr":"Je te présente mon collègue Vikram.","tgt":"यह मेरे सहकर्मी विक्रम हैं।","ro":"Yah mere sahkarmī Vikram haiṃ.","lit":"ceci · mon · collègue · Vikram · sont"},{"fr":"Il est très gentil.","tgt":"वह बहुत अच्छे हैं।","ro":"Vah bahut achchhe haiṃ.","lit":"il · très · bons · sont"},{"fr":"On déjeune ensemble tous les jours.","tgt":"हम रोज़ साथ में खाना खाते हैं।","ro":"Ham roz sāth meṃ khānā khāte haiṃ.","lit":"nous · chaque jour · ensemble · [dans] · repas · mangeons"},{"fr":"Notre chef est assez strict.","tgt":"हमारे बॉस काफ़ी सख़्त हैं।","ro":"Hamāre bos kāfī sakht haiṃ.","lit":"notre · chef · assez · strict · sont"},{"fr":"Le bureau est à côté de la gare.","tgt":"दफ़्तर स्टेशन के पास है।","ro":"Daftar sṭeshan ke pās hai.","lit":"bureau · gare · [de] · près · est"},{"fr":"Tu viens au bureau en train ?","tgt":"तुम ट्रेन से आते हो?","ro":"Tum ṭren se āte ho?","lit":"tu · train · [depuis] · viens ?"},{"fr":"Oui, en train de banlieue.","tgt":"हाँ, लोकल ट्रेन से।","ro":"Hāṃ, lokal ṭren se.","lit":"oui · local · train · [depuis]"},{"fr":"Le train est toujours bondé.","tgt":"ट्रेन हमेशा भरी रहती है।","ro":"Ṭren hameshā bharī rahtī hai.","lit":"train · toujours · pleine · reste"},{"fr":"Anjali est nouvelle dans l'équipe.","tgt":"अंजलि टीम में नई है।","ro":"Anjali ṭīm meṃ naī hai.","lit":"Anjali · équipe · [dans] · nouvelle · est"},{"fr":"On prend un thé à quatre heures ?","tgt":"चार बजे चाय पिएँ?","ro":"Chār baje chāy pieṃ?","lit":"quatre · heures · thé · buvons ?"}]},{"title":"Comparer les choses","phrases":[{"fr":"Mumbai est une plus grande ville que Pune.","tgt":"मुंबई पुणे से बड़ा शहर है।","ro":"Mumbaī Puṇe se baṛā shahar hai.","lit":"Mumbai · Pune · [depuis] · grande · ville · est"},{"fr":"Mon frère est plus grand que moi.","tgt":"मेरा भाई मुझसे लंबा है।","ro":"Merā bhāī mujhse lambā hai.","lit":"mon · frère · moi-[depuis] · grand · est"},{"fr":"J'aime la mer plus que la montagne.","tgt":"मुझे पहाड़ों से ज़्यादा समुद्र पसंद है।","ro":"Mujhe pahāṛoṃ se zyādā samudra pasand hai.","lit":"moi-[à] · montagnes · [depuis] · plus · mer · agréable · est"},{"fr":"Le vada pav est plus épicé que le pav bhaji.","tgt":"वड़ा पाव पाव भाजी से ज़्यादा तीखा है।","ro":"Vaṛā pāv pāv bhājī se zyādā tīkhā hai.","lit":"vada pav · pav bhaji · [depuis] · plus · épicé · est"},{"fr":"Il fait plus chaud qu'hier.","tgt":"आज कल से ज़्यादा गर्मी है।","ro":"Āj kal se zyādā garmī hai.","lit":"aujourd'hui · hier · [depuis] · plus · chaleur · est"},{"fr":"Le train va plus vite que le bus.","tgt":"ट्रेन बस से तेज़ है।","ro":"Ṭren bas se tez hai.","lit":"train · bus · [depuis] · rapide · est"},{"fr":"Priya parle plus vite que moi.","tgt":"प्रिया मुझसे ज़्यादा तेज़ बोलती है।","ro":"Priyā mujhse zyādā tez boltī hai.","lit":"Priya · moi-[depuis] · plus · vite · parle"},{"fr":"Qui est l'aîné, toi ou ton frère ?","tgt":"कौन बड़ा है, तुम या तुम्हारा भाई?","ro":"Kaun baṛā hai, tum yā tumhārā bhāī?","lit":"qui · grand · est · toi · ou · ton · frère ?"},{"fr":"Juhu est plus calme que Colaba.","tgt":"जुहू कोलाबा से ज़्यादा शांत है।","ro":"Juhū Kolābā se zyādā shānt hai.","lit":"Juhu · Colaba · [depuis] · plus · calme · est"},{"fr":"Ce film est meilleur que l'autre.","tgt":"यह फ़िल्म दूसरी वाली से बेहतर है।","ro":"Yah film dūsrī vālī se behtar hai.","lit":"ce · film · autre · celui · [depuis] · meilleur · est"}],"tip":{"title":"Comparer avec « se zyādā »","example":"J'aime la mer plus que la montagne. — मुझे पहाड़ों <b>से</b> <b>ज़्यादा</b> समुद्र पसंद है।","body":"Pour comparer, le hindi n'a pas besoin d'un mot comme « plus » placé avant l'adjectif. On met simplement « se », qui veut dire « depuis » ou « par rapport à », après la chose avec laquelle on compare. « Mumbaī Puṇe se baṛā shahar hai » veut dire Mumbai est une plus grande ville que Pune, mot à mot Mumbai Pune par rapport à grande ville est. On peut ajouter « zyādā », plus, pour bien marquer la différence : « mujhe pahāṛoṃ se zyādā samudra pasand hai », j'aime la mer plus que la montagne. L'ordre est donc l'inverse du français : d'abord ce à quoi on compare, puis « se », puis la qualité. Avec moi, « se » se colle au mot et donne « mujhse » : « merā bhāī mujhse lambā hai », mon frère est plus grand que moi. Astuce : entendez « se » comme « à côté de » : à côté de Pune, Mumbai est grande.","exampleRo":"Mujhe pahāṛoṃ se zyādā samudra pasand hai.","lit":"moi-[à] · montagnes · [depuis] · plus · mer · agréable · est","say":{"se zyādā":"से ज़्यादा","se":"से","Mumbaī Puṇe se baṛā shahar hai":"मुंबई पुणे से बड़ा शहर है","zyādā":"ज़्यादा","mujhe pahāṛoṃ se zyādā samudra pasand hai":"मुझे पहाड़ों से ज़्यादा समुद्र पसंद है","mujhse":"मुझसे","merā bhāī mujhse lambā hai":"मेरा भाई मुझसे लंबा है"}}},{"title":"Un film de Bollywood","phrases":[{"fr":"On va au cinéma ce soir ?","tgt":"आज रात सिनेमा चलें?","ro":"Āj rāt sinemā chaleṃ?","lit":"aujourd'hui · nuit · cinéma · allons ?"},{"fr":"Il y a un nouveau film de Bollywood.","tgt":"एक नई बॉलीवुड फ़िल्म आई है।","ro":"Ek naī Bolīvuḍ film āī hai.","lit":"un · nouveau · Bollywood · film · venu · est"},{"fr":"C'est une histoire d'amour ?","tgt":"क्या यह प्यार की कहानी है?","ro":"Kyā yah pyār kī kahānī hai?","lit":"[question] · ceci · amour · [de] · histoire · est ?"},{"fr":"Oui, avec plein de chansons.","tgt":"हाँ, बहुत सारे गानों के साथ।","ro":"Hāṃ, bahut sāre gānoṃ ke sāth.","lit":"oui · beaucoup · toutes · chansons · [de] · avec"},{"fr":"Le film démarre à neuf heures.","tgt":"शो नौ बजे शुरू होता है।","ro":"Sho nau baje shurū hotā hai.","lit":"séance · neuf · heures · début · se fait"},{"fr":"Je m'occupe des billets.","tgt":"मैं टिकट लेता हूँ।","ro":"Maiṃ ṭikaṭ letā hūṃ.","lit":"je · billets · prends"},{"fr":"Le film dure trois heures.","tgt":"फ़िल्म तीन घंटे की है।","ro":"Film tīn ghaṇṭe kī hai.","lit":"film · trois · heures · [de] · est"},{"fr":"Il y a un entracte au milieu.","tgt":"बीच में इंटरवल होता है।","ro":"Bīch meṃ inṭarval hotā hai.","lit":"milieu · [dans] · entracte · se fait"},{"fr":"Le héros danse vraiment bien.","tgt":"हीरो बहुत अच्छा नाचता है।","ro":"Hīro bahut achchhā nāchtā hai.","lit":"héros · très · bien · danse"},{"fr":"Les chansons sont magnifiques.","tgt":"गाने बहुत सुंदर हैं।","ro":"Gāne bahut sundar haiṃ.","lit":"chansons · très · belles · sont"}]},{"title":"Expliquer ses raisons","phrases":[{"fr":"Pourquoi tu es fatigué ?","tgt":"तुम थके हुए क्यों हो?","ro":"Tum thake hue kyoṃ ho?","lit":"tu · fatigué · étant · pourquoi · es ?"},{"fr":"Parce que je travaille beaucoup.","tgt":"क्योंकि मैं बहुत काम करता हूँ।","ro":"Kyoṃki maiṃ bahut kām kartā hūṃ.","lit":"parce que · je · beaucoup · travail · fais"},{"fr":"J'aime Mumbai parce qu'il y a la mer.","tgt":"मुझे मुंबई पसंद है क्योंकि यहाँ समुद्र है।","ro":"Mujhe Mumbaī pasand hai kyoṃki yahāṃ samudra hai.","lit":"moi-[à] · Mumbai · agréable · est · parce que · ici · mer · est"},{"fr":"Je ne viens pas, parce que je suis malade.","tgt":"मैं नहीं आ रहा, क्योंकि मैं बीमार हूँ।","ro":"Maiṃ nahīṃ ā rahā, kyoṃki maiṃ bīmār hūṃ.","lit":"je · pas · venir · en train · parce que · je · malade · suis"},{"fr":"Pourquoi tu apprends le hindi ?","tgt":"तुम हिंदी क्यों सीखते हो?","ro":"Tum hindī kyoṃ sīkhte ho?","lit":"tu · hindi · pourquoi · apprends ?"},{"fr":"Parce que je vis en Inde.","tgt":"क्योंकि मैं भारत में रहता हूँ।","ro":"Kyoṃki maiṃ Bhārat meṃ rahtā hūṃ.","lit":"parce que · je · Inde · [dans] · habite"},{"fr":"Je prends le train, parce que c'est rapide.","tgt":"मैं ट्रेन लेता हूँ क्योंकि वह तेज़ है।","ro":"Maiṃ ṭren letā hūṃ kyoṃki vah tez hai.","lit":"je · train · prends · parce que · il · rapide · est"},{"fr":"Rahul est content parce que l'Inde gagne.","tgt":"राहुल ख़ुश है क्योंकि भारत जीत रहा है।","ro":"Rāhul khush hai kyoṃki Bhārat jīt rahā hai.","lit":"Rahul · content · est · parce que · Inde · gagner · en train · est"},{"fr":"Pourquoi tu ne manges pas ?","tgt":"तुम क्यों नहीं खा रहे?","ro":"Tum kyoṃ nahīṃ khā rahe?","lit":"tu · pourquoi · pas · manger · en train ?"},{"fr":"Parce que je n'ai pas faim.","tgt":"क्योंकि मुझे भूख नहीं है।","ro":"Kyoṃki mujhe bhūkh nahīṃ hai.","lit":"parce que · moi-[à] · faim · pas · est"}],"tip":{"title":"« Kyoṃki » : parce que","example":"Parce que je travaille beaucoup. — <b>क्योंकि</b> मैं बहुत काम करता हूँ।","body":"Pour expliquer une raison, on utilise « kyoṃki », qui veut dire parce que. Bonne nouvelle, il s'emploie presque comme en français, au début de l'explication. À la question « tum thake hue kyoṃ ho ? », pourquoi es-tu fatigué, on répond « kyoṃki maiṃ bahut kām kartā hūṃ », parce que je travaille beaucoup, mot à mot parce que je beaucoup travail fais. On peut aussi relier deux idées dans une seule phrase : « mujhe Mumbaī pasand hai kyoṃki yahāṃ samudra hai », j'aime Mumbai parce qu'il y a la mer. Notez la parenté entre « kyoṃ », pourquoi, et « kyoṃki », parce que : la réponse ressemble à la question, avec juste un petit « ki » en plus. Côté prononciation, le « o » est long et légèrement nasal, et le « ki » final est bref. Astuce : pensez à un écho, on demande « kyoṃ » et on répond « kyoṃki ».","exampleRo":"Kyoṃki maiṃ bahut kām kartā hūṃ.","lit":"parce que · je · beaucoup · travail · fais","say":{"Kyoṃki":"क्योंकि","kyoṃki":"क्योंकि","tum thake hue kyoṃ ho ?":"तुम थके हुए क्यों हो?","kyoṃki maiṃ bahut kām kartā hūṃ":"क्योंकि मैं बहुत काम करता हूँ","mujhe Mumbaī pasand hai kyoṃki yahāṃ samudra hai":"मुझे मुंबई पसंद है क्योंकि यहाँ समुद्र है","kyoṃ":"क्यों","ki":"कि"}}},{"title":"Un match de cricket","phrases":[{"fr":"Le match commence à deux heures.","tgt":"मैच दो बजे शुरू होता है।","ro":"Maich do baje shurū hotā hai.","lit":"match · deux · heures · début · se fait"},{"fr":"Viens le regarder avec nous.","tgt":"हमारे साथ देखने आओ।","ro":"Hamāre sāth dekhne āo.","lit":"nous · [de] · avec · regarder · viens"},{"fr":"Qui joue aujourd'hui ?","tgt":"आज कौन खेल रहा है?","ro":"Āj kaun khel rahā hai?","lit":"aujourd'hui · qui · jouer · en train · est ?"},{"fr":"Mumbai joue contre Chennai.","tgt":"मुंबई चेन्नई के ख़िलाफ़ खेल रहा है।","ro":"Mumbaī Chennaī ke khilāf khel rahā hai.","lit":"Mumbai · Chennai · [de] · contre · jouer · en train · est"},{"fr":"Quel est le score ?","tgt":"स्कोर क्या है?","ro":"Skor kyā hai?","lit":"score · quoi · est ?"},{"fr":"Cent vingt pour trois guichets.","tgt":"तीन विकेट पर एक सौ बीस।","ro":"Tīn vikeṭ par ek sau bīs.","lit":"trois · guichets · [sur] · un · cent · vingt"},{"fr":"Un six magnifique !","tgt":"बहुत शानदार छक्का।","ro":"Bahut shāndār chhakkā.","lit":"très · magnifique · six"},{"fr":"Mon joueur préféré, c'est le capitaine.","tgt":"मेरा पसंदीदा खिलाड़ी कप्तान है।","ro":"Merā pasandīdā khilāṛī kaptān hai.","lit":"mon · préféré · joueur · capitaine · est"},{"fr":"Tu joues au cricket, toi aussi ?","tgt":"क्या तुम भी क्रिकेट खेलते हो?","ro":"Kyā tum bhī krikeṭ khelte ho?","lit":"[question] · tu · aussi · cricket · joues ?"},{"fr":"Oui, le dimanche sur la plage.","tgt":"हाँ, रविवार को बीच पर।","ro":"Hāṃ, ravivār ko bīch par.","lit":"oui · dimanche · [à] · plage · [sur]"}]},{"title":"Chez les parents d'un ami","phrases":[{"fr":"Bonjour, madame.","tgt":"नमस्ते आंटी जी।","ro":"Namaste ānṭī jī.","lit":"bonjour · tante · [respect]"},{"fr":"Voici le père de Rahul.","tgt":"ये राहुल के पिता जी हैं।","ro":"Ye Rāhul ke pitā jī haiṃ.","lit":"ceux-ci · Rahul · [de] · père · [respect] · sont"},{"fr":"Comment allez-vous, monsieur ?","tgt":"आप कैसे हैं, अंकल जी?","ro":"Āp kaise haiṃ, ankal jī?","lit":"vous · comment · êtes · oncle · [respect] ?"},{"fr":"Je vais très bien, merci.","tgt":"मैं बिल्कुल ठीक हूँ, शुक्रिया।","ro":"Maiṃ bilkul ṭhīk hūṃ, shukriyā.","lit":"je · tout à fait · bien · suis · merci"},{"fr":"Monsieur Sharma habite à côté.","tgt":"शर्मा जी पड़ोस में रहते हैं।","ro":"Sharmā jī paṛos meṃ rahte haiṃ.","lit":"Sharma · [respect] · voisinage · [dans] · habitent"},{"fr":"Oui, monsieur.","tgt":"जी हाँ।","ro":"Jī hāṃ.","lit":"[respect] · oui"},{"fr":"Grand-mère, voici Lucas.","tgt":"दादी जी, यह लुकास है।","ro":"Dādī jī, yah Lukās hai.","lit":"grand-mère · [respect] · ceci · Lucas · est"},{"fr":"Asseyez-vous, je vous en prie.","tgt":"बैठिए जी।","ro":"Baiṭhie jī.","lit":"asseyez-vous · [respect]"},{"fr":"Votre maison est très belle.","tgt":"आपका घर बहुत सुंदर है।","ro":"Āpkā ghar bahut sundar hai.","lit":"votre · maison · très · belle · est"},{"fr":"Merci mille fois, madame.","tgt":"बहुत-बहुत धन्यवाद, आंटी जी।","ro":"Bahut-bahut dhanyavād, ānṭī jī.","lit":"beaucoup-beaucoup · merci · tante · [respect]"}],"tip":{"title":"« -jī » : le petit mot de respect","example":"Monsieur Sharma habite à côté. — शर्मा <b>जी</b> पड़ोस में रहते हैं।","body":"« Jī » est le petit mot magique de la courtoisie en hindi. On l'ajoute après un nom, un titre ou même un simple oui pour montrer du respect. « Sharmā jī paṛos meṃ rahte haiṃ » veut dire monsieur Sharma habite à côté, mot à mot Sharma respect voisinage dans habitent. Avec les parents d'un ami, on dit volontiers « ānṭī jī » et « ankal jī », c'est à la fois affectueux et respectueux. Pour répondre poliment oui, on dit « jī hāṃ » ou « hāṃ jī », et « jī » tout seul peut même vouloir dire oui, je vous écoute. On peut aussi l'ajouter après une demande pour l'adoucir, comme dans « baiṭhie jī », asseyez-vous je vous en prie. Remarquez que le verbe passe aussi au pluriel de respect : « haiṃ » au lieu de « hai ». Astuce : en cas de doute avec une personne plus âgée, ajoutez « jī », vous ne vous tromperez jamais.","exampleRo":"Sharmā jī paṛos meṃ rahte haiṃ.","lit":"Sharma · [respect] · voisinage · [dans] · habitent","say":{"Jī":"जी","Sharmā jī paṛos meṃ rahte haiṃ":"शर्मा जी पड़ोस में रहते हैं","ānṭī jī":"आंटी जी","ankal jī":"अंकल जी","jī hāṃ":"जी हाँ","hāṃ jī":"हाँ जी","jī":"जी","baiṭhie jī":"बैठिए जी","haiṃ":"हैं","hai":"है","-jī":"जी"}}},{"title":"Inviter quelqu'un chez soi","phrases":[{"fr":"Tu es libre ce samedi soir ?","tgt":"क्या तुम शनिवार शाम को फ़्री हो?","ro":"Kyā tum shanivār shām ko frī ho?","lit":"[question] · tu · samedi · soir · [à] · libre · es ?"},{"fr":"Viens dîner à la maison.","tgt":"मेरे घर खाना खाने आओ।","ro":"Mere ghar khānā khāne āo.","lit":"ma · maison · repas · manger · viens"},{"fr":"Bien sûr, avec une grande joie.","tgt":"ज़रूर, बड़ी ख़ुशी से।","ro":"Zarūr, baṛī khushī se.","lit":"bien sûr · grande · joie · [depuis]"},{"fr":"À quelle heure je viens ?","tgt":"मैं कितने बजे आऊँ?","ro":"Maiṃ kitne baje āūṃ?","lit":"je · combien · heures · viens ?"},{"fr":"Vers huit heures, c'est parfait.","tgt":"आठ बजे के आसपास ठीक है।","ro":"Āṭh baje ke āspās ṭhīk hai.","lit":"huit · heures · [de] · environ · bien · est"},{"fr":"J'apporte quelque chose ?","tgt":"मैं कुछ लाऊँ?","ro":"Maiṃ kuchh lāūṃ?","lit":"je · quelque chose · apporte ?"},{"fr":"Non, viens juste avec Priya.","tgt":"नहीं, बस प्रिया के साथ आओ।","ro":"Nahīṃ, bas Priyā ke sāth āo.","lit":"non · juste · Priya · [de] · avec · viens"},{"fr":"Moi, j'habite au troisième étage.","tgt":"मैं तीसरी मंज़िल पर रहता हूँ।","ro":"Maiṃ tīsrī manzil par rahtā hūṃ.","lit":"je · troisième · étage · [sur] · habite"},{"fr":"Je prépare un repas français.","tgt":"मैं फ़्रांसीसी खाना बनाता हूँ।","ro":"Maiṃ frānsīsī khānā banātā hūṃ.","lit":"je · français · repas · fais"},{"fr":"Super, on se voit samedi.","tgt":"बढ़िया, शनिवार को मिलते हैं।","ro":"Baṛhiyā, shanivār ko milte haiṃ.","lit":"super · samedi · [à] · nous rencontrons"}]},{"title":"Offrir un cadeau","phrases":[{"fr":"Demain, c'est l'anniversaire de Priya.","tgt":"कल प्रिया का जन्मदिन है।","ro":"Kal Priyā kā janmadin hai.","lit":"demain · Priya · [de] · anniversaire · est"},{"fr":"J'offre un livre à Priya.","tgt":"मैं प्रिया को एक किताब दे रहा हूँ।","ro":"Maiṃ Priyā ko ek kitāb de rahā hūṃ.","lit":"je · Priya · [à] · un · livre · donner · en train · suis"},{"fr":"Qu'est-ce que tu offres à Rahul ?","tgt":"तुम राहुल को क्या दे रहे हो?","ro":"Tum Rāhul ko kyā de rahe ho?","lit":"tu · Rahul · [à] · quoi · donner · en train · es ?"},{"fr":"Je lui offre une montre.","tgt":"मैं उसको एक घड़ी दे रहा हूँ।","ro":"Maiṃ usko ek ghaṛī de rahā hūṃ.","lit":"je · lui-[à] · une · montre · donner · en train · suis"},{"fr":"Donne ce cadeau à ta mère.","tgt":"यह तोहफ़ा अपनी माँ को दो।","ro":"Yah tohfā apnī māṃ ko do.","lit":"ce · cadeau · ta propre · maman · [à] · donne"},{"fr":"Je téléphone à Neha chaque soir.","tgt":"मैं हर शाम नेहा को फ़ोन करता हूँ।","ro":"Maiṃ har shām Nehā ko fon kartā hūṃ.","lit":"je · chaque · soir · Neha · [à] · téléphone · fais"},{"fr":"Ma sœur adore les fleurs.","tgt":"मेरी बहन को फूल पसंद हैं।","ro":"Merī bahan ko phūl pasand haiṃ.","lit":"ma · sœur · [à] · fleurs · agréables · sont"},{"fr":"Rahul a besoin d'un nouveau téléphone.","tgt":"राहुल को नया फ़ोन चाहिए।","ro":"Rāhul ko nayā fon chāhie.","lit":"Rahul · [à] · nouveau · téléphone · faut"},{"fr":"Je fais visiter la plage à mes parents.","tgt":"मैं अपने माता-पिता को बीच दिखाता हूँ।","ro":"Maiṃ apne mātā-pitā ko bīch dikhātā hūṃ.","lit":"je · mes propres · mère-père · [à] · plage · montre"},{"fr":"Le cadeau plaît beaucoup à Priya.","tgt":"प्रिया को तोहफ़ा बहुत पसंद है।","ro":"Priyā ko tohfā bahut pasand hai.","lit":"Priya · [à] · cadeau · très · agréable · est"}],"tip":{"title":"« Ko » : à, pour quelqu'un","example":"J'offre un livre à Priya. — मैं प्रिया <b>को</b> एक किताब दे रहा हूँ।","body":"La petite postposition « ko » correspond souvent au français « à » quand on parle d'une personne qui reçoit quelque chose. Comme toutes les postpositions, elle se place après le nom, et non avant comme en français. « Maiṃ Priyā ko ek kitāb de rahā hūṃ » se décompose ainsi : je, Priya à, un livre, donner en train, suis. On dira de la même façon « Rāhul ko nayā fon chāhie », Rahul a besoin d'un nouveau téléphone, mot à mot à Rahul nouveau téléphone faut. Vous connaissez déjà « ko » sans le savoir : « mujhe », à moi, est la forme courte de « mujh ko », et « tumheṃ » celle de « tum ko ». C'est pourquoi on dit « merī bahan ko phūl pasand haiṃ », les fleurs plaisent à ma sœur. Astuce : imaginez « ko » comme une petite flèche qui montre la personne qui reçoit le cadeau.","exampleRo":"Maiṃ Priyā ko ek kitāb de rahā hūṃ.","lit":"je · Priya · [à] · un · livre · donner · en train · suis","say":{"Ko":"को","ko":"को","Maiṃ Priyā ko ek kitāb de rahā hūṃ":"मैं प्रिया को एक किताब दे रहा हूँ","Rāhul ko nayā fon chāhie":"राहुल को नया फ़ोन चाहिए","mujhe":"मुझे","mujh ko":"मुझ को","tumheṃ":"तुम्हें","tum ko":"तुम को","merī bahan ko phūl pasand haiṃ":"मेरी बहन को फूल पसंद हैं"}}},{"title":"Les loisirs du week-end","phrases":[{"fr":"Que fais-tu les jours de congé ?","tgt":"तुम छुट्टी के दिन क्या करते हो?","ro":"Tum chhuṭṭī ke din kyā karte ho?","lit":"tu · congé · [de] · jour · quoi · fais ?"},{"fr":"Je lis et je me balade.","tgt":"मैं पढ़ता हूँ और घूमता हूँ।","ro":"Maiṃ paṛhtā hūṃ aur ghūmtā hūṃ.","lit":"je · lis · suis · et · me promène · suis"},{"fr":"Le dimanche, je vais nager.","tgt":"रविवार को मैं तैरता हूँ।","ro":"Ravivār ko maiṃ tairtā hūṃ.","lit":"dimanche · [à] · je · nage · suis"},{"fr":"Tu fais de l'exercice ?","tgt":"क्या तुम कसरत करते हो?","ro":"Kyā tum kasrat karte ho?","lit":"[question] · tu · exercice · fais ?"},{"fr":"Oui, je cours sur la plage le matin.","tgt":"हाँ, मैं सुबह बीच पर दौड़ता हूँ।","ro":"Hāṃ, maiṃ subah bīch par dauṛtā hūṃ.","lit":"oui · je · matin · plage · [sur] · cours"},{"fr":"Ma sœur chante très bien.","tgt":"मेरी बहन बहुत अच्छा गाती है।","ro":"Merī bahan bahut achchhā gātī hai.","lit":"ma · sœur · très · bien · chante"},{"fr":"J'apprends la guitare en ce moment.","tgt":"मैं गिटार सीख रहा हूँ।","ro":"Maiṃ giṭār sīkh rahā hūṃ.","lit":"je · guitare · apprendre · en train · suis"},{"fr":"Tu aimes danser ?","tgt":"क्या तुम्हें नाचना पसंद है?","ro":"Kyā tumheṃ nāchnā pasand hai?","lit":"[question] · toi-[à] · danser · agréable · est ?"},{"fr":"Un peu, mais je ne danse pas bien.","tgt":"थोड़ा, लेकिन मैं अच्छा नहीं नाचता।","ro":"Thoṛā, lekin maiṃ achchhā nahīṃ nāchtā.","lit":"un peu · mais · je · bien · pas · danse"},{"fr":"Le soir, on se promène sur Marine Drive.","tgt":"शाम को हम मरीन ड्राइव पर घूमते हैं।","ro":"Shām ko ham Marīn Ḍrāiv par ghūmte haiṃ.","lit":"soir · [à] · nous · Marine Drive · [sur] · nous promenons"}]},{"title":"Donner son avis","phrases":[{"fr":"Ce film est très long.","tgt":"यह फ़िल्म बहुत लंबी है।","ro":"Yah film bahut lambī hai.","lit":"ce · film · très · long · est"},{"fr":"Il fait beaucoup trop chaud aujourd'hui.","tgt":"आज बहुत ज़्यादा गर्मी है।","ro":"Āj bahut zyādā garmī hai.","lit":"aujourd'hui · très · trop · chaleur · est"},{"fr":"Le vada pav est très bon.","tgt":"वड़ा पाव बहुत अच्छा है।","ro":"Vaṛā pāv bahut achchhā hai.","lit":"vada pav · très · bon · est"},{"fr":"C'est trop épicé pour moi.","tgt":"यह मेरे लिए ज़्यादा तीखा है।","ro":"Yah mere lie zyādā tīkhā hai.","lit":"ceci · moi · [de] · pour · trop · épicé · est"},{"fr":"Tu travailles beaucoup trop.","tgt":"तुम बहुत ज़्यादा काम करते हो।","ro":"Tum bahut zyādā kām karte ho.","lit":"tu · très · trop · travail · fais"},{"fr":"Il y a trop de monde dans le train.","tgt":"ट्रेन में बहुत ज़्यादा भीड़ है।","ro":"Ṭren meṃ bahut zyādā bhīṛ hai.","lit":"train · [dans] · très · trop · foule · est"},{"fr":"Ton cadeau est très joli.","tgt":"तुम्हारा तोहफ़ा बहुत सुंदर है।","ro":"Tumhārā tohfā bahut sundar hai.","lit":"ton · cadeau · très · beau · est"},{"fr":"Ne mange pas trop !","tgt":"ज़्यादा मत खाओ।","ro":"Zyādā mat khāo.","lit":"trop · ne pas · mange"},{"fr":"Le cricket me plaît énormément.","tgt":"मुझे क्रिकेट बहुत ज़्यादा पसंद है।","ro":"Mujhe krikeṭ bahut zyādā pasand hai.","lit":"moi-[à] · cricket · très · beaucoup · agréable · est"},{"fr":"Ce n'est pas trop cher.","tgt":"यह ज़्यादा महँगा नहीं है।","ro":"Yah zyādā mahaṃgā nahīṃ hai.","lit":"ceci · trop · cher · pas · est"}],"tip":{"title":"« Bahut » et « zyādā » : très et trop","example":"Il fait beaucoup trop chaud aujourd'hui. — आज <b>बहुत</b> <b>ज़्यादा</b> गर्मी है।","body":"« Bahut » veut dire très ou beaucoup, et « zyādā » veut dire plus ou trop. « Yah film bahut lambī hai », ce film est très long, mot à mot ce film très long est. Avec « zyādā », on dit qu'il y en a trop : « yah mere lie zyādā tīkhā hai », c'est trop épicé pour moi. Très souvent, on combine les deux pour insister : « bahut zyādā » veut dire vraiment trop ou énormément, comme dans « āj bahut zyādā garmī hai », il fait beaucoup trop chaud aujourd'hui. Avec un verbe, ces mots se placent avant l'action : « tum bahut zyādā kām karte ho », tu travailles beaucoup trop. Et pour un conseil amical, « zyādā mat khāo » veut dire ne mange pas trop. Astuce : « bahut », c'est beaucoup, « zyādā », c'est en plus, et les deux ensemble, c'est le maximum.","exampleRo":"Āj bahut zyādā garmī hai.","lit":"aujourd'hui · très · trop · chaleur · est","say":{"Bahut":"बहुत","zyādā":"ज़्यादा","Yah film bahut lambī hai":"यह फ़िल्म बहुत लंबी है","yah mere lie zyādā tīkhā hai":"यह मेरे लिए ज़्यादा तीखा है","bahut zyādā":"बहुत ज़्यादा","āj bahut zyādā garmī hai":"आज बहुत ज़्यादा गर्मी है","tum bahut zyādā kām karte ho":"तुम बहुत ज़्यादा काम करते हो","zyādā mat khāo":"ज़्यादा मत खाओ","bahut":"बहुत"}}},{"title":"Se dire au revoir","phrases":[{"fr":"Il est tard, je dois rentrer.","tgt":"देर हो गई है, मुझे घर जाना है।","ro":"Der ho gaī hai, mujhe ghar jānā hai.","lit":"retard · devenu · est · moi-[à] · maison · aller · est"},{"fr":"C'était une très bonne soirée.","tgt":"बहुत अच्छी शाम थी।","ro":"Bahut achchhī shām thī.","lit":"très · bonne · soirée · était"},{"fr":"Merci pour ce bon repas.","tgt":"खाने के लिए शुक्रिया।","ro":"Khāne ke lie shukriyā.","lit":"repas · [de] · pour · merci"},{"fr":"On se voit demain au bureau.","tgt":"कल दफ़्तर में मिलते हैं।","ro":"Kal daftar meṃ milte haiṃ.","lit":"demain · bureau · [dans] · nous rencontrons"},{"fr":"Appelle-moi en arrivant.","tgt":"पहुँचकर फ़ोन करना।","ro":"Pahuṃchkar fon karnā.","lit":"étant arrivé · téléphone · faire"},{"fr":"Fais attention sur la route.","tgt":"रास्ते में ध्यान रखना।","ro":"Rāste meṃ dhyān rakhnā.","lit":"route · [dans] · attention · garder"},{"fr":"Salue tes parents de ma part.","tgt":"अपने माता-पिता को मेरा नमस्ते कहना।","ro":"Apne mātā-pitā ko merā namaste kahnā.","lit":"tes propres · mère-père · [à] · mon · bonjour · dire"},{"fr":"À la prochaine !","tgt":"फिर मिलेंगे।","ro":"Phir milenge.","lit":"encore · nous rencontrerons"},{"fr":"Bonne nuit, Priya.","tgt":"शुभ रात्रि, प्रिया।","ro":"Shubh rātri, Priyā.","lit":"bonne · nuit · Priya"},{"fr":"Prends bien soin de toi.","tgt":"अपना ख़्याल रखना।","ro":"Apnā khyāl rakhnā.","lit":"ton propre · soin · garder"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Bon, c'est la dernière leçon.","tgt":"अच्छा, यह आख़िरी पाठ है।","ro":"Achchhā, yah ākhirī pāṭh hai.","lit":"bon · ceci · dernière · leçon · est"},{"fr":"Maintenant, je parle un peu le hindi.","tgt":"अब मैं थोड़ी हिंदी बोलता हूँ।","ro":"Ab maiṃ thoṛī hindī boltā hūṃ.","lit":"maintenant · je · un peu · hindi · parle"},{"fr":"Je sais me présenter en hindi.","tgt":"मैं हिंदी में अपना परिचय दे सकता हूँ।","ro":"Maiṃ hindī meṃ apnā parichay de saktā hūṃ.","lit":"je · hindi · [dans] · ma propre · présentation · donner · peux"},{"fr":"Je parle de la famille et du travail.","tgt":"मैं परिवार और काम की बात करता हूँ।","ro":"Maiṃ parivār aur kām kī bāt kartā hūṃ.","lit":"je · famille · et · travail · [de] · parole · fais"},{"fr":"Le hindi, c'est difficile ?","tgt":"क्या हिंदी मुश्किल है?","ro":"Kyā hindī mushkil hai?","lit":"[question] · hindi · difficile · est ?"},{"fr":"Un peu, mais ça va.","tgt":"थोड़ी, पर ठीक है।","ro":"Thoṛī, par ṭhīk hai.","lit":"un peu · mais · bien · est"},{"fr":"Ah bon, tu comprends le hindi ?","tgt":"अच्छा, तुम हिंदी समझते हो?","ro":"Achchhā, tum hindī samajhte ho?","lit":"ah bon · tu · hindi · comprends ?"},{"fr":"Oui, petit à petit.","tgt":"हाँ जी, थोड़ी-थोड़ी।","ro":"Hāṃ jī, thoṛī-thoṛī.","lit":"oui · [respect] · un peu-un peu"},{"fr":"D'accord, on passe au niveau suivant.","tgt":"ठीक है, अब अगले लेवल पर चलते हैं।","ro":"Ṭhīk hai, ab agle leval par chalte haiṃ.","lit":"bien · est · maintenant · suivant · niveau · [sur] · allons"},{"fr":"Bravo, et à très vite !","tgt":"शाबाश, जल्दी मिलते हैं।","ro":"Shābāsh, jaldī milte haiṃ.","lit":"bravo · bientôt · nous rencontrons"}],"tip":{"title":"« Achchhā », « ṭhīk hai », « hāṃ jī » : les mots de la conversation","example":"Ah bon, tu comprends le hindi ? — <b>अच्छा</b>, तुम हिंदी समझते हो?","body":"Dans une conversation en hindi, trois petites expressions reviennent sans arrêt. « Achchhā » veut dire bon ou bien, mais avec une intonation montante, il signifie « ah bon ? » ou « vraiment ? » : « achchhā, tum hindī samajhte ho ? », ah bon, tu comprends le hindi ? « Ṭhīk hai », mot à mot bien est, c'est notre « d'accord » ou « ça va » : on l'utilise pour accepter, pour rassurer ou pour clore une discussion. « Hāṃ jī » est un oui poli et chaleureux, très pratique avec les personnes qu'on respecte. En les glissant dans vos phrases, vous paraîtrez tout de suite plus naturel, car ce sont les mots qui font respirer la conversation. Écoutez bien autour de vous à Mumbai : vous entendrez « achchhā » et « ṭhīk hai » plusieurs fois par minute. Astuce : entraînez-vous à répondre « achchhā » en montant la voix, puis « ṭhīk hai » d'un ton calme, et vous aurez déjà l'air d'un habitué.","exampleRo":"Achchhā, tum hindī samajhte ho?","lit":"ah bon · tu · hindi · comprends ?","say":{"Achchhā":"अच्छा","ṭhīk hai":"ठीक है","hāṃ jī":"हाँ जी","achchhā, tum hindī samajhte ho ?":"अच्छा, तुम हिंदी समझते हो?","Ṭhīk hai":"ठीक है","Hāṃ jī":"हाँ जी","achchhā":"अच्छा"}}}]}]},{"id":2,"name":"Niveau 2","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours, avec un vocabulaire plus riche.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Un nouvel appartement à Bangalore","phrases":[{"fr":"Nous venons de nous installer dans un appartement à Bangalore.","tgt":"हम हाल ही में बेंगलुरु के एक फ़्लैट में शिफ़्ट हुए हैं।","ro":"Ham hāl hī meṃ Bengaluru ke ek flaiṭ meṃ shifṭ hue haiṃ."},{"fr":"L'appartement se trouve au troisième étage.","tgt":"फ़्लैट तीसरी मंज़िल पर है।","ro":"Flaiṭ tīsrī manzil par hai."},{"fr":"Il y a deux chambres et un petit balcon.","tgt":"इसमें दो कमरे और एक छोटी बालकनी है।","ro":"Ismeṃ do kamre aur ek chhoṭī bālkanī hai."},{"fr":"Le loyer est de vingt mille roupies par mois.","tgt":"किराया बीस हज़ार रुपये महीना है।","ro":"Kirāyā bīs hazār rupaye mahīnā hai."},{"fr":"Le propriétaire habite juste en dessous.","tgt":"मकान-मालिक ठीक नीचे रहते हैं।","ro":"Makān-mālik ṭhīk nīche rahte haiṃ."},{"fr":"Il faut verser trois mois de loyer à l'avance.","tgt":"तीन महीने का किराया पहले जमा करना पड़ता है।","ro":"Tīn mahīne kā kirāyā pahle jamā karnā paṛtā hai."},{"fr":"L'eau n'arrive que le matin.","tgt":"पानी सिर्फ़ सुबह आता है।","ro":"Pānī sirf subah ātā hai."},{"fr":"Le quartier est calme et plein d'arbres.","tgt":"मोहल्ला शांत है और यहाँ बहुत पेड़ हैं।","ro":"Mohallā shānt hai aur yahāṃ bahut peṛ haiṃ."},{"fr":"Il nous manque encore un lit et une table.","tgt":"हमें अभी भी एक पलंग और एक मेज़ चाहिए।","ro":"Hameṃ abhī bhī ek palang aur ek mez chāhie."},{"fr":"Je crois que nous serons heureux ici.","tgt":"मुझे लगता है कि हम यहाँ ख़ुश रहेंगे।","ro":"Mujhe lagtā hai ki ham yahāṃ khush raheṃge."}]},{"title":"Hier soir chez les voisins","phrases":[{"fr":"Hier soir, nos voisins nous ont invités à dîner.","tgt":"कल रात पड़ोसियों ने हमें खाने पर बुलाया।","ro":"Kal rāt paṛosiyoṃ ne hameṃ khāne par bulāyā."},{"fr":"Leur fille a préparé des dosas.","tgt":"उनकी बेटी ने डोसे बनाए।","ro":"Unkī beṭī ne ḍose banāe."},{"fr":"J'ai mangé trois dosas, un après l'autre.","tgt":"मैंने एक के बाद एक तीन डोसे खाए।","ro":"Maiṃne ek ke bād ek tīn ḍose khāe."},{"fr":"Ma femme a bu un thé bien chaud.","tgt":"मेरी पत्नी ने गरम चाय पी।","ro":"Merī patnī ne garam chāy pī."},{"fr":"Et vous, qu'est-ce que vous avez mangé hier ?","tgt":"और आपने कल क्या खाया?","ro":"Aur āpne kal kyā khāyā?"},{"fr":"Après le repas, nous avons regardé un film ensemble.","tgt":"खाने के बाद हमने साथ में एक फ़िल्म देखी।","ro":"Khāne ke bād hamne sāth meṃ ek film dekhī."},{"fr":"Le voisin m'a raconté une histoire drôle.","tgt":"पड़ोसी ने मुझे एक मज़ेदार कहानी सुनाई।","ro":"Paṛosī ne mujhe ek mazedār kahānī sunāī."},{"fr":"Nous sommes rentrés chez nous à minuit.","tgt":"हम आधी रात को घर लौटे।","ro":"Ham ādhī rāt ko ghar lauṭe."},{"fr":"J'ai fermé la porte et éteint la lumière.","tgt":"मैंने दरवाज़ा बंद किया और बत्ती बुझाई।","ro":"Maiṃne darvāzā band kiyā aur battī bujhāī."},{"fr":"C'était vraiment une soirée agréable.","tgt":"वह सचमुच बहुत अच्छी शाम थी।","ro":"Vah sachmuch bahut achchhī shām thī."}],"tip":{"title":"Le passé avec « ne » : « maiṃ ne khāyā »","example":"J'ai mangé trois dosas, un après l'autre. — <b>मैंने</b> एक के बाद एक तीन डोसे <b>खाए</b>।","body":"Pour raconter ce qu'on a fait avec un verbe qui a un complément, comme manger, voir ou acheter, le hindi ajoute la petite particule « ne » juste après celui qui agit : « maiṃ » devient « maiṃne », « āp » devient « āpne », « ham » devient « hamne ». Le plus surprenant, c'est que le verbe s'accorde alors avec la chose, pas avec la personne : « maiṃne ḍose khāe », j'ai mangé des dosas, mais « maiṃne roṭī khāī », j'ai mangé une galette, car « roṭī » est féminin. C'est un peu comme en français dans « la galette que j'ai mangée », où l'accord suit l'objet. Décomposons « āpne kyā khāyā » : vous avec « ne », quoi, mangé, c'est-à-dire qu'avez-vous mangé ? Les verbes de mouvement comme aller ou rentrer ne prennent jamais « ne » : on dit « ham ghar lauṭe », nous sommes rentrés. Astuce : quand le verbe français se conjugue avec être, oubliez « ne ».","exampleRo":"Maiṃne ek ke bād ek tīn ḍose khāe.","lit":"moi [ne] · un · [de] après · un · trois · dosas · mangés","say":{"ne":"ने","maiṃ":"मैं","maiṃne":"मैंने","āp":"आप","āpne":"आपने","ham":"हम","hamne":"हमने","maiṃne ḍose khāe":"मैंने डोसे खाए","maiṃne roṭī khāī":"मैंने रोटी खाई","roṭī":"रोटी","āpne kyā khāyā":"आपने क्या खाया","ham ghar lauṭe":"हम घर लौटे","maiṃ ne khāyā":"मैंने खाया"}}},{"title":"Une carte SIM pour le téléphone","phrases":[{"fr":"J'ai besoin d'une nouvelle carte SIM.","tgt":"मुझे एक नया सिम कार्ड चाहिए।","ro":"Mujhe ek nayā sim kārḍ chāhie."},{"fr":"Avez-vous apporté votre passeport ?","tgt":"क्या आप अपना पासपोर्ट लाए हैं?","ro":"Kyā āp apnā pāsporṭ lāe haiṃ?"},{"fr":"Oui, et voici aussi une photo de moi.","tgt":"हाँ, और यह रही मेरी एक फ़ोटो।","ro":"Hāṃ, aur yah rahī merī ek foṭo."},{"fr":"Quel forfait me conseillez-vous ?","tgt":"आप कौन-सा प्लान सुझाएँगे?","ro":"Āp kaun-sā plān sujhāeṃge?"},{"fr":"Celui-ci offre deux gigas d'internet par jour.","tgt":"इसमें रोज़ दो जीबी इंटरनेट मिलता है।","ro":"Ismeṃ roz do jībī inṭarneṭ miltā hai."},{"fr":"Ça coûte combien pour trois mois ?","tgt":"तीन महीने के लिए कितने पैसे लगेंगे?","ro":"Tīn mahīne ke lie kitne paise lageṃge?"},{"fr":"Environ sept cents roupies.","tgt":"लगभग सात सौ रुपये।","ro":"Lagbhag sāt sau rupaye."},{"fr":"La carte sera activée dans quelques heures.","tgt":"कार्ड कुछ घंटों में चालू हो जाएगा।","ro":"Kārḍ kuchh ghanṭoṃ meṃ chālū ho jāegā."},{"fr":"Un message arrivera alors sur votre téléphone.","tgt":"फिर आपके फ़ोन पर एक संदेश आएगा।","ro":"Phir āpke fon par ek sandesh āegā."},{"fr":"Parfait, je pourrai enfin appeler ma famille en France.","tgt":"बढ़िया, अब मैं आख़िरकार फ़्रांस में अपने परिवार को फ़ोन कर सकूँगा।","ro":"Baṛhiyā, ab maiṃ ākhirkār Frāns meṃ apne parivār ko fon kar sakūṃgā."}]},{"title":"Ouvrir un compte à la banque","phrases":[{"fr":"Je voudrais ouvrir un compte d'épargne.","tgt":"मैं एक बचत खाता खोलना चाहता हूँ।","ro":"Maiṃ ek bachat khātā kholnā chāhtā hūṃ."},{"fr":"Quels papiers faut-il apporter ?","tgt":"कौन-कौन से काग़ज़ लाने होंगे?","ro":"Kaun-kaun se kāgaz lāne hoṃge?"},{"fr":"Une pièce d'identité et un justificatif d'adresse.","tgt":"एक पहचान-पत्र और पते का कोई सबूत।","ro":"Ek pahchān-patr aur pate kā koī sabūt."},{"fr":"Il faudra signer ici et ici.","tgt":"यहाँ और यहाँ दस्तख़त करने होंगे।","ro":"Yahāṃ aur yahāṃ dastakhat karne hoṃge."},{"fr":"Le compte sera ouvert d'ici deux jours.","tgt":"खाता दो दिन में खुल जाएगा।","ro":"Khātā do din meṃ khul jāegā."},{"fr":"Faut-il garder un minimum d'argent sur le compte ?","tgt":"क्या खाते में कम से कम कुछ पैसे रखने पड़ते हैं?","ro":"Kyā khāte meṃ kam se kam kuchh paise rakhne paṛte haiṃ?"},{"fr":"Oui, au moins cinq mille roupies.","tgt":"हाँ, कम से कम पाँच हज़ार रुपये।","ro":"Hāṃ, kam se kam pāṃch hazār rupaye."},{"fr":"Quand ma carte de retrait arrivera-t-elle ?","tgt":"मेरा एटीएम कार्ड कब तक आएगा?","ro":"Merā eṭīem kārḍ kab tak āegā?"},{"fr":"Dans une semaine, à votre adresse.","tgt":"एक हफ़्ते में, आपके पते पर।","ro":"Ek hafte meṃ, āpke pate par."},{"fr":"Puis-je aussi envoyer de l'argent avec mon téléphone ?","tgt":"क्या मैं फ़ोन से भी पैसे भेज सकता हूँ?","ro":"Kyā maiṃ fon se bhī paise bhej saktā hūṃ?"}]},{"title":"Les livraisons à domicile","phrases":[{"fr":"J'ai commandé des courses sur une application.","tgt":"मैंने एक ऐप पर सामान मँगवा लिया।","ro":"Maiṃne ek aip par sāmān maṃgvā liyā."},{"fr":"Je vérifierai les courses à leur arrivée.","tgt":"सामान आने पर मैं उसे चेक कर लूँगा।","ro":"Sāmān āne par maiṃ use chek kar lūṃgā."},{"fr":"Pouvez-vous réceptionner mon colis à ma place ?","tgt":"क्या आप मेरा पार्सल ले लेंगे?","ro":"Kyā āp merā pārsal le leṃge?"},{"fr":"Bien sûr, je le garderai chez moi.","tgt":"ज़रूर, मैं उसे रख लूँगा।","ro":"Zarūr, maiṃ use rakh lūṃgā."},{"fr":"Je donnerai l'argent au livreur.","tgt":"मैं डिलीवरी वाले को पैसे दे दूँगा।","ro":"Maiṃ ḍilīvarī vāle ko paise de dūṃgā."},{"fr":"Je ferai le paiement par téléphone tout à l'heure.","tgt":"मैं थोड़ी देर में फ़ोन से पेमेंट कर दूँगा।","ro":"Maiṃ thoṛī der meṃ fon se pemenṭ kar dūṃgā."},{"fr":"Posez le paquet devant la porte, s'il vous plaît.","tgt":"पैकेट दरवाज़े के बाहर रख दीजिए।","ro":"Paikeṭ darvāze ke bāhar rakh dījie."},{"fr":"Je vais d'abord manger, ensuite je rangerai les courses.","tgt":"मैं पहले खाना खा लेता हूँ, फिर सामान रख दूँगा।","ro":"Maiṃ pahle khānā khā letā hūṃ, phir sāmān rakh dūṃgā."},{"fr":"Le livreur a oublié le lait.","tgt":"डिलीवरी वाला दूध देना भूल गया।","ro":"Ḍilīvarī vālā dūdh denā bhūl gayā."},{"fr":"Pas grave, je l'achèterai à l'épicerie du coin.","tgt":"कोई बात नहीं, मैं नुक्कड़ की दुकान से ख़रीद लूँगा।","ro":"Koī bāt nahīṃ, maiṃ nukkaṛ kī dukān se kharīd lūṃgā."}],"tip":{"title":"Les verbes composés : kar lenā, kar denā","example":"Je vais d'abord manger, ensuite je rangerai les courses. — मैं पहले खाना <b>खा लेता हूँ</b>, फिर सामान <b>रख दूँगा</b>।","body":"En hindi, on aime coller deux verbes ensemble : le premier donne le sens, le second ajoute une nuance. Avec « lenā », prendre, l'action revient vers soi : « maiṃ kar lūṃgā », je m'en occupe pour moi, ou « khā lījie », servez-vous donc. Avec « denā », donner, l'action part vers quelqu'un d'autre ou se termine pour de bon : « maiṃ āpkā kām kar dūṃgā », je vous ferai ce travail, ou « paise de dūṃgā », je donnerai l'argent. Dans « maiṃ pahle khānā khā letā hūṃ », mot à mot je, d'abord, repas, manger, prends, suis, le petit « letā » montre que je mange pour moi, tranquillement. Le sens de base reste le même, seule la couleur change, un peu comme entre « je me fais un thé » et « je fais un thé ». Astuce : imaginez un geste, la main qui ramène vers soi pour « lenā », la main qui tend vers l'autre pour « denā ».","exampleRo":"Maiṃ pahle khānā khā letā hūṃ, phir sāmān rakh dūṃgā.","lit":"je · d'abord · repas · manger · prends · suis · puis · affaires · poser · donnerai","say":{"lenā":"लेना","maiṃ kar lūṃgā":"मैं कर लूँगा","khā lījie":"खा लीजिए","denā":"देना","maiṃ āpkā kām kar dūṃgā":"मैं आपका काम कर दूँगा","paise de dūṃgā":"पैसे दे दूँगा","maiṃ pahle khānā khā letā hūṃ":"मैं पहले खाना खा लेता हूँ","letā":"लेता"}}},{"title":"À la pharmacie","phrases":[{"fr":"Donnez-moi quelque chose contre le rhume, s'il vous plaît.","tgt":"मुझे ज़ुकाम की कोई दवा दीजिए।","ro":"Mujhe zukām kī koī davā dījie."},{"fr":"Depuis quand avez-vous le nez qui coule ?","tgt":"आपकी नाक कब से बह रही है?","ro":"Āpkī nāk kab se bah rahī hai?"},{"fr":"Depuis hier soir, et j'ai aussi mal à la gorge.","tgt":"कल रात से, और मेरा गला भी ख़राब है।","ro":"Kal rāt se, aur merā galā bhī kharāb hai."},{"fr":"Prenez ce sirop trois fois par jour.","tgt":"यह सिरप दिन में तीन बार लीजिए।","ro":"Yah sirap din meṃ tīn bār lījie."},{"fr":"Ces comprimés, prenez-les après le repas.","tgt":"ये गोलियाँ खाने के बाद लीजिए।","ro":"Ye goliyāṃ khāne ke bād lījie."},{"fr":"Buvez beaucoup d'eau chaude.","tgt":"ख़ूब गरम पानी पीजिए।","ro":"Khūb garam pānī pījie."},{"fr":"Montrez-moi l'ordonnance, s'il vous plaît.","tgt":"ज़रा पर्ची दिखाइए।","ro":"Zarā parchī dikhāie."},{"fr":"Attendez cinq minutes, je vais chercher le médicament.","tgt":"पाँच मिनट रुकिए, मैं दवा निकालता हूँ।","ro":"Pāṃch minaṭ rukie, maiṃ davā nikāltā hūṃ."},{"fr":"Je vous dois combien ?","tgt":"कितने पैसे हुए?","ro":"Kitne paise hue?"},{"fr":"Cent quatre-vingts roupies. Reposez-vous bien.","tgt":"एक सौ अस्सी रुपये। अच्छे से आराम कीजिए।","ro":"Ek sau assī rupaye. Achchhe se ārām kījie."}],"tip":{"title":"L'impératif poli : « kījie, dījie »","example":"Donnez-moi quelque chose contre le rhume, s'il vous plaît. — मुझे ज़ुकाम की कोई दवा <b>दीजिए</b>।","body":"Pour demander quelque chose avec « āp », on ajoute « ie » au radical du verbe : « ruknā », s'arrêter, donne « rukie », attendez, et « dikhānā », montrer, donne « dikhāie », montrez. Quatre verbes très fréquents sont irréguliers et se terminent en « jie » : « kījie », faites, « dījie », donnez, « lījie », prenez, et « pījie », buvez. Prenons « mujhe zukām kī koī davā dījie » : à moi, de rhume, un, médicament, donnez, avec le verbe tout à la fin comme toujours. Cette forme est déjà très respectueuse, si bien qu'on n'a presque jamais besoin d'ajouter s'il vous plaît ; pour adoucir encore, on glisse « zarā », un peu, comme dans « zarā parchī dikhāie ». Astuce : entendez ce « jie » final comme une petite révérence en fin de phrase.","exampleRo":"Mujhe zukām kī koī davā dījie.","lit":"à moi · rhume · [de] · quelque · médicament · donnez","say":{"āp":"आप","ruknā":"रुकना","rukie":"रुकिए","dikhānā":"दिखाना","dikhāie":"दिखाइए","kījie":"कीजिए","dījie":"दीजिए","lījie":"लीजिए","pījie":"पीजिए","mujhe zukām kī koī davā dījie":"मुझे ज़ुकाम की कोई दवा दीजिए","zarā":"ज़रा","zarā parchī dikhāie":"ज़रा पर्ची दिखाइए","kījie, dījie":"कीजिए, दीजिए","ie":"इए","jie":"जिए"}}},{"title":"Une visite à la clinique","phrases":[{"fr":"J'ai de la fièvre depuis deux jours.","tgt":"मुझे दो दिन से बुख़ार है।","ro":"Mujhe do din se bukhār hai."},{"fr":"Asseyez-vous, je vais prendre votre température.","tgt":"बैठिए, मैं आपका बुख़ार नापता हूँ।","ro":"Baiṭhie, maiṃ āpkā bukhār nāptā hūṃ."},{"fr":"Avez-vous aussi mal à la tête ?","tgt":"क्या आपके सिर में भी दर्द है?","ro":"Kyā āpke sir meṃ bhī dard hai?"},{"fr":"Oui, surtout en fin de journée.","tgt":"हाँ, ख़ासकर शाम को।","ro":"Hāṃ, khāskar shām ko."},{"fr":"C'est probablement une fièvre virale.","tgt":"शायद वायरल बुख़ार है।","ro":"Shāyad vāyral bukhār hai."},{"fr":"Il faudra faire une prise de sang.","tgt":"ख़ून की जाँच करवानी होगी।","ro":"Khūn kī jāṃch karvānī hogī."},{"fr":"Le laboratoire est à l'étage du dessous.","tgt":"लैब नीचे की मंज़िल पर है।","ro":"Laib nīche kī manzil par hai."},{"fr":"Le résultat sera prêt demain matin.","tgt":"रिपोर्ट कल सुबह तक आ जाएगी।","ro":"Riporṭ kal subah tak ā jāegī."},{"fr":"Est-ce que je dois revenir ?","tgt":"क्या मुझे फिर से आना होगा?","ro":"Kyā mujhe phir se ānā hogā?"},{"fr":"Oui, revenez avec le résultat.","tgt":"हाँ, रिपोर्ट लेकर आइए।","ro":"Hāṃ, riporṭ lekar āie."}]},{"title":"Les voisins de l'immeuble","phrases":[{"fr":"Notre voisine d'à côté est très gentille.","tgt":"हमारी बगल वाली पड़ोसन बहुत अच्छी हैं।","ro":"Hamārī bagal vālī paṛosan bahut achchhī haiṃ."},{"fr":"Hier, elle nous a apporté des sucreries.","tgt":"कल वे हमारे लिए मिठाई लाईं।","ro":"Kal ve hamāre lie miṭhāī lāīṃ."},{"fr":"Ses enfants jouent souvent en bas, dans le parc.","tgt":"उनके बच्चे अक्सर नीचे पार्क में खेलते हैं।","ro":"Unke bachche aksar nīche pārk meṃ khelte haiṃ."},{"fr":"Le voisin du dessus fait du bruit la nuit.","tgt":"ऊपर वाले पड़ोसी रात को शोर करते हैं।","ro":"Ūpar vāle paṛosī rāt ko shor karte haiṃ."},{"fr":"Je vais lui en parler calmement.","tgt":"मैं उनसे आराम से बात करूँगा।","ro":"Maiṃ unse ārām se bāt karūṃgā."},{"fr":"Excusez-moi, la musique est un peu forte.","tgt":"माफ़ कीजिए, गाना थोड़ा ज़ोर से बज रहा है।","ro":"Māf kījie, gānā thoṛā zor se baj rahā hai."},{"fr":"Pardon, je baisse le son tout de suite.","tgt":"माफ़ कीजिए, मैं अभी आवाज़ कम करता हूँ।","ro":"Māf kījie, maiṃ abhī āvāz kam kartā hūṃ."},{"fr":"Venez prendre le thé chez nous dimanche.","tgt":"रविवार को हमारे यहाँ चाय पर आइए।","ro":"Ravivār ko hamāre yahāṃ chāy par āie."},{"fr":"Avec plaisir, merci pour l'invitation.","tgt":"ज़रूर, बुलाने के लिए शुक्रिया।","ro":"Zarūr, bulāne ke lie shukriyā."},{"fr":"Ici, les voisins s'entraident beaucoup.","tgt":"यहाँ पड़ोसी एक-दूसरे की बहुत मदद करते हैं।","ro":"Yahāṃ paṛosī ek-dūsre kī bahut madad karte haiṃ."}]},{"title":"Au marché aux légumes","phrases":[{"fr":"Les tomates sont à combien le kilo ?","tgt":"टमाटर कितने रुपये किलो हैं?","ro":"Ṭamāṭar kitne rupaye kilo haiṃ?"},{"fr":"Quarante roupies le kilo, monsieur.","tgt":"चालीस रुपये किलो, साहब।","ro":"Chālīs rupaye kilo, sāhab."},{"fr":"C'est un peu cher, baissez un peu le prix.","tgt":"थोड़ा महँगा है, कुछ कम कीजिए।","ro":"Thoṛā mahaṃgā hai, kuchh kam kījie."},{"fr":"D'accord, trente-cinq pour vous.","tgt":"ठीक है, आपके लिए पैंतीस।","ro":"Ṭhīk hai, āpke lie paintīs."},{"fr":"Donnez-moi aussi un kilo d'oignons.","tgt":"एक किलो प्याज़ भी दे दीजिए।","ro":"Ek kilo pyāz bhī de dījie."},{"fr":"Les mangues sont-elles bien mûres ?","tgt":"क्या आम अच्छे पके हुए हैं?","ro":"Kyā ām achchhe pake hue haiṃ?"},{"fr":"Goûtez celle-ci, elle est très sucrée.","tgt":"यह चखकर देखिए, बहुत मीठा है।","ro":"Yah chakhkar dekhie, bahut mīṭhā hai."},{"fr":"Mettez-moi aussi un peu de coriandre.","tgt":"थोड़ा धनिया भी डाल दीजिए।","ro":"Thoṛā dhaniyā bhī ḍāl dījie."},{"fr":"Avez-vous la monnaie sur cinq cents roupies ?","tgt":"क्या आपके पास पाँच सौ का छुट्टा है?","ro":"Kyā āpke pās pāṃch sau kā chhuṭṭā hai?"},{"fr":"Je viens ici chaque semaine, les légumes sont toujours frais.","tgt":"मैं हर हफ़्ते यहाँ आता हूँ, सब्ज़ियाँ हमेशा ताज़ी होती हैं।","ro":"Maiṃ har hafte yahāṃ ātā hūṃ, sabziyāṃ hameshā tāzī hotī haiṃ."}]},{"title":"Une journée au bureau","phrases":[{"fr":"Je travaille dans une entreprise informatique.","tgt":"मैं एक आईटी कंपनी में काम करता हूँ।","ro":"Maiṃ ek āīṭī kampanī meṃ kām kartā hūṃ."},{"fr":"Mon bureau est à Koramangala.","tgt":"मेरा दफ़्तर कोरमंगला में है।","ro":"Merā daftar Koramangalā meṃ hai."},{"fr":"Il me faut une heure pour y arriver.","tgt":"वहाँ पहुँचने में मुझे एक घंटा लगता है।","ro":"Vahāṃ pahuṃchne meṃ mujhe ek ghanṭā lagtā hai."},{"fr":"La réunion commence à dix heures.","tgt":"मीटिंग दस बजे शुरू होती है।","ro":"Mīṭing das baje shurū hotī hai."},{"fr":"Mon responsable est strict, mais gentil.","tgt":"मेरे मैनेजर सख़्त हैं, पर अच्छे हैं।","ro":"Mere mainejar sakht haiṃ, par achchhe haiṃ."},{"fr":"À midi, nous mangeons ensemble à la cantine.","tgt":"दोपहर को हम साथ में कैंटीन में खाना खाते हैं।","ro":"Dopahar ko ham sāth meṃ kainṭīn meṃ khānā khāte haiṃ."},{"fr":"Mes collègues apportent souvent leur repas de la maison.","tgt":"मेरे साथी अक्सर घर से टिफ़िन लाते हैं।","ro":"Mere sāthī aksar ghar se ṭifin lāte haiṃ."},{"fr":"Cet après-midi, je dois terminer un rapport.","tgt":"आज दोपहर मुझे एक रिपोर्ट पूरी करनी है।","ro":"Āj dopahar mujhe ek riporṭ pūrī karnī hai."},{"fr":"De temps en temps, je travaille de chez moi.","tgt":"कभी-कभी मैं घर से काम करता हूँ।","ro":"Kabhī-kabhī maiṃ ghar se kām kartā hūṃ."},{"fr":"Je quitte le bureau vers sept heures.","tgt":"मैं लगभग सात बजे दफ़्तर से निकलता हूँ।","ro":"Maiṃ lagbhag sāt baje daftar se nikaltā hūṃ."}]},{"title":"Hier au travail","phrases":[{"fr":"Hier, ma journée a été très chargée.","tgt":"कल मेरा दिन बहुत व्यस्त था।","ro":"Kal merā din bahut vyast thā."},{"fr":"J'ai envoyé trente mails avant midi.","tgt":"मैंने दोपहर से पहले तीस ईमेल भेजे।","ro":"Maiṃne dopahar se pahle tīs īmel bheje."},{"fr":"Ensuite, nous avons rencontré un nouveau client.","tgt":"फिर हम एक नए क्लाइंट से मिले।","ro":"Phir ham ek nae klāinṭ se mile."},{"fr":"Mon collègue a présenté notre projet.","tgt":"मेरे साथी ने हमारा प्रोजेक्ट पेश किया।","ro":"Mere sāthī ne hamārā projekṭ pesh kiyā."},{"fr":"Le client a posé beaucoup de questions.","tgt":"क्लाइंट ने बहुत सारे सवाल पूछे।","ro":"Klāinṭ ne bahut sāre savāl pūchhe."},{"fr":"Nous avons répondu à toutes ses questions.","tgt":"हमने उनके सब सवालों के जवाब दिए।","ro":"Hamne unke sab savāloṃ ke javāb die."},{"fr":"Notre idée lui a beaucoup plu.","tgt":"उन्हें हमारा आइडिया बहुत पसंद आया।","ro":"Unheṃ hamārā āiḍiyā bahut pasand āyā."},{"fr":"Le soir, j'ai raté le dernier bus.","tgt":"शाम को मेरी आख़िरी बस छूट गई।","ro":"Shām ko merī ākhirī bas chhūṭ gaī."},{"fr":"Alors j'ai pris un rickshaw pour rentrer.","tgt":"तो मैंने घर जाने के लिए रिक्शा लिया।","ro":"To maiṃne ghar jāne ke lie rikshā liyā."},{"fr":"J'étais épuisé et je me suis couché tôt.","tgt":"मैं बहुत थका हुआ था और जल्दी सो गया।","ro":"Maiṃ bahut thakā huā thā aur jaldī so gayā."}]},{"title":"Tout est prêt pour les invités","phrases":[{"fr":"Nos amis arrivent dans une heure.","tgt":"हमारे दोस्त एक घंटे में आ रहे हैं।","ro":"Hamāre dost ek ghanṭe meṃ ā rahe haiṃ."},{"fr":"J'ai déjà fait le ménage.","tgt":"मैं सफ़ाई कर चुका हूँ।","ro":"Maiṃ safāī kar chukā hūṃ."},{"fr":"Ma femme a déjà préparé le biryani.","tgt":"मेरी पत्नी बिरयानी बना चुकी है।","ro":"Merī patnī biryānī banā chukī hai."},{"fr":"Est-ce qu'on a déjà acheté les boissons fraîches ?","tgt":"क्या हम कोल्ड ड्रिंक ले चुके हैं?","ro":"Kyā ham kolḍ ḍrink le chuke haiṃ?"},{"fr":"Oui, je les ai déjà mises au frigo.","tgt":"हाँ, मैं उन्हें फ़्रिज में रख चुका हूँ।","ro":"Hāṃ, maiṃ unheṃ frij meṃ rakh chukā hūṃ."},{"fr":"Les enfants ont déjà dîné.","tgt":"बच्चे खाना खा चुके हैं।","ro":"Bachche khānā khā chuke haiṃ."},{"fr":"Il ne reste plus qu'à mettre la table.","tgt":"अब बस मेज़ लगानी बाकी है।","ro":"Ab bas mez lagānī bākī hai."},{"fr":"Rahul a appelé, il est déjà parti de chez lui.","tgt":"राहुल का फ़ोन आया, वह घर से निकल चुका है।","ro":"Rāhul kā fon āyā, vah ghar se nikal chukā hai."},{"fr":"Ce film, nous l'avons déjà vu deux fois.","tgt":"यह फ़िल्म हम दो बार देख चुके हैं।","ro":"Yah film ham do bār dekh chuke haiṃ."},{"fr":"Tout est prêt, nous pouvons nous détendre.","tgt":"सब कुछ तैयार है, अब हम आराम कर सकते हैं।","ro":"Sab kuchh taiyār hai, ab ham ārām kar sakte haiṃ."}],"tip":{"title":"« Chukā » : avoir déjà fini","example":"J'ai déjà fait le ménage. — मैं सफ़ाई <b>कर चुका हूँ</b>।","body":"Pour dire qu'une action est déjà terminée, on prend le radical du verbe, on ajoute « chukā », puis « hūṃ », « hai » ou « haiṃ ». Ainsi « maiṃ safāī kar chukā hūṃ » se décompose en je, ménage, faire, fini, suis : j'ai déjà fait le ménage. Bonne nouvelle, avec « chukā » on n'utilise jamais « ne », même avec manger ou voir : on dit « bachche khānā khā chuke haiṃ », les enfants ont déjà mangé. « Chukā » s'accorde avec celui qui agit : « chukā » pour un homme, « chukī » pour une femme, « chuke » au pluriel ou par respect, comme dans « merī patnī biryānī banā chukī hai ». Astuce : voyez « chukā » comme une case cochée sur votre liste, c'est fait et on n'y revient plus.","exampleRo":"Maiṃ safāī kar chukā hūṃ.","lit":"je · ménage · faire · fini · suis","say":{"Chukā":"चुका","chukā":"चुका","hūṃ":"हूँ","hai":"है","haiṃ":"हैं","maiṃ safāī kar chukā hūṃ":"मैं सफ़ाई कर चुका हूँ","ne":"ने","bachche khānā khā chuke haiṃ":"बच्चे खाना खा चुके हैं","chukī":"चुकी","chuke":"चुके","merī patnī biryānī banā chukī hai":"मेरी पत्नी बिरयानी बना चुकी है"}}},{"title":"Le week-end dernier","phrases":[{"fr":"Qu'avez-vous fait le week-end dernier ?","tgt":"पिछले वीकेंड आपने क्या किया?","ro":"Pichhle vīkenḍ āpne kyā kiyā?"},{"fr":"Samedi, nous sommes allés à Cubbon Park.","tgt":"शनिवार को हम कब्बन पार्क गए।","ro":"Shanivār ko ham Kabban Pārk gae."},{"fr":"Les enfants ont fait du vélo toute la matinée.","tgt":"बच्चों ने पूरी सुबह साइकिल चलाई।","ro":"Bachchoṃ ne pūrī subah sāikil chalāī."},{"fr":"Ensuite, nous avons déjeuné dans un petit restaurant.","tgt":"फिर हमने एक छोटे रेस्टोरेंट में खाना खाया।","ro":"Phir hamne ek chhoṭe resṭorenṭ meṃ khānā khāyā."},{"fr":"Dimanche, je suis resté à la maison.","tgt":"रविवार को मैं घर पर ही रहा।","ro":"Ravivār ko maiṃ ghar par hī rahā."},{"fr":"J'ai lu un roman et j'ai fait la sieste.","tgt":"मैंने एक उपन्यास पढ़ा और दोपहर को सोया।","ro":"Maiṃne ek upanyās paṛhā aur dopahar ko soyā."},{"fr":"Le soir, des amis sont passés nous voir.","tgt":"शाम को कुछ दोस्त हमसे मिलने आए।","ro":"Shām ko kuchh dost hamse milne āe."},{"fr":"Nous avons joué aux cartes jusqu'à onze heures.","tgt":"हमने ग्यारह बजे तक ताश खेला।","ro":"Hamne gyārah baje tak tāsh khelā."},{"fr":"Et vous ? Vous êtes sortis quelque part ?","tgt":"और आप? क्या आप कहीं बाहर गए?","ro":"Aur āp? Kyā āp kahīṃ bāhar gae?"},{"fr":"Non, chez nous, il a plu tout le week-end.","tgt":"नहीं, हमारे यहाँ पूरे वीकेंड बारिश हुई।","ro":"Nahīṃ, hamāre yahāṃ pūre vīkenḍ bārish huī."}]},{"title":"Souvenirs d'enfance","phrases":[{"fr":"Enfant, j'habitais dans un petit village en France.","tgt":"बचपन में मैं फ़्रांस के एक छोटे गाँव में रहता था।","ro":"Bachpan meṃ maiṃ Frāns ke ek chhoṭe gāṃv meṃ rahtā thā."},{"fr":"J'allais à l'école à vélo.","tgt":"मैं साइकिल से स्कूल जाता था।","ro":"Maiṃ sāikil se skūl jātā thā."},{"fr":"Après l'école, je jouais au ballon avec mes copains.","tgt":"स्कूल के बाद मैं दोस्तों के साथ गेंद खेलता था।","ro":"Skūl ke bād maiṃ dostoṃ ke sāth gend kheltā thā."},{"fr":"Ma grand-mère nous racontait des histoires.","tgt":"मेरी दादी हमें कहानियाँ सुनाती थीं।","ro":"Merī dādī hameṃ kahāniyāṃ sunātī thīṃ."},{"fr":"L'été, nous allions au bord de la mer.","tgt":"गर्मियों में हम समुद्र किनारे जाते थे।","ro":"Garmiyoṃ meṃ ham samudr kināre jāte the."},{"fr":"Mon frère et moi, nous nous disputions souvent.","tgt":"मैं और मेरा भाई अक्सर झगड़ते थे।","ro":"Maiṃ aur merā bhāī aksar jhagaṛte the."},{"fr":"Je n'aimais pas du tout les légumes.","tgt":"मुझे सब्ज़ियाँ बिल्कुल पसंद नहीं थीं।","ro":"Mujhe sabziyāṃ bilkul pasand nahīṃ thīṃ."},{"fr":"Mon père se levait toujours très tôt.","tgt":"मेरे पापा हमेशा बहुत जल्दी उठते थे।","ro":"Mere pāpā hameshā bahut jaldī uṭhte the."},{"fr":"Et vous, où avez-vous grandi ?","tgt":"और आप कहाँ बड़े हुए?","ro":"Aur āp kahāṃ baṛe hue?"},{"fr":"Moi, j'ai grandi à Mysore, tout près d'ici.","tgt":"मैं यहीं पास में, मैसूर में बड़ा हुआ।","ro":"Maiṃ yahīṃ pās meṃ, Maisūr meṃ baṛā huā."}]},{"title":"La saison de la mousson","phrases":[{"fr":"À Bangalore, la mousson arrive en juin.","tgt":"बेंगलुरु में मानसून जून में आता है।","ro":"Bengaluru meṃ mānsūn jūn meṃ ātā hai."},{"fr":"Il pleut presque tous les après-midis.","tgt":"लगभग हर दोपहर बारिश होती है।","ro":"Lagbhag har dopahar bārish hotī hai."},{"fr":"Gardez toujours un parapluie sur vous.","tgt":"हमेशा अपने साथ छाता रखिए।","ro":"Hameshā apne sāth chhātā rakhie."},{"fr":"L'eau envahit souvent les rues.","tgt":"सड़कों पर अक्सर पानी भर जाता है।","ro":"Saṛkoṃ par aksar pānī bhar jātā hai."},{"fr":"Hier, je suis rentré complètement trempé.","tgt":"कल मैं पूरी तरह भीगकर घर पहुँचा।","ro":"Kal maiṃ pūrī tarah bhīgkar ghar pahuṃchā."},{"fr":"Sous la pluie, la circulation devient encore pire.","tgt":"बारिश में ट्रैफ़िक और भी ख़राब हो जाता है।","ro":"Bārish meṃ ṭraifik aur bhī kharāb ho jātā hai."},{"fr":"Mais l'air devient frais et agréable.","tgt":"लेकिन हवा ठंडी और सुहानी हो जाती है।","ro":"Lekin havā ṭhanḍī aur suhānī ho jātī hai."},{"fr":"Les plantes et les arbres deviennent tout verts.","tgt":"पेड़-पौधे एकदम हरे हो जाते हैं।","ro":"Peṛ-paudhe ekdam hare ho jāte haiṃ."},{"fr":"Le soir, on mange des beignets avec le thé.","tgt":"शाम को हम चाय के साथ पकौड़े खाते हैं।","ro":"Shām ko ham chāy ke sāth pakauṛe khāte haiṃ."},{"fr":"J'adore la saison des pluies.","tgt":"मुझे बरसात का मौसम बहुत पसंद है।","ro":"Mujhe barsāt kā mausam bahut pasand hai."}]},{"title":"L'aide à la maison","phrases":[{"fr":"Une femme de ménage vient chez nous chaque matin.","tgt":"हमारे घर हर सुबह एक दीदी काम करने आती हैं।","ro":"Hamāre ghar har subah ek dīdī kām karne ātī haiṃ."},{"fr":"Elle s'appelle Sunita.","tgt":"उनका नाम सुनीता है।","ro":"Unkā nām Sunītā hai."},{"fr":"Elle balaie et lave le sol.","tgt":"वे झाड़ू-पोंछा करती हैं।","ro":"Ve jhāṛū-ponchhā kartī haiṃ."},{"fr":"Elle fait aussi la vaisselle.","tgt":"वे बर्तन भी धोती हैं।","ro":"Ve bartan bhī dhotī haiṃ."},{"fr":"Demain, elle ne viendra pas.","tgt":"कल वे नहीं आएँगी।","ro":"Kal ve nahīṃ āeṃgī."},{"fr":"Sa fille est malade.","tgt":"उनकी बेटी बीमार है।","ro":"Unkī beṭī bīmār hai."},{"fr":"Ce n'est rien, nous laverons la vaisselle nous-mêmes.","tgt":"कोई बात नहीं, हम ख़ुद बर्तन धो लेंगे।","ro":"Koī bāt nahīṃ, ham khud bartan dho leṃge."},{"fr":"Nous lui donnons quatre mille roupies par mois.","tgt":"हम उन्हें महीने के चार हज़ार रुपये देते हैं।","ro":"Ham unheṃ mahīne ke chār hazār rupaye dete haiṃ."},{"fr":"Pour les fêtes, nous lui offrons une prime.","tgt":"त्योहारों पर हम उन्हें बोनस देते हैं।","ro":"Tyohāroṃ par ham unheṃ bonas dete haiṃ."},{"fr":"Elle fait presque partie de la famille.","tgt":"वे लगभग परिवार का हिस्सा हैं।","ro":"Ve lagbhag parivār kā hissā haiṃ."}]},{"title":"Une coupure de courant","phrases":[{"fr":"Il n'y a plus d'électricité depuis ce matin.","tgt":"सुबह से बिजली नहीं है।","ro":"Subah se bijlī nahīṃ hai."},{"fr":"Ça arrive souvent dans notre quartier ?","tgt":"क्या हमारे इलाके में ऐसा अक्सर होता है?","ro":"Kyā hamāre ilāke meṃ aisā aksar hotā hai?"},{"fr":"Oui, surtout pendant la mousson.","tgt":"हाँ, ख़ासकर मानसून में।","ro":"Hāṃ, khāskar mānsūn meṃ."},{"fr":"Heureusement, l'immeuble a un groupe électrogène.","tgt":"शुक्र है, बिल्डिंग में जनरेटर है।","ro":"Shukr hai, bilḍing meṃ janareṭar hai."},{"fr":"Mais il fait marcher seulement l'ascenseur et les lumières.","tgt":"पर उससे सिर्फ़ लिफ़्ट और बत्तियाँ चलती हैं।","ro":"Par usse sirf lifṭ aur battiyāṃ chaltī haiṃ."},{"fr":"Le réfrigérateur ne fonctionne pas.","tgt":"फ़्रिज नहीं चल रहा है।","ro":"Frij nahīṃ chal rahā hai."},{"fr":"Mon téléphone n'a presque plus de batterie.","tgt":"मेरे फ़ोन की बैटरी लगभग ख़त्म हो गई है।","ro":"Mere fon kī baiṭarī lagbhag khatm ho gaī hai."},{"fr":"Appelons le service de l'électricité.","tgt":"चलिए, बिजली दफ़्तर में फ़ोन करते हैं।","ro":"Chalie, bijlī daftar meṃ fon karte haiṃ."},{"fr":"Ils disent que le courant reviendra vers quatre heures.","tgt":"वे कह रहे हैं कि चार बजे तक बिजली आ जाएगी।","ro":"Ve kah rahe haiṃ ki chār baje tak bijlī ā jāegī."},{"fr":"En attendant, allons boire un thé dehors.","tgt":"तब तक चलिए, बाहर चाय पीते हैं।","ro":"Tab tak chalie, bāhar chāy pīte haiṃ."}]},{"title":"En rickshaw dans la ville","phrases":[{"fr":"Monsieur, vous allez jusqu'à Indiranagar ?","tgt":"भैया, इंदिरानगर चलेंगे?","ro":"Bhaiyā, Indirānagar chaleṃge?"},{"fr":"Oui, mais ce sera deux cents roupies.","tgt":"हाँ, पर दो सौ रुपये लगेंगे।","ro":"Hāṃ, par do sau rupaye lageṃge."},{"fr":"Allons-y au compteur, s'il vous plaît.","tgt":"मीटर से चलिए।","ro":"Mīṭar se chalie."},{"fr":"D'accord, montez.","tgt":"ठीक है, बैठिए।","ro":"Ṭhīk hai, baiṭhie."},{"fr":"Passez par la grande route, on arrivera plus vite.","tgt":"मेन रोड से चलिए, जल्दी पहुँचेंगे।","ro":"Men roḍ se chalie, jaldī pahuṃcheṃge."},{"fr":"Il y a énormément de circulation aujourd'hui.","tgt":"आज बहुत ट्रैफ़िक है।","ro":"Āj bahut ṭraifik hai."},{"fr":"Tournez à gauche après le feu.","tgt":"सिग्नल के बाद बाएँ मुड़िए।","ro":"Signal ke bād bāeṃ muṛie."},{"fr":"Arrêtez-vous ici, devant la pharmacie.","tgt":"यहीं केमिस्ट की दुकान के सामने रोकिए।","ro":"Yahīṃ kemisṭ kī dukān ke sāmne rokie."},{"fr":"Combien ça fait au compteur ?","tgt":"मीटर में कितना हुआ?","ro":"Mīṭar meṃ kitnā huā?"},{"fr":"Cent dix roupies, merci beaucoup.","tgt":"एक सौ दस रुपये, बहुत शुक्रिया।","ro":"Ek sau das rupaye, bahut shukriyā."}]},{"title":"Les règles de l'immeuble","phrases":[{"fr":"Ne garez pas votre scooter ici.","tgt":"यहाँ स्कूटर मत लगाइए।","ro":"Yahāṃ skūṭar mat lagāie."},{"fr":"Ne jetez pas les ordures par la fenêtre.","tgt":"खिड़की से कूड़ा मत फेंकिए।","ro":"Khiṛkī se kūṛā mat phenkie."},{"fr":"Ne faites pas de bruit après dix heures du soir.","tgt":"रात दस बजे के बाद शोर मत कीजिए।","ro":"Rāt das baje ke bād shor mat kījie."},{"fr":"N'ouvrez pas la porte aux inconnus.","tgt":"अनजान लोगों के लिए दरवाज़ा मत खोलिए।","ro":"Anjān logoṃ ke lie darvāzā mat kholie."},{"fr":"Ne laissez pas l'eau couler pour rien.","tgt":"पानी बेकार मत बहाइए।","ro":"Pānī bekār mat bahāie."},{"fr":"Les enfants, ne jouez pas dans l'ascenseur.","tgt":"बच्चो, लिफ़्ट में मत खेलो।","ro":"Bachcho, lifṭ meṃ mat khelo."},{"fr":"Ne vous inquiétez pas, c'est juste pour la sécurité.","tgt":"चिंता मत कीजिए, यह बस सुरक्षा के लिए है।","ro":"Chintā mat kījie, yah bas surakshā ke lie hai."},{"fr":"Ne posez pas vos sacs dans l'escalier.","tgt":"सीढ़ियों पर थैले मत रखिए।","ro":"Sīṛhiyoṃ par thaile mat rakhie."},{"fr":"Ne donnez votre code secret à personne.","tgt":"अपना ओटीपी किसी को मत बताइए।","ro":"Apnā oṭīpī kisī ko mat batāie."},{"fr":"Ces règles rendent la vie plus facile pour tout le monde.","tgt":"इन नियमों से सबकी ज़िंदगी आसान होती है।","ro":"In niyamoṃ se sabkī zindagī āsān hotī hai."}],"tip":{"title":"« Mat » : l'interdiction","example":"Ne faites pas de bruit après dix heures du soir. — रात दस बजे के बाद शोर <b>मत</b> कीजिए।","body":"Pour interdire ou déconseiller quelque chose, le hindi utilise le petit mot « mat », placé juste avant le verbe à l'impératif. Là où le français a besoin de deux morceaux, ne et pas, le hindi n'en a qu'un : « mat kījie », ne faites pas, ou « mat lagāie », ne garez pas. Décomposons « rāt das baje ke bād shor mat kījie » : nuit, dix heures, après, bruit, ne pas, faites. « Mat » ne sert qu'aux ordres ; pour dire simplement qu'on ne fait pas quelque chose, on garde « nahīṃ », comme dans « maiṃ nahīṃ jātā », je n'y vais pas. Avec les enfants, on dit « mat khelo », ne jouez pas, et pour insister gentiment on peut aussi le mettre après le verbe : « ḍarie mat », n'ayez pas peur. Astuce : « mat » sonne comme un panneau stop, court et net, juste devant l'action.","exampleRo":"Rāt das baje ke bād shor mat kījie.","lit":"nuit · dix · heures · [de] après · bruit · ne pas · faites","say":{"Mat":"मत","mat":"मत","mat kījie":"मत कीजिए","mat lagāie":"मत लगाइए","rāt das baje ke bād shor mat kījie":"रात दस बजे के बाद शोर मत कीजिए","nahīṃ":"नहीं","maiṃ nahīṃ jātā":"मैं नहीं जाता","mat khelo":"मत खेलो","ḍarie mat":"डरिए मत"}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Dans ce module, nous avons découvert la vie de tous les jours à Bangalore.","tgt":"इस हिस्से में हमने बेंगलुरु की रोज़ की ज़िंदगी देखी।","ro":"Is hisse meṃ hamne Bengaluru kī roz kī zindagī dekhī."},{"fr":"Maintenant, nous savons raconter notre journée d'hier.","tgt":"अब हम अपने कल के दिन के बारे में बता सकते हैं।","ro":"Ab ham apne kal ke din ke bāre meṃ batā sakte haiṃ."},{"fr":"Nous savons aussi demander les choses avec respect.","tgt":"हम अब आदर से चीज़ें माँग सकते हैं।","ro":"Ham ab ādar se chīzeṃ māṃg sakte haiṃ."},{"fr":"Maintenant, « kar lenā » et « kar denā » me paraissent faciles.","tgt":"अब कर लेना और कर देना मुझे आसान लगते हैं।","ro":"Ab kar lenā aur kar denā mujhe āsān lagte haiṃ."},{"fr":"J'ai déjà appris plus de deux cents phrases en hindi.","tgt":"मैं हिंदी के दो सौ से ज़्यादा वाक्य सीख चुका हूँ।","ro":"Maiṃ hindī ke do sau se zyādā vāky sīkh chukā hūṃ."},{"fr":"Je parle avec mes voisins sans avoir peur.","tgt":"मैं बिना डरे अपने पड़ोसियों से बात करता हूँ।","ro":"Maiṃ binā ḍare apne paṛosiyoṃ se bāt kartā hūṃ."},{"fr":"Au marché, j'arrive même à négocier les prix.","tgt":"बाज़ार में मैं मोलभाव भी कर लेता हूँ।","ro":"Bāzār meṃ maiṃ molbhāv bhī kar letā hūṃ."},{"fr":"Dans le prochain module, nous partirons en voyage à travers l'Inde.","tgt":"अगले हिस्से में हम भारत की सैर पर निकलेंगे।","ro":"Agle hisse meṃ ham Bhārat kī sair par nikaleṃge."},{"fr":"N'ayez pas peur de faire des erreurs.","tgt":"ग़लतियाँ करने से मत डरिए।","ro":"Galtiyāṃ karne se mat ḍarie."},{"fr":"Continuons à parler hindi chaque jour.","tgt":"चलिए, हर दिन हिंदी बोलते रहें।","ro":"Chalie, har din hindī bolte raheṃ."}]}]},{"id":2,"name":"En voyage","desc":"Des situations de voyage plus variées et plus complexes.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"En bateau-maison sur les backwaters du Kerala","phrases":[{"fr":"Nous avons pris une chambre sur un bateau-maison pour deux nuits.","tgt":"हमने दो रातों के लिए हाउसबोट में कमरा लिया है।","ro":"Hamne do rātoṃ ke lie hāusboṭ meṃ kamrā liyā hai."},{"fr":"Le bateau avance lentement sur l'eau calme.","tgt":"नाव शांत पानी पर धीरे-धीरे चलती है।","ro":"Nāv shānt pānī par dhīre-dhīre chaltī hai."},{"fr":"Il y a des cocotiers sur les deux rives.","tgt":"दोनों किनारों पर नारियल के पेड़ हैं।","ro":"Donoṃ kināroṃ par nāriyal ke peṛ haiṃ."},{"fr":"Le cuisinier est en train de préparer un curry de poisson pour le déjeuner.","tgt":"रसोइया दोपहर के खाने के लिए मछली की करी बना रहा है।","ro":"Rasoiyā dopahar ke khāne ke lie machhlī kī karī banā rahā hai."},{"fr":"Avez-vous déjà mangé du riz rouge du Kerala ?","tgt":"क्या आपने कभी केरल के लाल चावल खाए हैं?","ro":"Kyā āpne kabhī Keral ke lāl chāval khāe haiṃ?"},{"fr":"Ce soir, nous dormirons sur le bateau même.","tgt":"आज रात हम नाव पर ही सोएँगे।","ro":"Āj rāt ham nāv par hī soeṃge."},{"fr":"Le calme ici est vraiment incroyable.","tgt":"यहाँ की शांति कमाल की है।","ro":"Yahāṃ kī shānti kamāl kī hai."},{"fr":"Regardez, des enfants nous font signe depuis la rive !","tgt":"देखिए, किनारे से बच्चे हाथ हिला रहे हैं।","ro":"Dekhie, kināre se bachche hāth hilā rahe haiṃ."},{"fr":"Le capitaine connaît très bien chaque canal.","tgt":"कप्तान हर नहर को अच्छी तरह जानता है।","ro":"Kaptān har nahar ko achchhī tarah jāntā hai."},{"fr":"C'est le voyage le plus reposant de ma vie.","tgt":"यह मेरी ज़िंदगी का सबसे आरामदेह सफ़र है।","ro":"Yah merī zindagī kā sabse ārāmdeh safar hai."}]},{"title":"Un village au bord de l'eau","phrases":[{"fr":"Le bateau s'est arrêté près d'un petit village.","tgt":"नाव एक छोटे-से गाँव के पास रुकी।","ro":"Nāv ek chhoṭe-se gāṃv ke pās rukī."},{"fr":"Les femmes du village font des cordes avec la fibre de coco.","tgt":"गाँव की औरतें नारियल के रेशे से रस्सी बनाती हैं।","ro":"Gāṃv kī aurateṃ nāriyal ke reshe se rassī banātī haiṃ."},{"fr":"Un pêcheur nous a montré ses filets.","tgt":"एक मछुआरे ने हमें अपने जाल दिखाए।","ro":"Ek machhuāre ne hameṃ apne jāl dikhāe."},{"fr":"Nous avons marché au milieu des rizières.","tgt":"हम धान के खेतों के बीच से पैदल चले।","ro":"Ham dhān ke khetoṃ ke bīch se paidal chale."},{"fr":"Les maisons d'ici sont peintes de couleurs vives.","tgt":"यहाँ के घर चटकीले रंगों से रंगे हुए हैं।","ro":"Yahāṃ ke ghar chaṭkīle rangoṃ se range hue haiṃ."},{"fr":"Une vieille dame nous a offert du thé.","tgt":"एक बूढ़ी अम्मा ने हमें चाय पिलाई।","ro":"Ek būṛhī ammā ne hameṃ chāy pilāī."},{"fr":"Les enfants voulaient se faire prendre en photo avec nous.","tgt":"बच्चे हमारे साथ फ़ोटो खिंचवाना चाहते थे।","ro":"Bachche hamāre sāth foṭo khinchvānā chāhte the."},{"fr":"Ici, le canal devient très étroit.","tgt":"यहाँ नहर बहुत तंग हो जाती है।","ro":"Yahāṃ nahar bahut tang ho jātī hai."},{"fr":"Nous avons acheté des bananes depuis une petite barque.","tgt":"हमने एक छोटी नाव से केले ख़रीदे।","ro":"Hamne ek chhoṭī nāv se kele kharīde."},{"fr":"Cette journée au village m'a beaucoup touché.","tgt":"गाँव का यह दिन मेरे दिल को छू गया।","ro":"Gāṃv kā yah din mere dil ko chhū gayā."}]},{"title":"Les plages de Goa","phrases":[{"fr":"Si la mer est calme, nous nagerons ce matin.","tgt":"अगर समुद्र शांत रहा, तो हम आज सुबह तैरेंगे।","ro":"Agar samudra shānt rahā, to ham āj subah taireṃge."},{"fr":"Si vous avez chaud, asseyez-vous à l'ombre.","tgt":"अगर आपको गर्मी लग रही है, तो छाँव में बैठ जाइए।","ro":"Agar āpko garmī lag rahī hai, to chhāṃv meṃ baiṭh jāie."},{"fr":"À midi, le sable est brûlant.","tgt":"दोपहर में रेत बहुत गर्म होती है।","ro":"Dopahar meṃ ret bahut garm hotī hai."},{"fr":"Si nous partons tôt, nous verrons des dauphins.","tgt":"अगर हम जल्दी निकलेंगे, तो डॉल्फ़िन दिखेंगी।","ro":"Agar ham jaldī nikleṃge, to ḍolfin dikheṃgī."},{"fr":"Les vagues sont très fortes aujourd'hui.","tgt":"आज लहरें बहुत तेज़ हैं।","ro":"Āj lahreṃ bahut tez haiṃ."},{"fr":"S'il pleut, nous irons dans un café de la plage.","tgt":"अगर बारिश हुई, तो हम समुद्र तट के किसी कैफ़े में जाएँगे।","ro":"Agar bārish huī, to ham samudra taṭ ke kisī kaife meṃ jāeṃge."},{"fr":"Si vous voulez, je peux vous apprendre à nager.","tgt":"अगर आप चाहें, तो मैं आपको तैरना सिखा सकता हूँ।","ro":"Agar āp chāheṃ, to maiṃ āpko tairnā sikhā saktā hūṃ."},{"fr":"Le soleil qui se couche sur la mer est superbe.","tgt":"समुद्र पर ढलता सूरज बहुत सुंदर लगता है।","ro":"Samudra par ḍhaltā sūraj bahut sundar lagtā hai."},{"fr":"Si vous oubliez la crème solaire, vous allez attraper un coup de soleil.","tgt":"अगर आप सनस्क्रीन भूल गए, तो धूप से जल जाएँगे।","ro":"Agar āp sanskrīn bhūl gae, to dhūp se jal jāeṃge."},{"fr":"Goa est encore plus belle que sur les photos.","tgt":"गोवा तस्वीरों से भी ज़्यादा सुंदर है।","ro":"Govā tasvīroṃ se bhī zyādā sundar hai."}],"tip":{"title":"« Agar... to... » : si... alors...","example":"Si la mer est calme, nous nagerons ce matin. — <b>अगर</b> समुद्र शांत रहा, <b>तो</b> हम आज सुबह तैरेंगे।","body":"Pour dire « si », on ouvre la phrase avec « agar », et on lance la conséquence avec « to », qui veut dire « alors ». En français on dit simplement « si la mer est calme, nous nagerons », mais en hindi on prononce presque toujours les deux mots, comme deux portes qu'on ouvre l'une après l'autre. Décomposons : « agar samudra shānt rahā » veut dire « si la mer reste calme », puis « to ham taireṃge », « alors nous nagerons ». Vous pouvez aussi dire « agar āp chāheṃ, to... », « si vous voulez, alors... », ou « agar bārish huī, to... », « s'il pleut, alors... ». Astuce : marquez une petite pause juste avant « to », c'est exactement le rythme naturel de la phrase parlée.","exampleRo":"Agar samudra shānt rahā, to ham āj subah taireṃge.","lit":"si · mer · calme · resta · alors · nous · aujourd'hui · matin · nagerons","say":{"agar":"अगर","to":"तो","agar samudra shānt rahā":"अगर समुद्र शांत रहा","to ham taireṃge":"तो हम तैरेंगे"}}},{"title":"Un marché de nuit à Goa","phrases":[{"fr":"Le marché de nuit ouvre le samedi soir.","tgt":"रात का बाज़ार शनिवार की शाम को खुलता है।","ro":"Rāt kā bāzār shanivār kī shām ko khultā hai."},{"fr":"Il y a ici des centaines de stands colorés.","tgt":"यहाँ सैकड़ों रंग-बिरंगी दुकानें हैं।","ro":"Yahāṃ saikṛoṃ rang-birangī dukāneṃ haiṃ."},{"fr":"Combien coûte ce sac en tissu ?","tgt":"कपड़े का यह थैला कितने का है?","ro":"Kapṛe kā yah thailā kitne kā hai?"},{"fr":"C'est trop cher, baissez un peu le prix.","tgt":"यह बहुत महँगा है, थोड़ा कम कीजिए।","ro":"Yah bahut mahaṃgā hai, thoṛā kam kījie."},{"fr":"Je vous le laisse à trois cents roupies.","tgt":"मैं आपको तीन सौ रुपये में दे दूँगा।","ro":"Maiṃ āpko tīn sau rupaye meṃ de dūṃgā."},{"fr":"Un groupe joue de la musique là-bas.","tgt":"एक ग्रुप वहाँ संगीत बजा रहा है।","ro":"Ek grup vahāṃ sangīt bajā rahā hai."},{"fr":"Ces bijoux sont faits à la main.","tgt":"ये गहने हाथ से बने हैं।","ro":"Ye gahne hāth se bane haiṃ."},{"fr":"J'ai bu un délicieux jus de canne à sucre.","tgt":"मैंने गन्ने का बढ़िया रस पिया।","ro":"Maiṃne ganne kā baṛhiyā ras piyā."},{"fr":"Faites attention à votre portefeuille dans la foule.","tgt":"भीड़ में अपने बटुए का ध्यान रखिए।","ro":"Bhīṛ meṃ apne baṭue kā dhyān rakhie."},{"fr":"Nous sommes rentrés à l'hôtel après minuit.","tgt":"हम आधी रात के बाद होटल लौटे।","ro":"Ham ādhī rāt ke bād hoṭal lauṭe."}]},{"title":"Louer un scooter","phrases":[{"fr":"Je voudrais louer un scooter pour trois jours.","tgt":"मुझे तीन दिन के लिए स्कूटर किराए पर लेना है।","ro":"Mujhe tīn din ke lie skūṭar kirāe par lenā hai."},{"fr":"Le loueur de scooters est tout près.","tgt":"स्कूटर वाला बिल्कुल पास में है।","ro":"Skūṭar vālā bilkul pās meṃ hai."},{"fr":"Le magasin est sur le point de fermer, dépêchons-nous.","tgt":"दुकान बंद होने वाली है, जल्दी चलिए।","ro":"Dukān band hone vālī hai, jaldī chalie."},{"fr":"Prenez le scooter rouge, il est plus récent.","tgt":"लाल वाला स्कूटर लीजिए, वह ज़्यादा नया है।","ro":"Lāl vālā skūṭar lījie, vah zyādā nayā hai."},{"fr":"Le casque est-il compris dans la location ?","tgt":"क्या हेलमेट किराए में शामिल है?","ro":"Kyā helmeṭ kirāe meṃ shāmil hai?"},{"fr":"Le réservoir est presque vide, je dois mettre de l'essence.","tgt":"टंकी लगभग ख़ाली है, पेट्रोल डलवाना है।","ro":"Ṭankī lagbhag khālī hai, peṭrol ḍalvānā hai."},{"fr":"Ce vendeur de noix de coco est très sympathique.","tgt":"वह नारियल वाला बहुत अच्छा है।","ro":"Vah nāriyal vālā bahut achchhā hai."},{"fr":"Il est sur le point de pleuvoir, rentrons vite.","tgt":"बारिश होने वाली है, जल्दी वापस चलते हैं।","ro":"Bārish hone vālī hai, jaldī vāpas chalte haiṃ."},{"fr":"Le bus pour Panaji est sur le point de partir.","tgt":"पणजी वाली बस छूटने वाली है।","ro":"Paṇjī vālī bas chhūṭne vālī hai."},{"fr":"Roulez prudemment, les routes sont étroites.","tgt":"ध्यान से चलाइए, सड़कें तंग हैं।","ro":"Dhyān se chalāie, saṛkeṃ tang haiṃ."}],"tip":{"title":"« Vālā » : celui qui, et être sur le point de","example":"Le magasin est sur le point de fermer, dépêchons-nous. — दुकान बंद होने <b>वाली</b> है, जल्दी चलिए।","body":"Le petit mot « vālā » est partout dans la bouche des gens. Collé à un nom, il désigne la personne ou la chose liée à ce nom : « skūṭar vālā », c'est le gars des scooters, et « lāl vālā », c'est le rouge, celui-là. Placé après un verbe en « -ne », il veut dire « être sur le point de » : « band hone vālī hai » se décompose en « fermé, devenir, sur le point, est », donc « ça va fermer ». Il s'accorde comme un adjectif : « vālā » au masculin, « vālī » au féminin, « vāle » au pluriel, d'où « bārish hone vālī hai », il va pleuvoir, car la pluie est féminine. Astuce : pensez à « celui de... », et vous l'utiliserez naturellement.","exampleRo":"Dukān band hone vālī hai, jaldī chalie.","lit":"magasin · fermé · devenir · [vālī] · est · vite · allez","say":{"Vālā":"वाला","vālā":"वाला","skūṭar vālā":"स्कूटर वाला","lāl vālā":"लाल वाला","band hone vālī hai":"बंद होने वाली है","vālī":"वाली","vāle":"वाले","bārish hone vālī hai":"बारिश होने वाली है"}}},{"title":"Le train de nuit","phrases":[{"fr":"Notre train de nuit part à dix heures du soir.","tgt":"हमारी रात वाली ट्रेन रात दस बजे छूटती है।","ro":"Hamārī rāt vālī ṭren rāt das baje chhūṭtī hai."},{"fr":"J'ai réservé deux couchettes dans un wagon climatisé.","tgt":"मैंने एसी डिब्बे में दो बर्थ बुक कीं।","ro":"Maiṃne esī ḍibbe meṃ do barth buk kīṃ."},{"fr":"Ma couchette, c'est celle du haut.","tgt":"मेरी बर्थ ऊपर वाली है।","ro":"Merī barth ūpar vālī hai."},{"fr":"Le contrôleur est en train de vérifier les billets.","tgt":"टीटी टिकट चेक कर रहा है।","ro":"Ṭīṭī ṭikaṭ chek kar rahā hai."},{"fr":"Un vendeur arrive avec du thé chaud.","tgt":"एक चायवाला गरम चाय लेकर आ रहा है।","ro":"Ek chāyvālā garam chāy lekar ā rahā hai."},{"fr":"Où avez-vous mis nos bagages ?","tgt":"आपने हमारा सामान कहाँ रखा?","ro":"Āpne hamārā sāmān kahāṃ rakhā?"},{"fr":"Je les ai attachés sous la banquette avec une chaîne.","tgt":"मैंने उसे सीट के नीचे ज़ंजीर से बाँध दिया।","ro":"Maiṃne use sīṭ ke nīche zanjīr se bāṃdh diyā."},{"fr":"Le train s'est arrêté quelque part en pleine campagne.","tgt":"ट्रेन कहीं बीच रास्ते में रुक गई।","ro":"Ṭren kahīṃ bīch rāste meṃ ruk gaī."},{"fr":"J'ai très bien dormi malgré le bruit.","tgt":"शोर के बावजूद मुझे बहुत अच्छी नींद आई।","ro":"Shor ke bāvjūd mujhe bahut achchhī nīnd āī."},{"fr":"Nous arriverons demain matin à New Jalpaiguri.","tgt":"हम कल सुबह न्यू जलपाईगुड़ी पहुँचेंगे।","ro":"Ham kal subah Nyū Jalpāīguṛī pahuṃcheṃge."}]},{"title":"Les plantations de thé de Darjeeling","phrases":[{"fr":"Les plantations de thé couvrent toutes les collines.","tgt":"चाय के बागान सारी पहाड़ियों पर फैले हैं।","ro":"Chāy ke bāgān sārī pahāṛiyoṃ par phaile haiṃ."},{"fr":"Ici, les gens cueillent les feuilles à la main.","tgt":"यहाँ लोग हाथ से पत्तियाँ तोड़ते हैं।","ro":"Yahāṃ log hāth se pattiyāṃ toṛte haiṃ."},{"fr":"On ne cueille que les deux feuilles du haut.","tgt":"वे सिर्फ़ ऊपर की दो पत्तियाँ तोड़ते हैं।","ro":"Ve sirf ūpar kī do pattiyāṃ toṛte haiṃ."},{"fr":"Nous avons visité une petite fabrique de thé.","tgt":"हमने चाय की एक छोटी फ़ैक्टरी देखी।","ro":"Hamne chāy kī ek chhoṭī faikṭrī dekhī."},{"fr":"Le guide nous a expliqué comment on fait sécher les feuilles.","tgt":"गाइड ने हमें बताया कि पत्तियाँ कैसे सुखाई जाती हैं।","ro":"Gāiḍ ne hameṃ batāyā ki pattiyāṃ kaise sukhāī jātī haiṃ."},{"fr":"Goûtez ce thé, son parfum est très léger.","tgt":"यह चाय चखिए, इसकी ख़ुशबू बहुत हल्की है।","ro":"Yah chāy chakhie, iskī khushbū bahut halkī hai."},{"fr":"Le thé de printemps est toujours le plus cher.","tgt":"बसंत की चाय सबसे महँगी होती है।","ro":"Basant kī chāy sabse mahaṃgī hotī hai."},{"fr":"Le brouillard monte depuis la vallée.","tgt":"घाटी से कोहरा ऊपर उठ रहा है।","ro":"Ghāṭī se kohrā ūpar uṭh rahā hai."},{"fr":"Par temps clair, on aperçoit le Kangchenjunga.","tgt":"साफ़ मौसम में कंचनजंगा दिखता है।","ro":"Sāf mausam meṃ Kanchanjangā dikhtā hai."},{"fr":"J'ai acheté deux paquets pour ma famille.","tgt":"मैंने अपने परिवार के लिए दो पैकेट ख़रीदे।","ro":"Maiṃne apne parivār ke lie do paikeṭ kharīde."}]},{"title":"Un réveil très matinal à Tiger Hill","phrases":[{"fr":"Nous allons devoir nous lever à quatre heures du matin.","tgt":"हमें सुबह चार बजे उठना पड़ेगा।","ro":"Hameṃ subah chār baje uṭhnā paṛegā."},{"fr":"Pour voir le soleil se lever, il faut partir très tôt.","tgt":"सूरज को उगते हुए देखने के लिए बहुत जल्दी निकलना पड़ता है।","ro":"Sūraj ko ugte hue dekhne ke lie bahut jaldī nikalnā paṛtā hai."},{"fr":"En montagne, on doit toujours prendre un pull.","tgt":"पहाड़ों में हमेशा स्वेटर साथ रखना पड़ता है।","ro":"Pahāṛoṃ meṃ hameshā sveṭar sāth rakhnā paṛtā hai."},{"fr":"Hier, nous avons dû attendre le taxi une heure.","tgt":"कल हमें एक घंटा टैक्सी का इंतज़ार करना पड़ा।","ro":"Kal hameṃ ek ghanṭā ṭaiksī kā intazār karnā paṛā."},{"fr":"Il fait si froid qu'on est obligé de porter des gants.","tgt":"इतनी ठंड है कि दस्ताने पहनने पड़ते हैं।","ro":"Itnī ṭhanḍ hai ki dastāne pahanne paṛte haiṃ."},{"fr":"Le soleil se lève derrière les sommets enneigés.","tgt":"सूरज बर्फ़ीली चोटियों के पीछे से उगता है।","ro":"Sūraj barfīlī choṭiyoṃ ke pīchhe se ugtā hai."},{"fr":"Quand le ciel devient rose, tout le monde applaudit.","tgt":"जब आसमान गुलाबी होता है, तो सब लोग ताली बजाते हैं।","ro":"Jab āsmān gulābī hotā hai, to sab log tālī bajāte haiṃ."},{"fr":"Est-ce qu'on doit payer pour entrer ?","tgt":"क्या अंदर जाने के लिए पैसे देने पड़ते हैं?","ro":"Kyā andar jāne ke lie paise dene paṛte haiṃ?"},{"fr":"Oui, il faut prendre un billet à l'entrée.","tgt":"हाँ, गेट पर टिकट लेना पड़ता है।","ro":"Hāṃ, geṭ par ṭikaṭ lenā paṛtā hai."},{"fr":"Franchement, se lever tôt en valait la peine.","tgt":"सच में, जल्दी उठना बिल्कुल सही रहा।","ro":"Sach meṃ, jaldī uṭhnā bilkul sahī rahā."}],"tip":{"title":"« Paṛtā hai » : être obligé de","example":"En montagne, on doit toujours prendre un pull. — पहाड़ों में हमेशा स्वेटर साथ रखना <b>पड़ता</b> है।","body":"Quand une obligation vous tombe dessus sans que vous l'ayez choisie, on utilise le verbe « paṛnā », qui veut dire littéralement « tomber ». On met le verbe à l'infinitif en « -nā », puis « paṛtā hai » : « rakhnā paṛtā hai », il faut garder, mot à mot « garder tombe ». La personne obligée prend « ko » : « hameṃ », c'est-à-dire « à nous », comme en français « il nous faut ». Pour le passé on dit « paṛā », pour le futur « paṛegā » : « intazār karnā paṛā », on a dû attendre, et « uṭhnā paṛegā », on devra se lever. Astuce : imaginez que la corvée vous tombe sur la tête, et le mot « paṛnā » vous reviendra tout seul.","exampleRo":"Pahāṛoṃ meṃ hameshā sveṭar sāth rakhnā paṛtā hai.","lit":"montagnes · [dans] · toujours · pull · avec · garder · tombe · est","say":{"Paṛtā hai":"पड़ता है","paṛnā":"पड़ना","paṛtā hai":"पड़ता है","rakhnā paṛtā hai":"रखना पड़ता है","ko":"को","hameṃ":"हमें","paṛā":"पड़ा","paṛegā":"पड़ेगा","intazār karnā paṛā":"इंतज़ार करना पड़ा","uṭhnā paṛegā":"उठना पड़ेगा","-nā":"ना"}}},{"title":"Une auberge à Manali","phrases":[{"fr":"Nous avons trouvé une bonne auberge dans le vieux Manali.","tgt":"हमें पुराने मनाली में एक अच्छा हॉस्टल मिला।","ro":"Hameṃ purāne Manālī meṃ ek achchhā hosṭal milā."},{"fr":"Un lit en dortoir coûte quatre cents roupies.","tgt":"डॉरमेट्री में एक बिस्तर चार सौ रुपये का है।","ro":"Ḍormeṭrī meṃ ek bistar chār sau rupaye kā hai."},{"fr":"Depuis la terrasse, la vue sur la rivière est magnifique.","tgt":"छत से नदी का नज़ारा शानदार है।","ro":"Chhat se nadī kā nazārā shāndār hai."},{"fr":"Est-ce qu'il y a de l'eau chaude le matin ?","tgt":"क्या सुबह गरम पानी आता है?","ro":"Kyā subah garam pānī ātā hai?"},{"fr":"Oui, mais seulement de sept à neuf heures.","tgt":"हाँ, पर सिर्फ़ सात से नौ बजे तक।","ro":"Hāṃ, par sirf sāt se nau baje tak."},{"fr":"Le soir, tout le monde se réunit autour du feu.","tgt":"शाम को सब लोग आग के पास इकट्ठा होते हैं।","ro":"Shām ko sab log āg ke pās ikaṭṭhā hote haiṃ."},{"fr":"Le gérant m'a donné une couverture de plus.","tgt":"मैनेजर ने मुझे एक और कंबल दिया।","ro":"Mainejar ne mujhe ek aur kambal diyā."},{"fr":"Le wifi ne marche que dans la salle commune.","tgt":"वाई-फ़ाई सिर्फ़ कॉमन रूम में चलता है।","ro":"Vāī-fāī sirf koman rūm meṃ chaltā hai."},{"fr":"Pouvons-nous laisser nos sacs ici jusqu'à midi ?","tgt":"क्या हम दोपहर तक अपने बैग यहाँ छोड़ सकते हैं?","ro":"Kyā ham dopahar tak apne baig yahāṃ chhoṛ sakte haiṃ?"},{"fr":"Cette auberge est parfaite pour rencontrer d'autres voyageurs.","tgt":"यह हॉस्टल दूसरे यात्रियों से मिलने के लिए एकदम सही है।","ro":"Yah hosṭal dūsre yātriyoṃ se milne ke lie ekdam sahī hai."}]},{"title":"Randonnée vers une cascade","phrases":[{"fr":"Aujourd'hui, nous allons grimper jusqu'à une cascade.","tgt":"आज हम एक झरने तक चढ़ाई करेंगे।","ro":"Āj ham ek jharne tak chaṛhāī kareṃge."},{"fr":"Le sentier passe par une forêt de pins.","tgt":"रास्ता चीड़ के जंगल से होकर जाता है।","ro":"Rāstā chīṛ ke jangal se hokar jātā hai."},{"fr":"N'oubliez pas de prendre assez d'eau.","tgt":"काफ़ी पानी लेना मत भूलिए।","ro":"Kāfī pānī lenā mat bhūlie."},{"fr":"Je suis un peu essoufflé, arrêtons-nous un moment.","tgt":"मेरी साँस फूल रही है, थोड़ा रुकते हैं।","ro":"Merī sāṃs phūl rahī hai, thoṛā rukte haiṃ."},{"fr":"Combien de temps faut-il pour arriver en haut ?","tgt":"ऊपर पहुँचने में कितना समय लगता है?","ro":"Ūpar pahuṃchne meṃ kitnā samay lagtā hai?"},{"fr":"Environ deux heures, en marchant tranquillement.","tgt":"आराम से चलने पर लगभग दो घंटे।","ro":"Ārām se chalne par lagbhag do ghanṭe."},{"fr":"Des bergers descendent avec leurs moutons.","tgt":"चरवाहे अपनी भेड़ों के साथ नीचे आ रहे हैं।","ro":"Charvāhe apnī bheṛoṃ ke sāth nīche ā rahe haiṃ."},{"fr":"L'eau de la cascade est glacée.","tgt":"झरने का पानी बर्फ़ जैसा ठंडा है।","ro":"Jharne kā pānī barf jaisā ṭhanḍā hai."},{"fr":"J'ai pris des dizaines de photos du paysage.","tgt":"मैंने नज़ारे की दर्जनों तस्वीरें लीं।","ro":"Maiṃne nazāre kī darjanoṃ tasvīreṃ līṃ."},{"fr":"J'ai les jambes fatiguées, mais je suis heureux.","tgt":"मेरी टाँगें थक गई हैं, पर मैं ख़ुश हूँ।","ro":"Merī ṭāṃgeṃ thak gaī haiṃ, par maiṃ khush hūṃ."}]},{"title":"Un col sous la neige","phrases":[{"fr":"La route du col est ouverte depuis hier.","tgt":"दर्रे की सड़क कल से खुली है।","ro":"Darre kī saṛak kal se khulī hai."},{"fr":"Nous avons loué des vêtements chauds en bas.","tgt":"हमने नीचे गरम कपड़े किराए पर लिए।","ro":"Hamne nīche garam kapṛe kirāe par lie."},{"fr":"À cette altitude, il y a moins d'oxygène dans l'air.","tgt":"इतनी ऊँचाई पर हवा में ऑक्सीजन कम होती है।","ro":"Itnī ūṃchāī par havā meṃ oksījan kam hotī hai."},{"fr":"J'ai un léger mal de tête.","tgt":"मेरे सिर में हल्का दर्द है।","ro":"Mere sir meṃ halkā dard hai."},{"fr":"Buvez de l'eau et marchez lentement.","tgt":"पानी पीजिए और धीरे-धीरे चलिए।","ro":"Pānī pījie aur dhīre-dhīre chalie."},{"fr":"Les enfants font des bonshommes de neige.","tgt":"बच्चे बर्फ़ के पुतले बना रहे हैं।","ro":"Bachche barf ke putle banā rahe haiṃ."},{"fr":"J'ai fait du ski pour la toute première fois.","tgt":"मैंने पहली बार स्कीइंग की।","ro":"Maiṃne pahlī bār skīing kī."},{"fr":"Je suis tombé trois fois dans la neige !","tgt":"मैं बर्फ़ में तीन बार गिरा।","ro":"Maiṃ barf meṃ tīn bār girā."},{"fr":"Le chauffeur veut redescendre avant la tombée de la nuit.","tgt":"ड्राइवर अँधेरे से पहले नीचे उतरना चाहता है।","ro":"Ḍrāivar aṃdhere se pahle nīche utarnā chāhtā hai."},{"fr":"Je me souviendrai toujours de ce paysage blanc.","tgt":"यह सफ़ेद नज़ारा मुझे हमेशा याद रहेगा।","ro":"Yah safed nazārā mujhe hameshā yād rahegā."}]},{"title":"Qu'est-ce qu'on fait demain ?","phrases":[{"fr":"Et si on allait à Solang demain matin ?","tgt":"कल सुबह सोलंग चलें?","ro":"Kal subah Solang chaleṃ?"},{"fr":"Qu'est-ce que je fais, je réserve un taxi ?","tgt":"मैं क्या करूँ, टैक्सी बुक करूँ?","ro":"Maiṃ kyā karūṃ, ṭaiksī buk karūṃ?"},{"fr":"Peut-être qu'il fera beau demain.","tgt":"शायद कल मौसम अच्छा रहे।","ro":"Shāyad kal mausam achchhā rahe."},{"fr":"Je voudrais que vous veniez avec nous.","tgt":"मैं चाहता हूँ कि आप हमारे साथ चलें।","ro":"Maiṃ chāhtā hūṃ ki āp hamāre sāth chaleṃ."},{"fr":"Je m'assieds ici ?","tgt":"क्या मैं यहाँ बैठूँ?","ro":"Kyā maiṃ yahāṃ baiṭhūṃ?"},{"fr":"Mangeons d'abord, ensuite on part.","tgt":"पहले खाना खा लें, फिर निकलें।","ro":"Pahle khānā khā leṃ, phir nikleṃ."},{"fr":"Il vaut mieux que nous partions avant la pluie.","tgt":"बेहतर है कि हम बारिश से पहले निकल जाएँ।","ro":"Behtar hai ki ham bārish se pahle nikal jāeṃ."},{"fr":"Je prends du thé ou un café ?","tgt":"मैं चाय लूँ या कॉफ़ी?","ro":"Maiṃ chāy lūṃ yā kofī?"},{"fr":"Le guide propose que nous dormions sous la tente.","tgt":"गाइड कहता है कि हम तंबू में सोएँ।","ro":"Gāiḍ kahtā hai ki ham tambū meṃ soeṃ."},{"fr":"D'accord, allons-y tous ensemble.","tgt":"ठीक है, सब साथ चलें।","ro":"Ṭhīk hai, sab sāth chaleṃ."}],"tip":{"title":"Le subjonctif : « chaleṃ, karūṃ »","example":"Qu'est-ce que je fais, je réserve un taxi ? — मैं क्या <b>करूँ</b>, टैक्सी बुक <b>करूँ</b>?","body":"Pour proposer, hésiter ou demander l'avis de quelqu'un, le hindi a une forme très courte, le subjonctif. On prend la racine du verbe et on ajoute « -ūṃ » pour moi, « -eṃ » pour nous ou pour vous : « karūṃ », que je fasse, « chaleṃ », allons-y, ou que vous veniez. Décomposons : « maiṃ kyā karūṃ ? » veut dire « je, quoi, que je fasse ? », c'est-à-dire « qu'est-ce que je fais ? ». On l'emploie aussi après « ki » quand on souhaite quelque chose, comme en français : « maiṃ chāhtā hūṃ ki āp chaleṃ », je voudrais que vous veniez. Astuce : dès que vous voulez dire « et si on... ? », dites simplement « chaleṃ ? » avec une voix qui monte.","exampleRo":"Maiṃ kyā karūṃ, ṭaiksī buk karūṃ?","lit":"je · quoi · fasse · taxi · réservation · fasse ?","say":{"karūṃ":"करूँ","chaleṃ":"चलें","maiṃ kyā karūṃ ?":"मैं क्या करूँ?","ki":"कि","maiṃ chāhtā hūṃ ki āp chaleṃ":"मैं चाहता हूँ कि आप चलें","chaleṃ ?":"चलें?","chaleṃ, karūṃ":"चलें, करूँ"}}},{"title":"Le bus de nuit dans la montagne","phrases":[{"fr":"Le bus pour Delhi part à cinq heures du soir.","tgt":"दिल्ली की बस शाम पाँच बजे निकलती है।","ro":"Dillī kī bas shām pāṃch baje nikaltī hai."},{"fr":"J'ai pris une place côté fenêtre.","tgt":"मैंने खिड़की वाली सीट ली।","ro":"Maiṃne khiṛkī vālī sīṭ lī."},{"fr":"La route est pleine de virages.","tgt":"रास्ते में बहुत मोड़ हैं।","ro":"Rāste meṃ bahut moṛ haiṃ."},{"fr":"Mon voisin a mal au cœur.","tgt":"मेरे पास बैठे आदमी का जी मिचला रहा है।","ro":"Mere pās baiṭhe ādmī kā jī michlā rahā hai."},{"fr":"Je lui ai donné un bonbon au gingembre.","tgt":"मैंने उसे अदरक वाली टॉफ़ी दी।","ro":"Maiṃne use adrak vālī ṭofī dī."},{"fr":"Le bus s'arrête pour le dîner vers neuf heures.","tgt":"बस नौ बजे के आसपास खाने के लिए रुकती है।","ro":"Bas nau baje ke āspās khāne ke lie ruktī hai."},{"fr":"Nous avons mangé un dal bien chaud dans un petit dhaba.","tgt":"हमने एक छोटे ढाबे में गरमागरम दाल खाई।","ro":"Hamne ek chhoṭe ḍhābe meṃ garmāgaram dāl khāī."},{"fr":"Le chauffeur roule vite, mais avec prudence.","tgt":"ड्राइवर तेज़ चलाता है, पर सावधानी से।","ro":"Ḍrāivar tez chalātā hai, par sāvdhānī se."},{"fr":"Je n'ai presque pas fermé l'œil de la nuit.","tgt":"मुझे रात भर लगभग नींद नहीं आई।","ro":"Mujhe rāt bhar lagbhag nīnd nahīṃ āī."},{"fr":"Nous sommes arrivés au petit matin, épuisés.","tgt":"हम सुबह-सुबह थके-हारे पहुँचे।","ro":"Ham subah-subah thake-hāre pahuṃche."}]},{"title":"Un train annulé","phrases":[{"fr":"Notre train a été annulé à cause des pluies.","tgt":"बारिश की वजह से हमारी ट्रेन रद्द हो गई।","ro":"Bārish kī vajah se hamārī ṭren radd ho gaī."},{"fr":"Où se trouve le guichet des réservations ?","tgt":"रिज़र्वेशन की खिड़की कहाँ है?","ro":"Rizarveshan kī khiṛkī kahāṃ hai?"},{"fr":"Pouvez-vous nous rembourser nos billets ?","tgt":"क्या आप हमारे टिकट के पैसे वापस कर सकते हैं?","ro":"Kyā āp hamāre ṭikaṭ ke paise vāpas kar sakte haiṃ?"},{"fr":"Oui, remplissez d'abord ce formulaire.","tgt":"हाँ, पहले यह फ़ॉर्म भरिए।","ro":"Hāṃ, pahle yah form bharie."},{"fr":"Y a-t-il un autre train ce soir ?","tgt":"क्या आज रात कोई और ट्रेन है?","ro":"Kyā āj rāt koī aur ṭren hai?"},{"fr":"Il n'y a plus aucune place libre avant après-demain.","tgt":"परसों से पहले कोई सीट ख़ाली नहीं है।","ro":"Parsoṃ se pahle koī sīṭ khālī nahīṃ hai."},{"fr":"Dans ce cas, nous partirons en bus.","tgt":"तो हम बस से चले जाएँगे।","ro":"To ham bas se chale jāeṃge."},{"fr":"J'ai appelé l'hôtel pour dire que nous arriverons en retard.","tgt":"मैंने होटल को फ़ोन करके बताया कि हम देर से आएँगे।","ro":"Maiṃne hoṭal ko fon karke batāyā ki ham der se āeṃge."},{"fr":"Ne vous inquiétez pas, votre chambre sera prête.","tgt":"चिंता मत कीजिए, आपका कमरा तैयार रहेगा।","ro":"Chintā mat kījie, āpkā kamrā taiyār rahegā."},{"fr":"En voyage, il faut savoir garder son calme.","tgt":"सफ़र में शांत रहना आना चाहिए।","ro":"Safar meṃ shānt rahnā ānā chāhie."}]},{"title":"Un petit souci de santé","phrases":[{"fr":"Je ne me sens pas très bien depuis ce matin.","tgt":"सुबह से मेरी तबीयत ठीक नहीं है।","ro":"Subah se merī tabīyat ṭhīk nahīṃ hai."},{"fr":"J'ai mal au ventre et un peu de fièvre.","tgt":"मेरे पेट में दर्द है और हल्का बुख़ार है।","ro":"Mere peṭ meṃ dard hai aur halkā bukhār hai."},{"fr":"Y a-t-il une pharmacie près d'ici ?","tgt":"क्या यहाँ पास में कोई दवाई की दुकान है?","ro":"Kyā yahāṃ pās meṃ koī davāī kī dukān hai?"},{"fr":"Qu'avez-vous mangé hier soir ?","tgt":"आपने कल रात क्या खाया था?","ro":"Āpne kal rāt kyā khāyā thā?"},{"fr":"J'ai mangé des fruits coupés dans la rue.","tgt":"मैंने सड़क पर कटे हुए फल खाए थे।","ro":"Maiṃne saṛak par kaṭe hue phal khāe the."},{"fr":"Prenez ce médicament deux fois par jour.","tgt":"यह दवाई दिन में दो बार लीजिए।","ro":"Yah davāī din meṃ do bār lījie."},{"fr":"Buvez beaucoup d'eau en bouteille.","tgt":"ख़ूब बोतल वाला पानी पीजिए।","ro":"Khūb botal vālā pānī pījie."},{"fr":"Évitez la nourriture épicée pendant deux jours.","tgt":"दो दिन तक मसालेदार खाना मत खाइए।","ro":"Do din tak masāledār khānā mat khāie."},{"fr":"Merci, je me sens déjà un peu mieux.","tgt":"शुक्रिया, अब थोड़ा बेहतर लग रहा है।","ro":"Shukriyā, ab thoṛā behtar lag rahā hai."},{"fr":"Aujourd'hui, je vais me reposer à l'auberge.","tgt":"आज मैं हॉस्टल में आराम करूँगा।","ro":"Āj maiṃ hosṭal meṃ ārām karūṃgā."}]},{"title":"Une journée où tout va de travers","phrases":[{"fr":"Il pleuvait, mais nous sommes quand même sortis.","tgt":"बारिश हो रही थी, लेकिन हम बाहर गए।","ro":"Bārish ho rahī thī, lekin ham bāhar gae."},{"fr":"Le scooter est tombé en panne, mais un mécanicien nous a aidés.","tgt":"स्कूटर ख़राब हो गया, लेकिन एक मिस्त्री ने हमारी मदद की।","ro":"Skūṭar kharāb ho gayā, lekin ek mistrī ne hamārī madad kī."},{"fr":"J'ai perdu ma carte, et pourtant j'ai trouvé le chemin.","tgt":"मेरा नक्शा खो गया, फिर भी मुझे रास्ता मिल गया।","ro":"Merā nakshā kho gayā, phir bhī mujhe rāstā mil gayā."},{"fr":"L'auberge était pleine, mais le patron nous a trouvé une chambre.","tgt":"हॉस्टल भरा हुआ था, लेकिन मालिक ने हमें एक कमरा दिला दिया।","ro":"Hosṭal bharā huā thā, lekin mālik ne hameṃ ek kamrā dilā diyā."},{"fr":"La route était fermée, et pourtant nous sommes arrivés à l'heure.","tgt":"सड़क बंद थी, फिर भी हम समय पर पहुँच गए।","ro":"Saṛak band thī, phir bhī ham samay par pahuṃch gae."},{"fr":"Je suis très fatigué, mais je veux voir le lac.","tgt":"मैं बहुत थका हुआ हूँ, लेकिन झील देखना चाहता हूँ।","ro":"Maiṃ bahut thakā huā hūṃ, lekin jhīl dekhnā chāhtā hūṃ."},{"fr":"Le repas était simple, et pourtant délicieux.","tgt":"खाना सादा था, फिर भी बहुत स्वादिष्ट था।","ro":"Khānā sādā thā, phir bhī bahut svādishṭ thā."},{"fr":"On nous avait prévenus, mais nous n'avons pas écouté.","tgt":"हमें पहले ही बताया गया था, लेकिन हमने नहीं सुना।","ro":"Hameṃ pahle hī batāyā gayā thā, lekin hamne nahīṃ sunā."},{"fr":"Rien ne s'est passé comme prévu.","tgt":"कुछ भी प्लान के मुताबिक़ नहीं हुआ।","ro":"Kuchh bhī plān ke mutābik nahīṃ huā."},{"fr":"Et pourtant, c'était une très belle journée.","tgt":"फिर भी, यह बहुत अच्छा दिन था।","ro":"Phir bhī, yah bahut achchhā din thā."}],"tip":{"title":"« Lekin » et « phir bhī » : mais et pourtant","example":"J'ai perdu ma carte, et pourtant j'ai trouvé le chemin. — मेरा नक्शा खो गया, <b>फिर भी</b> मुझे रास्ता मिल गया।","body":"Pour opposer deux idées, on place « lekin », qui veut dire « mais », exactement comme en français, au milieu de la phrase : « bārish ho rahī thī, lekin ham bāhar gae », il pleuvait, mais nous sommes sortis. Dans la conversation de tous les jours, on entend aussi « par », plus court et plus familier, qui a le même sens. Quand on veut dire « et pourtant » ou « quand même », on utilise « phir bhī », mot à mot « encore aussi » : « merā nakshā kho gayā, phir bhī mujhe rāstā mil gayā », ma carte s'est perdue, pourtant j'ai trouvé le chemin. On peut même commencer une phrase par « phir bhī », comme « phir bhī, yah achchhā din thā ». Astuce : « lekin » oppose, « phir bhī » résiste, prononcez-le avec un petit sourire de victoire.","exampleRo":"Merā nakshā kho gayā, phir bhī mujhe rāstā mil gayā.","lit":"mon · carte · perdu · alla · pourtant · [à moi] · chemin · trouvé · alla","say":{"Lekin":"लेकिन","phir bhī":"फिर भी","lekin":"लेकिन","bārish ho rahī thī, lekin ham bāhar gae":"बारिश हो रही थी, लेकिन हम बाहर गए","par":"पर","merā nakshā kho gayā, phir bhī mujhe rāstā mil gayā":"मेरा नक्शा खो गया, फिर भी मुझे रास्ता मिल गया","phir bhī, yah achchhā din thā":"फिर भी, यह अच्छा दिन था"}}},{"title":"Rencontres entre voyageurs","phrases":[{"fr":"Depuis combien de temps voyagez-vous en Inde ?","tgt":"आप भारत में कब से घूम रहे हैं?","ro":"Āp Bhārat meṃ kab se ghūm rahe haiṃ?"},{"fr":"Ça fait déjà trois semaines que je voyage.","tgt":"मुझे घूमते हुए तीन हफ़्ते हो गए हैं।","ro":"Mujhe ghūmte hue tīn hafte ho gae haiṃ."},{"fr":"Quel endroit avez-vous préféré jusqu'ici ?","tgt":"अब तक आपको कौन-सी जगह सबसे अच्छी लगी?","ro":"Ab tak āpko kaun-sī jagah sabse achchhī lagī?"},{"fr":"J'ai adoré les backwaters du Kerala.","tgt":"मुझे केरल के बैकवाटर बहुत पसंद आए।","ro":"Mujhe Keral ke baikvāṭar bahut pasand āe."},{"fr":"Une jeune Française m'a parlé d'un village près d'ici.","tgt":"एक फ़्रांसीसी लड़की ने मुझे पास के एक गाँव के बारे में बताया।","ro":"Ek frānsīsī laṛkī ne mujhe pās ke ek gāṃv ke bāre meṃ batāyā."},{"fr":"Voulez-vous partager un taxi demain ?","tgt":"क्या आप कल टैक्सी शेयर करना चाहेंगे?","ro":"Kyā āp kal ṭaiksī sheyar karnā chāheṃge?"},{"fr":"Bonne idée, ça nous reviendra moins cher.","tgt":"अच्छा विचार है, सस्ता पड़ेगा।","ro":"Achchhā vichār hai, sastā paṛegā."},{"fr":"Échangeons nos numéros de téléphone.","tgt":"चलिए, एक-दूसरे का नंबर ले लेते हैं।","ro":"Chalie, ek-dūsre kā nambar le lete haiṃ."},{"fr":"Ce soir, nous allons cuisiner tous ensemble.","tgt":"आज रात हम सब मिलकर खाना बनाएँगे।","ro":"Āj rāt ham sab milkar khānā banāeṃge."},{"fr":"Voyager, c'est aussi rencontrer des gens.","tgt":"सफ़र का मतलब लोगों से मिलना भी है।","ro":"Safar kā matlab logoṃ se milnā bhī hai."}]},{"title":"Le marché aux épices de Kochi","phrases":[{"fr":"Le marché aux épices de Kochi sent merveilleusement bon.","tgt":"कोच्चि के मसाला बाज़ार की ख़ुशबू कमाल की है।","ro":"Kochchi ke masālā bāzār kī khushbū kamāl kī hai."},{"fr":"Je cherche de la cardamome verte.","tgt":"मुझे हरी इलायची चाहिए।","ro":"Mujhe harī ilāychī chāhie."},{"fr":"Ce poivre noir vient des collines voisines.","tgt":"यह काली मिर्च पास की पहाड़ियों से आती है।","ro":"Yah kālī mirch pās kī pahāṛiyoṃ se ātī hai."},{"fr":"Pouvez-vous bien fermer le sachet ?","tgt":"क्या आप थैली अच्छी तरह बंद कर सकते हैं?","ro":"Kyā āp thailī achchhī tarah band kar sakte haiṃ?"},{"fr":"Donnez-moi cent grammes de chaque.","tgt":"हर चीज़ सौ-सौ ग्राम दीजिए।","ro":"Har chīz sau-sau grām dījie."},{"fr":"Le vendeur m'a fait goûter du gingembre séché.","tgt":"दुकानदार ने मुझे सूखी अदरक चखाई।","ro":"Dukāndār ne mujhe sūkhī adrak chakhāī."},{"fr":"Ma mère adore la cannelle.","tgt":"मेरी माँ को दालचीनी बहुत पसंद है।","ro":"Merī māṃ ko dālchīnī bahut pasand hai."},{"fr":"Acceptez-vous le paiement par téléphone ?","tgt":"क्या आप फ़ोन से पेमेंट लेते हैं?","ro":"Kyā āp fon se pemenṭ lete haiṃ?"},{"fr":"Le tout fait huit cent cinquante roupies.","tgt":"सब मिलाकर आठ सौ पचास रुपये हुए।","ro":"Sab milākar āṭh sau pachās rupaye hue."},{"fr":"Ma valise va sentir les épices pendant des semaines.","tgt":"मेरा सूटकेस हफ़्तों तक मसालों से महकेगा।","ro":"Merā sūṭkes haftoṃ tak masāloṃ se mahkegā."}]},{"title":"Les derniers jours en Inde","phrases":[{"fr":"Notre vol pour Paris part après-demain.","tgt":"पेरिस के लिए हमारी फ़्लाइट परसों है।","ro":"Peris ke lie hamārī flāiṭ parsoṃ hai."},{"fr":"Je dois confirmer le taxi pour l'aéroport.","tgt":"हवाई अड्डे के लिए टैक्सी पक्की करनी है।","ro":"Havāī aḍḍe ke lie ṭaiksī pakkī karnī hai."},{"fr":"J'ai mis les cadeaux fragiles dans mon sac.","tgt":"मैंने नाज़ुक तोहफ़े अपने बैग में रखे।","ro":"Maiṃne nāzuk tohfe apne baig meṃ rakhe."},{"fr":"Ma valise est devenue beaucoup trop lourde.","tgt":"मेरा सूटकेस बहुत भारी हो गया है।","ro":"Merā sūṭkes bahut bhārī ho gayā hai."},{"fr":"Il nous reste encore quelques roupies.","tgt":"हमारे पास अभी भी थोड़े रुपये बचे हैं।","ro":"Hamāre pās abhī bhī thoṛe rupaye bache haiṃ."},{"fr":"Allons faire une dernière promenade sur la plage.","tgt":"चलिए, समुद्र तट पर आख़िरी बार घूम लेते हैं।","ro":"Chalie, samudra taṭ par ākhirī bār ghūm lete haiṃ."},{"fr":"La cuisine d'ici va beaucoup me manquer.","tgt":"मुझे यहाँ के खाने की बहुत याद आएगी।","ro":"Mujhe yahāṃ ke khāne kī bahut yād āegī."},{"fr":"Nous avons vu tellement d'endroits différents !","tgt":"हमने कितनी अलग-अलग जगहें देखीं।","ro":"Hamne kitnī alag-alag jagaheṃ dekhīṃ."},{"fr":"Nous reviendrons l'année prochaine, c'est promis.","tgt":"हम अगले साल फिर आएँगे, पक्का।","ro":"Ham agle sāl phir āeṃge, pakkā."},{"fr":"Au revoir l'Inde, et merci pour tout !","tgt":"अलविदा भारत, सब कुछ के लिए शुक्रिया।","ro":"Alvidā Bhārat, sab kuchh ke lie shukriyā."}]},{"title":"Fin du module : un bilan de voyage","phrases":[{"fr":"Dans ce module, nous avons voyagé du Kerala jusqu'à Manali.","tgt":"इस मॉड्यूल में हमने केरल से मनाली तक सफ़र किया।","ro":"Is moḍyūl meṃ hamne Keral se Manālī tak safar kiyā."},{"fr":"Maintenant, je peux louer un scooter et réserver un train.","tgt":"अब मैं स्कूटर किराए पर ले सकता हूँ और ट्रेन बुक कर सकता हूँ।","ro":"Ab maiṃ skūṭar kirāe par le saktā hūṃ aur ṭren buk kar saktā hūṃ."},{"fr":"Je sais aussi faire face aux situations difficiles.","tgt":"मैं मुश्किल हालात भी सँभाल सकता हूँ।","ro":"Maiṃ mushkil hālāt bhī saṃbhāl saktā hūṃ."},{"fr":"Avec « agar » et « to », je peux faire des projets.","tgt":"अगर और तो से मैं योजनाएँ बना सकता हूँ।","ro":"Agar aur to se maiṃ yojnāeṃ banā saktā hūṃ."},{"fr":"Et avec « paṛtā hai », je peux dire ce que je dois faire.","tgt":"और पड़ता है से मैं अपनी मजबूरियाँ बता सकता हूँ।","ro":"Aur paṛtā hai se maiṃ apnī majbūriyāṃ batā saktā hūṃ."},{"fr":"Je fais encore des erreurs, mais je parle sans peur.","tgt":"मैं अब भी ग़लतियाँ करता हूँ, लेकिन बिना डरे बोलता हूँ।","ro":"Maiṃ ab bhī galtiyāṃ kartā hūṃ, lekin binā ḍare boltā hūṃ."},{"fr":"Le hindi devient un vrai compagnon de voyage.","tgt":"हिंदी सच में मेरे सफ़र की साथी बन रही है।","ro":"Hindī sach meṃ mere safar kī sāthī ban rahī hai."},{"fr":"Bravo pour tout ce chemin parcouru.","tgt":"इतना लंबा सफ़र तय करने के लिए बधाई।","ro":"Itnā lambā safar tay karne ke lie badhāī."},{"fr":"Reposez-vous un peu avant le prochain module.","tgt":"अगले मॉड्यूल से पहले थोड़ा आराम कर लीजिए।","ro":"Agle moḍyūl se pahle thoṛā ārām kar lījie."},{"fr":"À bientôt, pour bavarder avec de nouveaux amis.","tgt":"जल्दी मिलेंगे, नए दोस्तों से बात करने के लिए।","ro":"Jaldī mileṃge, nae dostoṃ se bāt karne ke lie."}]}]},{"id":3,"name":"Conversation sociale","desc":"Des échanges sociaux plus nuancés et plus naturels.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Retrouver un vieil ami à Park Street","phrases":[{"fr":"Salut Rohan, ça fait des mois qu'on ne s'est pas croisés !","tgt":"अरे रोहन, कितने महीनों बाद मिले हैं!","ro":"Are Rohan, kitne mahīnoṃ bād mile haiṃ!"},{"fr":"Tu as très bonne mine, qu'est-ce que tu deviens ces temps-ci ?","tgt":"तुम तो बहुत अच्छे लग रहे हो, आजकल क्या चल रहा है?","ro":"Tum to bahut achchhe lag rahe ho, ājkal kyā chal rahā hai?"},{"fr":"J'ai changé de boulot le mois dernier.","tgt":"मैंने पिछले महीने नौकरी बदल ली।","ro":"Maiṃne pichhle mahīne naukrī badal lī."},{"fr":"Maintenant, je travaille du côté de Gariahat.","tgt":"अब मैं गरियाहाट के पास काम करता हूँ।","ro":"Ab maiṃ Gariyāhāṭ ke pās kām kartā hūṃ."},{"fr":"Et toi, tu vis toujours avec tes parents ?","tgt":"और तुम, अब भी माँ-बाप के साथ रहते हो?","ro":"Aur tum, ab bhī māṃ-bāp ke sāth rahte ho?"},{"fr":"Non, l'an dernier j'ai pris un petit appartement.","tgt":"नहीं, पिछले साल मैंने एक छोटा फ़्लैट ले लिया।","ro":"Nahīṃ, pichhle sāl maiṃne ek chhoṭā flaiṭ le liyā."},{"fr":"Allez, on va boire un thé quelque part ?","tgt":"चलो, कहीं चाय पीते हैं?","ro":"Chalo, kahīṃ chāy pīte haiṃ?"},{"fr":"Il y a une vieille échoppe de thé au coin de la rue.","tgt":"गली के कोने पर चाय की एक पुरानी दुकान है।","ro":"Galī ke kone par chāy kī ek purānī dukān hai."},{"fr":"Raconte-moi tout, je veux toutes les nouvelles.","tgt":"सब कुछ बताओ, मुझे सारी ख़बरें सुननी हैं।","ro":"Sab kuchh batāo, mujhe sārī khabreṃ sunnī haiṃ."},{"fr":"Ça m'a vraiment fait plaisir de te retrouver.","tgt":"तुमसे फिर मिलकर सच में बहुत अच्छा लगा।","ro":"Tumse phir milkar sach meṃ bahut achchhā lagā."}]},{"title":"Bavarder entre copains","phrases":[{"fr":"Salut mon pote, quoi de neuf ?","tgt":"और यार, क्या हाल है?","ro":"Aur yār, kyā hāl hai?"},{"fr":"Tout roule, mec, et toi, raconte ?","tgt":"सब बढ़िया, यार, तू बता?","ro":"Sab baṛhiyā, yār, tū batā?"},{"fr":"Arrête, tu me fais marcher ou quoi ?","tgt":"अरे छोड़ यार, मज़ाक कर रहा है क्या?","ro":"Are chhoṛ yār, mazāk kar rahā hai kyā?"},{"fr":"Viens, on va manger des phuchkas à Gariahat.","tgt":"चल, गरियाहाट में पुचके खाते हैं।","ro":"Chal, Gariyāhāṭ meṃ puchke khāte haiṃ."},{"fr":"T'inquiète, aujourd'hui c'est moi qui paie.","tgt":"टेंशन मत ले, आज मैं पैसे दूँगा।","ro":"Ṭeṃshan mat le, āj maiṃ paise dūṃgā."},{"fr":"Ton nouveau téléphone est vraiment trop bien.","tgt":"तेरा नया फ़ोन तो एकदम मस्त है।","ro":"Terā nayā fon to ekdam mast hai."},{"fr":"Allez mon vieux, grouille-toi, on est en retard !","tgt":"चल यार, जल्दी कर, देर हो रही है।","ro":"Chal yār, jaldī kar, der ho rahī hai."},{"fr":"Avec mes amis d'enfance, je parle toujours en « tū ».","tgt":"बचपन के दोस्तों से मैं हमेशा तू करके बात करता हूँ।","ro":"Bachpan ke dostoṃ se maiṃ hameshā tū karke bāt kartā hūṃ."},{"fr":"Avec les collègues du bureau, je préfère le « tum ».","tgt":"दफ़्तर के साथियों से मैं तुम करके बात करता हूँ।","ro":"Daftar ke sāthiyoṃ se maiṃ tum karke bāt kartā hūṃ."},{"fr":"Bon, rendez-vous ce soir, mon vieux.","tgt":"चल, शाम को मिलते हैं।","ro":"Chal, shām ko milte haiṃ."}],"tip":{"title":"Le registre familier entre amis","example":"Salut mon pote, quoi de neuf ? — और <b>यार</b>, क्या हाल है?","body":"Entre amis, le hindi devient beaucoup plus détendu. Il existe trois façons de dire tu : « āp », très respectueux, « tum », amical, et « tū », réservé aux amis très proches et à la famille. Le verbe suit le même chemin : on dit « chaliye » à quelqu'un qu'on respecte, « chalo » à un ami, et simplement « chal » à un copain d'enfance. Décomposons « aur yār, kyā hāl hai » : « aur » veut dire et, « yār » copain, « kyā hāl hai » quel est l'état, donc salut mon pote, comment ça va. Le petit mot « yār » se glisse partout, un peu comme mec en français : « chal yār », « bas yār ». Astuce : plus la forme du verbe est courte, plus le ton est familier, et dans le doute, restez sur « tum ».","exampleRo":"Aur yār, kyā hāl hai?","lit":"et · copain · quel · état · est ?","say":{"āp":"आप","tum":"तुम","tū":"तू","chaliye":"चलिये","chalo":"चलो","chal":"चल","aur yār, kyā hāl hai":"और यार, क्या हाल है","aur":"और","yār":"यार","kyā hāl hai":"क्या हाल है","chal yār":"चल यार","bas yār":"बस यार"}}},{"title":"Une invitation au mariage","phrases":[{"fr":"Ma cousine se marie le mois prochain.","tgt":"मेरी चचेरी बहन की अगले महीने शादी है।","ro":"Merī chacherī bahan kī agle mahīne shādī hai."},{"fr":"Tu dois absolument venir, avec toute ta famille.","tgt":"तुम्हें ज़रूर आना है, पूरे परिवार के साथ।","ro":"Tumheṃ zarūr ānā hai, pūre parivār ke sāth."},{"fr":"Le mariage se fera sous une grande tente à Ballygunge.","tgt":"शादी बालीगंज के एक बड़े शामियाने में होगी।","ro":"Shādī Bālīgaṃj ke ek baṛe shāmiyāne meṃ hogī."},{"fr":"Il y aura au moins cinq cents invités.","tgt":"कम से कम पाँच सौ मेहमान आएँगे।","ro":"Kam se kam pāṃch sau mehmān āeṃge."},{"fr":"La fête va durer trois jours entiers.","tgt":"जश्न पूरे तीन दिन चलेगा।","ro":"Jashn pūre tīn din chalegā."},{"fr":"Qu'est-ce que je devrais porter pour l'occasion ?","tgt":"मुझे उस मौके पर क्या पहनना चाहिए?","ro":"Mujhe us mauke par kyā pahannā chāhie?"},{"fr":"Mets un kurta, ce sera parfait.","tgt":"कुर्ता पहन लेना, बिल्कुल ठीक रहेगा।","ro":"Kurtā pahan lenā, bilkul ṭhīk rahegā."},{"fr":"Je peux aussi amener une amie ?","tgt":"क्या मैं अपनी दोस्त को भी ला सकता हूँ?","ro":"Kyā maiṃ apnī dost ko bhī lā saktā hūṃ?"},{"fr":"Évidemment, plus on est de fous, plus on rit.","tgt":"बिल्कुल, जितने ज़्यादा लोग, उतना ज़्यादा मज़ा।","ro":"Bilkul, jitne zyādā log, utnā zyādā mazā."},{"fr":"Je t'envoie le faire-part demain.","tgt":"मैं कल तुम्हें शादी का कार्ड भेज दूँगा।","ro":"Maiṃ kal tumheṃ shādī kā kārḍ bhej dūṃgā."}]},{"title":"Les préparatifs du mariage","phrases":[{"fr":"Toute la famille court dans tous les sens depuis une semaine.","tgt":"पूरा परिवार एक हफ़्ते से भाग-दौड़ कर रहा है।","ro":"Pūrā parivār ek hafte se bhāg-dauṛ kar rahā hai."},{"fr":"C'est ma tante qui s'occupe du repas.","tgt":"खाने का इंतज़ाम मेरी मौसी देख रही हैं।","ro":"Khāne kā iṃtazām merī mausī dekh rahī haiṃ."},{"fr":"On a fait venir des kilos de rasgoullas.","tgt":"हमने कई किलो रसगुल्ले मँगवाए हैं।","ro":"Hamne kaī kilo rasgulle maṃgvāe haiṃ."},{"fr":"La veille du mariage, les filles se feront poser du henné.","tgt":"शादी से एक दिन पहले लड़कियाँ मेहँदी लगवाएँगी।","ro":"Shādī se ek din pahle laṛkiyāṃ mehaṃdī lagvāeṃgī."},{"fr":"Le cousin du marié jouera du tambour toute la nuit.","tgt":"दूल्हे का चचेरा भाई रात भर ढोल बजाएगा।","ro":"Dūlhe kā chacherā bhāī rāt bhar ḍhol bajāegā."},{"fr":"Il faut encore décorer toute la maison de guirlandes de fleurs.","tgt":"अभी पूरे घर को फूलों की मालाओं से सजाना है।","ro":"Abhī pūre ghar ko phūloṃ kī mālāoṃ se sajānā hai."},{"fr":"Tu m'aides à porter les chaises ?","tgt":"कुर्सियाँ उठाने में मेरी मदद करोगे?","ro":"Kursiyāṃ uṭhāne meṃ merī madad karoge?"},{"fr":"Bien sûr, dis-moi juste où les poser.","tgt":"हाँ ज़रूर, बस बता दो कहाँ रखनी हैं।","ro":"Hāṃ zarūr, bas batā do kahāṃ rakhnī haiṃ."},{"fr":"Ma grand-mère a déjà sorti ses plus beaux saris.","tgt":"दादी ने अपनी सबसे अच्छी साड़ियाँ निकाल ली हैं।","ro":"Dādī ne apnī sabse achchhī sāṛiyāṃ nikāl lī haiṃ."},{"fr":"J'en suis sûr, tout sera prêt à temps.","tgt":"मुझे यकीन है, सब कुछ समय पर तैयार हो जाएगा।","ro":"Mujhe yakīn hai, sab kuchh samay par taiyār ho jāegā."}]},{"title":"Des projets incertains","phrases":[{"fr":"Je viendrai peut-être ce soir.","tgt":"मैं शायद आज शाम आऊँगा।","ro":"Maiṃ shāyad āj shām āūṃgā."},{"fr":"Il va peut-être pleuvoir sur Calcutta demain.","tgt":"शायद कल कोलकाता में बारिश होगी।","ro":"Shāyad kal Kolkātā meṃ bārish hogī."},{"fr":"Ananya est peut-être déjà partie.","tgt":"अनन्या शायद निकल चुकी है।","ro":"Ananyā shāyad nikal chukī hai."},{"fr":"On ira peut-être voir le pont Howrah de nuit.","tgt":"शायद हम रात में हावड़ा ब्रिज देखने जाएँगे।","ro":"Shāyad ham rāt meṃ Hāvṛā brij dekhne jāeṃge."},{"fr":"Tu as peut-être raison, je ne sais pas trop.","tgt":"शायद तुम सही हो, पता नहीं।","ro":"Shāyad tum sahī ho, patā nahīṃ."},{"fr":"Il est sans doute coincé dans les bouchons.","tgt":"शायद वह ट्रैफ़िक में फँसा है।","ro":"Shāyad vah ṭraifik meṃ phaṃsā hai."},{"fr":"On devrait peut-être lui passer un coup de fil.","tgt":"शायद हमें उसे फ़ोन करना चाहिए।","ro":"Shāyad hameṃ use fon karnā chāhie."},{"fr":"Il passera peut-être, qui sait.","tgt":"शायद वह आ जाए, क्या पता।","ro":"Shāyad vah ā jāe, kyā patā."},{"fr":"Si j'ai le temps, je passerai chez toi.","tgt":"अगर समय मिला, तो मैं तुम्हारे घर आऊँगा।","ro":"Agar samay milā, to maiṃ tumhāre ghar āūṃgā."},{"fr":"Elle n'était peut-être pas au courant.","tgt":"शायद उसे पता नहीं था।","ro":"Shāyad use patā nahīṃ thā."}],"tip":{"title":"« Shāyad » : peut-être","example":"Je viendrai peut-être ce soir. — मैं <b>शायद</b> आज शाम आऊँगा।","body":"« Shāyad » veut dire peut-être, et c'est un mot très pratique pour nuancer ce qu'on dit. Il se place librement, souvent en début de phrase ou juste avant le verbe, là où le français dit volontiers peut-être que. Dans « maiṃ shāyad āj shām āūṃgā », on a mot à mot je, peut-être, aujourd'hui, soir, viendrai. Avec le futur, la chose reste assez probable ; avec le subjonctif, le doute grandit : « shāyad vah ā jāe, kyā patā » se traduit par il passera peut-être, qui sait. Pour répondre peut-être pas, dites simplement « shāyad nahīṃ ». Astuce : imaginez « shāyad » comme un petit nuage posé devant la phrase, qui la rend moins certaine.","exampleRo":"Maiṃ shāyad āj shām āūṃgā.","lit":"je · peut-être · aujourd'hui · soir · viendrai","say":{"Shāyad":"शायद","maiṃ shāyad āj shām āūṃgā":"मैं शायद आज शाम आऊँगा","shāyad vah ā jāe, kyā patā":"शायद वह आ जाए, क्या पता","shāyad nahīṃ":"शायद नहीं","shāyad":"शायद"}}},{"title":"La fête des couleurs","phrases":[{"fr":"Pour la fête des couleurs, on se retrouve tous sur le toit.","tgt":"होली पर हम सब छत पर इकट्ठा होते हैं।","ro":"Holī par ham sab chhat par ikaṭṭhā hote haiṃ."},{"fr":"L'an dernier, on s'est lancé des couleurs jusqu'à midi.","tgt":"पिछले साल हमने दोपहर तक रंग खेला।","ro":"Pichhle sāl hamne dopahar tak raṃg khelā."},{"fr":"Mets de vieux habits, ils seront fichus.","tgt":"पुराने कपड़े पहनना, वे ख़राब हो जाएँगे।","ro":"Purāne kapṛe pahannā, ve kharāb ho jāeṃge."},{"fr":"Mon petit frère m'a renversé un seau d'eau colorée dessus.","tgt":"मेरे छोटे भाई ने मुझ पर रंग वाले पानी की बाल्टी फेंक दी।","ro":"Mere chhoṭe bhāī ne mujh par raṃg vāle pānī kī bālṭī pheṃk dī."},{"fr":"Les enfants courent partout avec leurs pistolets à eau.","tgt":"बच्चे पिचकारियाँ लेकर इधर-उधर भागते हैं।","ro":"Bachche pichkāriyāṃ lekar idhar-udhar bhāgte haiṃ."},{"fr":"Ensuite, on mange des sucreries et on boit du lait glacé aux amandes.","tgt":"फिर हम मिठाई खाते हैं और ठंडाई पीते हैं।","ro":"Phir ham miṭhāī khāte haiṃ aur ṭhaṃḍāī pīte haiṃ."},{"fr":"Mets un peu d'huile sur ton visage avant de sortir.","tgt":"बाहर निकलने से पहले चेहरे पर तेल लगा लेना।","ro":"Bāhar nikalne se pahle chehre par tel lagā lenā."},{"fr":"Comme ça, la couleur partira plus facilement.","tgt":"इससे रंग आसानी से छूट जाएगा।","ro":"Isse raṃg āsānī se chhūṭ jāegā."},{"fr":"J'ai encore du rose dans les cheveux.","tgt":"मेरे बालों में अभी भी गुलाबी रंग लगा है।","ro":"Mere bāloṃ meṃ abhī bhī gulābī raṃg lagā hai."},{"fr":"Ça faisait des années que je n'avais pas vécu une fête des couleurs aussi drôle.","tgt":"बरसों बाद इतनी मज़ेदार होली खेली।","ro":"Barsoṃ bād itnī mazedār holī khelī."}]},{"title":"Un match à l'Eden Gardens","phrases":[{"fr":"Tu as suivi le match d'hier à l'Eden Gardens ?","tgt":"कल ईडन गार्डन्स वाला मैच देखा?","ro":"Kal Īḍan Gārḍans vālā maich dekhā?"},{"fr":"Bien sûr, j'étais dans le stade avec mon père.","tgt":"हाँ, मैं पापा के साथ स्टेडियम में था।","ro":"Hāṃ, maiṃ pāpā ke sāth sṭeḍiyam meṃ thā."},{"fr":"L'ambiance était folle, soixante mille personnes criaient.","tgt":"माहौल ज़बरदस्त था, साठ हज़ार लोग चिल्ला रहे थे।","ro":"Māhaul zabardast thā, sāṭh hazār log chillā rahe the."},{"fr":"Notre capitaine a marqué cent runs.","tgt":"हमारे कप्तान ने शतक बनाया।","ro":"Hamāre kaptān ne shatak banāyā."},{"fr":"Au dernier over, j'avais le cœur qui battait fort.","tgt":"आख़िरी ओवर में तो दिल धड़क रहा था।","ro":"Ākhirī ovar meṃ to dil dhaṛak rahā thā."},{"fr":"On a gagné de justesse, à deux balles de la fin.","tgt":"हम बस दो गेंद पहले जीत गए।","ro":"Ham bas do geṃd pahle jīt gae."},{"fr":"Les jours de congé, on joue au cricket dans la ruelle.","tgt":"छुट्टी के दिन हम गली में क्रिकेट खेलते हैं।","ro":"Chhuṭṭī ke din ham galī meṃ kriket khelte haiṃ."},{"fr":"Tu viendras jouer avec nous dimanche ?","tgt":"रविवार को हमारे साथ खेलोगे?","ro":"Ravivār ko hamāre sāth kheloge?"},{"fr":"Je ne sais pas lancer, mais je peux essayer.","tgt":"मुझे गेंदबाज़ी नहीं आती, पर कोशिश कर सकता हूँ।","ro":"Mujhe geṃdbāzī nahīṃ ātī, par koshish kar saktā hūṃ."},{"fr":"Si on perd, c'est toi qui offres le thé !","tgt":"अगर हम हारे, तो चाय तुम पिलाओगे!","ro":"Agar ham hāre, to chāy tum pilāoge!"}]},{"title":"Une soirée au cinéma","phrases":[{"fr":"Ça te dit d'aller voir un film samedi ?","tgt":"शनिवार को फ़िल्म देखने चलोगे?","ro":"Shanivār ko film dekhne chaloge?"},{"fr":"Un nouveau film vient de sortir, tout le monde en parle.","tgt":"एक नई फ़िल्म आई है, सब उसी की बात कर रहे हैं।","ro":"Ek naī film āī hai, sab usī kī bāt kar rahe haiṃ."},{"fr":"C'est une histoire d'amour avec plein de chansons.","tgt":"प्यार की कहानी है, बहुत सारे गाने हैं।","ro":"Pyār kī kahānī hai, bahut sāre gāne haiṃ."},{"fr":"Pour être honnête, je préfère les films d'action.","tgt":"सच कहूँ तो मुझे एक्शन फ़िल्में ज़्यादा पसंद हैं।","ro":"Sach kahūṃ to mujhe ekshan filmeṃ zyādā pasaṃd haiṃ."},{"fr":"On a vu ce film dans une vieille salle du centre-ville.","tgt":"हमने वह फ़िल्म शहर के एक पुराने सिनेमाघर में देखी।","ro":"Hamne vah film shahar ke ek purāne sinemāghar meṃ dekhī."},{"fr":"Le héros chantait sous la pluie, la scène était superbe.","tgt":"हीरो बारिश में गा रहा था, बहुत सुंदर सीन था।","ro":"Hīro bārish meṃ gā rahā thā, bahut suṃdar sīn thā."},{"fr":"Je l'avoue, j'ai pleuré à la fin.","tgt":"मानता हूँ, आख़िर में मैं रो पड़ा।","ro":"Māntā hūṃ, ākhir meṃ maiṃ ro paṛā."},{"fr":"Réserve les billets à l'avance, sinon il n'y aura plus de places.","tgt":"टिकट पहले से बुक कर लो, वरना सीटें भर जाएँगी।","ro":"Ṭikaṭ pahle se buk kar lo, varnā sīṭeṃ bhar jāeṃgī."},{"fr":"À l'entracte, on mangera des samoussas.","tgt":"इंटरवल में समोसे खाएँगे।","ro":"Iṃṭarval meṃ samose khāeṃge."},{"fr":"Ce film était encore meilleur que le premier.","tgt":"यह फ़िल्म पहली वाली से भी अच्छी थी।","ro":"Yah film pahlī vālī se bhī achchhī thī."}]},{"title":"Les sucreries de Calcutta","phrases":[{"fr":"Calcutta, c'est vraiment la ville des sucreries.","tgt":"कोलकाता मिठाइयों का शहर है।","ro":"Kolkātā miṭhāiyoṃ kā shahar hai."},{"fr":"Tu as déjà goûté au sandesh ?","tgt":"तुमने कभी संदेश चखा है?","ro":"Tumne kabhī saṃdesh chakhā hai?"},{"fr":"Les rasgoullas de cette boutique sont imbattables.","tgt":"इस दुकान के रसगुल्ले सबसे अच्छे हैं।","ro":"Is dukān ke rasgulle sabse achchhe haiṃ."},{"fr":"Mon grand-père venait les acheter ici tous les dimanches.","tgt":"मेरे दादाजी हर रविवार यहीं से लाते थे।","ro":"Mere dādājī har ravivār yahīṃ se lāte the."},{"fr":"On mange le yaourt sucré bien frais, dans un pot en terre.","tgt":"मीठा दही मिट्टी के बर्तन में ठंडा खाते हैं।","ro":"Mīṭhā dahī miṭṭī ke bartan meṃ ṭhaṃḍā khāte haiṃ."},{"fr":"Attention, c'est très sucré !","tgt":"ध्यान से, यह बहुत मीठा है!","ro":"Dhyān se, yah bahut mīṭhā hai!"},{"fr":"Prends-en un autre, ne fais pas le timide.","tgt":"एक और लो, शरमाओ मत।","ro":"Ek aur lo, sharmāo mat."},{"fr":"Je ne peux plus rien avaler, j'ai trop mangé.","tgt":"अब और नहीं खा सकता, बहुत खा लिया।","ro":"Ab aur nahīṃ khā saktā, bahut khā liyā."},{"fr":"On rapportera une boîte à ta mère.","tgt":"तुम्हारी माँ के लिए एक डिब्बा ले चलेंगे।","ro":"Tumhārī māṃ ke lie ek ḍibbā le chaleṃge."},{"fr":"En hiver, on trouve du sandesh au sucre de palme.","tgt":"सर्दियों में नलेन गुड़ का संदेश मिलता है।","ro":"Sardiyoṃ meṃ nalen guṛ kā saṃdesh miltā hai."}]},{"title":"Un anniversaire surprise","phrases":[{"fr":"Samedi, c'est l'anniversaire de Priya.","tgt":"शनिवार को प्रिया का जन्मदिन है।","ro":"Shanivār ko Priyā kā janmdin hai."},{"fr":"On lui organise une fête surprise.","tgt":"हम उसके लिए सरप्राइज़ पार्टी रख रहे हैं।","ro":"Ham uske lie sarprāiz pārṭī rakh rahe haiṃ."},{"fr":"Surtout, ne lui dis rien !","tgt":"ख़बरदार, उसे कुछ मत बताना!","ro":"Khabardār, use kuchh mat batānā!"},{"fr":"Son frère l'emmènera dîner pour qu'elle ne se doute de rien.","tgt":"उसका भाई उसे खाने पर ले जाएगा, ताकि उसे शक न हो।","ro":"Uskā bhāī use khāne par le jāegā, tāki use shak na ho."},{"fr":"Pendant ce temps, on décorera son appartement.","tgt":"तब तक हम उसका फ़्लैट सजा देंगे।","ro":"Tab tak ham uskā flaiṭ sajā deṃge."},{"fr":"Qui se charge d'apporter le gâteau ?","tgt":"केक कौन लाएगा?","ro":"Kek kaun lāegā?"},{"fr":"Je l'ai déjà commandé dans une pâtisserie de Park Street.","tgt":"मैंने पार्क स्ट्रीट की एक बेकरी से मँगवा लिया है।","ro":"Maiṃne Pārk Sṭrīṭ kī ek bekrī se maṃgvā liyā hai."},{"fr":"Dès qu'elle est entrée, tout le monde a crié joyeux anniversaire !","tgt":"जैसे ही वह अंदर आई, सब चिल्लाए, जन्मदिन मुबारक हो!","ro":"Jaise hī vah aṃdar āī, sab chillāe, janmdin mubārak ho!"},{"fr":"Elle ne s'attendait absolument pas à ça.","tgt":"उसे बिल्कुल उम्मीद नहीं थी।","ro":"Use bilkul ummīd nahīṃ thī."},{"fr":"On a dansé jusqu'à deux heures du matin.","tgt":"हम रात के दो बजे तक नाचते रहे।","ro":"Ham rāt ke do baje tak nāchte rahe."}]},{"title":"Parler de séries","phrases":[{"fr":"Tu regardes quelle série en ce moment ?","tgt":"आजकल तुम कौन-सी सीरीज़ देख रहे हो?","ro":"Ājkal tum kaun-sī sīrīz dekh rahe ho?"},{"fr":"Une série de détectives, l'histoire se passe à Calcutta.","tgt":"एक जासूसी सीरीज़, कोलकाता की कहानी है।","ro":"Ek jāsūsī sīrīz, Kolkātā kī kahānī hai."},{"fr":"J'ai avalé toute la saison en deux jours.","tgt":"मैंने पूरा सीज़न दो दिन में देख डाला।","ro":"Maiṃne pūrā sīzan do din meṃ dekh ḍālā."},{"fr":"Ne me dis pas ce qui se passe à la fin !","tgt":"आख़िर में क्या होता है, मत बताना!","ro":"Ākhir meṃ kyā hotā hai, mat batānā!"},{"fr":"Juré, je ne dévoilerai rien.","tgt":"पक्का, कुछ नहीं बताऊँगा।","ro":"Pakkā, kuchh nahīṃ batāūṃgā."},{"fr":"L'actrice principale a fait un travail formidable.","tgt":"मुख्य अभिनेत्री ने बहुत अच्छा काम किया है।","ro":"Mukhya abhinetrī ne bahut achchhā kām kiyā hai."},{"fr":"Le deuxième épisode m'a paru un peu ennuyeux.","tgt":"दूसरा एपिसोड मुझे थोड़ा बोरिंग लगा।","ro":"Dūsrā episoḍ mujhe thoṛā boriṃg lagā."},{"fr":"Mais après, l'histoire devient passionnante.","tgt":"पर उसके बाद कहानी बहुत दिलचस्प हो जाती है।","ro":"Par uske bād kahānī bahut dilchasp ho jātī hai."},{"fr":"La nouvelle saison arrive le mois prochain.","tgt":"नया सीज़न अगले महीने आएगा।","ro":"Nayā sīzan agle mahīne āegā."},{"fr":"On pourrait la regarder ensemble chez moi.","tgt":"हम मेरे घर पर साथ बैठकर देख सकते हैं।","ro":"Ham mere ghar par sāth baiṭhkar dekh sakte haiṃ."}]},{"title":"Les nouvelles du quartier","phrases":[{"fr":"J'ai entendu dire que Vikram allait se marier.","tgt":"सुना है कि विक्रम की शादी होने वाली है।","ro":"Sunā hai ki Vikram kī shādī hone vālī hai."},{"fr":"Il paraît qu'un nouveau restaurant a ouvert à Park Street.","tgt":"सुना है कि पार्क स्ट्रीट पर एक नया रेस्टोरेंट खुला है।","ro":"Sunā hai ki Pārk Sṭrīṭ par ek nayā resṭoreṃṭ khulā hai."},{"fr":"On m'a dit que leur biryani était délicieux.","tgt":"सुना है कि वहाँ की बिरयानी लाजवाब है।","ro":"Sunā hai ki vahāṃ kī biryānī lājavāb hai."},{"fr":"Qui est-ce qui t'a raconté ça ?","tgt":"तुमसे किसने कहा?","ro":"Tumse kisne kahā?"},{"fr":"C'est ma voisine qui me l'a appris ce matin.","tgt":"आज सुबह मेरी पड़ोसन ने बताया।","ro":"Āj subah merī paṛosan ne batāyā."},{"fr":"J'ai aussi entendu dire que les Sharma déménagent.","tgt":"मैंने यह भी सुना है कि शर्मा जी का परिवार घर बदल रहा है।","ro":"Maiṃne yah bhī sunā hai ki Sharmā jī kā parivār ghar badal rahā hai."},{"fr":"Il paraît que la rue sera refaite après la mousson.","tgt":"सुना है कि बरसात के बाद गली की सड़क नई बनेगी।","ro":"Sunā hai ki barsāt ke bād galī kī saṛak naī banegī."},{"fr":"Ce ne sont peut-être que des rumeurs.","tgt":"शायद ये सिर्फ़ अफ़वाहें हैं।","ro":"Shāyad ye sirf afvāheṃ haiṃ."},{"fr":"Moi, je ne crois pas tout ce qui se raconte.","tgt":"मैं हर सुनी-सुनाई बात पर यकीन नहीं करता।","ro":"Maiṃ har sunī-sunāī bāt par yakīn nahīṃ kartā."},{"fr":"J'ai entendu dire que le concert de dimanche était annulé.","tgt":"सुना है कि रविवार वाला गाने का कार्यक्रम रद्द हो गया है।","ro":"Sunā hai ki ravivār vālā gāne kā kāryakram radd ho gayā hai."}],"tip":{"title":"« Sunā hai ki » : j'ai entendu dire que","example":"J'ai entendu dire que Vikram allait se marier. — <b>सुना</b> <b>है</b> <b>कि</b> विक्रम की शादी होने वाली है।","body":"Pour rapporter une rumeur ou une nouvelle, le hindi utilise « sunā hai ki », littéralement entendu est que. C'est l'équivalent exact de j'ai entendu dire que, ou de il paraît que. On n'a même pas besoin de dire je : « sunā hai ki Vikram kī shādī hone vālī hai » signifie il paraît que Vikram va se marier. Le petit mot « ki » joue le rôle de notre que et ouvre la nouvelle, qui garde l'ordre habituel avec le verbe à la fin. Pour insister sur vous-même, ajoutez « maiṃne » devant : « maiṃne sunā hai ki », moi, j'ai entendu dire que. Astuce : « sunnā » veut dire entendre ou écouter, donc « sunā hai », c'est tout simplement c'est entendu.","exampleRo":"Sunā hai ki Vikram kī shādī hone vālī hai.","lit":"entendu · est · que · Vikram · [de] · mariage · se-faire · va · est","say":{"Sunā hai ki":"सुना है कि","sunā hai ki":"सुना है कि","sunā hai ki Vikram kī shādī hone vālī hai":"सुना है कि विक्रम की शादी होने वाली है","ki":"कि","maiṃne":"मैंने","maiṃne sunā hai ki":"मैंने सुना है कि","sunnā":"सुनना","sunā hai":"सुना है"}}},{"title":"La fête des lumières en famille","phrases":[{"fr":"Pour la fête des lumières, toute la famille se réunit chez mes grands-parents.","tgt":"दिवाली पर पूरा परिवार दादा-दादी के घर इकट्ठा होता है।","ro":"Divālī par pūrā parivār dādā-dādī ke ghar ikaṭṭhā hotā hai."},{"fr":"On allume des petites lampes à huile sur chaque fenêtre.","tgt":"हम हर खिड़की पर दीये जलाते हैं।","ro":"Ham har khiṛkī par dīye jalāte haiṃ."},{"fr":"Ma mère prépare des sucreries pendant des jours.","tgt":"माँ कई दिनों तक मिठाइयाँ बनाती हैं।","ro":"Māṃ kaī dinoṃ tak miṭhāiyāṃ banātī haiṃ."},{"fr":"Les enfants adorent les feux d'artifice.","tgt":"बच्चों को आतिशबाज़ी बहुत पसंद है।","ro":"Bachchoṃ ko ātishbāzī bahut pasaṃd hai."},{"fr":"Cette année, on a nettoyé la maison de fond en comble.","tgt":"इस साल हमने पूरे घर की सफ़ाई की।","ro":"Is sāl hamne pūre ghar kī safāī kī."},{"fr":"Mes cousins sont venus exprès de Delhi.","tgt":"मेरे चचेरे भाई ख़ास तौर पर दिल्ली से आए।","ro":"Mere chachere bhāī khās taur par Dillī se āe."},{"fr":"On a dessiné une rangoli devant la porte.","tgt":"हमने दरवाज़े के सामने रंगोली बनाई।","ro":"Hamne darvāze ke sāmne raṃgolī banāī."},{"fr":"Le soir, toute la ruelle scintillait de lumières.","tgt":"शाम को पूरी गली रोशनी से जगमगा रही थी।","ro":"Shām ko pūrī galī roshnī se jagmagā rahī thī."},{"fr":"On échange des boîtes de friandises avec les voisins.","tgt":"हम पड़ोसियों के साथ मिठाई के डिब्बे बाँटते हैं।","ro":"Ham paṛosiyoṃ ke sāth miṭhāī ke ḍibbe bāṃṭte haiṃ."},{"fr":"Pour moi, c'est la plus belle soirée de l'année.","tgt":"मेरे लिए यह साल की सबसे खूबसूरत शाम है।","ro":"Mere lie yah sāl kī sabse khūbsūrat shām hai."}]},{"title":"Souvenirs d'enfance","phrases":[{"fr":"Je faisais mes devoirs en écoutant la radio.","tgt":"मैं रेडियो सुनते हुए होमवर्क करता था।","ro":"Maiṃ reḍiyo sunte hue homvark kartā thā."},{"fr":"On rentrait de l'école en chantant.","tgt":"हम गाते हुए स्कूल से घर लौटते थे।","ro":"Ham gāte hue skūl se ghar lauṭte the."},{"fr":"Mon grand-père racontait des histoires en buvant son thé.","tgt":"दादाजी चाय पीते हुए कहानियाँ सुनाते थे।","ro":"Dādājī chāy pīte hue kahāniyāṃ sunāte the."},{"fr":"Un jour, je suis tombé en courant après un cerf-volant.","tgt":"पतंग के पीछे भागते हुए मैं गिर गया था।","ro":"Pataṃg ke pīchhe bhāgte hue maiṃ gir gayā thā."},{"fr":"Ma mère souriait en nous regardant jouer.","tgt":"माँ हमें खेलते हुए देखकर मुस्कुराती थीं।","ro":"Māṃ hameṃ khelte hue dekhkar muskurātī thīṃ."},{"fr":"Je l'ai aperçu en passant devant le marché.","tgt":"बाज़ार के सामने से गुज़रते हुए मैंने उसे देखा।","ro":"Bāzār ke sāmne se guzarte hue maiṃne use dekhā."},{"fr":"On prenait le tram pour aller à l'école.","tgt":"हम ट्राम से स्कूल जाते थे।","ro":"Ham ṭrām se skūl jāte the."},{"fr":"Ma grand-mère répétait : ne parle pas en mangeant.","tgt":"दादी हमेशा कहती थीं, खाते हुए बात मत करो।","ro":"Dādī hameshā kahtī thīṃ, khāte hue bāt mat karo."},{"fr":"Les vacances d'été semblaient ne jamais finir.","tgt":"गर्मी की छुट्टियाँ कभी ख़त्म ही नहीं होती थीं।","ro":"Garmī kī chhuṭṭiyāṃ kabhī khatm hī nahīṃ hotī thīṃ."},{"fr":"Aujourd'hui encore, je repense à ces jours-là en souriant.","tgt":"मैं आज भी मुस्कुराते हुए उन दिनों को याद करता हूँ।","ro":"Maiṃ āj bhī muskurāte hue un dinoṃ ko yād kartā hūṃ."}],"tip":{"title":"« Karte hue » : en faisant","example":"Je faisais mes devoirs en écoutant la radio. — मैं रेडियो <b>सुनते</b> <b>हुए</b> होमवर्क करता था।","body":"Pour dire en faisant quelque chose, le hindi prend le radical du verbe, ajoute « -te », puis le petit mot « hue ». « Karnā », faire, donne « karte hue », en faisant ; « sunnā », écouter, donne « sunte hue », en écoutant. Dans « maiṃ reḍiyo sunte hue homvark kartā thā », on a mot à mot je, radio, en écoutant, devoirs, faisais : le geste secondaire vient juste avant l'action principale, qui reste à la fin. Vous pouvez faire de même avec « khāte hue », en mangeant, « gāte hue », en chantant, ou « muskurāte hue », en souriant. Astuce : retenez la petite musique « -te hue », qui se prononce à peu près té houé, et collez-la à n'importe quel verbe.","exampleRo":"Maiṃ reḍiyo sunte hue homvark kartā thā.","lit":"je · radio · en-écoutant · devoirs · faisais","say":{"Karte hue":"करते हुए","hue":"हुए","Karnā":"करना","karte hue":"करते हुए","sunnā":"सुनना","sunte hue":"सुनते हुए","maiṃ reḍiyo sunte hue homvark kartā thā":"मैं रेडियो सुनते हुए होमवर्क करता था","khāte hue":"खाते हुए","gāte hue":"गाते हुए","muskurāte hue":"मुस्कुराते हुए","-te hue":"ते हुए"}}},{"title":"Donner son avis","phrases":[{"fr":"À mon avis, les gens de Calcutta ont le plus grand cœur.","tgt":"मेरे ख़याल से कोलकाता के लोग सबसे दिलवाले हैं।","ro":"Mere khayāl se Kolkātā ke log sabse dilvāle haiṃ."},{"fr":"Là, je ne suis pas complètement d'accord avec toi.","tgt":"मैं तुमसे पूरी तरह सहमत नहीं हूँ।","ro":"Maiṃ tumse pūrī tarah sahmat nahīṃ hūṃ."},{"fr":"Et toi, tu en penses quoi ?","tgt":"तुम्हारा क्या ख़याल है?","ro":"Tumhārā kyā khayāl hai?"},{"fr":"Je trouve que la ville a énormément changé.","tgt":"मुझे लगता है कि शहर बहुत बदल गया है।","ro":"Mujhe lagtā hai ki shahar bahut badal gayā hai."},{"fr":"Les vieux quartiers ont quand même gardé leur charme.","tgt":"फिर भी पुराने मोहल्लों की रौनक बरकरार है।","ro":"Phir bhī purāne mohalloṃ kī raunak barkarār hai."},{"fr":"Tu exagères un peu, non ?","tgt":"तुम थोड़ा बढ़ा-चढ़ाकर बोल रहे हो, है ना?","ro":"Tum thoṛā baṛhā-chaṛhākar bol rahe ho, hai nā?"},{"fr":"Possible, mais c'est vraiment mon impression.","tgt":"हो सकता है, पर मुझे तो ऐसा ही लगता है।","ro":"Ho saktā hai, par mujhe to aisā hī lagtā hai."},{"fr":"Chacun voit les choses à sa façon.","tgt":"हर किसी का अपना नज़रिया होता है।","ro":"Har kisī kā apnā nazriyā hotā hai."},{"fr":"Si tu veux mon avis, le tram doit continuer à rouler.","tgt":"अगर मेरी राय पूछो, तो ट्राम चलती रहनी चाहिए।","ro":"Agar merī rāy pūchho, to ṭrām chaltī rahnī chāhie."},{"fr":"Bon, on n'est pas d'accord, mais ce n'est pas grave.","tgt":"चलो, हम सहमत नहीं हैं, पर कोई बात नहीं।","ro":"Chalo, ham sahmat nahīṃ haiṃ, par koī bāt nahīṃ."}]},{"title":"Remonter le moral d'un ami","phrases":[{"fr":"Tu as l'air triste ces jours-ci, qu'est-ce qui ne va pas ?","tgt":"आजकल उदास लग रहे हो, क्या बात है?","ro":"Ājkal udās lag rahe ho, kyā bāt hai?"},{"fr":"Mon entretien pour le poste ne s'est pas bien passé.","tgt":"मेरा नौकरी का इंटरव्यू अच्छा नहीं गया।","ro":"Merā naukrī kā iṃṭarvyū achchhā nahīṃ gayā."},{"fr":"Ne te décourage pas, ça arrive à tout le monde.","tgt":"हिम्मत मत हारो, ऐसा सबके साथ होता है।","ro":"Himmat mat hāro, aisā sabke sāth hotā hai."},{"fr":"Tu trouveras sûrement quelque chose de mieux.","tgt":"तुम्हें इससे बेहतर कुछ ज़रूर मिलेगा।","ro":"Tumheṃ isse behtar kuchh zarūr milegā."},{"fr":"Viens faire un tour, ça te changera les idées.","tgt":"चलो, थोड़ा घूम आते हैं, मन बदल जाएगा।","ro":"Chalo, thoṛā ghūm āte haiṃ, man badal jāegā."},{"fr":"Merci, tu es un ami en or.","tgt":"शुक्रिया, तुम सच्चे दोस्त हो।","ro":"Shukriyā, tum sachche dost ho."},{"fr":"Si tu as besoin de parler, appelle-moi.","tgt":"अगर बात करनी हो, तो मुझे फ़ोन कर देना।","ro":"Agar bāt karnī ho, to mujhe fon kar denā."},{"fr":"Même au beau milieu de la nuit ?","tgt":"आधी रात को भी?","ro":"Ādhī rāt ko bhī?"},{"fr":"Oui, à n'importe quelle heure.","tgt":"हाँ, किसी भी वक्त।","ro":"Hāṃ, kisī bhī vakt."},{"fr":"Allez, fais-moi un petit sourire, tout va s'arranger.","tgt":"चलो, थोड़ा मुस्कुराओ, सब ठीक हो जाएगा।","ro":"Chalo, thoṛā muskurāo, sab ṭhīk ho jāegā."}]},{"title":"Une balade au bord de la Hooghly","phrases":[{"fr":"Au coucher du soleil, on va souvent au bord de la Hooghly.","tgt":"सूरज ढलते समय हम अक्सर हुगली के किनारे जाते हैं।","ro":"Sūraj ḍhalte samay ham aksar Huglī ke kināre jāte haiṃ."},{"fr":"De là, la vue sur le pont Howrah est splendide.","tgt":"वहाँ से हावड़ा ब्रिज का नज़ारा शानदार है।","ro":"Vahāṃ se Hāvṛā brij kā nazārā shāndār hai."},{"fr":"On a pris une petite barque pour traverser.","tgt":"हमने उस पार जाने के लिए एक छोटी नाव ली।","ro":"Hamne us pār jāne ke lie ek chhoṭī nāv lī."},{"fr":"Après la chaleur, l'air frais du fleuve fait du bien.","tgt":"गर्मी के बाद नदी की ठंडी हवा बहुत अच्छी लगती है।","ro":"Garmī ke bād nadī kī ṭhaṃḍī havā bahut achchhī lagtī hai."},{"fr":"Un vendeur servait du thé dans des gobelets en terre.","tgt":"एक चायवाला कुल्हड़ में चाय बेच रहा था।","ro":"Ek chāyvālā kulhaṛ meṃ chāy bech rahā thā."},{"fr":"Ici, on dirait que le temps s'arrête.","tgt":"यहाँ जैसे वक्त थम जाता है।","ro":"Yahāṃ jaise vakt tham jātā hai."},{"fr":"Prenons une photo avant qu'il fasse nuit.","tgt":"अँधेरा होने से पहले एक फ़ोटो ले लेते हैं।","ro":"Aṃdherā hone se pahle ek foṭo le lete haiṃ."},{"fr":"Assieds-toi là, la lumière est parfaite.","tgt":"वहाँ बैठ जाओ, रोशनी एकदम सही है।","ro":"Vahāṃ baiṭh jāo, roshnī ekdam sahī hai."},{"fr":"Après, on va dîner à Park Street ?","tgt":"उसके बाद पार्क स्ट्रीट में खाना खाने चलें?","ro":"Uske bād Pārk Sṭrīṭ meṃ khānā khāne chaleṃ?"},{"fr":"Excellente idée, j'ai une faim de loup.","tgt":"अच्छा ख़याल है, मुझे ज़ोरों की भूख लगी है।","ro":"Achchhā khayāl hai, mujhe zoroṃ kī bhūkh lagī hai."}]},{"title":"Chez les parents d'un ami","phrases":[{"fr":"Bonjour monsieur Banerjee, comment allez-vous ?","tgt":"नमस्ते बनर्जी जी, आप कैसे हैं?","ro":"Namaste Banarjī jī, āp kaise haiṃ?"},{"fr":"Entrez, je vous en prie, asseyez-vous.","tgt":"आइए, कृपया बैठिए।","ro":"Āie, kṛpayā baiṭhie."},{"fr":"Merci infiniment, madame, c'est très gentil à vous.","tgt":"बहुत-बहुत शुक्रिया आंटी जी, आप बहुत दयालु हैं।","ro":"Bahut-bahut shukriyā āṃṭī jī, āp bahut dayālu haiṃ."},{"fr":"Vous prendrez un peu de thé ?","tgt":"आप चाय लेंगे?","ro":"Āp chāy leṃge?"},{"fr":"Oui, avec plaisir, mais sans sucre s'il vous plaît.","tgt":"जी हाँ, ज़रूर, पर कृपया बिना चीनी के।","ro":"Jī hāṃ, zarūr, par kṛpayā binā chīnī ke."},{"fr":"Excusez-moi, vous pourriez le redire plus lentement ?","tgt":"माफ़ कीजिए, क्या आप ज़रा धीरे से दोबारा बोलेंगे?","ro":"Māf kījie, kyā āp zarā dhīre se dobārā boleṃge?"},{"fr":"Votre fils me parle souvent de vous deux.","tgt":"आपका बेटा अक्सर आपकी बातें करता है।","ro":"Āpkā beṭā aksar āpkī bāteṃ kartā hai."},{"fr":"Madame, votre poisson à la moutarde est un délice.","tgt":"आंटी जी, आपकी सरसों वाली मछली लाजवाब है।","ro":"Āṃṭī jī, āpkī sarsoṃ vālī machhlī lājavāb hai."},{"fr":"Revenez nous voir quand le cœur vous en dit.","tgt":"जब भी मन करे, फिर ज़रूर आइएगा।","ro":"Jab bhī man kare, phir zarūr āiegā."},{"fr":"Merci pour votre accueil, monsieur, je vais y aller.","tgt":"स्वागत के लिए धन्यवाद अंकल जी, अब मैं चलता हूँ।","ro":"Svāgat ke lie dhanyavād aṃkal jī, ab maiṃ chaltā hūṃ."}],"tip":{"title":"La politesse : « āp, -jī, kṛpayā »","example":"Oui, avec plaisir, mais sans sucre s'il vous plaît. — <b>जी</b> हाँ, ज़रूर, पर <b>कृपया</b> बिना चीनी के।","body":"Le hindi exprime le respect avec trois outils qui se combinent. D'abord « āp », vous, avec des verbes qui finissent en « -ie » : « baiṭhie », asseyez-vous, « āie », venez, « kījie », faites. Ensuite « -jī », qu'on accroche après un nom ou un titre, comme « Banarjī jī » ou « aṃkal jī », et même après oui : « jī hāṃ » est un oui très poli. Enfin « kṛpayā », s'il vous plaît, un peu soutenu ; à l'oral, la forme en « -ie » suffit souvent à être courtois. Décomposons « jī hāṃ, zarūr, par kṛpayā binā chīnī ke » : oui respectueux, bien sûr, mais, s'il vous plaît, sans sucre. Astuce : chez les parents d'un ami, mettez « jī » partout, personne ne vous le reprochera jamais.","exampleRo":"Jī hāṃ, zarūr, par kṛpayā binā chīnī ke.","lit":"[respect] · oui · bien-sûr · mais · s'il-vous-plaît · sans · sucre · [de]","say":{"āp":"आप","baiṭhie":"बैठिए","āie":"आइए","kījie":"कीजिए","Banarjī jī":"बनर्जी जी","aṃkal jī":"अंकल जी","jī hāṃ":"जी हाँ","kṛpayā":"कृपया","jī hāṃ, zarūr, par kṛpayā binā chīnī ke":"जी हाँ, ज़रूर, पर कृपया बिना चीनी के","jī":"जी","āp, -jī, kṛpayā":"आप, जी, कृपया","-ie":"इए","-jī":"जी"}}},{"title":"Souvenirs de fac à College Street","phrases":[{"fr":"Tu te rappelles nos années de fac ?","tgt":"तुम्हें हमारे कॉलेज के दिन याद हैं?","ro":"Tumheṃ hamāre kolej ke din yād haiṃ?"},{"fr":"On passait des heures chez les bouquinistes de College Street.","tgt":"हम कॉलेज स्ट्रीट की किताबों की दुकानों में घंटों बिताते थे।","ro":"Ham Kolej Sṭrīṭ kī kitāboṃ kī dukānoṃ meṃ ghaṃṭoṃ bitāte the."},{"fr":"Ensuite, on allait refaire le monde au vieux café.","tgt":"फिर हम गप्पें मारने पुराने कॉफ़ी हाउस जाते थे।","ro":"Phir ham gappeṃ mārne purāne kofī hāus jāte the."},{"fr":"Toi, tu arrivais toujours en retard en cours.","tgt":"तुम हमेशा क्लास में देर से आते थे।","ro":"Tum hameshā klās meṃ der se āte the."},{"fr":"Et toi, tu dormais au fond de la salle !","tgt":"और तुम पीछे बैठकर सोते थे!","ro":"Aur tum pīchhe baiṭhkar sote the!"},{"fr":"Notre prof d'histoire était vraiment sévère.","tgt":"हमारे इतिहास वाले सर बहुत सख़्त थे।","ro":"Hamāre itihās vāle sar bahut sakht the."},{"fr":"Mais c'est grâce à lui que j'ai eu mes examens.","tgt":"पर उन्हीं की वजह से मैं इम्तिहान में पास हुआ।","ro":"Par unhīṃ kī vajah se maiṃ imtihān meṃ pās huā."},{"fr":"Qu'est-ce que devient notre copain Arjun ?","tgt":"हमारा दोस्त अर्जुन आजकल कहाँ है?","ro":"Hamārā dost Arjun ājkal kahāṃ hai?"},{"fr":"Il est devenu médecin à Mumbai.","tgt":"वह मुंबई में डॉक्टर बन गया है।","ro":"Vah Muṃbaī meṃ ḍokṭar ban gayā hai."},{"fr":"On devrait réunir toute la bande un de ces jours.","tgt":"हमें पूरे ग्रुप के साथ एक बार फिर मिलना चाहिए।","ro":"Hameṃ pūre grup ke sāth ek bār phir milnā chāhie."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Dans ce module, on a appris à bavarder entre amis en hindi.","tgt":"इस हिस्से में हमने दोस्तों के साथ हिंदी में गपशप करना सीखा।","ro":"Is hisse meṃ hamne dostoṃ ke sāth hiṃdī meṃ gapshap karnā sīkhā."},{"fr":"Mariages, fêtes, cricket, cinéma : on peut maintenant parler de tout.","tgt":"शादी, त्योहार, क्रिकेट, फ़िल्में, अब हम हर विषय पर बात कर सकते हैं।","ro":"Shādī, tyohār, kriket, filmeṃ, ab ham har vishay par bāt kar sakte haiṃ."},{"fr":"On sait maintenant à qui dire tum et à qui dire āp.","tgt":"हम जानते हैं कि किससे तुम और किससे आप बोलना है।","ro":"Ham jānte haiṃ ki kisse tum aur kisse āp bolnā hai."},{"fr":"J'ai entendu dire que le niveau suivant est encore plus intéressant.","tgt":"सुना है कि अगला स्तर और भी दिलचस्प है।","ro":"Sunā hai ki aglā star aur bhī dilchasp hai."},{"fr":"Bientôt, on regardera peut-être un film sans sous-titres.","tgt":"शायद जल्द ही हम बिना सबटाइटल के फ़िल्म देखेंगे।","ro":"Shāyad jald hī ham binā sabṭāiṭal ke film dekheṃge."},{"fr":"En conduisant, je répète les phrases à voix haute.","tgt":"गाड़ी चलाते हुए मैं वाक्य ज़ोर से दोहराता हूँ।","ro":"Gāṛī chalāte hue maiṃ vākya zor se dohrātā hūṃ."},{"fr":"Et voilà, le deuxième niveau est bouclé.","tgt":"दूसरा स्तर यहीं ख़त्म होता है।","ro":"Dūsrā star yahīṃ khatm hotā hai."},{"fr":"Bravo pour tous ces efforts réguliers.","tgt":"इतनी लगातार मेहनत के लिए शाबाश।","ro":"Itnī lagātār mehnat ke lie shābāsh."},{"fr":"Prends quelques jours de repos avant la suite.","tgt":"आगे बढ़ने से पहले कुछ दिन आराम कर लो।","ro":"Āge baṛhne se pahle kuchh din ārām kar lo."},{"fr":"À bientôt pour le troisième et dernier niveau !","tgt":"जल्द मिलेंगे, तीसरे और आख़िरी स्तर में!","ro":"Jald mileṃge, tīsre aur ākhirī star meṃ!"}]}]}]},{"id":3,"name":"Niveau 3","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"Une vie quotidienne installée en Inde, avec ses subtilités.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Les règles d'une entreprise informatique","phrases":[{"fr":"Ici, les réunions ont lieu chaque lundi matin.","tgt":"यहाँ हर सोमवार सुबह मीटिंग रखी जाती है।","ro":"Yahāṃ har somvār subah mīṭing rakhī jātī hai."},{"fr":"Le travail est vérifié deux fois avant d'être envoyé au client.","tgt":"क्लाइंट को भेजने से पहले काम दो बार जाँचा जाता है।","ro":"Klāinṭ ko bhejne se pahle kām do bār jāṃchā jātā hai."},{"fr":"Les nouveaux employés sont formés pendant deux semaines.","tgt":"नए कर्मचारियों को दो हफ़्ते तक ट्रेनिंग दी जाती है।","ro":"Nae karmachāriyoṃ ko do hafte tak ṭrening dī jātī hai."},{"fr":"Les mots de passe sont changés tous les trois mois.","tgt":"पासवर्ड हर तीन महीने में बदले जाते हैं।","ro":"Pāsvarḍ har tīn mahīne meṃ badle jāte haiṃ."},{"fr":"Dans cette entreprise, on ne demande jamais de travailler le dimanche.","tgt":"इस कंपनी में रविवार को काम करने के लिए कभी नहीं कहा जाता।","ro":"Is kampanī meṃ ravivār ko kām karne ke lie kabhī nahīṃ kahā jātā."},{"fr":"Les demandes de congé sont déposées un mois à l'avance.","tgt":"छुट्टियों की अर्ज़ी एक महीना पहले दी जाती है।","ro":"Chhuṭṭiyoṃ kī arzī ek mahīnā pahle dī jātī hai."},{"fr":"Ce logiciel est utilisé par toute l'équipe.","tgt":"यह सॉफ़्टवेयर पूरी टीम द्वारा इस्तेमाल किया जाता है।","ro":"Yah sofṭveyar pūrī ṭīm dvārā istemāl kiyā jātā hai."},{"fr":"Le salaire est versé le premier de chaque mois.","tgt":"तनख़्वाह हर महीने की पहली तारीख़ को दी जाती है।","ro":"Tankhvāh har mahīne kī pahlī tārīkh ko dī jātī hai."},{"fr":"Les grandes décisions sont prises par la direction.","tgt":"बड़े फ़ैसले मैनेजमेंट द्वारा लिए जाते हैं।","ro":"Baṛe faisle mainejmenṭ dvārā lie jāte haiṃ."},{"fr":"Ici, arriver en retard n'est pas bien vu.","tgt":"यहाँ देर से आना अच्छा नहीं माना जाता।","ro":"Yahāṃ der se ānā achchhā nahīṃ mānā jātā."}],"tip":{"title":"Le passif : « kiyā jātā hai »","example":"Ce logiciel est utilisé par toute l'équipe. — यह सॉफ़्टवेयर पूरी टीम द्वारा इस्तेमाल <b>किया जाता है</b>।","body":"En hindi, le passif se construit avec le participe passé du verbe suivi de « jānā », le verbe aller. « Kiyā jātā hai » signifie mot à mot « fait, allé, est », c'est-à-dire « est fait » ou « on fait ». Le participe s'accorde avec la chose dont on parle : « kām kiyā jātā hai », le travail est fait, mais « mīṭing rakhī jātī hai », la réunion est tenue. À l'oral, on l'emploie surtout pour les règles et les habitudes, là où le français dit « on » : « yahāṃ der se ānā achchhā nahīṃ mānā jātā », ici, arriver en retard n'est pas bien vu. Pour nommer l'auteur, on ajoute « dvārā », par, mais c'est assez formel et souvent omis. Astuce : pensez « ça va être fait », c'est le verbe aller qui porte le passif.","exampleRo":"Yah sofṭveyar pūrī ṭīm dvārā istemāl kiyā jātā hai.","lit":"ce · logiciel · toute · équipe · [par] · utilisation · fait · allé · est","say":{"jānā":"जाना","Kiyā jātā hai":"किया जाता है","kām kiyā jātā hai":"काम किया जाता है","mīṭing rakhī jātī hai":"मीटिंग रखी जाती है","yahāṃ der se ānā achchhā nahīṃ mānā jātā":"यहाँ देर से आना अच्छा नहीं माना जाता","dvārā":"द्वारा","kiyā jātā hai":"किया जाता है"}}},{"title":"Choisir une assurance santé","phrases":[{"fr":"Mon entreprise offre une assurance santé à tous les employés.","tgt":"मेरी कंपनी सभी कर्मचारियों को हेल्थ इंश्योरेंस देती है।","ro":"Merī kampanī sabhī karmachāriyoṃ ko helth inshyorens detī hai."},{"fr":"Mais mes parents n'y sont pas inclus.","tgt":"लेकिन उसमें मेरे माता-पिता शामिल नहीं हैं।","ro":"Lekin usmeṃ mere mātā-pitā shāmil nahīṃ haiṃ."},{"fr":"Je voudrais prendre une assurance séparée pour eux.","tgt":"मैं उनके लिए अलग से एक पॉलिसी लेना चाहता हूँ।","ro":"Maiṃ unke lie alag se ek polisī lenā chāhtā hūṃ."},{"fr":"L'agent m'a montré trois formules différentes.","tgt":"एजेंट ने मुझे तीन अलग-अलग प्लान दिखाए।","ro":"Ejenṭ ne mujhe tīn alag-alag plān dikhāe."},{"fr":"La prime annuelle me paraît un peu élevée.","tgt":"सालाना प्रीमियम मुझे थोड़ा ज़्यादा लग रहा है।","ro":"Sālānā prīmiyam mujhe thoṛā zyādā lag rahā hai."},{"fr":"Les maladies déjà existantes sont-elles couvertes ?","tgt":"क्या पहले से मौजूद बीमारियाँ कवर की जाती हैं?","ro":"Kyā pahle se maujūd bīmāriyāṃ kavar kī jātī haiṃ?"},{"fr":"Pour certains traitements, il faut attendre deux ans.","tgt":"कुछ इलाजों के लिए दो साल इंतज़ार करना पड़ता है।","ro":"Kuchh ilājoṃ ke lie do sāl intazār karnā paṛtā hai."},{"fr":"Avant de signer, je préfère lire toutes les conditions.","tgt":"साइन करने से पहले मैं सारी शर्तें पढ़ना पसंद करता हूँ।","ro":"Sāin karne se pahle maiṃ sārī sharteṃ paṛhnā pasand kartā hūṃ."},{"fr":"Cette clinique de Banjara Hills accepte notre assurance.","tgt":"बंजारा हिल्स का यह क्लिनिक हमारा इंश्योरेंस लेता है।","ro":"Banjārā Hils kā yah klinik hamārā inshyorens letā hai."},{"fr":"Finalement, j'ai choisi la formule la plus simple.","tgt":"आख़िर में मैंने सबसे सीधा प्लान चुना।","ro":"Ākhir meṃ maiṃne sabse sīdhā plān chunā."}]},{"title":"Les travaux dans l'appartement","phrases":[{"fr":"Je dois faire réparer le climatiseur avant l'été.","tgt":"गर्मियों से पहले मुझे एसी ठीक करवाना है।","ro":"Garmiyoṃ se pahle mujhe esī ṭhīk karvānā hai."},{"fr":"Le propriétaire a fait repeindre toute la cuisine.","tgt":"मकान-मालिक ने पूरी रसोई में पेंट करवाया।","ro":"Makān-mālik ne pūrī rasoī meṃ penṭ karvāyā."},{"fr":"Nous avons fait installer un filtre à eau.","tgt":"हमने पानी का फ़िल्टर लगवाया।","ro":"Hamne pānī kā filṭar lagvāyā."},{"fr":"Je vais faire nettoyer le réservoir d'eau sur le toit.","tgt":"मैं छत पर पानी की टंकी साफ़ करवाऊँगा।","ro":"Maiṃ chhat par pānī kī ṭankī sāf karvāūṃgā."},{"fr":"Il faudrait faire vérifier l'installation électrique.","tgt":"बिजली की वायरिंग चेक करवानी चाहिए।","ro":"Bijlī kī vāyaring chek karvānī chāhie."},{"fr":"Ma femme a fait faire des rideaux sur mesure.","tgt":"मेरी पत्नी ने नाप के पर्दे बनवाए।","ro":"Merī patnī ne nāp ke parde banvāe."},{"fr":"Combien ça coûte de faire faire ce genre de réparation ?","tgt":"इस तरह की मरम्मत करवाने में कितना ख़र्च आता है?","ro":"Is tarah kī marammat karvāne meṃ kitnā kharch ātā hai?"},{"fr":"L'électricien viendra demain vers dix heures.","tgt":"इलेक्ट्रीशियन कल लगभग दस बजे आएगा।","ro":"Ilekṭrīshiyan kal lagbhag das baje āegā."},{"fr":"Je fais toujours établir un devis avant de lancer les travaux.","tgt":"काम शुरू करवाने से पहले मैं हमेशा कोटेशन बनवाता हूँ।","ro":"Kām shurū karvāne se pahle maiṃ hameshā koṭeshan banvātā hūṃ."},{"fr":"Après ces travaux, l'appartement a l'air tout neuf.","tgt":"इस काम के बाद फ़्लैट बिल्कुल नया लगता है।","ro":"Is kām ke bād flaiṭ bilkul nayā lagtā hai."}],"tip":{"title":"Faire faire : karvānā","example":"Je dois faire réparer le climatiseur avant l'été. — गर्मियों से पहले मुझे एसी ठीक <b>करवाना</b> है।","body":"Pour dire « faire faire » quelque chose, le hindi ne rajoute pas de verbe comme le français : il transforme le verbe lui-même en glissant « vā » en son milieu. « Karnā », faire, devient « karvānā », faire faire, et « ṭhīk karnā », réparer, devient « ṭhīk karvānā », faire réparer. Décomposons : « mujhe esī ṭhīk karvānā hai », à moi, climatiseur, réparé, faire faire, est, donc « je dois faire réparer le climatiseur ». Le même procédé marche avec beaucoup de verbes : « lagvānā », faire installer, « banvānā », faire fabriquer, « paṛhvānā », faire lire. La personne qui exécute le travail se place avec « se » : « vakīl dost se paṛhvāyā », je l'ai fait lire par un ami avocat. Astuce : quand vous entendez « vā » au cœur du verbe, c'est quelqu'un d'autre qui travaille.","exampleRo":"Garmiyoṃ se pahle mujhe esī ṭhīk karvānā hai.","lit":"étés · [depuis] · avant · moi [à] · climatiseur · réparé · faire faire · est","say":{"Karnā":"करना","karvānā":"करवाना","ṭhīk karnā":"ठीक करना","ṭhīk karvānā":"ठीक करवाना","mujhe esī ṭhīk karvānā hai":"मुझे एसी ठीक करवाना है","lagvānā":"लगवाना","banvānā":"बनवाना","paṛhvānā":"पढ़वाना","se":"से","vakīl dost se paṛhvāyā":"वकील दोस्त से पढ़वाया"}}},{"title":"Les embouteillages de Hyderabad","phrases":[{"fr":"Le matin, la route vers Hitech City est toujours bouchée.","tgt":"सुबह हाइटेक सिटी की सड़क पर बहुत ज़्यादा जाम रहता है।","ro":"Subah Hāiṭek Siṭī kī saṛak par bahut zyādā jām rahtā hai."},{"fr":"Parfois, dix kilomètres me prennent une heure et demie.","tgt":"कभी-कभी दस किलोमीटर के लिए डेढ़ घंटा लग जाता है।","ro":"Kabhī-kabhī das kilomīṭar ke lie ḍeṛh ghanṭā lag jātā hai."},{"fr":"C'est pour ça que je prends surtout le métro maintenant.","tgt":"इसीलिए मैं अब ज़्यादातर मेट्रो से जाता हूँ।","ro":"Isīlie maiṃ ab zyādātar meṭro se jātā hūṃ."},{"fr":"Pendant la mousson, la circulation devient encore pire.","tgt":"बारिश के मौसम में ट्रैफ़िक और भी ख़राब हो जाता है।","ro":"Bārish ke mausam meṃ ṭraifik aur bhī kharāb ho jātā hai."},{"fr":"Après une grosse pluie, les rues de Gachibowli sont souvent inondées.","tgt":"तेज़ बारिश के बाद गच्चीबावली की सड़कों पर अक्सर पानी भर जाता है।","ro":"Tez bārish ke bād Gachchībāvlī kī saṛkoṃ par aksar pānī bhar jātā hai."},{"fr":"Mon chauffeur connaît tous les raccourcis du quartier.","tgt":"मेरा ड्राइवर इलाके के सारे छोटे रास्ते जानता है।","ro":"Merā ḍrāivar ilāke ke sāre chhoṭe rāste jāntā hai."},{"fr":"Ici, klaxonner ne sert pratiquement à rien.","tgt":"यहाँ हॉर्न बजाने से कोई फ़ायदा नहीं होता।","ro":"Yahāṃ horn bajāne se koī fāydā nahīṃ hotā."},{"fr":"J'écoute des podcasts pour passer le temps dans les bouchons.","tgt":"जाम में समय काटने के लिए मैं पॉडकास्ट सुनता हूँ।","ro":"Jām meṃ samay kāṭne ke lie maiṃ poḍkāsṭ suntā hūṃ."},{"fr":"Si je pars avant huit heures, j'évite les gros bouchons.","tgt":"अगर मैं आठ बजे से पहले निकल जाता हूँ, तो बड़े जाम से बच जाता हूँ।","ro":"Agar maiṃ āṭh baje se pahle nikal jātā hūṃ, to baṛe jām se bach jātā hūṃ."},{"fr":"Apparemment, le nouveau pont routier va beaucoup aider.","tgt":"कहा जा रहा है कि नया फ़्लाईओवर बहुत मदद करेगा।","ro":"Kahā jā rahā hai ki nayā flāīovar bahut madad karegā."}]},{"title":"Une réunion d'équipe tendue","phrases":[{"fr":"Quand le chef est arrivé, la réunion a commencé.","tgt":"जब बॉस आए, तब मीटिंग शुरू हुई।","ro":"Jab bos āe, tab mīṭing shurū huī."},{"fr":"Celui qui finit le premier aide les autres.","tgt":"जो पहले ख़त्म करता है, वह दूसरों की मदद करता है।","ro":"Jo pahle khatm kartā hai, vah dūsroṃ kī madad kartā hai."},{"fr":"Quand le client a vu les chiffres, il n'était pas content.","tgt":"जब क्लाइंट ने आँकड़े देखे, तब वह ख़ुश नहीं था।","ro":"Jab klāinṭ ne āṃkṛe dekhe, tab vah khush nahīṃ thā."},{"fr":"Ce que vous avez dit hier était tout à fait juste.","tgt":"आपने कल जो कहा, वह बिल्कुल सही था।","ro":"Āpne kal jo kahā, vah bilkul sahī thā."},{"fr":"Celle qui a préparé la présentation s'appelle Priya.","tgt":"जिसने प्रेज़ेंटेशन तैयार की, उसका नाम प्रिया है।","ro":"Jisne prezenṭeshan taiyār kī, uskā nām Priyā hai."},{"fr":"Quand tout le monde parle en même temps, personne n'écoute personne.","tgt":"जब सब एक साथ बोलते हैं, तब कोई किसी की नहीं सुनता।","ro":"Jab sab ek sāth bolte haiṃ, tab koī kisī kī nahīṃ suntā."},{"fr":"Le chef a demandé à tout le monde de rester calme.","tgt":"बॉस ने सबसे शांत रहने को कहा।","ro":"Bos ne sabse shānt rahne ko kahā."},{"fr":"Ceux qui ont des questions peuvent m'envoyer un mail après.","tgt":"जिनके पास कोई सवाल हो, वे बाद में मुझे मेल कर सकते हैं।","ro":"Jinke pās koī savāl ho, ve bād meṃ mujhe mel kar sakte haiṃ."},{"fr":"Quand la décision sera prise, je vous préviendrai.","tgt":"जब फ़ैसला हो जाएगा, तब मैं आपको बता दूँगा।","ro":"Jab faislā ho jāegā, tab maiṃ āpko batā dūṃgā."},{"fr":"Au bout du compte, la réunion s'est mieux terminée que prévu.","tgt":"आख़िरकार मीटिंग उम्मीद से बेहतर ख़त्म हुई।","ro":"Ākhirkār mīṭing ummīd se behtar khatm huī."}],"tip":{"title":"« Jab... tab... » et « jo... vah... »","example":"Ce que vous avez dit hier était tout à fait juste. — आपने कल <b>जो</b> कहा, <b>वह</b> बिल्कुल सही था।","body":"Le hindi aime les phrases en deux moitiés qui se répondent, comme un écho. « Jab... tab... » veut dire « quand... alors... » : « jab bos āe, tab mīṭing shurū huī », quand le chef est arrivé, alors la réunion a commencé. De la même façon, « jo... vah... » signifie « celui qui... celui-là » ou « ce que... cela » : « āpne kal jo kahā, vah bilkul sahī thā », vous hier ce que avez dit, cela tout à fait juste était. Là où le français se contente de « ce que », le hindi reprend l'idée avec « vah » au début de la deuxième moitié. À l'oral, on marque une petite pause entre les deux parties, et on laisse souvent tomber « tab » quand le sens est clair. Astuce : retenez ces paires comme une question et sa réponse, « jo » ouvre la porte et « vah » la referme.","exampleRo":"Āpne kal jo kahā, vah bilkul sahī thā.","lit":"vous [ne] · hier · ce que · a dit · cela · tout à fait · juste · était","say":{"jab bos āe, tab mīṭing shurū huī":"जब बॉस आए, तब मीटिंग शुरू हुई","āpne kal jo kahā, vah bilkul sahī thā":"आपने कल जो कहा, वह बिल्कुल सही था","vah":"वह","tab":"तब","jo":"जो"}}},{"title":"Négocier son salaire","phrases":[{"fr":"J'ai demandé un rendez-vous avec les ressources humaines.","tgt":"मैंने एचआर के साथ मीटिंग का समय माँगा।","ro":"Maiṃne echār ke sāth mīṭing kā samay māṃgā."},{"fr":"Je voudrais parler de mon augmentation annuelle.","tgt":"मैं अपनी सालाना बढ़ोतरी के बारे में बात करना चाहता हूँ।","ro":"Maiṃ apnī sālānā baṛhotarī ke bāre meṃ bāt karnā chāhtā hūṃ."},{"fr":"Cette année, j'ai mené deux gros projets.","tgt":"इस साल मैंने दो बड़े प्रोजेक्ट संभाले।","ro":"Is sāl maiṃne do baṛe projekṭ sambhāle."},{"fr":"Dans notre domaine, les salaires ont beaucoup augmenté.","tgt":"हमारी फ़ील्ड में तनख़्वाहें काफ़ी बढ़ गई हैं।","ro":"Hamārī fīlḍ meṃ tankhvāheṃ kāfī baṛh gaī haiṃ."},{"fr":"Une autre entreprise m'a fait une offre.","tgt":"एक दूसरी कंपनी ने मुझे ऑफ़र दिया है।","ro":"Ek dūsrī kampanī ne mujhe ofar diyā hai."},{"fr":"Mais si possible, j'aimerais rester ici.","tgt":"लेकिन हो सके तो मैं यहीं रहना चाहूँगा।","ro":"Lekin ho sake to maiṃ yahīṃ rahnā chāhūṃgā."},{"fr":"Pouvez-vous faire un effort sur le salaire fixe ?","tgt":"क्या आप फ़िक्स्ड सैलरी में थोड़ा और कर सकते हैं?","ro":"Kyā āp fiksḍ sailarī meṃ thoṛā aur kar sakte haiṃ?"},{"fr":"La prime dépend des résultats de l'équipe.","tgt":"बोनस टीम के नतीजों पर निर्भर करता है।","ro":"Bonas ṭīm ke natījoṃ par nirbhar kartā hai."},{"fr":"Prenez le temps d'y réfléchir jusqu'à vendredi.","tgt":"आप शुक्रवार तक सोच लीजिए।","ro":"Āp shukravār tak soch lījie."},{"fr":"Nous sommes arrivés à un accord raisonnable.","tgt":"हम एक ठीक-ठाक समझौते पर पहुँच गए।","ro":"Ham ek ṭhīk-ṭhāk samjhaute par pahuṃch gae."}]},{"title":"Le contrat de location","phrases":[{"fr":"Nous avons trouvé un appartement de deux chambres à Kondapur.","tgt":"हमें कोंडापुर में दो बेडरूम का फ़्लैट मिल गया।","ro":"Hameṃ Konḍāpur meṃ do beḍrūm kā flaiṭ mil gayā."},{"fr":"Le propriétaire demande dix mois de loyer comme caution.","tgt":"मकान-मालिक दस महीने का किराया डिपॉज़िट के तौर पर माँग रहा है।","ro":"Makān-mālik das mahīne kā kirāyā ḍipozit ke taur par māṃg rahā hai."},{"fr":"Pour nous, c'est vraiment trop cher.","tgt":"यह हमारे लिए सच में बहुत महँगा है।","ro":"Yah hamāre lie sach meṃ bahut mahaṃgā hai."},{"fr":"Comme d'habitude, le bail est fait pour onze mois.","tgt":"हमेशा की तरह एग्रीमेंट ग्यारह महीने का है।","ro":"Hameshā kī tarah egrīmenṭ gyārah mahīne kā hai."},{"fr":"Les charges d'entretien sont-elles comprises dans le loyer ?","tgt":"क्या मेंटेनेंस किराए में शामिल है?","ro":"Kyā menṭenens kirāe meṃ shāmil hai?"},{"fr":"Si quelque chose casse, qui paiera ?","tgt":"अगर कुछ टूट जाए तो पैसे कौन देगा?","ro":"Agar kuchh ṭūṭ jāe to paise kaun degā?"},{"fr":"Le préavis est de deux mois des deux côtés.","tgt":"दोनों तरफ़ से दो महीने का नोटिस देना होगा।","ro":"Donoṃ taraf se do mahīne kā noṭis denā hogā."},{"fr":"J'ai fait relire le contrat par un ami avocat.","tgt":"मैंने एक वकील दोस्त से एग्रीमेंट पढ़वाया।","ro":"Maiṃne ek vakīl dost se egrīmenṭ paṛhvāyā."},{"fr":"A-t-on le droit d'avoir des animaux dans l'immeuble ?","tgt":"क्या बिल्डिंग में पालतू जानवर रखने की इजाज़त है?","ro":"Kyā bilḍing meṃ pāltū jānvar rakhne kī ijāzat hai?"},{"fr":"Nous emménageons le premier du mois prochain.","tgt":"हम अगले महीने की पहली तारीख़ को शिफ़्ट हो रहे हैं।","ro":"Ham agle mahīne kī pahlī tārīkh ko shifṭ ho rahe haiṃ."}]},{"title":"Le jour du déménagement","phrases":[{"fr":"Même le canapé n'est pas entré dans l'ascenseur.","tgt":"सोफ़ा तक लिफ़्ट में नहीं घुसा।","ro":"Sofā tak lifṭ meṃ nahīṃ ghusā."},{"fr":"Les déménageurs ont travaillé jusqu'à minuit.","tgt":"सामान ढोने वाले आधी रात तक काम करते रहे।","ro":"Sāmān ḍhone vāle ādhī rāt tak kām karte rahe."},{"fr":"Je n'ai même pas eu le temps de manger.","tgt":"मुझे खाना खाने का समय तक नहीं मिला।","ro":"Mujhe khānā khāne kā samay tak nahīṃ milā."},{"fr":"Même ma voisine est venue nous aider.","tgt":"मेरी पड़ोसन भी हमारी मदद करने आई।","ro":"Merī paṛosan bhī hamārī madad karne āī."},{"fr":"Les cartons sont restés dans le couloir jusqu'au lendemain.","tgt":"डिब्बे अगले दिन तक गलियारे में पड़े रहे।","ro":"Ḍibbe agle din tak galiyāre meṃ paṛe rahe."},{"fr":"Il n'y a même pas encore internet dans le nouvel appartement.","tgt":"नए फ़्लैट में अभी तक इंटरनेट भी नहीं है।","ro":"Nae flaiṭ meṃ abhī tak inṭarneṭ bhī nahīṃ hai."},{"fr":"Même un petit déménagement demande beaucoup d'efforts.","tgt":"छोटी-सी शिफ़्टिंग में भी बहुत मेहनत लगती है।","ro":"Chhoṭī-sī shifṭing meṃ bhī bahut mehnat lagtī hai."},{"fr":"Le camion a roulé de Secunderabad jusqu'à Madhapur.","tgt":"ट्रक सिकंदराबाद से माधापुर तक गया।","ro":"Ṭrak Sikandarābād se Mādhāpur tak gayā."},{"fr":"Rien ne s'est cassé, pas même les verres.","tgt":"कुछ नहीं टूटा, गिलास तक नहीं।","ro":"Kuchh nahīṃ ṭūṭā, gilās tak nahīṃ."},{"fr":"Ce soir, même les enfants sont épuisés.","tgt":"आज शाम बच्चे भी बहुत थक गए हैं।","ro":"Āj shām bachche bhī bahut thak gae haiṃ."}],"tip":{"title":"« Tak » et « bhī » : même","example":"Je n'ai même pas eu le temps de manger. — मुझे खाना खाने का समय <b>तक</b> नहीं मिला।","body":"Pour dire « même » en hindi, on place un petit mot juste après le mot qu'on veut souligner, jamais avant comme en français. « Bhī » veut dire « aussi » ou « même » : « merī paṛosan bhī āī », même ma voisine est venue. « Tak », qui signifie d'habitude « jusqu'à », prend un sens plus fort dans une phrase négative : « samay tak nahīṃ milā », je n'ai même pas eu le temps. Mot à mot, cela donne : à moi, manger, de, temps, même, pas, trouvé. Avec une heure ou un lieu, « tak » garde son sens de base : « ādhī rāt tak », jusqu'à minuit, et « Mādhāpur tak », jusqu'à Madhapur. Astuce : « bhī » ajoute quelque chose, alors que « tak » pousse jusqu'au bout et marque la surprise.","exampleRo":"Mujhe khānā khāne kā samay tak nahīṃ milā.","lit":"moi [à] · nourriture · manger · [de] · temps · même · pas · a été trouvé","say":{"Tak":"तक","bhī":"भी","Bhī":"भी","merī paṛosan bhī āī":"मेरी पड़ोसन भी आई","samay tak nahīṃ milā":"समय तक नहीं मिला","tak":"तक","ādhī rāt tak":"आधी रात तक","Mādhāpur tak":"माधापुर तक"}}},{"title":"Le télétravail","phrases":[{"fr":"Je télétravaille trois jours sur cinq.","tgt":"मैं हफ़्ते में तीन दिन घर से काम करता हूँ।","ro":"Maiṃ hafte meṃ tīn din ghar se kām kartā hūṃ."},{"fr":"J'économise deux heures de trajet par jour.","tgt":"मेरा रोज़ दो घंटे का सफ़र बच जाता है।","ro":"Merā roz do ghanṭe kā safar bach jātā hai."},{"fr":"Mais les coupures de courant fréquentes sont gênantes.","tgt":"लेकिन बार-बार बिजली जाने से परेशानी होती है।","ro":"Lekin bār-bār bijlī jāne se pareshānī hotī hai."},{"fr":"J'ai acheté un onduleur pour ne pas perdre mon travail.","tgt":"काम बर्बाद न हो, इसलिए मैंने इन्वर्टर ख़रीदा।","ro":"Kām barbād na ho, islie maiṃne invarṭar kharīdā."},{"fr":"Mon équipe est répartie entre Hyderabad et Pune.","tgt":"मेरी टीम हैदराबाद और पुणे में बँटी हुई है।","ro":"Merī ṭīm Haidarābād aur Puṇe meṃ baṃṭī huī hai."},{"fr":"On se parle surtout par appel vidéo.","tgt":"हम ज़्यादातर वीडियो कॉल पर बात करते हैं।","ro":"Ham zyādātar vīḍiyo kol par bāt karte haiṃ."},{"fr":"Parfois, les enfants font du bruit pendant les réunions.","tgt":"कभी-कभी मीटिंग के दौरान बच्चे शोर मचाते हैं।","ro":"Kabhī-kabhī mīṭing ke daurān bachche shor machāte haiṃ."},{"fr":"J'ai installé un petit bureau près de la fenêtre.","tgt":"मैंने खिड़की के पास एक छोटी-सी वर्क डेस्क लगाई है।","ro":"Maiṃne khiṛkī ke pās ek chhoṭī-sī vark ḍesk lagāī hai."},{"fr":"Le soir, j'ai du mal à décrocher du travail.","tgt":"शाम को काम से ध्यान हटाना मुश्किल होता है।","ro":"Shām ko kām se dhyān haṭānā mushkil hotā hai."},{"fr":"Le jeudi, je vais au bureau pour voir mes collègues.","tgt":"गुरुवार को मैं साथियों से मिलने ऑफ़िस जाता हूँ।","ro":"Guruvār ko maiṃ sāthiyoṃ se milne ofis jātā hūṃ."}]},{"title":"Un malentendu avec un collègue","phrases":[{"fr":"Ravi pense que je lui ai volé son idée.","tgt":"रवि को लगता है कि मैंने उसका आइडिया चुराया।","ro":"Ravi ko lagtā hai ki maiṃne uskā āiḍiyā churāyā."},{"fr":"Depuis lundi, il ne me dit même plus bonjour.","tgt":"सोमवार से वह मुझसे नमस्ते तक नहीं करता।","ro":"Somvār se vah mujhse namaste tak nahīṃ kartā."},{"fr":"Je préfère lui parler directement plutôt que d'attendre.","tgt":"इंतज़ार करने के बजाय मैं उससे सीधे बात करना बेहतर समझता हूँ।","ro":"Intazār karne ke bajāy maiṃ usse sīdhe bāt karnā behtar samajhtā hūṃ."},{"fr":"Allons boire un thé à la cantine.","tgt":"चलिए, कैंटीन में चाय पीते हैं।","ro":"Chalie, kainṭīn meṃ chāy pīte haiṃ."},{"fr":"Je n'avais aucune intention de vous blesser.","tgt":"मेरा इरादा आपको ठेस पहुँचाने का नहीं था।","ro":"Merā irādā āpko ṭhes pahuṃchāne kā nahīṃ thā."},{"fr":"En réalité, la manager avait confondu nos deux noms.","tgt":"असल में मैनेजर ने हमारे नाम आपस में मिला दिए थे।","ro":"Asal meṃ mainejar ne hamāre nām āpas meṃ milā die the."},{"fr":"Quand il a compris le malentendu, il a éclaté de rire.","tgt":"जब उसे ग़लतफ़हमी समझ आई, तब वह हँस पड़ा।","ro":"Jab use galatfahmī samajh āī, tab vah haṃs paṛā."},{"fr":"Nous allons présenter le projet ensemble.","tgt":"हम मिलकर प्रोजेक्ट पेश करेंगे।","ro":"Ham milkar projekṭ pesh kareṃge."},{"fr":"Il vaut mieux régler les tensions tout de suite.","tgt":"मसले तुरंत सुलझा लेना ही अच्छा है।","ro":"Masle turant suljhā lenā hī achchhā hai."},{"fr":"Maintenant, nous déjeunons souvent ensemble.","tgt":"अब हम अक्सर साथ में लंच करते हैं।","ro":"Ab ham aksar sāth meṃ lanch karte haiṃ."}]},{"title":"Changer d'adresse à la banque","phrases":[{"fr":"Je dois faire changer mon adresse à la banque.","tgt":"मुझे बैंक में अपना पता बदलवाना है।","ro":"Mujhe baink meṃ apnā patā badalvānā hai."},{"fr":"Quels papiers est-ce qu'il faut apporter ?","tgt":"कौन-कौन से कागज़ात लाने होंगे?","ro":"Kaun-kaun se kāgazāt lāne hoṃge?"},{"fr":"Une copie du bail suffira-t-elle ?","tgt":"क्या किराए के एग्रीमेंट की कॉपी काफ़ी होगी?","ro":"Kyā kirāe ke egrīmenṭ kī kopī kāfī hogī?"},{"fr":"Le formulaire doit être rempli en majuscules.","tgt":"फ़ॉर्म बड़े अक्षरों में भरा जाना चाहिए।","ro":"Form baṛe aksharoṃ meṃ bharā jānā chāhie."},{"fr":"On m'a dit de revenir après le déjeuner.","tgt":"मुझसे कहा गया कि लंच के बाद आइए।","ro":"Mujhse kahā gayā ki lanch ke bād āie."},{"fr":"La file d'attente avançait très lentement.","tgt":"लाइन बहुत धीरे-धीरे आगे बढ़ रही थी।","ro":"Lāin bahut dhīre-dhīre āge baṛh rahī thī."},{"fr":"Heureusement, une partie des démarches se fait maintenant en ligne.","tgt":"अच्छी बात है कि अब कुछ काम ऑनलाइन भी हो जाता है।","ro":"Achchhī bāt hai ki ab kuchh kām onlāin bhī ho jātā hai."},{"fr":"Pour confirmer, j'ai reçu un code sur mon téléphone.","tgt":"कन्फ़र्म करने के लिए मेरे फ़ोन पर एक कोड आया।","ro":"Kanfarm karne ke lie mere fon par ek koḍ āyā."},{"fr":"La nouvelle carte arrivera par la poste sous dix jours.","tgt":"नया कार्ड दस दिन के अंदर डाक से आ जाएगा।","ro":"Nayā kārḍ das din ke andar ḍāk se ā jāegā."},{"fr":"Toutes ces démarches m'ont pris une matinée entière.","tgt":"इन सब कामों में मेरी पूरी सुबह निकल गई।","ro":"In sab kāmoṃ meṃ merī pūrī subah nikal gaī."}]},{"title":"Une présentation devant la direction","phrases":[{"fr":"Je vous prie de bien vouloir excuser mon retard.","tgt":"कृपया मेरी देरी के लिए क्षमा करें।","ro":"Kripayā merī derī ke lie kshamā kareṃ."},{"fr":"Si vous le permettez, je vais vous présenter notre nouveau projet.","tgt":"अनुमति हो तो मैं आपके सामने हमारा नया प्रोजेक्ट प्रस्तुत करूँ।","ro":"Anumati ho to maiṃ āpke sāmne hamārā nayā projekṭ prastut karūṃ."},{"fr":"Je tiens à vous informer que le travail a été terminé dans les délais.","tgt":"आपको सूचित करना चाहता हूँ कि काम समय पर पूरा कर लिया गया है।","ro":"Āpko sūchit karnā chāhtā hūṃ ki kām samay par pūrā kar liyā gayā hai."},{"fr":"Vos suggestions nous seraient très précieuses.","tgt":"आपके सुझाव हमारे लिए बहुत मूल्यवान होंगे।","ro":"Āpke sujhāv hamāre lie bahut mūlyavān hoṃge."},{"fr":"Le rapport complet vous sera envoyé demain.","tgt":"पूरी रिपोर्ट कल आपको भेज दी जाएगी।","ro":"Pūrī riporṭ kal āpko bhej dī jāegī."},{"fr":"Pour toute question, je reste à votre disposition.","tgt":"किसी भी प्रश्न के लिए मैं उपलब्ध हूँ।","ro":"Kisī bhī prashn ke lie maiṃ upalabdh hūṃ."},{"fr":"Nous sollicitons votre accord pour recruter deux personnes.","tgt":"हम दो लोगों की नियुक्ति के लिए आपकी स्वीकृति चाहते हैं।","ro":"Ham do logoṃ kī niyukti ke lie āpkī svīkriti chāhte haiṃ."},{"fr":"Avec votre permission, je passe au point suivant.","tgt":"आपकी अनुमति से मैं अगले विषय पर आता हूँ।","ro":"Āpkī anumati se maiṃ agle vishay par ātā hūṃ."},{"fr":"Je vous remercie sincèrement pour votre temps précieux.","tgt":"आपने अपना कीमती समय दिया, इसके लिए हार्दिक धन्यवाद।","ro":"Āpne apnā kīmtī samay diyā, iske lie hārdik dhanyavād."},{"fr":"Entre collègues, en revanche, on parle beaucoup plus simplement.","tgt":"वैसे साथियों के बीच हम काफ़ी आसान भाषा में बात करते हैं।","ro":"Vaise sāthiyoṃ ke bīch ham kāfī āsān bhāshā meṃ bāt karte haiṃ."}],"tip":{"title":"Le hindi formel du bureau","example":"Je vous prie de bien vouloir excuser mon retard. — <b>कृपया</b> मेरी देरी के लिए <b>क्षमा करें</b>।","body":"Au bureau, surtout face à la direction, le hindi change de registre et emprunte des mots plus soutenus. « Kripayā » remplace le simple « s'il vous plaît », « kshamā kareṃ » veut dire « veuillez pardonner », et « dhanyavād » devient le merci officiel. Décomposons notre exemple : « kripayā merī derī ke lie kshamā kareṃ », s'il vous plaît, mon retard, pour, pardon, faites. La terminaison « -eṃ », comme dans « kareṃ », est une manière très polie et un peu distante de demander. Dans une réunion officielle, on entend aussi « sūchit karnā », informer, et « upalabdh », disponible, comme dans « maiṃ upalabdh hūṃ », je suis à votre disposition. Astuce : réservez ces mots aux moments solennels, et revenez au hindi simple de tous les jours dès que vous êtes entre collègues.","exampleRo":"Kripayā merī derī ke lie kshamā kareṃ.","lit":"s'il vous plaît · mon · retard · [pour] · pardon · faites","say":{"Kripayā":"कृपया","kshamā kareṃ":"क्षमा करें","dhanyavād":"धन्यवाद","kripayā merī derī ke lie kshamā kareṃ":"कृपया मेरी देरी के लिए क्षमा करें","kareṃ":"करें","sūchit karnā":"सूचित करना","upalabdh":"उपलब्ध","maiṃ upalabdh hūṃ":"मैं उपलब्ध हूँ"}}},{"title":"La hiérarchie au bureau","phrases":[{"fr":"Ici, on ajoute « ji » après le nom des supérieurs.","tgt":"यहाँ सीनियर लोगों के नाम के बाद जी लगाते हैं।","ro":"Yahāṃ sīniyar logoṃ ke nām ke bād jī lagāte haiṃ."},{"fr":"Mon responsable direct, c'est monsieur Reddy.","tgt":"मेरे डायरेक्ट मैनेजर रेड्डी जी हैं।","ro":"Mere ḍāyrekṭ mainejar Reḍḍī jī haiṃ."},{"fr":"Pour un congé, il faut l'accord de deux personnes.","tgt":"छुट्टी के लिए दो लोगों की मंज़ूरी चाहिए।","ro":"Chhuṭṭī ke lie do logoṃ kī manzūrī chāhie."},{"fr":"Les jeunes employés parlent rarement pendant les réunions.","tgt":"नए कर्मचारी मीटिंग में कम ही बोलते हैं।","ro":"Nae karmachārī mīṭing meṃ kam hī bolte haiṃ."},{"fr":"Contredire le chef devant tout le monde n'est pas bien vu.","tgt":"सबके सामने बॉस की बात काटना ठीक नहीं माना जाता।","ro":"Sabke sāmne bos kī bāt kāṭnā ṭhīk nahīṃ mānā jātā."},{"fr":"Mais notre nouvelle directrice encourage le débat.","tgt":"लेकिन हमारी नई डायरेक्टर खुलकर चर्चा को बढ़ावा देती हैं।","ro":"Lekin hamārī naī ḍāyrekṭar khulkar charchā ko baṛhāvā detī haiṃ."},{"fr":"Elle déjeune même avec les stagiaires.","tgt":"वे इंटर्न्स के साथ भी लंच करती हैं।","ro":"Ve inṭarns ke sāth bhī lanch kartī haiṃ."},{"fr":"La promotion dépend encore souvent de l'ancienneté.","tgt":"प्रमोशन अब भी अक्सर सीनियरिटी पर निर्भर करता है।","ro":"Pramoshan ab bhī aksar sīniyariṭī par nirbhar kartā hai."},{"fr":"Je dois faire signer ce document par trois responsables.","tgt":"मुझे यह कागज़ तीन अफ़सरों से साइन करवाना है।","ro":"Mujhe yah kāgaz tīn afsaroṃ se sāin karvānā hai."},{"fr":"Avec le temps, j'ai appris ces codes.","tgt":"समय के साथ मैंने ये तौर-तरीके समझ लिए हैं।","ro":"Samay ke sāth maiṃne ye taur-tarīke samajh lie haiṃ."}]},{"title":"Passer le permis de conduire","phrases":[{"fr":"Je veux obtenir un permis de conduire indien.","tgt":"मुझे भारतीय ड्राइविंग लाइसेंस बनवाना है।","ro":"Mujhe bhāratīy ḍrāiving lāisens banvānā hai."},{"fr":"Il faut d'abord passer un test en ligne.","tgt":"पहले एक ऑनलाइन टेस्ट देना पड़ता है।","ro":"Pahle ek onlāin ṭesṭ denā paṛtā hai."},{"fr":"Ensuite, on reçoit un permis provisoire.","tgt":"उसके बाद लर्निंग लाइसेंस मिलता है।","ro":"Uske bād larning lāisens miltā hai."},{"fr":"L'examen pratique a lieu au bureau des transports.","tgt":"ड्राइविंग टेस्ट आरटीओ दफ़्तर में होता है।","ro":"Ḍrāiving ṭesṭ ārṭīo daftar meṃ hotā hai."},{"fr":"J'ai pris dix leçons dans une auto-école de Madhapur.","tgt":"मैंने माधापुर के एक ड्राइविंग स्कूल में दस क्लास लीं।","ro":"Maiṃne Mādhāpur ke ek ḍrāiving skūl meṃ das klās līṃ."},{"fr":"Conduire ici demande une attention de chaque instant.","tgt":"यहाँ गाड़ी चलाते समय हर पल ध्यान रखना पड़ता है।","ro":"Yahāṃ gāṛī chalāte samay har pal dhyān rakhnā paṛtā hai."},{"fr":"Les deux-roues arrivent de tous les côtés.","tgt":"दोपहिया गाड़ियाँ हर तरफ़ से आती हैं।","ro":"Dopahiyā gāṛiyāṃ har taraf se ātī haiṃ."},{"fr":"L'inspecteur m'a demandé de dessiner un huit.","tgt":"इंस्पेक्टर ने मुझसे आठ का आकार बनाने को कहा।","ro":"Inspekṭar ne mujhse āṭh kā ākār banāne ko kahā."},{"fr":"Je l'ai réussi du premier coup !","tgt":"मैं पहली बार में ही पास हो गया!","ro":"Maiṃ pahlī bār meṃ hī pās ho gayā!"},{"fr":"Le permis définitif me sera envoyé à la maison.","tgt":"पक्का लाइसेंस घर भेज दिया जाएगा।","ro":"Pakkā lāisens ghar bhej diyā jāegā."}]},{"title":"La vie dans une résidence","phrases":[{"fr":"Nous habitons dans une résidence fermée à Gachibowli.","tgt":"हम गच्चीबावली की एक गेटेड सोसाइटी में रहते हैं।","ro":"Ham Gachchībāvlī kī ek geṭeḍ sosāiṭī meṃ rahte haiṃ."},{"fr":"Un gardien contrôle tous ceux qui entrent et sortent.","tgt":"एक गार्ड हर आने-जाने वाले की जाँच करता है।","ro":"Ek gārḍ har āne-jāne vāle kī jāṃch kartā hai."},{"fr":"En été, l'eau arrive parfois par camion-citerne.","tgt":"गर्मियों में कभी-कभी पानी टैंकर से आता है।","ro":"Garmiyoṃ meṃ kabhī-kabhī pānī ṭainkar se ātā hai."},{"fr":"L'association des résidents se réunit chaque mois.","tgt":"रेज़िडेंट्स एसोसिएशन की हर महीने बैठक होती है।","ro":"Reziḍenṭs esosieshan kī har mahīne baiṭhak hotī hai."},{"fr":"On y discute des charges et des réparations.","tgt":"उसमें मेंटेनेंस और मरम्मत पर चर्चा होती है।","ro":"Usmeṃ menṭenens aur marammat par charchā hotī hai."},{"fr":"Dès qu'il y a une coupure, le groupe électrogène démarre.","tgt":"बिजली जाते ही जेनरेटर चालू हो जाता है।","ro":"Bijlī jāte hī jenareṭar chālū ho jātā hai."},{"fr":"Il y a une piscine que les enfants adorent.","tgt":"यहाँ एक स्विमिंग पूल है, जो बच्चों को बहुत पसंद है।","ro":"Yahāṃ ek sviming pūl hai, jo bachchoṃ ko bahut pasand hai."},{"fr":"Pour Diwali, la fête des lumières, les voisins illuminent tout l'immeuble.","tgt":"दिवाली पर पड़ोसी पूरी बिल्डिंग को रोशनी से सजाते हैं।","ro":"Divālī par paṛosī pūrī bilḍing ko roshnī se sajāte haiṃ."},{"fr":"Sans autorisation, le livreur ne peut pas monter.","tgt":"इजाज़त के बिना डिलीवरी वाला ऊपर नहीं आ सकता।","ro":"Ijāzat ke binā ḍilīvarī vālā ūpar nahīṃ ā saktā."},{"fr":"On se sent vraiment en sécurité ici.","tgt":"यहाँ हम सच में सुरक्षित महसूस करते हैं।","ro":"Yahāṃ ham sach meṃ surakshit mahsūs karte haiṃ."}]},{"title":"Recruter un nouveau collègue","phrases":[{"fr":"Nous cherchons un développeur avec cinq ans d'expérience.","tgt":"हमें पाँच साल के अनुभव वाला एक डेवलपर चाहिए।","ro":"Hameṃ pāṃch sāl ke anubhav vālā ek ḍevlapar chāhie."},{"fr":"L'annonce a été publiée lundi dernier.","tgt":"पिछले सोमवार को विज्ञापन निकाला गया।","ro":"Pichhle somvār ko vigyāpan nikālā gayā."},{"fr":"Nous avons reçu plus de trois cents candidatures.","tgt":"हमें तीन सौ से ज़्यादा आवेदन मिले।","ro":"Hameṃ tīn sau se zyādā āvedan mile."},{"fr":"Les meilleurs profils sont convoqués à un entretien.","tgt":"सबसे अच्छे उम्मीदवारों को इंटरव्यू के लिए बुलाया जाता है।","ro":"Sabse achchhe ummīdvāroṃ ko inṭarvyū ke lie bulāyā jātā hai."},{"fr":"Le premier entretien se fait par téléphone.","tgt":"पहला इंटरव्यू फ़ोन पर होता है।","ro":"Pahlā inṭarvyū fon par hotā hai."},{"fr":"Ensuite, il y a un test technique de deux heures.","tgt":"फिर दो घंटे का टेक्निकल टेस्ट होता है।","ro":"Phir do ghanṭe kā ṭeknikal ṭesṭ hotā hai."},{"fr":"Celui qui le réussit rencontre le directeur.","tgt":"जो पास होता है, वह डायरेक्टर से मिलता है।","ro":"Jo pās hotā hai, vah ḍāyrekṭar se miltā hai."},{"fr":"Une candidate m'a beaucoup impressionné.","tgt":"एक उम्मीदवार ने मुझे बहुत प्रभावित किया।","ro":"Ek ummīdvār ne mujhe bahut prabhāvit kiyā."},{"fr":"Elle a fait réduire son préavis par son ancienne entreprise.","tgt":"उसने अपनी पुरानी कंपनी से नोटिस पीरियड कम करवाया।","ro":"Usne apnī purānī kampanī se noṭis pīriyaḍ kam karvāyā."},{"fr":"Elle nous rejoint dans un mois.","tgt":"वह एक महीने बाद हमारे यहाँ जॉइन करेगी।","ro":"Vah ek mahīne bād hamāre yahāṃ join karegī."}]},{"title":"Un dégât des eaux","phrases":[{"fr":"Pendant la nuit, un tuyau a éclaté dans la salle de bains.","tgt":"रात में बाथरूम का एक पाइप फट गया।","ro":"Rāt meṃ bāthrūm kā ek pāip phaṭ gayā."},{"fr":"L'eau a coulé jusque chez le voisin du dessous.","tgt":"पानी नीचे वाले पड़ोसी के घर तक पहुँच गया।","ro":"Pānī nīche vāle paṛosī ke ghar tak pahuṃch gayā."},{"fr":"J'ai tout de suite fait venir un plombier.","tgt":"मैंने तुरंत प्लंबर को बुलवाया।","ro":"Maiṃne turant plambar ko bulvāyā."},{"fr":"J'ai dû photographier tous les dégâts.","tgt":"मुझे सारे नुकसान की फ़ोटो खींचनी पड़ीं।","ro":"Mujhe sāre nuksān kī foṭo khīṃchnī paṛīṃ."},{"fr":"Ensuite, j'ai déclaré le sinistre à l'assurance.","tgt":"फिर मैंने इंश्योरेंस कंपनी में क्लेम डाला।","ro":"Phir maiṃne inshyorens kampanī meṃ klem ḍālā."},{"fr":"Un inspecteur passera jeudi pour estimer les réparations.","tgt":"गुरुवार को एक सर्वेयर मरम्मत का ख़र्च आँकने आएगा।","ro":"Guruvār ko ek sarveyar marammat kā kharch āṃkne āegā."},{"fr":"Il faudra refaire entièrement le plafond du voisin.","tgt":"पड़ोसी की सीलिंग पूरी दोबारा बनवानी पड़ेगी।","ro":"Paṛosī kī sīling pūrī dobārā banvānī paṛegī."},{"fr":"Par chance, notre contrat couvre ce genre d'accident.","tgt":"ख़ुशकिस्मती से हमारी पॉलिसी में ऐसा नुकसान कवर होता है।","ro":"Khushkismatī se hamārī polisī meṃ aisā nuksān kavar hotā hai."},{"fr":"Le remboursement devrait arriver d'ici trois semaines.","tgt":"पैसा तीन हफ़्ते में वापस आ जाना चाहिए।","ro":"Paisā tīn hafte meṃ vāpas ā jānā chāhie."},{"fr":"Désormais, je fais contrôler la plomberie chaque année.","tgt":"अब मैं हर साल प्लंबिंग चेक करवाता हूँ।","ro":"Ab maiṃ har sāl plambing chek karvātā hūṃ."}]},{"title":"Un dimanche en ville","phrases":[{"fr":"Le dimanche, nous allons souvent au bord du lac Hussain Sagar.","tgt":"रविवार को हम अक्सर हुसैन सागर झील के किनारे जाते हैं।","ro":"Ravivār ko ham aksar Husain Sāgar jhīl ke kināre jāte haiṃ."},{"fr":"Le soir, une brise fraîche y souffle.","tgt":"शाम को वहाँ ठंडी हवा चलती है।","ro":"Shām ko vahāṃ ṭhanḍī havā chaltī hai."},{"fr":"Parfois, nous mangeons un biryani dans la vieille ville.","tgt":"कभी-कभी हम पुराने शहर में बिरयानी खाते हैं।","ro":"Kabhī-kabhī ham purāne shahar meṃ biryānī khāte haiṃ."},{"fr":"Le Charminar est magnifique au coucher du soleil.","tgt":"सूरज ढलते समय चारमीनार बहुत ख़ूबसूरत लगता है।","ro":"Sūraj ḍhalte samay Chārmīnār bahut khūbsūrat lagtā hai."},{"fr":"Les bazars autour sont pleins de bracelets colorés.","tgt":"आसपास के बाज़ार रंग-बिरंगी चूड़ियों से भरे हैं।","ro":"Āspās ke bāzār rang-birangī chūṛiyoṃ se bhare haiṃ."},{"fr":"Il faut marchander, sinon on paie le double.","tgt":"मोलभाव करना पड़ता है, वरना दोगुना पैसा देना पड़ता है।","ro":"Molbhāv karnā paṛtā hai, varnā dogunā paisā denā paṛtā hai."},{"fr":"Ma femme a fait graver nos noms sur un bracelet.","tgt":"मेरी पत्नी ने एक चूड़ी पर हमारे नाम खुदवाए।","ro":"Merī patnī ne ek chūṛī par hamāre nām khudvāe."},{"fr":"Plus il se fait tard, plus il y a de monde.","tgt":"जितनी देर होती है, उतनी भीड़ बढ़ती जाती है।","ro":"Jitnī der hotī hai, utnī bhīṛ baṛhtī jātī hai."},{"fr":"Nous rentrons en métro pour éviter les bouchons.","tgt":"जाम से बचने के लिए हम मेट्रो से लौटते हैं।","ro":"Jām se bachne ke lie ham meṭro se lauṭte haiṃ."},{"fr":"Ces dimanches me font oublier la semaine de travail.","tgt":"ऐसे रविवार मुझे पूरे हफ़्ते का काम भुला देते हैं।","ro":"Aise ravivār mujhe pūre hafte kā kām bhulā dete haiṃ."}]},{"title":"Trouver le bon équilibre","phrases":[{"fr":"Après huit heures du soir, je ne réponds plus aux mails.","tgt":"रात आठ बजे के बाद मैं ईमेल का जवाब नहीं देता।","ro":"Rāt āṭh baje ke bād maiṃ īmel kā javāb nahīṃ detā."},{"fr":"Le matin, je cours une demi-heure dans un parc de Jubilee Hills.","tgt":"सुबह मैं जुबली हिल्स के एक पार्क में आधा घंटा दौड़ता हूँ।","ro":"Subah maiṃ Jublī Hils ke ek pārk meṃ ādhā ghanṭā dauṛtā hūṃ."},{"fr":"Le week-end, ma femme et moi cuisinons ensemble.","tgt":"वीकेंड पर मैं और मेरी पत्नी साथ मिलकर खाना बनाते हैं।","ro":"Vīkenḍ par maiṃ aur merī patnī sāth milkar khānā banāte haiṃ."},{"fr":"Le travail est important, mais la santé l'est encore plus.","tgt":"काम ज़रूरी है, लेकिन सेहत उससे भी ज़्यादा ज़रूरी है।","ro":"Kām zarūrī hai, lekin sehat usse bhī zyādā zarūrī hai."},{"fr":"J'ai appris à refuser poliment.","tgt":"मैंने विनम्रता से मना करना सीख लिया है।","ro":"Maiṃne vinamratā se manā karnā sīkh liyā hai."},{"fr":"Mes beaux-parents viennent de Warangal pour nous voir.","tgt":"मेरे सास-ससुर वारंगल से हमसे मिलने आ रहे हैं।","ro":"Mere sās-sasur Vārangal se hamse milne ā rahe haiṃ."},{"fr":"Quand ils viennent, je prends toujours quelques jours de congé.","tgt":"जब वे आते हैं, तब मैं हमेशा कुछ दिनों की छुट्टी लेता हूँ।","ro":"Jab ve āte haiṃ, tab maiṃ hameshā kuchh dinoṃ kī chhuṭṭī letā hūṃ."},{"fr":"Le dimanche soir, je prépare calmement ma semaine.","tgt":"रविवार शाम को मैं आराम से अपने हफ़्ते की प्लानिंग करता हूँ।","ro":"Ravivār shām ko maiṃ ārām se apne hafte kī plāning kartā hūṃ."},{"fr":"Pendant le dîner, mon téléphone reste dans un tiroir.","tgt":"रात के खाने के समय मेरा फ़ोन दराज़ में रहता है।","ro":"Rāt ke khāne ke samay merā fon darāz meṃ rahtā hai."},{"fr":"Je me sens beaucoup moins stressé qu'avant.","tgt":"मैं पहले से बहुत कम तनाव महसूस करता हूँ।","ro":"Maiṃ pahle se bahut kam tanāv mahsūs kartā hūṃ."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a fait vivre le quotidien d'un employé à Hyderabad.","tgt":"इस मॉड्यूल में हमने हैदराबाद में एक कर्मचारी की रोज़मर्रा की ज़िंदगी देखी।","ro":"Is moḍyūl meṃ hamne Haidarābād meṃ ek karmachārī kī rozmarrā kī zindagī dekhī."},{"fr":"Nous avons parlé de contrats, d'assurances et de réunions.","tgt":"हमने कॉन्ट्रैक्ट, इंश्योरेंस और मीटिंग के बारे में बात की।","ro":"Hamne konṭraikṭ, inshyorens aur mīṭing ke bāre meṃ bāt kī."},{"fr":"En hindi, les phrases au passif nous semblent maintenant faciles.","tgt":"हिंदी में पैसिव वाक्य अब आसान लगने लगे हैं।","ro":"Hindī meṃ paisiv vāky ab āsān lagne lage haiṃ."},{"fr":"Avec « karvānā », on sait maintenant faire faire les choses.","tgt":"करवाना की मदद से अब हम दूसरों से काम करवा सकते हैं।","ro":"Karvānā kī madad se ab ham dūsroṃ se kām karvā sakte haiṃ."},{"fr":"Les phrases avec « jo » et « vah » sont devenues naturelles.","tgt":"जो और वह वाले वाक्य अब सहज हो गए हैं।","ro":"Jo aur vah vāle vāky ab sahaj ho gae haiṃ."},{"fr":"Nous savons aussi passer au registre formel au bureau.","tgt":"हम ऑफ़िस में औपचारिक भाषा भी बोल सकते हैं।","ro":"Ham ofis meṃ aupchārik bhāshā bhī bol sakte haiṃ."},{"fr":"Le prochain module nous emmènera en voyage à travers l'Inde.","tgt":"अगला मॉड्यूल हमें पूरे भारत की यात्रा पर ले जाएगा।","ro":"Aglā moḍyūl hameṃ pūre Bhārat kī yātrā par le jāegā."},{"fr":"Prenez le temps de réécouter les leçons difficiles.","tgt":"मुश्किल पाठों को फिर से सुनने के लिए समय निकालिए।","ro":"Mushkil pāṭhoṃ ko phir se sunne ke lie samay nikālie."},{"fr":"Chaque jour, votre hindi devient plus solide.","tgt":"हर दिन आपकी हिंदी और मज़बूत हो रही है।","ro":"Har din āpkī hindī aur mazbūt ho rahī hai."},{"fr":"Bravo, et à très vite pour la suite !","tgt":"शाबाश, और जल्द ही आगे मिलते हैं!","ro":"Shābāsh, aur jald hī āge milte haiṃ!"}]}]},{"id":2,"name":"En voyage","desc":"Des aventures de voyage plus poussées et plus authentiques.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Hampi, parmi les rochers","phrases":[{"fr":"Nous sommes arrivés à Hampi après une nuit entière en bus.","tgt":"हम रात भर बस में सफ़र करके हम्पी पहुँचे।","ro":"Ham rāt bhar bas meṃ safar karke Hampī pahuṃche."},{"fr":"Partout ici, d'énormes rochers sont éparpillés dans le paysage.","tgt":"यहाँ हर तरफ़ बड़े-बड़े पत्थर बिखरे पड़े हैं।","ro":"Yahāṃ har taraf baṛe-baṛe patthar bikhre paṛe haiṃ."},{"fr":"Ce paysage ressemble à celui d'une autre planète.","tgt":"ये नज़ारा किसी दूसरी दुनिया जैसा है।","ro":"Ye nazārā kisī dūsrī duniyā jaisā hai."},{"fr":"Cette ville était autrefois la capitale d'un immense royaume.","tgt":"ये शहर कभी एक विशाल राज्य की राजधानी था।","ro":"Ye shahar kabhī ek vishāl rājya kī rājdhānī thā."},{"fr":"Aujourd'hui, il ne reste qu'un petit village au milieu des ruines.","tgt":"आज खंडहरों के बीच बस एक छोटा-सा गाँव बचा है।","ro":"Āj khanḍaharoṃ ke bīch bas ek chhoṭā-sā gāṃv bachā hai."},{"fr":"Nous avons loué des vélos pour toute la journée.","tgt":"हमने पूरे दिन के लिए साइकिलें किराए पर लीं।","ro":"Hamne pūre din ke lie sāikileṃ kirāe par līṃ."},{"fr":"Dès dix heures du matin, le soleil tape très fort.","tgt":"सुबह दस बजे से ही धूप बहुत तेज़ हो जाती है।","ro":"Subah das baje se hī dhūp bahut tez ho jātī hai."},{"fr":"Mieux vaut découvrir ces sites tôt le matin.","tgt":"इन जगहों को सुबह जल्दी देखना बेहतर है।","ro":"In jagahoṃ ko subah jaldī dekhnā behtar hai."},{"fr":"Le soir, tout le monde grimpe sur une colline pour admirer le coucher du soleil.","tgt":"शाम को सब लोग सूर्यास्त देखने के लिए एक पहाड़ी पर चढ़ते हैं।","ro":"Shām ko sab log sūryāst dekhne ke lie ek pahāṛī par chaṛhte haiṃ."},{"fr":"Dès le premier jour à Hampi, nous sommes restés bouche bée.","tgt":"हम्पी में पहले ही दिन हम दंग रह गए।","ro":"Hampī meṃ pahle hī din ham dang rah gae."}]},{"title":"Les ruines de Hampi","phrases":[{"fr":"Les ruines que nous visitons aujourd'hui ont plus de cinq cents ans.","tgt":"आज हम जो खंडहर देख रहे हैं, वो पाँच सौ साल से ज़्यादा पुराने हैं।","ro":"Āj ham jo khanḍahar dekh rahe haiṃ, vo pāṃch sau sāl se zyādā purāne haiṃ."},{"fr":"Le guide qui nous accompagne a grandi dans ce village.","tgt":"जो गाइड हमारे साथ है, वो इसी गाँव में बड़ा हुआ है।","ro":"Jo gāiḍ hamāre sāth hai, vo isī gāṃv meṃ baṛā huā hai."},{"fr":"Le bazar qui longeait cette rue était immense.","tgt":"इस सड़क के किनारे जो बाज़ार था, वो बहुत बड़ा था।","ro":"Is saṛak ke kināre jo bāzār thā, vo bahut baṛā thā."},{"fr":"Ceux qui grimpent jusqu'en haut ont la plus belle vue.","tgt":"जो लोग ऊपर तक चढ़ते हैं, उन्हें सबसे सुंदर नज़ारा मिलता है।","ro":"Jo log ūpar tak chaṛhte haiṃ, unheṃ sabse sundar nazārā miltā hai."},{"fr":"Ce que vous voyez là-bas, ce sont les anciennes écuries des éléphants.","tgt":"जो आप वहाँ देख रहे हैं, वो हाथियों के पुराने अस्तबल हैं।","ro":"Jo āp vahāṃ dekh rahe haiṃ, vo hāthiyoṃ ke purāne astabal haiṃ."},{"fr":"Tout ce qui reste ici a été taillé dans la pierre.","tgt":"यहाँ जो कुछ भी बचा है, वो पत्थर से तराशा गया है।","ro":"Yahāṃ jo kuchh bhī bachā hai, vo patthar se tarāshā gayā hai."},{"fr":"L'endroit que j'ai préféré, c'est le vieux bassin à gradins.","tgt":"मुझे जो जगह सबसे ज़्यादा पसंद आई, वो पुराना सीढ़ीदार तालाब है।","ro":"Mujhe jo jagah sabse zyādā pasand āī, vo purānā sīṛhīdār tālāb hai."},{"fr":"Gardez de l'eau avec vous, il n'y a presque pas d'ombre ici.","tgt":"अपने साथ पानी रखिए, क्योंकि यहाँ लगभग छाँव नहीं है।","ro":"Apne sāth pānī rakhie, kyoṃki yahāṃ lagbhag chhāṃv nahīṃ hai."},{"fr":"Ceux qui ont le temps restent ici plusieurs jours.","tgt":"जिनके पास समय होता है, वो यहाँ कई दिन रुकते हैं।","ro":"Jinke pās samay hotā hai, vo yahāṃ kaī din rukte haiṃ."},{"fr":"Ce que nous avons vu aujourd'hui, je ne l'oublierai jamais.","tgt":"आज हमने जो देखा, वो मैं कभी नहीं भूलूँगा।","ro":"Āj hamne jo dekhā, vo maiṃ kabhī nahīṃ bhūlūṃgā."}],"tip":{"title":"Les relatives avec « jo »","example":"Le guide qui nous accompagne a grandi dans ce village. — <b>जो</b> गाइड हमारे साथ है, <b>वो</b> इसी गाँव में बड़ा हुआ है।","body":"Pour dire « le guide qui nous accompagne », le hindi ne glisse pas la relative après le nom comme en français : il pose d'abord « jo », puis la petite phrase, puis il reprend avec « vo », qui veut dire « celui-là ». Mot à mot, « jo gāiḍ hamāre sāth hai, vo isī gāṃv meṃ baṛā huā hai » donne : quel guide est avec nous, celui-là a grandi dans ce village. À l'oral, marquez une petite pause juste avant « vo », comme une respiration entre les deux moitiés de la phrase. Vous pouvez ainsi dire « jo āp dekh rahe haiṃ, vo... », ce que vous voyez, c'est..., ou « jo log ūpar chaṛhte haiṃ », les gens qui montent. Devant « ke » ou « ne », « jo » devient « jin » au pluriel : « jinke pās samay hai », ceux qui ont le temps. Astuce : imaginez une balance, « jo » d'un côté, « vo » de l'autre, et la phrase tient en équilibre.","exampleRo":"Jo gāiḍ hamāre sāth hai, vo isī gāṃv meṃ baṛā huā hai.","lit":"qui · guide · notre · [avec] · est, · lui · ce-même · village · [dans] · grand · devenu · est","say":{"jo":"जो","vo":"वो","jo gāiḍ hamāre sāth hai, vo isī gāṃv meṃ baṛā huā hai":"जो गाइड हमारे साथ है, वो इसी गाँव में बड़ा हुआ है","jo log ūpar chaṛhte haiṃ":"जो लोग ऊपर चढ़ते हैं","ke":"के","ne":"ने","jin":"जिन","jinke pās samay hai":"जिनके पास समय है"}}},{"title":"Traverser la rivière en bateau rond","phrases":[{"fr":"Pour rejoindre l'autre rive, on monte dans un bateau rond en bambou.","tgt":"दूसरे किनारे तक जाने के लिए हम बाँस की एक गोल नाव लेते हैं।","ro":"Dūsre kināre tak jāne ke lie ham bāṃs kī ek gol nāv lete haiṃ."},{"fr":"Le batelier fait tourner le bateau sur lui-même pour faire rire les enfants.","tgt":"नाविक बच्चों को हँसाने के लिए नाव को गोल-गोल घुमाता है।","ro":"Nāvik bachchoṃ ko haṃsāne ke lie nāv ko gol-gol ghumātā hai."},{"fr":"La rivière reste calme en hiver, mais devient dangereuse pendant la mousson.","tgt":"सर्दियों में नदी शांत रहती है, पर बारिश के मौसम में ख़तरनाक हो जाती है।","ro":"Sardiyoṃ meṃ nadī shānt rahtī hai, par bārish ke mausam meṃ khatarnāk ho jātī hai."},{"fr":"Pendant les crues, la traversée est strictement interdite.","tgt":"बाढ़ के दिनों में नदी पार करना बिल्कुल मना है।","ro":"Bāṛh ke dinoṃ meṃ nadī pār karnā bilkul manā hai."},{"fr":"J'avais un peu peur de tomber à l'eau.","tgt":"मुझे पानी में गिरने का थोड़ा डर था।","ro":"Mujhe pānī meṃ girne kā thoṛā ḍar thā."},{"fr":"Le batelier m'a rassuré en riant.","tgt":"नाविक ने हँसते हुए मुझे तसल्ली दी।","ro":"Nāvik ne haṃste hue mujhe tasallī dī."},{"fr":"Il fait ce trajet des dizaines de fois par jour depuis vingt ans.","tgt":"वो बीस साल से रोज़ दर्जनों बार ये सफ़र करता है।","ro":"Vo bīs sāl se roz darjanoṃ bār ye safar kartā hai."},{"fr":"De l'autre côté, des singes nous attendaient sur les rochers.","tgt":"उस पार चट्टानों पर बंदर हमारा इंतज़ार कर रहे थे।","ro":"Us pār chaṭṭānoṃ par bandar hamārā intazār kar rahe the."},{"fr":"Ne laissez jamais votre sac ouvert près d'eux.","tgt":"उनके पास अपना बैग कभी खुला मत छोड़िए।","ro":"Unke pās apnā baig kabhī khulā mat chhoṛie."},{"fr":"Cette petite traversée est devenue un moment inoubliable.","tgt":"नदी का ये छोटा-सा सफ़र एक यादगार पल बन गया।","ro":"Nadī kā ye chhoṭā-sā safar ek yādgār pal ban gayā."}]},{"title":"Le désert de sel du Kutch","phrases":[{"fr":"Nous sommes venus au Kutch pour voir le désert blanc.","tgt":"हम सफ़ेद रेगिस्तान देखने के लिए कच्छ आए हैं।","ro":"Ham safed registān dekhne ke lie Kachchh āe haiṃ."},{"fr":"À perte de vue, le sol n'est que du sel.","tgt":"जहाँ तक नज़र जाती है, ज़मीन पर नमक ही नमक है।","ro":"Jahāṃ tak nazar jātī hai, zamīn par namak hī namak hai."},{"fr":"Pour entrer dans cette zone, il faut un permis spécial.","tgt":"इस इलाक़े में जाने के लिए एक ख़ास परमिट चाहिए।","ro":"Is ilāqe meṃ jāne ke lie ek khās parmiṭ chāhie."},{"fr":"On arrive avant l'aube pour profiter du lever du soleil.","tgt":"सूर्योदय का मज़ा लेने के लिए हम भोर से पहले पहुँचते हैं।","ro":"Sūryoday kā mazā lene ke lie ham bhor se pahle pahuṃchte haiṃ."},{"fr":"Les nuits de pleine lune, le sel brille comme de la neige.","tgt":"पूर्णिमा की रात नमक बर्फ़ की तरह चमकता है।","ro":"Pūrṇimā kī rāt namak barf kī tarah chamaktā hai."},{"fr":"Prenez des lunettes de soleil pour protéger vos yeux.","tgt":"अपनी आँखों को बचाने के लिए धूप का चश्मा ले लीजिए।","ro":"Apnī āṃkhoṃ ko bachāne ke lie dhūp kā chashmā le lījie."},{"fr":"Les familles d'ici récoltent le sel pour gagner leur vie.","tgt":"यहाँ के परिवार गुज़ारे के लिए नमक इकट्ठा करते हैं।","ro":"Yahāṃ ke parivār guzāre ke lie namak ikaṭṭhā karte haiṃ."},{"fr":"Pour eux, c'est un travail très dur sous un soleil brûlant.","tgt":"उनके लिए ये तपती धूप में बहुत मेहनत का काम है।","ro":"Unke lie ye taptī dhūp meṃ bahut mehnat kā kām hai."},{"fr":"J'ai acheté un châle brodé pour ma mère.","tgt":"मैंने अपनी माँ के लिए एक कढ़ाई वाली शाल ख़रीदी।","ro":"Maiṃne apnī māṃ ke lie ek kaṛhāī vālī shāl kharīdī."},{"fr":"Ce désert mérite vraiment le voyage.","tgt":"ये रेगिस्तान सचमुच इस सफ़र के लायक़ है।","ro":"Ye registān sachmuch is safar ke lāyaq hai."}],"tip":{"title":"« Ke lie » : pour, afin de","example":"Nous sommes venus au Kutch pour voir le désert blanc. — हम सफ़ेद रेगिस्तान देखने <b>के लिए</b> कच्छ आए हैं।","body":"« Ke lie » se place après le mot, là où le français met « pour » devant : « mere lie », pour moi, « māṃ ke lie », pour ma mère. Pour dire « afin de faire quelque chose », on prend le verbe à l'infinitif, on change le « nā » final en « ne », puis on ajoute « ke lie » : « dekhnā », voir, devient « dekhne ke lie », pour voir. Mot à mot, « ham safed registān dekhne ke lie Kachchh āe haiṃ » donne : nous, désert blanc voir pour, Kutch venus sommes. À l'oral, prononcez « ke lie » d'un seul souffle, presque « kélié », bien collé au verbe. Autres exemples : « jāne ke lie », pour aller, « bachāne ke lie », pour protéger. Astuce : en hindi, le but arrive avant l'action, comme si l'on annonçait d'abord pourquoi on se met en route.","exampleRo":"Ham safed registān dekhne ke lie Kachchh āe haiṃ.","lit":"nous · blanc · désert · voir · [pour] · Kutch · venus · sommes","say":{"Ke lie":"के लिए","mere lie":"मेरे लिए","māṃ ke lie":"माँ के लिए","ke lie":"के लिए","dekhnā":"देखना","dekhne ke lie":"देखने के लिए","ham safed registān dekhne ke lie Kachchh āe haiṃ":"हम सफ़ेद रेगिस्तान देखने के लिए कच्छ आए हैं","jāne ke lie":"जाने के लिए","bachāne ke lie":"बचाने के लिए","nā":"ना"}}},{"title":"Une nuit dans un village du Kutch","phrases":[{"fr":"Ce soir, nous dormons dans une hutte ronde en terre.","tgt":"आज रात हम मिट्टी की एक गोल झोपड़ी में सोएँगे।","ro":"Āj rāt ham miṭṭī kī ek gol jhopṛī meṃ soeṃge."},{"fr":"Ces huttes tiennent debout même pendant les tremblements de terre.","tgt":"ये झोपड़ियाँ भूकंप में भी मज़बूती से खड़ी रहती हैं।","ro":"Ye jhopṛiyāṃ bhūkamp meṃ bhī mazbūtī se khaṛī rahtī haiṃ."},{"fr":"Les murs sont décorés de minuscules miroirs.","tgt":"दीवारें छोटे-छोटे शीशों से सजी हुई हैं।","ro":"Dīvāreṃ chhoṭe-chhoṭe shīshoṃ se sajī huī haiṃ."},{"fr":"Les femmes du village brodent depuis leur enfance.","tgt":"गाँव की औरतें बचपन से कढ़ाई करती आ रही हैं।","ro":"Gāṃv kī aurteṃ bachpan se kaṛhāī kartī ā rahī haiṃ."},{"fr":"Chaque motif raconte une histoire de la région.","tgt":"हर नमूना इस इलाक़े की कोई न कोई कहानी सुनाता है।","ro":"Har namūnā is ilāqe kī koī na koī kahānī sunātā hai."},{"fr":"Le dîner a été préparé sur un feu de bois.","tgt":"रात का खाना लकड़ी की आग पर बनाया गया।","ro":"Rāt kā khānā lakṛī kī āg par banāyā gayā."},{"fr":"Après le repas, un vieil homme a joué de la flûte.","tgt":"खाने के बाद एक बुज़ुर्ग ने बाँसुरी बजाई।","ro":"Khāne ke bād ek buzurg ne bāṃsurī bajāī."},{"fr":"Le ciel du désert était rempli d'étoiles.","tgt":"रेगिस्तान का आसमान तारों से भरा हुआ था।","ro":"Registān kā āsmān tāroṃ se bharā huā thā."},{"fr":"Il faisait bien plus froid que je ne l'imaginais.","tgt":"मेरी सोच से कहीं ज़्यादा ठंड थी।","ro":"Merī soch se kahīṃ zyādā ṭhanḍ thī."},{"fr":"Nos hôtes nous ont donné d'épaisses couvertures.","tgt":"हमारे मेज़बानों ने हमें मोटे कंबल दिए।","ro":"Hamāre mezbānoṃ ne hameṃ moṭe kambal die."}]},{"title":"En route vers les Sundarbans","phrases":[{"fr":"Les Sundarbans sont la plus grande forêt de mangroves du monde.","tgt":"सुंदरबन दुनिया का सबसे बड़ा मैंग्रोव जंगल है।","ro":"Sundarban duniyā kā sabse baṛā maingrov jangal hai."},{"fr":"On ne peut s'y rendre qu'en bateau, depuis un petit embarcadère.","tgt":"वहाँ सिर्फ़ नाव से जाया जा सकता है, एक छोटे-से घाट से।","ro":"Vahāṃ sirf nāv se jāyā jā saktā hai, ek chhoṭe-se ghāṭ se."},{"fr":"Depuis Kolkata, il faut environ trois heures de voiture.","tgt":"कोलकाता से गाड़ी में लगभग तीन घंटे लगते हैं।","ro":"Kolkātā se gāṛī meṃ lagbhag tīn ghanṭe lagte haiṃ."},{"fr":"Les routes deviennent étroites et pleines de trous.","tgt":"सड़कें पतली और गड्ढों से भरी होती जाती हैं।","ro":"Saṛkeṃ patlī aur gaḍḍhoṃ se bharī hotī jātī haiṃ."},{"fr":"À l'embarcadère, notre bateau nous attendait déjà.","tgt":"घाट पर हमारी नाव पहले से हमारा इंतज़ार कर रही थी।","ro":"Ghāṭ par hamārī nāv pahle se hamārā intazār kar rahī thī."},{"fr":"Nous allons passer deux nuits à bord.","tgt":"हम दो रातें नाव पर ही बिताएँगे।","ro":"Ham do rāteṃ nāv par hī bitāeṃge."},{"fr":"Les cabines sont simples, mais très propres.","tgt":"केबिन सादे हैं, लेकिन बहुत साफ़-सुथरे हैं।","ro":"Kebin sāde haiṃ, lekin bahut sāf-suthre haiṃ."},{"fr":"Le cuisinier prépare du poisson frais à chaque repas.","tgt":"रसोइया हर खाने में ताज़ी मछली बनाता है।","ro":"Rasoiyā har khāne meṃ tāzī machhlī banātā hai."},{"fr":"Ici, la marée transforme tout le paysage deux fois par jour.","tgt":"यहाँ ज्वार-भाटा दिन में दो बार पूरा नज़ारा बदल देता है।","ro":"Yahāṃ jvār-bhāṭā din meṃ do bār pūrā nazārā badal detā hai."},{"fr":"Les habitants vivent au rythme de l'eau.","tgt":"यहाँ के लोग पानी की लय के साथ जीते हैं।","ro":"Yahāṃ ke log pānī kī lay ke sāth jīte haiṃ."}]},{"title":"Sur la piste du tigre","phrases":[{"fr":"On dirait que le tigre est passé par ici ce matin.","tgt":"लगता है कि बाघ आज सुबह यहाँ से गुज़रा है।","ro":"Lagtā hai ki bāgh āj subah yahāṃ se guzrā hai."},{"fr":"Ces traces dans la boue ont l'air toutes fraîches.","tgt":"कीचड़ में ये निशान बिल्कुल ताज़ा लगते हैं।","ro":"Kīchaṛ meṃ ye nishān bilkul tāzā lagte haiṃ."},{"fr":"Soudain, les oiseaux se sont mis à crier.","tgt":"अचानक चिड़ियाँ चिल्लाने लगीं।","ro":"Achānak chiṛiyāṃ chillāne lagīṃ."},{"fr":"Le guide s'est mis à parler tout bas.","tgt":"गाइड बहुत धीमी आवाज़ में बोलने लगा।","ro":"Gāiḍ bahut dhīmī āvāz meṃ bolne lagā."},{"fr":"Mon cœur s'est mis à battre très fort.","tgt":"मेरा दिल ज़ोर-ज़ोर से धड़कने लगा।","ro":"Merā dil zor-zor se dhaṛakne lagā."},{"fr":"On avait l'impression que le tigre nous observait derrière les arbres.","tgt":"ऐसा लग रहा था कि बाघ पेड़ों के पीछे से हमें देख रहा है।","ro":"Aisā lag rahā thā ki bāgh peṛoṃ ke pīchhe se hameṃ dekh rahā hai."},{"fr":"Finalement, le tigre ne s'est pas montré.","tgt":"आख़िर में हमें बाघ दिखा ही नहीं।","ro":"Ākhir meṃ hameṃ bāgh dikhā hī nahīṃ."},{"fr":"Mais cette attente m'a semblé passionnante.","tgt":"लेकिन मुझे ये इंतज़ार बहुत रोमांचक लगा।","ro":"Lekin mujhe ye intazār bahut romānchak lagā."},{"fr":"Sur le chemin du retour, il s'est mis à pleuvoir.","tgt":"लौटते वक़्त बारिश होने लगी।","ro":"Lauṭte vaqt bārish hone lagī."},{"fr":"Selon le guide, les tigres d'ici nagent très bien.","tgt":"गाइड कहता है कि यहाँ के बाघ अच्छी तरह तैरना जानते हैं।","ro":"Gāiḍ kahtā hai ki yahāṃ ke bāgh achchhī tarah tairnā jānte haiṃ."}],"tip":{"title":"« Lagnā » : sembler, et commencer à","example":"Soudain, les oiseaux se sont mis à crier. — अचानक चिड़ियाँ चिल्लाने <b>लगीं</b>।","body":"« Lagnā » est un verbe caméléon. Dans « lagtā hai ki », il veut dire « on dirait que » : « lagtā hai ki bāgh yahāṃ se guzrā hai », on dirait que le tigre est passé par ici. Avec « mujhe », il exprime une impression personnelle : « mujhe ye intazār romānchak lagā », cette attente m'a semblé passionnante. Mais placé juste après un verbe terminé en « ne », il signifie se mettre à : « chillāne lagīṃ », mot à mot crier se-mirent, elles se sont mises à crier. On l'entend tout le temps pour la météo : « bārish hone lagī », il s'est mis à pleuvoir. Astuce : si « lagnā » suit un autre verbe, quelque chose démarre ; s'il est seul, c'est une impression.","exampleRo":"Achānak chiṛiyāṃ chillāne lagīṃ.","lit":"soudain · oiseaux · crier · se-mirent","say":{"Lagnā":"लगना","lagtā hai ki":"लगता है कि","lagtā hai ki bāgh yahāṃ se guzrā hai":"लगता है कि बाघ यहाँ से गुज़रा है","mujhe":"मुझे","mujhe ye intazār romānchak lagā":"मुझे ये इंतज़ार रोमांचक लगा","chillāne lagīṃ":"चिल्लाने लगीं","bārish hone lagī":"बारिश होने लगी","lagnā":"लगना"}}},{"title":"Les ponts de racines vivantes","phrases":[{"fr":"Au Meghalaya, les villageois font pousser des ponts avec des racines d'arbres.","tgt":"मेघालय में गाँव वाले पेड़ों की जड़ों से पुल उगाते हैं।","ro":"Meghālay meṃ gāṃv vāle peṛoṃ kī jaṛoṃ se pul ugāte haiṃ."},{"fr":"Il faut plusieurs décennies pour qu'un pont devienne solide.","tgt":"एक पुल को मज़बूत होने में कई दशक लगते हैं।","ro":"Ek pul ko mazbūt hone meṃ kaī dashak lagte haiṃ."},{"fr":"Certains de ces ponts ont plus de cent ans.","tgt":"इनमें से कुछ पुल सौ साल से भी पुराने हैं।","ro":"Inmeṃ se kuchh pul sau sāl se bhī purāne haiṃ."},{"fr":"Plus ces ponts vieillissent, plus ils deviennent solides.","tgt":"ये पुल जितने पुराने होते हैं, उतने ही मज़बूत होते जाते हैं।","ro":"Ye pul jitne purāne hote haiṃ, utne hī mazbūt hote jāte haiṃ."},{"fr":"Pour y arriver, il faut descendre plus de trois mille marches.","tgt":"वहाँ तक पहुँचने के लिए तीन हज़ार से ज़्यादा सीढ़ियाँ उतरनी पड़ती हैं।","ro":"Vahāṃ tak pahuṃchne ke lie tīn hazār se zyādā sīṛhiyāṃ utarnī paṛtī haiṃ."},{"fr":"Le pont à deux étages est le plus célèbre.","tgt":"दो मंज़िला पुल सबसे मशहूर है।","ro":"Do manzilā pul sabse mashhūr hai."},{"fr":"On traverse lentement, en se tenant aux racines.","tgt":"हम जड़ों को पकड़कर धीरे से पुल पार करते हैं।","ro":"Ham jaṛoṃ ko pakaṛkar dhīre se pul pār karte haiṃ."},{"fr":"Sous nos pieds, une rivière turquoise coule entre les rochers.","tgt":"हमारे पैरों के नीचे फ़िरोज़ी रंग की नदी चट्टानों के बीच बहती है।","ro":"Hamāre pairoṃ ke nīche firozī rang kī nadī chaṭṭānoṃ ke bīch bahtī hai."},{"fr":"Beaucoup de visiteurs se baignent dans les bassins naturels.","tgt":"बहुत से सैलानी प्राकृतिक कुंडों में नहाते हैं।","ro":"Bahut se sailānī prākritik kunḍoṃ meṃ nahāte haiṃ."},{"fr":"Ces ponts prouvent qu'on peut construire avec la nature, pas contre elle.","tgt":"ये पुल दिखाते हैं कि प्रकृति के ख़िलाफ़ नहीं, उसके साथ मिलकर भी बनाया जा सकता है।","ro":"Ye pul dikhāte haiṃ ki prakriti ke khilāf nahīṃ, uske sāth milkar bhī banāyā jā saktā hai."}]},{"title":"Randonnée sous la pluie au Meghalaya","phrases":[{"fr":"Cette région est l'une des plus pluvieuses de la planète.","tgt":"ये इलाक़ा धरती की सबसे ज़्यादा बारिश वाली जगहों में से एक है।","ro":"Ye ilāqā dhartī kī sabse zyādā bārish vālī jagahoṃ meṃ se ek hai."},{"fr":"Il a plu sans arrêt pendant toute la randonnée.","tgt":"पूरी पैदल यात्रा के दौरान लगातार बारिश होती रही।","ro":"Pūrī paidal yātrā ke daurān lagātār bārish hotī rahī."},{"fr":"Malgré nos imperméables, nous étions trempés de la tête aux pieds.","tgt":"रेनकोट के बावजूद हम सिर से पैर तक भीग गए थे।","ro":"Renkoṭ ke bāvjūd ham sir se pair tak bhīg gae the."},{"fr":"Les nuages montaient de la vallée comme de la fumée.","tgt":"बादल घाटी से धुएँ की तरह ऊपर उठ रहे थे।","ro":"Bādal ghāṭī se dhueṃ kī tarah ūpar uṭh rahe the."},{"fr":"On voyait des cascades partout sur les falaises.","tgt":"चट्टानों पर हर तरफ़ झरने दिखाई दे रहे थे।","ro":"Chaṭṭānoṃ par har taraf jharne dikhāī de rahe the."},{"fr":"Le sentier était glissant, alors on avançait prudemment.","tgt":"पगडंडी फिसलन भरी थी, इसलिए हम सँभलकर चल रहे थे।","ro":"Pagḍanḍī fisalan bharī thī, islie ham saṃbhalkar chal rahe the."},{"fr":"Une famille nous a offert du thé dans sa maison en bois.","tgt":"एक परिवार ने अपने लकड़ी के घर में हमें चाय पिलाई।","ro":"Ek parivār ne apne lakṛī ke ghar meṃ hameṃ chāy pilāī."},{"fr":"Nous nous sommes séchés près du feu pendant une heure.","tgt":"हमने एक घंटे तक आग के पास बैठकर ख़ुद को सुखाया।","ro":"Hamne ek ghanṭe tak āg ke pās baiṭhkar khud ko sukhāyā."},{"fr":"Ici, on dit que la pluie fait partie de la famille.","tgt":"यहाँ कहा जाता है कि बारिश भी परिवार का हिस्सा है।","ro":"Yahāṃ kahā jātā hai ki bārish bhī parivār kā hissā hai."},{"fr":"Je n'avais jamais vu une nature aussi généreuse.","tgt":"मैंने इतनी भरपूर प्रकृति पहले कभी नहीं देखी थी।","ro":"Maiṃne itnī bharpūr prakriti pahle kabhī nahīṃ dekhī thī."}]},{"title":"Un guide passionné","phrases":[{"fr":"Notre guide connaît chaque sentier de la forêt.","tgt":"हमारा गाइड जंगल की हर पगडंडी को जानता है।","ro":"Hamārā gāiḍ jangal kī har pagḍanḍī ko jāntā hai."},{"fr":"Il a appris ce métier avec son grand-père.","tgt":"उसने ये काम अपने दादाजी से सीखा।","ro":"Usne ye kām apne dādājī se sīkhā."},{"fr":"Il reconnaît les oiseaux rien qu'à leur chant.","tgt":"वो पक्षियों को सिर्फ़ उनकी आवाज़ से पहचान लेता है।","ro":"Vo pakshiyoṃ ko sirf unkī āvāz se pahchān letā hai."},{"fr":"Grâce à lui, nous remarquons des choses qu'on ne verrait jamais seuls.","tgt":"उसकी वजह से हमें वो चीज़ें दिखती हैं जो वरना नज़र नहीं आतीं।","ro":"Uskī vajah se hameṃ vo chīzeṃ dikhtī haiṃ jo varnā nazar nahīṃ ātīṃ."},{"fr":"Il nous a appris à marcher sans faire de bruit.","tgt":"उसने हमें बिना आवाज़ किए चलना सिखाया।","ro":"Usne hameṃ binā āvāz kie chalnā sikhāyā."},{"fr":"Il gagne sa vie en partageant sa passion.","tgt":"वो अपने शौक़ को बाँटकर अपनी रोज़ी-रोटी कमाता है।","ro":"Vo apne shauq ko bāṃṭkar apnī rozī-roṭī kamātā hai."},{"fr":"Choisir un guide du coin aide directement le village.","tgt":"यहीं के गाइड को चुनने से सीधे गाँव की मदद होती है।","ro":"Yahīṃ ke gāiḍ ko chunne se sīdhe gāṃv kī madad hotī hai."},{"fr":"Il nous a raconté des contes de sa région.","tgt":"उसने हमें अपने इलाक़े की लोककथाएँ सुनाईं।","ro":"Usne hameṃ apne ilāqe kī lokkathāeṃ sunāīṃ."},{"fr":"En l'écoutant, chaque arbre devenait passionnant.","tgt":"उसकी बातें सुनकर हर पेड़ दिलचस्प लगने लगता था।","ro":"Uskī bāteṃ sunkar har peṛ dilchasp lagne lagtā thā."},{"fr":"À la fin, nous lui avons laissé un bon pourboire.","tgt":"आख़िर में हमने उसे अच्छी-ख़ासी बख़्शीश दी।","ro":"Ākhir meṃ hamne use achchhī-khāsī bakhshīsh dī."}]},{"title":"Le ferry vers les îles Andaman","phrases":[{"fr":"Le ferry pour l'île voisine part à six heures du matin.","tgt":"पास वाले द्वीप के लिए फ़ेरी सुबह छह बजे निकलती है।","ro":"Pās vāle dvīp ke lie ferī subah chhah baje nikaltī hai."},{"fr":"Il faut réserver ses billets plusieurs jours à l'avance.","tgt":"टिकट कई दिन पहले से बुक करने पड़ते हैं।","ro":"Ṭikaṭ kaī din pahle se buk karne paṛte haiṃ."},{"fr":"Sur le quai, la foule attend patiemment l'embarquement.","tgt":"घाट पर भीड़ धीरज से जहाज़ पर चढ़ने का इंतज़ार कर रही है।","ro":"Ghāṭ par bhīṛ dhīraj se jahāz par chaṛhne kā intazār kar rahī hai."},{"fr":"Les bagages sont rangés à l'avant du bateau.","tgt":"सामान जहाज़ के आगे वाले हिस्से में रखा जाता है।","ro":"Sāmān jahāz ke āge vāle hisse meṃ rakhā jātā hai."},{"fr":"La mer était si calme qu'on aurait dit un miroir.","tgt":"समंदर इतना शांत था कि शीशे जैसा लग रहा था।","ro":"Samandar itnā shānt thā ki shīshe jaisā lag rahā thā."},{"fr":"Des poissons volants bondissaient à la surface de l'eau.","tgt":"पानी की सतह पर उड़ने वाली मछलियाँ छलाँग लगा रही थीं।","ro":"Pānī kī satah par uṛne vālī machhliyāṃ chhalāṃg lagā rahī thīṃ."},{"fr":"Certains passagers ont commencé à avoir le mal de mer.","tgt":"कुछ यात्रियों का जी मिचलाने लगा।","ro":"Kuchh yātriyoṃ kā jī michlāne lagā."},{"fr":"La traversée dure un peu moins de deux heures.","tgt":"ये सफ़र दो घंटे से थोड़ा कम का है।","ro":"Ye safar do ghanṭe se thoṛā kam kā hai."},{"fr":"Au loin, on apercevait déjà des plages de sable blanc.","tgt":"दूर से ही सफ़ेद रेत वाले समुद्र-तट दिखने लगे थे।","ro":"Dūr se hī safed ret vāle samudra-taṭ dikhne lage the."},{"fr":"L'eau scintillait dans toutes les nuances de bleu.","tgt":"पानी नीले रंग के हर रूप में चमक रहा था।","ro":"Pānī nīle rang ke har rūp meṃ chamak rahā thā."}]},{"title":"Ma première plongée","phrases":[{"fr":"Normalement, l'eau devrait être chaude à cette saison.","tgt":"इस मौसम में पानी गर्म होना चाहिए।","ro":"Is mausam meṃ pānī garm honā chāhie."},{"fr":"Le moniteur devrait arriver d'ici dix minutes.","tgt":"प्रशिक्षक को दस मिनट में यहाँ पहुँच जाना चाहिए।","ro":"Prashikshak ko das minaṭ meṃ yahāṃ pahuṃch jānā chāhie."},{"fr":"On m'a appris à respirer calmement sous l'eau.","tgt":"मुझे पानी के नीचे आराम से साँस लेना सिखाया गया।","ro":"Mujhe pānī ke nīche ārām se sāṃs lenā sikhāyā gayā."},{"fr":"À cette profondeur, il ne devrait pas y avoir de courant.","tgt":"इस गहराई पर धारा नहीं होनी चाहिए।","ro":"Is gahrāī par dhārā nahīṃ honī chāhie."},{"fr":"Si tout va bien, l'eau devrait être très claire.","tgt":"अगर सब ठीक रहा, तो पानी बहुत साफ़ होना चाहिए।","ro":"Agar sab ṭhīk rahā, to pānī bahut sāf honā chāhie."},{"fr":"J'ai un peu de mal à rester calme sous l'eau.","tgt":"पानी के नीचे शांत रहना मुझे थोड़ा मुश्किल लग रहा है।","ro":"Pānī ke nīche shānt rahnā mujhe thoṛā mushkil lag rahā hai."},{"fr":"Ne touchez jamais le corail, il est très fragile.","tgt":"मूँगे को कभी हाथ मत लगाइए, वो बहुत नाज़ुक होता है।","ro":"Mūṃge ko kabhī hāth mat lagāie, vo bahut nāzuk hotā hai."},{"fr":"Le bateau aurait déjà dû revenir, non ?","tgt":"नाव को अब तक वापस आ जाना चाहिए था, है न?","ro":"Nāv ko ab tak vāpas ā jānā chāhie thā, hai na?"},{"fr":"Nous sommes restés quarante minutes sous l'eau.","tgt":"हम चालीस मिनट तक पानी के नीचे रहे।","ro":"Ham chālīs minaṭ tak pānī ke nīche rahe."},{"fr":"Une telle expérience devrait toujours se faire avec un moniteur.","tgt":"ऐसा अनुभव हमेशा किसी प्रशिक्षक के साथ होना चाहिए।","ro":"Aisā anubhav hameshā kisī prashikshak ke sāth honā chāhie."}],"tip":{"title":"« Honā chāhie » : normalement, ça devrait","example":"Normalement, l'eau devrait être chaude à cette saison. — इस मौसम में पानी गर्म <b>होना चाहिए</b>।","body":"« Honā chāhie » assemble « être » et « il faut », mais à l'oral il sert surtout à dire ce qui devrait normalement se passer. « Is mausam meṃ pānī garm honā chāhie », mot à mot cette saison dans eau chaude être il-faut, signifie : normalement, l'eau devrait être chaude. Le petit mot « honā » s'accorde avec ce dont on parle : on dit « dhārā nahīṃ honī chāhie », il ne devrait pas y avoir de courant, parce que le courant est féminin en hindi. Pour un regret ou un étonnement, on ajoute « thā » à la fin : « nāv ko ab tak vāpas ā jānā chāhie thā », le bateau aurait déjà dû revenir. Astuce : dès que vous pensez « normalement » ou « ça devrait » en français, finissez votre phrase par « chāhie ».","exampleRo":"Is mausam meṃ pānī garm honā chāhie.","lit":"cette · saison · [dans] · eau · chaude · être · il-faut","say":{"Honā chāhie":"होना चाहिए","Is mausam meṃ pānī garm honā chāhie":"इस मौसम में पानी गर्म होना चाहिए","honā":"होना","dhārā nahīṃ honī chāhie":"धारा नहीं होनी चाहिए","thā":"था","nāv ko ab tak vāpas ā jānā chāhie thā":"नाव को अब तक वापस आ जाना चाहिए था","chāhie":"चाहिए"}}},{"title":"Le monde sous la mer","phrases":[{"fr":"Le récif de corail grouillait de vie.","tgt":"मूँगे की चट्टान ज़िंदगी से भरी हुई थी।","ro":"Mūṃge kī chaṭṭān zindagī se bharī huī thī."},{"fr":"Des poissons de toutes les couleurs nageaient autour de nous.","tgt":"हर रंग की मछलियाँ हमारे चारों ओर तैर रही थीं।","ro":"Har rang kī machhliyāṃ hamāre chāroṃ or tair rahī thīṃ."},{"fr":"Une tortue de mer nageait tranquillement à côté de moi.","tgt":"एक समुद्री कछुआ आराम से मेरे बगल में तैर रहा था।","ro":"Ek samudrī kachhuā ārām se mere bagal meṃ tair rahā thā."},{"fr":"Un petit poisson orange se cachait dans les algues.","tgt":"एक छोटी नारंगी मछली समुद्री घास में छिपी हुई थी।","ro":"Ek chhoṭī nārangī machhlī samudrī ghās meṃ chhipī huī thī."},{"fr":"Sous l'eau, on n'entend que sa propre respiration.","tgt":"पानी के नीचे बस अपनी साँसों की आवाज़ सुनाई देती है।","ro":"Pānī ke nīche bas apnī sāṃsoṃ kī āvāz sunāī detī hai."},{"fr":"Quand la mer devient trop chaude, le corail blanchit.","tgt":"जब समंदर बहुत गर्म हो जाता है, तो मूँगा सफ़ेद पड़ जाता है।","ro":"Jab samandar bahut garm ho jātā hai, to mūṃgā safed paṛ jātā hai."},{"fr":"Une partie du récif est déjà abîmée.","tgt":"चट्टान का कुछ हिस्सा पहले ही ख़राब हो चुका है।","ro":"Chaṭṭān kā kuchh hissā pahle hī kharāb ho chukā hai."},{"fr":"Certaines crèmes solaires abîment le corail.","tgt":"कुछ सनस्क्रीन मूँगे को नुक़सान पहुँचाती हैं।","ro":"Kuchh sanskrīn mūṃge ko nuqsān pahuṃchātī haiṃ."},{"fr":"Remonter trop vite peut être dangereux.","tgt":"बहुत तेज़ी से ऊपर आना ख़तरनाक हो सकता है।","ro":"Bahut tezī se ūpar ānā khatarnāk ho saktā hai."},{"fr":"À peine sorti de l'eau, je voulais déjà replonger.","tgt":"पानी से निकलते ही मैं दोबारा गोता लगाना चाहता था।","ro":"Pānī se nikalte hī maiṃ dobārā gotā lagānā chāhtā thā."}]},{"title":"Une tempête sur les îles","phrases":[{"fr":"Les services météo annoncent une tempête pour demain.","tgt":"मौसम विभाग ने कल के लिए तूफ़ान की चेतावनी दी है।","ro":"Mausam vibhāg ne kal ke lie tūfān kī chetāvnī dī hai."},{"fr":"Tous les ferries sont annulés jusqu'à nouvel ordre.","tgt":"अगले आदेश तक सारी फ़ेरियाँ रद्द कर दी गई हैं।","ro":"Agle ādesh tak sārī feriyāṃ radd kar dī gaī haiṃ."},{"fr":"Un vent violent a soufflé toute la nuit.","tgt":"रात भर तेज़ हवा चलती रही।","ro":"Rāt bhar tez havā chaltī rahī."},{"fr":"Les vagues s'écrasaient violemment contre la jetée.","tgt":"लहरें ज़ोर-ज़ोर से घाट से टकरा रही थीं।","ro":"Lahreṃ zor-zor se ghāṭ se ṭakrā rahī thīṃ."},{"fr":"L'électricité a été coupée pendant plusieurs heures.","tgt":"कई घंटों तक बिजली गुल रही।","ro":"Kaī ghanṭoṃ tak bijlī gul rahī."},{"fr":"Nous avons joué aux cartes à la lueur des bougies.","tgt":"हमने मोमबत्ती की रोशनी में ताश खेला।","ro":"Hamne mombattī kī roshnī meṃ tāsh khelā."},{"fr":"Le patron de la pension nous a assuré que tout irait bien.","tgt":"गेस्टहाउस के मालिक ने हमें भरोसा दिलाया कि सब ठीक होगा।","ro":"Gesṭhāus ke mālik ne hameṃ bharosā dilāyā ki sab ṭhīk hogā."},{"fr":"Les habitants des îles ont l'habitude de ces tempêtes.","tgt":"यहाँ के लोग ऐसे तूफ़ानों के आदी हैं।","ro":"Yahāṃ ke log aise tūfānoṃ ke ādī haiṃ."},{"fr":"Le lendemain matin, le ciel était parfaitement bleu.","tgt":"अगली सुबह आसमान बिल्कुल नीला था।","ro":"Aglī subah āsmān bilkul nīlā thā."},{"fr":"Nous avons dû partir avec deux jours de retard.","tgt":"हमें दो दिन देर से निकलना पड़ा।","ro":"Hameṃ do din der se nikalnā paṛā."}]},{"title":"Pondichéry et son quartier français","phrases":[{"fr":"Les ruelles du quartier français de Pondichéry sont jaunes et paisibles.","tgt":"पांडिचेरी के फ़्रांसीसी इलाक़े की गलियाँ पीली और शांत हैं।","ro":"Pānḍicherī ke frānsīsī ilāqe kī galiyāṃ pīlī aur shānt haiṃ."},{"fr":"Les noms des rues sont écrits en français.","tgt":"सड़कों के नाम फ़्रांसीसी में लिखे हुए हैं।","ro":"Saṛkoṃ ke nām frānsīsī meṃ likhe hue haiṃ."},{"fr":"Je me suis presque senti chez moi.","tgt":"मुझे लगभग अपने घर जैसा महसूस हुआ।","ro":"Mujhe lagbhag apne ghar jaisā mahsūs huā."},{"fr":"Des bougainvilliers recouvrent les murs des vieilles maisons.","tgt":"पुराने घरों की दीवारों पर बोगनविलिया की बेलें छाई हुई हैं।","ro":"Purāne gharoṃ kī dīvāroṃ par boganviliyā kī beleṃ chhāī huī haiṃ."},{"fr":"Le soir, les gens se promènent au bord de la mer.","tgt":"शाम को लोग समंदर के किनारे टहलते हैं।","ro":"Shām ko log samandar ke kināre ṭahalte haiṃ."},{"fr":"Le soir, la route du front de mer est interdite aux voitures.","tgt":"शाम को समुद्र-तट वाली सड़क पर गाड़ियाँ नहीं चलतीं।","ro":"Shām ko samudra-taṭ vālī saṛak par gāṛiyāṃ nahīṃ chaltīṃ."},{"fr":"Un vieux monsieur m'a parlé en français, j'en suis resté stupéfait.","tgt":"एक बुज़ुर्ग ने मुझसे फ़्रांसीसी में बात की, मैं तो हैरान रह गया।","ro":"Ek buzurg ne mujhse frānsīsī meṃ bāt kī, maiṃ to hairān rah gayā."},{"fr":"On trouve ici d'excellentes boulangeries.","tgt":"यहाँ बहुत बढ़िया बेकरियाँ मिलती हैं।","ro":"Yahāṃ bahut baṛhiyā bekariyāṃ miltī haiṃ."},{"fr":"De l'autre côté du canal, la ville est beaucoup plus animée.","tgt":"नहर के उस पार शहर कहीं ज़्यादा चहल-पहल वाला है।","ro":"Nahar ke us pār shahar kahīṃ zyādā chahal-pahal vālā hai."},{"fr":"Ce mélange de cultures rend la ville unique.","tgt":"संस्कृतियों का ये मेल इस शहर को अनोखा बनाता है।","ro":"Sanskritiyoṃ kā ye mel is shahar ko anokhā banātā hai."}]},{"title":"En scooter autour de Pondichéry","phrases":[{"fr":"Ce matin, nous avons loué un scooter pour explorer les environs.","tgt":"आज सुबह हमने आसपास घूमने के लिए एक स्कूटर किराए पर लिया।","ro":"Āj subah hamne āspās ghūmne ke lie ek skūṭar kirāe par liyā."},{"fr":"Il faut toujours porter un casque, même pour un petit trajet.","tgt":"छोटे सफ़र के लिए भी हमेशा हेलमेट पहनना चाहिए।","ro":"Chhoṭe safar ke lie bhī hameshā helmeṭ pahannā chāhie."},{"fr":"En ville, la circulation demande beaucoup d'attention.","tgt":"शहर के ट्रैफ़िक में बहुत ध्यान रखना पड़ता है।","ro":"Shahar ke ṭraifik meṃ bahut dhyān rakhnā paṛtā hai."},{"fr":"Hors de la ville, les routes longent des rizières.","tgt":"शहर के बाहर सड़कें धान के खेतों के साथ-साथ चलती हैं।","ro":"Shahar ke bāhar saṛkeṃ dhān ke khetoṃ ke sāth-sāth chaltī haiṃ."},{"fr":"Nous nous sommes arrêtés sur une plage presque déserte.","tgt":"हम एक लगभग सुनसान समुद्र-तट पर रुके।","ro":"Ham ek lagbhag sunsān samudra-taṭ par ruke."},{"fr":"Des pêcheurs réparaient leurs filets à l'ombre.","tgt":"मछुआरे छाँव में अपने जाल ठीक कर रहे थे।","ro":"Machhuāre chhāṃv meṃ apne jāl ṭhīk kar rahe the."},{"fr":"L'un d'eux nous a montré les poissons pêchés le matin même.","tgt":"उनमें से एक ने हमें सुबह पकड़ी हुई मछलियाँ दिखाईं।","ro":"Unmeṃ se ek ne hameṃ subah pakṛī huī machhliyāṃ dikhāīṃ."},{"fr":"Nous avons mangé du poisson grillé dans un petit restaurant de bord de route.","tgt":"हमने एक छोटे-से ढाबे में भुनी हुई मछली खाई।","ro":"Hamne ek chhoṭe-se ḍhābe meṃ bhunī huī machhlī khāī."},{"fr":"Sur le chemin du retour, nous nous sommes un peu égarés.","tgt":"लौटते हुए हम थोड़ा रास्ता भटक गए।","ro":"Lauṭte hue ham thoṛā rāstā bhaṭak gae."},{"fr":"Un passant nous a très gentiment indiqué la bonne route.","tgt":"एक राहगीर ने बड़े प्यार से हमें सही रास्ता बताया।","ro":"Ek rāhgīr ne baṛe pyār se hameṃ sahī rāstā batāyā."}]},{"title":"Voyager de façon responsable","phrases":[{"fr":"Voyager de façon responsable commence par de petits gestes.","tgt":"ज़िम्मेदारी से सफ़र करना छोटी-छोटी बातों से शुरू होता है।","ro":"Zimmedārī se safar karnā chhoṭī-chhoṭī bātoṃ se shurū hotā hai."},{"fr":"Nous gardons toujours notre propre bouteille d'eau.","tgt":"हम हमेशा अपनी पानी की बोतल साथ रखते हैं।","ro":"Ham hameshā apnī pānī kī botal sāth rakhte haiṃ."},{"fr":"Mieux vaut refuser les sacs en plastique.","tgt":"प्लास्टिक की थैलियों को मना कर देना बेहतर है।","ro":"Plāsṭik kī thailiyoṃ ko manā kar denā behtar hai."},{"fr":"Nous préférons loger chez l'habitant plutôt qu'à l'hôtel.","tgt":"हम होटल के बजाय स्थानीय परिवारों के घर रुकना पसंद करते हैं।","ro":"Ham hoṭal ke bajāy sthānīy parivāroṃ ke ghar ruknā pasand karte haiṃ."},{"fr":"Acheter directement aux artisans les aide vraiment.","tgt":"सीधे कारीगरों से ख़रीदने से उनकी सचमुच मदद होती है।","ro":"Sīdhe kārīgaroṃ se kharīdne se unkī sachmuch madad hotī hai."},{"fr":"Demandez toujours avant de photographier quelqu'un.","tgt":"किसी की तस्वीर लेने से पहले हमेशा पूछ लीजिए।","ro":"Kisī kī tasvīr lene se pahle hameshā pūchh lījie."},{"fr":"Il ne faut jamais nourrir les animaux sauvages.","tgt":"जंगली जानवरों को कभी खाना नहीं खिलाना चाहिए।","ro":"Janglī jānvaroṃ ko kabhī khānā nahīṃ khilānā chāhie."},{"fr":"Le train pollue bien moins que l'avion.","tgt":"रेलगाड़ी हवाई जहाज़ से बहुत कम प्रदूषण करती है।","ro":"Relgāṛī havāī jahāz se bahut kam pradūshaṇ kartī hai."},{"fr":"Respecter les coutumes locales fait aussi partie d'un bon voyage.","tgt":"स्थानीय रीति-रिवाज़ों का सम्मान करना भी अच्छे सफ़र का हिस्सा है।","ro":"Sthānīy rīti-rivāzoṃ kā sammān karnā bhī achchhe safar kā hissā hai."},{"fr":"Nous voulons laisser chaque endroit aussi beau qu'à notre arrivée.","tgt":"हम हर जगह को उतना ही सुंदर छोड़ना चाहते हैं जितना वो हमारे आने पर थी।","ro":"Ham har jagah ko utnā hī sundar chhoṛnā chāhte haiṃ jitnā vo hamāre āne par thī."}]},{"title":"Petit à petit, le voyage nous change","phrases":[{"fr":"Petit à petit, je commence à comprendre les gens d'ici.","tgt":"धीरे-धीरे मैं यहाँ के लोगों को समझने लगा हूँ।","ro":"Dhīre-dhīre maiṃ yahāṃ ke logoṃ ko samajhne lagā hūṃ."},{"fr":"Peu à peu, le hindi devient plus facile pour moi.","tgt":"धीरे-धीरे हिंदी मेरे लिए आसान होती जा रही है।","ro":"Dhīre-dhīre hindī mere lie āsān hotī jā rahī hai."},{"fr":"Chaque jour, ce pays me paraît encore plus fascinant.","tgt":"हर दिन ये देश मुझे और भी दिलचस्प लगता है।","ro":"Har din ye desh mujhe aur bhī dilchasp lagtā hai."},{"fr":"Le bateau s'éloignait lentement du rivage.","tgt":"नाव धीरे-धीरे किनारे से दूर जा रही थी।","ro":"Nāv dhīre-dhīre kināre se dūr jā rahī thī."},{"fr":"Après la pluie, la forêt était encore plus verte.","tgt":"बारिश के बाद जंगल और भी हरा-भरा था।","ro":"Bārish ke bād jangal aur bhī harā-bharā thā."},{"fr":"Je parle de plus en plus avec des inconnus.","tgt":"मैं अनजान लोगों से और भी ज़्यादा बात करने लगा हूँ।","ro":"Maiṃ anjān logoṃ se aur bhī zyādā bāt karne lagā hūṃ."},{"fr":"Mes peurs ont disparu peu à peu.","tgt":"मेरा डर धीरे-धीरे ग़ायब हो गया।","ro":"Merā ḍar dhīre-dhīre gāyab ho gayā."},{"fr":"Le soir, la mer devient encore plus belle.","tgt":"शाम को समंदर और भी ख़ूबसूरत हो जाता है।","ro":"Shām ko samandar aur bhī khūbsūrat ho jātā hai."},{"fr":"Ne vous pressez pas, avancez petit à petit.","tgt":"जल्दी मत कीजिए, धीरे-धीरे आगे बढ़िए।","ro":"Jaldī mat kījie, dhīre-dhīre āge baṛhie."},{"fr":"L'année prochaine, j'ai envie d'aller encore plus loin.","tgt":"अगले साल मैं और भी दूर जाना चाहता हूँ।","ro":"Agle sāl maiṃ aur bhī dūr jānā chāhtā hūṃ."}],"tip":{"title":"« Dhīre-dhīre » et « aur bhī » : petit à petit, de plus en plus","example":"Petit à petit, je commence à comprendre les gens d'ici. — <b>धीरे-धीरे</b> मैं यहाँ के लोगों को समझने लगा हूँ।","body":"« Dhīre » veut dire lentement ; en le répétant, « dhīre-dhīre », on obtient petit à petit, un peu comme le français dit « tout doucement ». On l'associe souvent à un verbe qui s'installe dans la durée : « dhīre-dhīre maiṃ yahāṃ ke logoṃ ko samajhne lagā hūṃ », mot à mot petit-à-petit je ici de gens à comprendre commencé suis. « Aur bhī » signifie encore plus : « aur bhī khūbsūrat », encore plus beau, « aur bhī dūr », encore plus loin. Pour dire de plus en plus, on ajoute « hotā jā rahā hai », qui décrit un changement en cours : « mere vākya aur bhī lambe hote jā rahe haiṃ », mes phrases deviennent de plus en plus longues. Astuce : dites « dhīre-dhīre » lentement, en allongeant le « ī », et « aur bhī » avec un peu d'élan, comme si vous montiez une marche.","exampleRo":"Dhīre-dhīre maiṃ yahāṃ ke logoṃ ko samajhne lagā hūṃ.","lit":"petit-à-petit · je · ici · [de] · gens · [à] · comprendre · commencé · suis","say":{"Dhīre-dhīre":"धीरे-धीरे","aur bhī":"और भी","Dhīre":"धीरे","dhīre-dhīre":"धीरे-धीरे","dhīre-dhīre maiṃ yahāṃ ke logoṃ ko samajhne lagā hūṃ":"धीरे-धीरे मैं यहाँ के लोगों को समझने लगा हूँ","Aur bhī":"और भी","aur bhī khūbsūrat":"और भी ख़ूबसूरत","aur bhī dūr":"और भी दूर","hotā jā rahā hai":"होता जा रहा है","mere vākya aur bhī lambe hote jā rahe haiṃ":"मेरे वाक्य और भी लंबे होते जा रहे हैं"}}},{"title":"Ce que le voyage nous apprend","phrases":[{"fr":"Les plus beaux souvenirs naissent souvent des imprévus.","tgt":"सबसे अच्छी यादें अक्सर अचानक हुई घटनाओं से बनती हैं।","ro":"Sabse achchhī yādeṃ aksar achānak huī ghaṭnāoṃ se bantī haiṃ."},{"fr":"Notre bus est tombé en panne, et ça nous a permis de découvrir un joli village.","tgt":"हमारी बस ख़राब हो गई और इसी बहाने हमने एक प्यारा-सा गाँव देख लिया।","ro":"Hamārī bas kharāb ho gaī aur isī bahāne hamne ek pyārā-sā gāṃv dekh liyā."},{"fr":"Ce voyage m'a appris la patience.","tgt":"इस सफ़र ने मुझे सब्र करना सिखा दिया।","ro":"Is safar ne mujhe sabr karnā sikhā diyā."},{"fr":"On n'a pas besoin de tout organiser à l'avance.","tgt":"हर चीज़ पहले से तय करने की ज़रूरत नहीं होती।","ro":"Har chīz pahle se tay karne kī zarūrat nahīṃ hotī."},{"fr":"Les gens nous ont aidés sans rien attendre en retour.","tgt":"लोगों ने बदले में कुछ चाहे बिना हमारी मदद की।","ro":"Logoṃ ne badle meṃ kuchh chāhe binā hamārī madad kī."},{"fr":"J'ai rempli mon carnet de souvenirs et de dessins.","tgt":"मैंने अपनी डायरी यादों और चित्रों से भर दी है।","ro":"Maiṃne apnī ḍāyrī yādoṃ aur chitroṃ se bhar dī hai."},{"fr":"Chaque rencontre m'a appris quelque chose de nouveau.","tgt":"हर मुलाक़ात ने मुझे कुछ नया सिखाया।","ro":"Har mulāqāt ne mujhe kuchh nayā sikhāyā."},{"fr":"Désormais, je regarde aussi mon propre pays avec d'autres yeux.","tgt":"अब मैं अपने देश को भी नई नज़र से देखता हूँ।","ro":"Ab maiṃ apne desh ko bhī naī nazar se dekhtā hūṃ."},{"fr":"C'est difficile de résumer ce voyage en quelques mots.","tgt":"इस सफ़र को कुछ शब्दों में बयान करना मुश्किल है।","ro":"Is safar ko kuchh shabdoṃ meṃ bayān karnā mushkil hai."},{"fr":"Une partie de moi est restée là-bas.","tgt":"मेरा एक हिस्सा वहीं रह गया है।","ro":"Merā ek hissā vahīṃ rah gayā hai."}]},{"title":"Fin du module : un bilan de voyage","phrases":[{"fr":"Dans ce module, nous sommes allés du désert jusqu'à la mer.","tgt":"इस खंड में हम रेगिस्तान से समंदर तक घूमे।","ro":"Is khanḍ meṃ ham registān se samandar tak ghūme."},{"fr":"Je peux maintenant parler facilement de ce que je vois.","tgt":"अब मैं जो देखता हूँ, उसके बारे में आराम से बोल सकता हूँ।","ro":"Ab maiṃ jo dekhtā hūṃ, uske bāre meṃ ārām se bol saktā hūṃ."},{"fr":"Je sais expliquer pourquoi je vais quelque part.","tgt":"अब मैं बता सकता हूँ कि मैं कहीं किस लिए जा रहा हूँ।","ro":"Ab maiṃ batā saktā hūṃ ki maiṃ kahīṃ kis lie jā rahā hūṃ."},{"fr":"Je peux parler d'une tempête, d'une plongée ou d'un guide.","tgt":"मैं तूफ़ान, गोताख़ोरी या किसी गाइड के बारे में बात कर सकता हूँ।","ro":"Maiṃ tūfān, gotākhorī yā kisī gāiḍ ke bāre meṃ bāt kar saktā hūṃ."},{"fr":"Le hindi ne me semble plus une langue étrangère.","tgt":"हिंदी मुझे अब पराई नहीं लगती।","ro":"Hindī mujhe ab parāī nahīṃ lagtī."},{"fr":"Mes phrases deviennent de plus en plus longues.","tgt":"मेरे वाक्य और भी लंबे होते जा रहे हैं।","ro":"Mere vākya aur bhī lambe hote jā rahe haiṃ."},{"fr":"Bravo pour tout le chemin parcouru.","tgt":"इतना लंबा रास्ता तय करने के लिए बधाई हो।","ro":"Itnā lambā rāstā tay karne ke lie badhāī ho."},{"fr":"Prenons une petite pause avant la suite.","tgt":"आगे बढ़ने से पहले थोड़ा आराम कर लेते हैं।","ro":"Āge baṛhne se pahle thoṛā ārām kar lete haiṃ."},{"fr":"Le prochain module sera consacré à la conversation.","tgt":"अगला खंड बातचीत के बारे में होगा।","ro":"Aglā khanḍ bātchīt ke bāre meṃ hogā."},{"fr":"À très vite, et bon voyage !","tgt":"जल्दी मिलते हैं, और आपका सफ़र शुभ हो।","ro":"Jaldī milte haiṃ, aur āpkā safar shubh ho."}]}]},{"id":3,"name":"Conversation sociale","desc":"Des conversations profondes : opinions, débats, émotions.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Le travail et l'équilibre de vie","phrases":[{"fr":"Je passe presque dix heures par jour au bureau.","tgt":"मैं रोज़ लगभग दस घंटे ऑफ़िस में बिताता हूँ।","ro":"Maiṃ roz lagbhag das ghanṭe ofis meṃ bitātā hūṃ."},{"fr":"Après le travail, je n'ai plus l'énergie de faire quoi que ce soit.","tgt":"काम के बाद मुझमें कुछ भी करने की एनर्जी नहीं बचती।","ro":"Kām ke bād mujhmeṃ kuchh bhī karne kī enarjī nahīṃ bachtī."},{"fr":"Mon chef m'envoie des messages même le dimanche.","tgt":"मेरे बॉस मुझे रविवार को भी मैसेज भेजते हैं।","ro":"Mere bos mujhe ravivār ko bhī maisej bhejte haiṃ."},{"fr":"Les réunions en ligne ont rendu les journées encore plus longues.","tgt":"ऑनलाइन मीटिंगों ने दिन और भी लंबे कर दिए हैं।","ro":"Onlāin mīṭingoṃ ne din aur bhī lambe kar die haiṃ."},{"fr":"Je ferme mon ordinateur portable à sept heures pile.","tgt":"मैं ठीक सात बजे अपना लैपटॉप बंद कर देता हूँ।","ro":"Maiṃ ṭhīk sāt baje apnā laipṭop band kar detā hūṃ."},{"fr":"Ma santé compte plus que n'importe quelle promotion.","tgt":"मेरी सेहत किसी भी प्रमोशन से ज़्यादा ज़रूरी है।","ro":"Merī sehat kisī bhī pramoshan se zyādā zarūrī hai."},{"fr":"Le week-end, j'éteins complètement mon téléphone.","tgt":"वीकेंड पर मैं अपना फ़ोन पूरी तरह बंद कर देता हूँ।","ro":"Vīkenḍ par maiṃ apnā fon pūrī tarah band kar detā hūṃ."},{"fr":"Beaucoup de jeunes en Inde veulent désormais un meilleur équilibre entre travail et vie.","tgt":"भारत में बहुत से युवा अब बेहतर वर्क-लाइफ़ बैलेंस चाहते हैं।","ro":"Bhārat meṃ bahut se yuvā ab behtar vark-lāif bailens chāhte haiṃ."},{"fr":"À Bengaluru, il faut parfois deux heures pour arriver au bureau.","tgt":"बेंगलुरु में ऑफ़िस पहुँचने में दो घंटे लग सकते हैं।","ro":"Bengaluru meṃ ofis pahuṃchne meṃ do ghanṭe lag sakte haiṃ."},{"fr":"Au fond, on travaille pour vivre, on ne vit pas pour travailler.","tgt":"आख़िर हम जीने के लिए काम करते हैं, काम के लिए नहीं जीते।","ro":"Ākhir ham jīne ke lie kām karte haiṃ, kām ke lie nahīṃ jīte."}],"tip":{"title":"Le hindi et ses mots venus d'ailleurs","example":"Je ferme mon ordinateur portable à sept heures pile. — मैं ठीक सात बजे अपना <b>लैपटॉप</b> बंद कर देता हूँ।","body":"Le hindi parlé en ville est plein de mots venus d'ailleurs, et c'est une bonne nouvelle pour vous : vous en connaissez déjà beaucoup. On dit « ofis » pour le bureau, « fon » pour le téléphone, et aussi « laipṭop », « mīṭing » ou « bos ». Ces mots se prononcent à la manière hindie, avec le « ṭ » rétroflexe, la langue recourbée vers le palais, et surtout ils obéissent à la grammaire hindie : « ofis meṃ », au bureau, avec la postposition après le nom, ou « mīṭingoṃ ne », avec un pluriel bien hindi. Décomposons « maiṃ ṭhīk sāt baje apnā laipṭop band kar detā hūṃ » : je, pile, sept heures, mon portable, fermé, fais et laisse, suis. Le hindi a aussi adopté depuis des siècles des mots devenus tout à fait ordinaires, comme « zindagī », la vie, « dost », l'ami, ou « dukān », la boutique. Astuce : si un mot technique vous manque, tentez le mot international avec une prononciation hindie, on vous comprendra très souvent.","exampleRo":"Maiṃ ṭhīk sāt baje apnā laipṭop band kar detā hūṃ.","lit":"je · pile · sept · heures · mon · ordinateur portable · fermé · fais · [donne] · suis","say":{"ofis":"ऑफ़िस","fon":"फ़ोन","laipṭop":"लैपटॉप","mīṭing":"मीटिंग","bos":"बॉस","ofis meṃ":"ऑफ़िस में","mīṭingoṃ ne":"मीटिंगों ने","maiṃ ṭhīk sāt baje apnā laipṭop band kar detā hūṃ":"मैं ठीक सात बजे अपना लैपटॉप बंद कर देता हूँ","zindagī":"ज़िंदगी","dost":"दोस्त","dukān":"दुकान"}}},{"title":"Débattre : la ville ou le village","phrases":[{"fr":"J'ai grandi dans un petit village près de Jaipur.","tgt":"मैं जयपुर के पास एक छोटे से गाँव में बड़ा हुआ।","ro":"Maiṃ Jaipur ke pās ek chhoṭe se gāṃv meṃ baṛā huā."},{"fr":"Aujourd'hui je vis à Mumbai, et entre les deux, c'est le jour et la nuit.","tgt":"आज मैं मुंबई में रहता हूँ, और दोनों में ज़मीन-आसमान का अंतर है।","ro":"Āj maiṃ Mumbaī meṃ rahtā hūṃ, aur donoṃ meṃ zamīn-āsmān kā antar hai."},{"fr":"En ville, on trouve de tout, mais personne n'a le temps.","tgt":"शहर में सब कुछ मिलता है, पर किसी के पास समय नहीं होता।","ro":"Shahar meṃ sab kuchh miltā hai, par kisī ke pās samay nahīṃ hotā."},{"fr":"Au village, les voisins savent tout de votre vie.","tgt":"गाँव में पड़ोसी आपकी ज़िंदगी के बारे में सब कुछ जानते हैं।","ro":"Gāṃv meṃ paṛosī āpkī zindagī ke bāre meṃ sab kuchh jānte haiṃ."},{"fr":"Ceux qui partent en ville reviennent souvent pour les fêtes.","tgt":"जो लोग शहर चले जाते हैं, वे अक्सर त्योहारों पर लौट आते हैं।","ro":"Jo log shahar chale jāte haiṃ, ve aksar tyohāroṃ par lauṭ āte haiṃ."},{"fr":"Au village, l'air est plus pur, mais les hôpitaux sont loin.","tgt":"गाँव में हवा ज़्यादा साफ़ है, लेकिन अस्पताल दूर हैं।","ro":"Gāṃv meṃ havā zyādā sāf hai, lekin aspatāl dūr haiṃ."},{"fr":"Mes parents refusent de quitter leur maison et leurs champs.","tgt":"मेरे माता-पिता अपना घर और खेत छोड़ने से मना करते हैं।","ro":"Mere mātā-pitā apnā ghar aur khet chhoṛne se manā karte haiṃ."},{"fr":"Avec internet, la vie au village a beaucoup changé.","tgt":"इंटरनेट की वजह से गाँव की ज़िंदगी काफ़ी बदल गई है।","ro":"Inṭarneṭ kī vajah se gāṃv kī zindagī kāfī badal gaī hai."},{"fr":"Certains jeunes préfèrent désormais quitter la ville pour travailler au village.","tgt":"कुछ युवा अब शहर छोड़कर गाँव में ही काम करना पसंद करते हैं।","ro":"Kuchh yuvā ab shahar chhoṛkar gāṃv meṃ hī kām karnā pasand karte haiṃ."},{"fr":"Pour moi, l'idéal serait de profiter un peu des deux.","tgt":"मेरे लिए सबसे अच्छा होगा कि दोनों का थोड़ा-थोड़ा मज़ा लिया जाए।","ro":"Mere lie sabse achchhā hogā ki donoṃ kā thoṛā-thoṛā mazā liyā jāe."}]},{"title":"Les petites expressions de tous les jours","phrases":[{"fr":"Ce n'est pas grave, nous venons d'arriver nous aussi.","tgt":"कोई बात नहीं, हम भी अभी-अभी पहुँचे हैं।","ro":"Koī bāt nahīṃ, ham bhī abhī-abhī pahuṃche haiṃ."},{"fr":"Allez, on se fait livrer à manger, j'ai une faim de loup.","tgt":"चलो, खाना मँगवाते हैं, मुझे बहुत ज़ोर की भूख लगी है।","ro":"Chalo, khānā maṃgvāte haiṃ, mujhe bahut zor kī bhūkh lagī hai."},{"fr":"Ça suffit, je ne pourrai plus rien avaler.","tgt":"बस, अब मुझसे और नहीं खाया जाएगा।","ro":"Bas, ab mujhse aur nahīṃ khāyā jāegā."},{"fr":"Vous avez cassé un verre ? Ce n'est vraiment pas grave.","tgt":"आपसे गिलास टूट गया? कोई बात नहीं, सच में।","ro":"Āpse gilās ṭūṭ gayā? Koī bāt nahīṃ, sach meṃ."},{"fr":"Bon, il se fait tard, allons-y.","tgt":"चलो, देर हो गई है, अब चलते हैं।","ro":"Chalo, der ho gaī hai, ab chalte haiṃ."},{"fr":"Juste une tasse de thé, et ensuite je rentre.","tgt":"बस एक कप चाय, फिर मैं घर जाता हूँ।","ro":"Bas ek kap chāy, phir maiṃ ghar jātā hūṃ."},{"fr":"Je voulais simplement vous dire merci.","tgt":"मुझे बस आपको शुक्रिया कहना था।","ro":"Mujhe bas āpko shukriyā kahnā thā."},{"fr":"Si on ne trouve pas d'auto-rickshaw, pas de souci, on marchera.","tgt":"अगर ऑटो नहीं मिला तो कोई बात नहीं, हम पैदल चल लेंगे।","ro":"Agar oṭo nahīṃ milā to koī bāt nahīṃ, ham paidal chal leṃge."},{"fr":"Allez, ne vous inquiétez pas, tout va s'arranger.","tgt":"चलिए, चिंता मत कीजिए, सब ठीक हो जाएगा।","ro":"Chalie, chintā mat kījie, sab ṭhīk ho jāegā."},{"fr":"C'est tout pour aujourd'hui, on se voit demain.","tgt":"बस, आज के लिए इतना ही, कल मिलते हैं।","ro":"Bas, āj ke lie itnā hī, kal milte haiṃ."}],"tip":{"title":"Les expressions du quotidien : « koī bāt nahīṃ, chalo, bas »","example":"Ce n'est pas grave, nous venons d'arriver nous aussi. — <b>कोई बात नहीं</b>, हम भी अभी-अभी पहुँचे हैं।","body":"Trois petits mots suffisent à faire sonner votre hindi comme celui de la rue. « Koī bāt nahīṃ », mot à mot aucune chose non, veut dire ce n'est pas grave, pas de souci : on le dit avec un sourire quand quelqu'un s'excuse. « Chalo », qui vient du verbe « chalnā », marcher, aller, lance une action comme notre allez ou bon : « chalo, ab chalte haiṃ », bon, allons-y ; avec quelqu'un qu'on vouvoie, on dit plus poliment « chalie ». « Bas » veut dire assez, juste ou c'est tout : « bas, ab nahīṃ », ça suffit maintenant, et « bas ek kap chāy », juste une tasse de thé. Placez-les en tout début de phrase, avec une petite pause juste après, et votre interlocuteur sentira tout de suite le naturel. Astuce : voyez « chalo » comme un bouton marche, « bas » comme un bouton stop, et « koī bāt nahīṃ » comme une main posée sur l'épaule.","exampleRo":"Koī bāt nahīṃ, ham bhī abhī-abhī pahuṃche haiṃ.","lit":"aucune · chose · non, · nous · aussi · tout juste · arrivés · sommes","say":{"Koī bāt nahīṃ":"कोई बात नहीं","Chalo":"चलो","chalnā":"चलना","chalo, ab chalte haiṃ":"चलो, अब चलते हैं","chalie":"चलिए","Bas":"बस","bas, ab nahīṃ":"बस, अब नहीं","bas ek kap chāy":"बस एक कप चाय","chalo":"चलो","bas":"बस","koī bāt nahīṃ":"कोई बात नहीं","koī bāt nahīṃ, chalo, bas":"कोई बात नहीं, चलो, बस"}}},{"title":"Tradition et modernité","phrases":[{"fr":"Ma grand-mère porte toujours un sari, alors que ma sœur préfère le jean.","tgt":"मेरी दादी हमेशा साड़ी पहनती हैं, जबकि मेरी बहन जींस पसंद करती है।","ro":"Merī dādī hameshā sāṛī pahantī haiṃ, jabki merī bahan jīns pasand kartī hai."},{"fr":"Dans bien des familles, les mariages sont encore décidés par les parents.","tgt":"कई परिवारों में शादियाँ आज भी माता-पिता द्वारा तय की जाती हैं।","ro":"Kaī parivāroṃ meṃ shādiyāṃ āj bhī mātā-pitā dvārā tay kī jātī haiṃ."},{"fr":"Pourtant, de plus en plus de jeunes choisissent eux-mêmes leur conjoint.","tgt":"फिर भी, ज़्यादा से ज़्यादा युवा अपना जीवनसाथी ख़ुद चुन रहे हैं।","ro":"Phir bhī, zyādā se zyādā yuvā apnā jīvansāthī khud chun rahe haiṃ."},{"fr":"On peut être moderne tout en respectant ses aînés.","tgt":"आधुनिक होते हुए भी बड़ों का सम्मान किया जा सकता है।","ro":"Ādhunik hote hue bhī baṛoṃ kā sammān kiyā jā saktā hai."},{"fr":"Chez nous, on mange encore tous ensemble, assis par terre.","tgt":"हमारे घर में आज भी सब ज़मीन पर बैठकर साथ खाना खाते हैं।","ro":"Hamāre ghar meṃ āj bhī sab zamīn par baiṭhkar sāth khānā khāte haiṃ."},{"fr":"Les grandes familles sous un même toit se font de plus en plus rares.","tgt":"एक ही छत के नीचे रहने वाले बड़े परिवार अब कम होते जा रहे हैं।","ro":"Ek hī chhat ke nīche rahne vāle baṛe parivār ab kam hote jā rahe haiṃ."},{"fr":"Ce que nos parents trouvaient normal nous semble parfois étrange.","tgt":"जो बातें हमारे माता-पिता को सामान्य लगती थीं, वे हमें कभी-कभी अजीब लगती हैं।","ro":"Jo bāteṃ hamāre mātā-pitā ko sāmānya lagtī thīṃ, ve hameṃ kabhī-kabhī ajīb lagtī haiṃ."},{"fr":"Aujourd'hui, des jeunes apprennent le kathak grâce à des vidéos en ligne.","tgt":"आजकल युवा ऑनलाइन वीडियो से कथक सीख रहे हैं।","ro":"Ājkal yuvā onlāin vīḍiyo se kathak sīkh rahe haiṃ."},{"fr":"La tradition n'est pas un musée, elle évolue avec nous.","tgt":"परंपरा कोई संग्रहालय नहीं है, वह हमारे साथ बदलती रहती है।","ro":"Paramparā koī sangrahālay nahīṃ hai, vah hamāre sāth badaltī rahtī hai."},{"fr":"Garder le meilleur des deux mondes, voilà le vrai défi.","tgt":"दोनों दुनियाओं की अच्छी बातें बचाकर रखना, यही असली चुनौती है।","ro":"Donoṃ duniyāoṃ kī achchhī bāteṃ bachākar rakhnā, yahī aslī chunautī hai."}]},{"title":"Les cuisines régionales","phrases":[{"fr":"On dirait que ce plat vient du sud de l'Inde.","tgt":"लगता है यह खाना दक्षिण भारत का है।","ro":"Lagtā hai yah khānā dakshiṇ Bhārat kā hai."},{"fr":"Ce dosa a l'air vraiment délicieux.","tgt":"यह डोसा बहुत स्वादिष्ट लग रहा है।","ro":"Yah ḍosā bahut svādishṭ lag rahā hai."},{"fr":"Il me semble que dans la cuisine du Kerala, on met beaucoup de noix de coco.","tgt":"मुझे लगता है कि केरल के खाने में नारियल बहुत डाला जाता है।","ro":"Mujhe lagtā hai ki Keral ke khāne meṃ nāriyal bahut ḍālā jātā hai."},{"fr":"Au Pendjab, on consomme beaucoup de beurre et de lait.","tgt":"पंजाब में लोग ख़ूब मक्खन और दूध खाते-पीते हैं।","ro":"Panjāb meṃ log khūb makkhan aur dūdh khāte-pīte haiṃ."},{"fr":"J'ai l'impression qu'il y aura trop de piment pour moi.","tgt":"लगता है इसमें मेरे लिए बहुत ज़्यादा मिर्च होगी।","ro":"Lagtā hai ismeṃ mere lie bahut zyādā mirch hogī."},{"fr":"Les plats du Bengale sont souvent préparés avec du poisson.","tgt":"बंगाल के पकवान अक्सर मछली से बनाए जाते हैं।","ro":"Bangāl ke pakvān aksar machhlī se banāe jāte haiṃ."},{"fr":"Vous avez l'air fatigué, vous prendrez un thé bien chaud ?","tgt":"आप थके हुए लग रहे हैं, गरम चाय लेंगे?","ro":"Āp thake hue lag rahe haiṃ, garam chāy leṃge?"},{"fr":"Au Gujarat, les plats sont souvent un peu sucrés.","tgt":"गुजरात में खाना अक्सर थोड़ा मीठा होता है।","ro":"Gujarāt meṃ khānā aksar thoṛā mīṭhā hotā hai."},{"fr":"On dirait que tout le monde connaît ce petit dhaba.","tgt":"लगता है इस छोटे से ढाबे को सब जानते हैं।","ro":"Lagtā hai is chhoṭe se ḍhābe ko sab jānte haiṃ."},{"fr":"Chaque État a sa cuisine, et chaque cuisine a sa saveur.","tgt":"हर राज्य का अपना खाना है, और हर खाने का अपना स्वाद।","ro":"Har rājya kā apnā khānā hai, aur har khāne kā apnā svād."}],"tip":{"title":"« Lagtā hai » : on dirait que","example":"On dirait que ce plat vient du sud de l'Inde. — <b>लगता</b> <b>है</b> यह खाना दक्षिण भारत का है।","body":"« Lagtā hai » vient du verbe « lagnā », sembler, et c'est la façon la plus naturelle de donner une impression en hindi. Placé en tête de phrase, il veut dire on dirait que, j'ai l'impression que : « lagtā hai bārish hogī », on dirait qu'il va pleuvoir. Décomposons « lagtā hai yah khānā dakshiṇ Bhārat kā hai » : semble est, ce plat, sud de l'Inde de, est ; la suite est une phrase tout à fait normale. Avec « mujhe », à moi, cela devient un avis personnel : « mujhe lagtā hai ki... », il me semble que, je pense que. Pour l'air qu'a quelque chose en ce moment, on passe à la forme progressive : « yah ḍosā svādishṭ lag rahā hai », ce dosa a l'air délicieux, ou « āp thake hue lag rahe haiṃ », vous avez l'air fatigué. Astuce : chaque fois que vous diriez on dirait en français, lancez « lagtā hai », puis enchaînez tranquillement votre phrase.","exampleRo":"Lagtā hai yah khānā dakshiṇ Bhārat kā hai.","lit":"semble · est · ce · plat · sud · Inde · [de] · est","say":{"Lagtā hai":"लगता है","lagnā":"लगना","lagtā hai bārish hogī":"लगता है बारिश होगी","lagtā hai yah khānā dakshiṇ Bhārat kā hai":"लगता है यह खाना दक्षिण भारत का है","mujhe":"मुझे","yah ḍosā svādishṭ lag rahā hai":"यह डोसा स्वादिष्ट लग रहा है","āp thake hue lag rahe haiṃ":"आप थके हुए लग रहे हैं","lagtā hai":"लगता है"}}},{"title":"Une soirée au cinéma","phrases":[{"fr":"Hier soir, nous sommes allés voir le nouveau film dont tout le monde parle.","tgt":"कल रात हम वह नई फ़िल्म देखने गए जिसकी सब चर्चा कर रहे हैं।","ro":"Kal rāt ham vah naī film dekhne gae jiskī sab charchā kar rahe haiṃ."},{"fr":"La salle était bondée, les gens sifflaient et applaudissaient.","tgt":"हॉल खचाखच भरा था, लोग सीटियाँ और तालियाँ बजा रहे थे।","ro":"Hol khachākhach bharā thā, log sīṭiyāṃ aur tāliyāṃ bajā rahe the."},{"fr":"En Inde, aller au cinéma est une sorte de fête collective.","tgt":"भारत में सिनेमा जाना एक तरह का सामूहिक उत्सव है।","ro":"Bhārat meṃ sinemā jānā ek tarah kā sāmūhik utsav hai."},{"fr":"Avec l'entracte, le film durait presque trois heures.","tgt":"फ़िल्म बीच में इंटरवल के साथ लगभग तीन घंटे की थी।","ro":"Film bīch meṃ inṭarval ke sāth lagbhag tīn ghanṭe kī thī."},{"fr":"Les chansons avaient été tournées dans les montagnes de Manali.","tgt":"गाने मनाली के पहाड़ों में फ़िल्माए गए थे।","ro":"Gāne Manālī ke pahāṛoṃ meṃ filmāe gae the."},{"fr":"À mon avis, le héros danse mieux qu'il ne joue.","tgt":"मेरे ख़याल से हीरो एक्टिंग से बेहतर डांस करता है।","ro":"Mere khayāl se hīro ekṭing se behtar ḍāns kartā hai."},{"fr":"On devinait l'histoire d'avance, mais la musique m'a beaucoup plu.","tgt":"कहानी का अंदाज़ा पहले से हो गया था, पर संगीत मुझे बहुत अच्छा लगा।","ro":"Kahānī kā andāzā pahle se ho gayā thā, par sangīt mujhe bahut achchhā lagā."},{"fr":"Vous préférez les films d'action ou les comédies romantiques ?","tgt":"आपको एक्शन फ़िल्में ज़्यादा पसंद हैं या रोमांटिक कॉमेडी?","ro":"Āpko ekshan filmeṃ zyādā pasand haiṃ yā romānṭik komeḍī?"},{"fr":"Les films du sud de l'Inde deviennent très populaires dans tout le pays.","tgt":"दक्षिण भारत की फ़िल्में अब पूरे देश में बहुत लोकप्रिय हो रही हैं।","ro":"Dakshiṇ Bhārat kī filmeṃ ab pūre desh meṃ bahut lokpriya ho rahī haiṃ."},{"fr":"Après le film, on a débattu de la fin jusqu'à minuit.","tgt":"फ़िल्म के बाद हम आधी रात तक उसके अंत पर बहस करते रहे।","ro":"Film ke bād ham ādhī rāt tak uske ant par bahas karte rahe."}]},{"title":"Le yoga comme loisir","phrases":[{"fr":"Je fais du yoga tous les matins avant d'aller travailler.","tgt":"मैं रोज़ सुबह काम पर जाने से पहले योग करता हूँ।","ro":"Maiṃ roz subah kām par jāne se pahle yog kartā hūṃ."},{"fr":"Au début, je n'arrivais même pas à toucher mes pieds.","tgt":"शुरू में मुझसे अपने पैर तक नहीं छुए जाते थे।","ro":"Shurū meṃ mujhse apne pair tak nahīṃ chhue jāte the."},{"fr":"Mon professeur nous demande de respirer lentement pendant dix minutes.","tgt":"मेरे टीचर हमें दस मिनट तक धीरे-धीरे साँस लेने को कहते हैं।","ro":"Mere ṭīchar hameṃ das minaṭ tak dhīre-dhīre sāṃs lene ko kahte haiṃ."},{"fr":"Pour moi, c'est juste de l'exercice, rien de plus.","tgt":"मेरे लिए यह बस एक कसरत है, और कुछ नहीं।","ro":"Mere lie yah bas ek kasrat hai, aur kuchh nahīṃ."},{"fr":"Depuis que je fais du yoga, mon mal de dos a bien diminué.","tgt":"जब से मैं योग करने लगा हूँ, मेरी कमर का दर्द काफ़ी कम हो गया है।","ro":"Jab se maiṃ yog karne lagā hūṃ, merī kamar kā dard kāfī kam ho gayā hai."},{"fr":"Le dimanche, des cours gratuits sont proposés dans le parc.","tgt":"रविवार को पार्क में मुफ़्त योग क्लासें चलाई जाती हैं।","ro":"Ravivār ko pārk meṃ muft yog klāseṃ chalāī jātī haiṃ."},{"fr":"Il faut des années pour bien maîtriser certaines postures.","tgt":"कुछ आसन ठीक से सीखने में बरसों लग जाते हैं।","ro":"Kuchh āsan ṭhīk se sīkhne meṃ barsoṃ lag jāte haiṃ."},{"fr":"Ma femme préfère courir, elle trouve le yoga trop lent.","tgt":"मेरी पत्नी को दौड़ना ज़्यादा पसंद है, उसे योग बहुत धीमा लगता है।","ro":"Merī patnī ko dauṛnā zyādā pasand hai, use yog bahut dhīmā lagtā hai."},{"fr":"Une heure de yoga me rend calme pour toute la journée.","tgt":"एक घंटे का योग मुझे पूरे दिन के लिए शांत कर देता है।","ro":"Ek ghanṭe kā yog mujhe pūre din ke lie shānt kar detā hai."},{"fr":"Quiconque s'y met sérieusement finit par y prendre plaisir.","tgt":"जो भी इसे मन लगाकर करता है, उसे इसका मज़ा आने लगता है।","ro":"Jo bhī ise man lagākar kartā hai, use iskā mazā āne lagtā hai."}]},{"title":"Les obligations de la vie","phrases":[{"fr":"J'ai accepté ce travail par obligation, pas par choix.","tgt":"मैंने यह नौकरी मजबूरी में ली, अपनी मर्ज़ी से नहीं।","ro":"Maiṃne yah naukrī majbūrī meṃ lī, apnī marzī se nahīṃ."},{"fr":"Il a été obligé de vendre sa moto.","tgt":"उसे मजबूरी में अपनी मोटरसाइकिल बेचनी पड़ी।","ro":"Use majbūrī meṃ apnī moṭarsāikil bechnī paṛī."},{"fr":"Beaucoup de gens quittent leur village par nécessité.","tgt":"बहुत से लोग मजबूरी में अपना गाँव छोड़ते हैं।","ro":"Bahut se log majbūrī meṃ apnā gāṃv chhoṛte haiṃ."},{"fr":"Je ne voulais pas partir, mais je n'avais pas le choix.","tgt":"मैं जाना नहीं चाहता था, लेकिन मजबूर था।","ro":"Maiṃ jānā nahīṃ chāhtā thā, lekin majbūr thā."},{"fr":"Excusez-moi, je dois partir tôt aujourd'hui, je n'y peux rien.","tgt":"माफ़ कीजिए, आज मुझे जल्दी जाना पड़ेगा, मजबूरी है।","ro":"Māf kījie, āj mujhe jaldī jānā paṛegā, majbūrī hai."},{"fr":"Elle travaille la nuit par nécessité, pour payer les études de son fils.","tgt":"वह मजबूरी में रात को काम करती है, ताकि बेटे की पढ़ाई का ख़र्च निकल सके।","ro":"Vah majbūrī meṃ rāt ko kām kartī hai, tāki beṭe kī paṛhāī kā kharch nikal sake."},{"fr":"Ce qu'on fait par contrainte, on le fait rarement bien.","tgt":"जो काम मजबूरी में किया जाता है, वह शायद ही कभी अच्छा होता है।","ro":"Jo kām majbūrī meṃ kiyā jātā hai, vah shāyad hī kabhī achchhā hotā hai."},{"fr":"Je comprends que vous n'ayez pas le choix, ne vous en faites pas.","tgt":"मैं आपकी मजबूरी समझता हूँ, आप परेशान मत होइए।","ro":"Maiṃ āpkī majbūrī samajhtā hūṃ, āp pareshān mat hoie."},{"fr":"Pendant la mousson, on est bien obligé de rester à la maison.","tgt":"बरसात में मजबूरी में घर पर ही रहना पड़ता है।","ro":"Barsāt meṃ majbūrī meṃ ghar par hī rahnā paṛtā hai."},{"fr":"Parfois, une contrainte finit par devenir une chance.","tgt":"कभी-कभी मजबूरी आख़िर में एक मौका बन जाती है।","ro":"Kabhī-kabhī majbūrī ākhir meṃ ek maukā ban jātī hai."}],"tip":{"title":"« Majbūrī meṃ » : être obligé de","example":"J'ai accepté ce travail par obligation, pas par choix. — मैंने यह नौकरी <b>मजबूरी</b> <b>में</b> ली, अपनी मर्ज़ी से नहीं।","body":"« Majbūrī » veut dire la contrainte, le fait de ne pas avoir le choix, et « majbūrī meṃ », mot à mot dans la contrainte, se traduit par obligé, par nécessité, à contrecœur. On le place juste avant le verbe : « maiṃne yah naukrī majbūrī meṃ lī », moi, ce travail, dans la contrainte, ai pris, autrement dit j'ai pris ce travail parce que je n'avais pas le choix. Il s'associe très bien avec « paṛnā », devoir : « use majbūrī meṃ bechnī paṛī », il a été forcé de la vendre. Tout seul, « majbūrī hai » est une excuse polie très courante, l'équivalent de je n'y peux rien. Pour parler d'une personne, on prend l'adjectif « majbūr » : « maiṃ majbūr thā », j'étais obligé. Astuce : « majbūrī » a une petite note de regret, gardez-le pour les vraies contraintes, et pour une simple obligation du quotidien, « paṛnā » suffit.","exampleRo":"Maiṃne yah naukrī majbūrī meṃ lī, apnī marzī se nahīṃ.","lit":"moi [erg.] · ce · emploi · contrainte · [dans] · ai pris, · propre · volonté · [depuis] · non","say":{"Majbūrī meṃ":"मजबूरी में","Majbūrī":"मजबूरी","majbūrī meṃ":"मजबूरी में","maiṃne yah naukrī majbūrī meṃ lī":"मैंने यह नौकरी मजबूरी में ली","paṛnā":"पड़ना","use majbūrī meṃ bechnī paṛī":"उसे मजबूरी में बेचनी पड़ी","majbūrī hai":"मजबूरी है","majbūr":"मजबूर","maiṃ majbūr thā":"मैं मजबूर था","majbūrī":"मजबूरी"}}},{"title":"Parler de musique","phrases":[{"fr":"Aux mariages de notre famille, tout le monde chante.","tgt":"हमारे परिवार की शादियों में हर कोई गाना गाता है।","ro":"Hamāre parivār kī shādiyoṃ meṃ har koī gānā gātā hai."},{"fr":"Mon oncle joue du tabla depuis quarante ans.","tgt":"मेरे चाचा चालीस साल से तबला बजा रहे हैं।","ro":"Mere chāchā chālīs sāl se tablā bajā rahe haiṃ."},{"fr":"J'ai appris quelques chansons de film pour faire plaisir à mes amis.","tgt":"दोस्तों को ख़ुश करने के लिए मैंने कुछ फ़िल्मी गाने सीखे हैं।","ro":"Dostoṃ ko khush karne ke lie maiṃne kuchh filmī gāne sīkhe haiṃ."},{"fr":"La musique classique demande une patience incroyable.","tgt":"शास्त्रीय संगीत के लिए ग़ज़ब का धैर्य चाहिए।","ro":"Shāstrīya sangīt ke lie gazab kā dhairya chāhie."},{"fr":"Ce raga se chante traditionnellement le soir.","tgt":"यह राग पारंपरिक रूप से शाम को गाया जाता है।","ro":"Yah rāg pāramparik rūp se shām ko gāyā jātā hai."},{"fr":"À Kolkata, j'ai assisté à un concert qui a duré toute la nuit.","tgt":"कोलकाता में मैंने एक ऐसा कॉन्सर्ट देखा जो पूरी रात चला।","ro":"Kolkātā meṃ maiṃne ek aisā konsarṭ dekhā jo pūrī rāt chalā."},{"fr":"Les jeunes mélangent les mélodies traditionnelles avec la musique électronique.","tgt":"युवा पारंपरिक धुनों को इलेक्ट्रॉनिक संगीत के साथ मिला रहे हैं।","ro":"Yuvā pāramparik dhunoṃ ko ilekṭronik sangīt ke sāth milā rahe haiṃ."},{"fr":"Chaque fois que j'entends cette chanson, je repense à mon premier voyage en Inde.","tgt":"जब भी मैं यह गाना सुनता हूँ, मुझे भारत की अपनी पहली यात्रा याद आ जाती है।","ro":"Jab bhī maiṃ yah gānā suntā hūṃ, mujhe Bhārat kī apnī pahlī yātrā yād ā jātī hai."},{"fr":"Pourriez-vous m'apprendre les paroles de cette chanson ?","tgt":"क्या आप मुझे इस गाने के बोल सिखा सकते हैं?","ro":"Kyā āp mujhe is gāne ke bol sikhā sakte haiṃ?"},{"fr":"Même sans comprendre les mots, la musique touche le cœur.","tgt":"शब्द समझे बिना भी संगीत दिल को छू जाता है।","ro":"Shabd samjhe binā bhī sangīt dil ko chhū jātā hai."}]},{"title":"Une amitié qui dure","phrases":[{"fr":"Rahul et moi, nous nous connaissons depuis l'école.","tgt":"राहुल और मैं स्कूल के दिनों से एक-दूसरे को जानते हैं।","ro":"Rāhul aur maiṃ skūl ke dinoṃ se ek-dūsre ko jānte haiṃ."},{"fr":"Maintenant, nous n'arrivons à nous voir que deux fois par an.","tgt":"अब हम साल में बस दो बार मिल पाते हैं।","ro":"Ab ham sāl meṃ bas do bār mil pāte haiṃ."},{"fr":"Pourtant, à chaque fois, c'est comme si on ne s'était jamais quittés.","tgt":"फिर भी हर बार ऐसा लगता है जैसे हम कभी अलग हुए ही नहीं।","ro":"Phir bhī har bār aisā lagtā hai jaise ham kabhī alag hue hī nahīṃ."},{"fr":"Quand j'ai perdu mon emploi, c'est lui qui m'a aidé.","tgt":"जब मेरी नौकरी छूटी थी, तब उसी ने मेरी मदद की थी।","ro":"Jab merī naukrī chhūṭī thī, tab usī ne merī madad kī thī."},{"fr":"C'est dans les moments difficiles qu'on reconnaît un vrai ami.","tgt":"सच्चे दोस्त की पहचान मुश्किल समय में होती है।","ro":"Sachche dost kī pahchān mushkil samay meṃ hotī hai."},{"fr":"Il nous arrive de nous disputer, mais jamais bien longtemps.","tgt":"हम कभी-कभी झगड़ते हैं, पर कभी ज़्यादा देर तक नहीं।","ro":"Ham kabhī-kabhī jhagaṛte haiṃ, par kabhī zyādā der tak nahīṃ."},{"fr":"Sa famille m'a toujours accueilli comme un fils.","tgt":"उसके परिवार ने हमेशा मुझे बेटे की तरह अपनाया है।","ro":"Uske parivār ne hameshā mujhe beṭe kī tarah apnāyā hai."},{"fr":"Chaque dimanche, on se raconte la semaine au téléphone.","tgt":"हर रविवार हम फ़ोन पर एक-दूसरे को पूरे हफ़्ते का हाल सुनाते हैं।","ro":"Har ravivār ham fon par ek-dūsre ko pūre hafte kā hāl sunāte haiṃ."},{"fr":"Avec lui, je n'ai pas besoin de faire semblant.","tgt":"उसके सामने मुझे दिखावा करने की ज़रूरत नहीं पड़ती।","ro":"Uske sāmne mujhe dikhāvā karne kī zarūrat nahīṃ paṛtī."},{"fr":"Une amitié comme la nôtre, ça ne se trouve pas facilement.","tgt":"हमारी जैसी दोस्ती आसानी से नहीं मिलती।","ro":"Hamārī jaisī dostī āsānī se nahīṃ miltī."}]},{"title":"Les fêtes des lumières et des couleurs","phrases":[{"fr":"À Diwali, toute la rue s'orne de petites lampes à huile.","tgt":"दिवाली पर पूरी गली छोटे-छोटे दीयों से सजाई जाती है।","ro":"Divālī par pūrī galī chhoṭe-chhoṭe dīyoṃ se sajāī jātī hai."},{"fr":"On offre des sucreries aux voisins et aux collègues.","tgt":"पड़ोसियों और सहकर्मियों को मिठाइयाँ दी जाती हैं।","ro":"Paṛosiyoṃ aur sahkarmiyoṃ ko miṭhāiyāṃ dī jātī haiṃ."},{"fr":"Les enfants adorent les pétards, les chiens beaucoup moins.","tgt":"बच्चों को पटाखे बहुत पसंद हैं, कुत्तों को बिल्कुल नहीं।","ro":"Bachchoṃ ko paṭākhe bahut pasand haiṃ, kuttoṃ ko bilkul nahīṃ."},{"fr":"À Holi, les gens se lancent des couleurs de toutes sortes.","tgt":"होली पर लोग एक-दूसरे पर तरह-तरह के रंग डालते हैं।","ro":"Holī par log ek-dūsre par tarah-tarah ke rang ḍālte haiṃ."},{"fr":"Mettez de vieux vêtements, ils seront couverts de couleurs.","tgt":"पुराने कपड़े पहनिए, वे रंगों से भर जाएँगे।","ro":"Purāne kapṛe pahanie, ve rangoṃ se bhar jāeṃge."},{"fr":"Ce jour-là, même les inconnus deviennent des amis.","tgt":"उस दिन अजनबी भी दोस्त बन जाते हैं।","ro":"Us din ajnabī bhī dost ban jāte haiṃ."},{"fr":"Ma mère commence à préparer les douceurs une semaine à l'avance.","tgt":"मेरी माँ एक हफ़्ते पहले से ही मिठाइयाँ बनाना शुरू कर देती हैं।","ro":"Merī māṃ ek hafte pahle se hī miṭhāiyāṃ banānā shurū kar detī haiṃ."},{"fr":"Pendant les fêtes, les trains vers les villages sont pris d'assaut.","tgt":"त्योहारों के समय गाँवों की ओर जाने वाली ट्रेनें खचाखच भर जाती हैं।","ro":"Tyohāroṃ ke samay gāṃvoṃ kī or jāne vālī ṭreneṃ khachākhach bhar jātī haiṃ."},{"fr":"Ceux qui vivent loin font tout pour rentrer chez eux.","tgt":"जो लोग दूर रहते हैं, वे घर लौटने की पूरी कोशिश करते हैं।","ro":"Jo log dūr rahte haiṃ, ve ghar lauṭne kī pūrī koshish karte haiṃ."},{"fr":"Ces fêtes sont avant tout une occasion de se retrouver.","tgt":"ये त्योहार सबसे बढ़कर मिलने-जुलने का मौका हैं।","ro":"Ye tyohār sabse baṛhkar milne-julne kā maukā haiṃ."}]},{"title":"Parler avec des images","phrases":[{"fr":"Le bruit de l'immeuble d'à côté me rend la vie impossible.","tgt":"बगल वाली इमारत के शोर ने मेरी नाक में दम कर रखा है।","ro":"Bagal vālī imārat ke shor ne merī nāk meṃ dam kar rakhā hai."},{"fr":"Sa petite-fille, c'est la prunelle de ses yeux.","tgt":"उसकी पोती उसकी आँखों का तारा है।","ro":"Uskī potī uskī āṃkhoṃ kā tārā hai."},{"fr":"Une si petite augmentation, c'est une goutte d'eau dans l'océan.","tgt":"इतनी सी बढ़ोतरी तो ऊँट के मुँह में ज़ीरा है।","ro":"Itnī sī baṛhotarī to ūṃṭ ke muṃh meṃ zīrā hai."},{"fr":"Puissiez-vous dire vrai !","tgt":"आपके मुँह में घी-शक्कर।","ro":"Āpke muṃh meṃ ghī-shakkar."},{"fr":"Mon fils veut maintenant voler de ses propres ailes.","tgt":"मेरा बेटा अब अपने पैरों पर खड़ा होना चाहता है।","ro":"Merā beṭā ab apne pairoṃ par khaṛā honā chāhtā hai."},{"fr":"Il y a anguille sous roche, il ne décroche même plus son téléphone.","tgt":"दाल में कुछ काला है, वह फ़ोन ही नहीं उठा रहा।","ro":"Dāl meṃ kuchh kālā hai, vah fon hī nahīṃ uṭhā rahā."},{"fr":"Les enfants ont fait un vacarme de tous les diables.","tgt":"बच्चों ने तो आसमान सिर पर उठा लिया।","ro":"Bachchoṃ ne to āsmān sir par uṭhā liyā."},{"fr":"Rien que d'y penser, j'en ai l'eau à la bouche.","tgt":"सिर्फ़ सोचकर ही मेरे मुँह में पानी आ गया।","ro":"Sirf sochkar hī mere muṃh meṃ pānī ā gayā."},{"fr":"Dès qu'il a vu le patron, il a pris la poudre d'escampette.","tgt":"बॉस को देखते ही वह नौ दो ग्यारह हो गया।","ro":"Bos ko dekhte hī vah nau do gyārah ho gayā."},{"fr":"On ne voit pas la beauté de sa propre ville : ce qu'on a chez soi ne vaut rien à nos yeux.","tgt":"हम अपने शहर की ख़ूबसूरती नहीं देखते, घर की मुर्गी दाल बराबर।","ro":"Ham apne shahar kī khūbsūratī nahīṃ dekhte, ghar kī murgī dāl barābar."}],"tip":{"title":"Les expressions imagées (« muhāvare »)","example":"Rien que d'y penser, j'en ai l'eau à la bouche. — सिर्फ़ सोचकर ही मेरे <b>मुँह</b> <b>में</b> <b>पानी</b> <b>आ</b> <b>गया</b>।","body":"Les « muhāvare », les expressions imagées, sont le sel de la conversation en hindi, et les gens adorent entendre un étranger les employer. Certaines ressemblent aux nôtres : « mere muṃh meṃ pānī ā gayā », mot à mot de l'eau est venue dans ma bouche, c'est exactement avoir l'eau à la bouche. D'autres sont plus surprenantes : « ūṃṭ ke muṃh meṃ zīrā », du cumin dans la bouche d'un chameau, désigne une quantité ridicule, notre goutte d'eau dans l'océan, et « dāl meṃ kuchh kālā hai », il y a quelque chose de noir dans les lentilles, veut dire qu'il y a anguille sous roche. Le verbe de l'expression se conjugue comme d'habitude : « nāk meṃ dam kar rakhā hai », il m'a mis le souffle dans le nez, c'est-à-dire il me rend la vie impossible. Astuce : associez chaque expression à une petite image mentale, comme ce chameau qui mâche une seule graine de cumin, et elle ne vous quittera plus.","exampleRo":"Sirf sochkar hī mere muṃh meṃ pānī ā gayā.","lit":"seulement · en pensant · même · ma · bouche · [dans] · eau · venue · est allée","say":{"muhāvare":"मुहावरे","mere muṃh meṃ pānī ā gayā":"मेरे मुँह में पानी आ गया","ūṃṭ ke muṃh meṃ zīrā":"ऊँट के मुँह में ज़ीरा","dāl meṃ kuchh kālā hai":"दाल में कुछ काला है","nāk meṃ dam kar rakhā hai":"नाक में दम कर रखा है"}}},{"title":"La vie en ville : bouchons et transports","phrases":[{"fr":"À Delhi, à cause des bouchons, il faut partir une heure plus tôt.","tgt":"दिल्ली में जाम की वजह से एक घंटा पहले निकलना पड़ता है।","ro":"Dillī meṃ jām kī vajah se ek ghanṭā pahle nikalnā paṛtā hai."},{"fr":"Le métro a vraiment changé la vie de millions de gens.","tgt":"मेट्रो ने लाखों लोगों की ज़िंदगी सचमुच बदल दी है।","ro":"Meṭro ne lākhoṃ logoṃ kī zindagī sachmuch badal dī hai."},{"fr":"Aux heures de pointe, il n'y a même pas la place de bouger dans le wagon.","tgt":"भीड़ के समय डिब्बे में हिलने तक की जगह नहीं होती।","ro":"Bhīṛ ke samay ḍibbe meṃ hilne tak kī jagah nahīṃ hotī."},{"fr":"Les chauffeurs d'auto-rickshaw klaxonnent sans arrêt.","tgt":"ऑटो वाले लगातार हॉर्न बजाते रहते हैं।","ro":"Oṭo vāle lagātār horn bajāte rahte haiṃ."},{"fr":"Ce matin, un voisin m'a déposé à la gare.","tgt":"आज सुबह एक पड़ोसी ने मुझे स्टेशन तक छोड़ दिया।","ro":"Āj subah ek paṛosī ne mujhe sṭeshan tak chhoṛ diyā."},{"fr":"En hiver, la pollution est devenue un gros problème.","tgt":"सर्दियों में प्रदूषण एक बड़ी समस्या बन गया है।","ro":"Sardiyoṃ meṃ pradūshaṇ ek baṛī samasyā ban gayā hai."},{"fr":"De plus en plus de gens se sont mis à aller au bureau à vélo.","tgt":"ज़्यादा से ज़्यादा लोग साइकिल से ऑफ़िस जाने लगे हैं।","ro":"Zyādā se zyādā log sāikil se ofis jāne lage haiṃ."},{"fr":"Les loyers de Mumbai sont les plus élevés du pays.","tgt":"मुंबई के किराए पूरे देश में सबसे ज़्यादा हैं।","ro":"Mumbaī ke kirāe pūre desh meṃ sabse zyādā haiṃ."},{"fr":"Malgré tout, cette ville ne dort jamais, et c'est ce que j'aime.","tgt":"फिर भी यह शहर कभी नहीं सोता, और यही मुझे पसंद है।","ro":"Phir bhī yah shahar kabhī nahīṃ sotā, aur yahī mujhe pasand hai."},{"fr":"Si on construisait plus de parcs, la vie en ville serait plus agréable.","tgt":"अगर ज़्यादा पार्क बनाए जाते, तो शहर में रहना ज़्यादा सुखद होता।","ro":"Agar zyādā pārk banāe jāte, to shahar meṃ rahnā zyādā sukhad hotā."}]},{"title":"Le cricket entre amis","phrases":[{"fr":"Le dimanche, tout le quartier joue au cricket dans la rue.","tgt":"रविवार को पूरा मोहल्ला गली में क्रिकेट खेलता है।","ro":"Ravivār ko pūrā mohallā galī meṃ krikeṭ kheltā hai."},{"fr":"Quand je suis arrivé ici, je ne comprenais rien aux règles.","tgt":"जब मैं यहाँ आया था, तब मुझे नियम बिल्कुल समझ नहीं आते थे।","ro":"Jab maiṃ yahāṃ āyā thā, tab mujhe niyam bilkul samajh nahīṃ āte the."},{"fr":"Ce sont les enfants qui m'ont appris à bien tenir la batte.","tgt":"बच्चों ने मुझे बल्ला ठीक से पकड़ना सिखाया।","ro":"Bachchoṃ ne mujhe ballā ṭhīk se pakaṛnā sikhāyā."},{"fr":"Pendant un grand match, les rues se vident complètement.","tgt":"बड़े मैच के दौरान सड़कें पूरी तरह ख़ाली हो जाती हैं।","ro":"Baṛe maich ke daurān saṛkeṃ pūrī tarah khālī ho jātī haiṃ."},{"fr":"À votre avis, qui va gagner ce soir ?","tgt":"आपके हिसाब से आज रात कौन जीतेगा?","ro":"Āpke hisāb se āj rāt kaun jītegā?"},{"fr":"Le match a été interrompu à cause de la pluie.","tgt":"मैच बारिश की वजह से रोक दिया गया।","ro":"Maich bārish kī vajah se rok diyā gayā."},{"fr":"Mon voisin connaît par cœur le score de chaque match.","tgt":"मेरे पड़ोसी को हर मैच का स्कोर ज़ुबानी याद है।","ro":"Mere paṛosī ko har maich kā skor zubānī yād hai."},{"fr":"Ma balle a cassé la vitre d'un voisin.","tgt":"मेरी गेंद से एक पड़ोसी की खिड़की का शीशा टूट गया।","ro":"Merī gend se ek paṛosī kī khiṛkī kā shīshā ṭūṭ gayā."},{"fr":"Ici, le cricket est bien plus qu'un simple sport.","tgt":"यहाँ क्रिकेट सिर्फ़ एक खेल नहीं, उससे कहीं ज़्यादा है।","ro":"Yahāṃ krikeṭ sirf ek khel nahīṃ, usse kahīṃ zyādā hai."},{"fr":"Qu'on gagne ou qu'on perde, l'essentiel est de jouer ensemble.","tgt":"जीतें या हारें, असली बात साथ मिलकर खेलना है।","ro":"Jīteṃ yā hāreṃ, aslī bāt sāth milkar khelnā hai."}]},{"title":"Le téléphone, ami ou ennemi ?","phrases":[{"fr":"Au dîner, nous posons tous nos téléphones dans un panier.","tgt":"रात के खाने पर हम सब अपने फ़ोन एक टोकरी में रख देते हैं।","ro":"Rāt ke khāne par ham sab apne fon ek ṭokrī meṃ rakh dete haiṃ."},{"fr":"Mes neveux passent des heures à regarder des vidéos.","tgt":"मेरे भतीजे घंटों वीडियो देखते रहते हैं।","ro":"Mere bhatīje ghanṭoṃ vīḍiyo dekhte rahte haiṃ."},{"fr":"Grâce au téléphone, je parle tous les jours avec ma famille en France.","tgt":"फ़ोन की बदौलत मैं रोज़ फ़्रांस में अपने परिवार से बात करता हूँ।","ro":"Fon kī badaulat maiṃ roz Frāns meṃ apne parivār se bāt kartā hūṃ."},{"fr":"Maintenant, même le marchand de légumes est payé par téléphone.","tgt":"अब तो सब्ज़ी वाले को भी फ़ोन से पैसे दिए जाते हैं।","ro":"Ab to sabzī vāle ko bhī fon se paise die jāte haiṃ."},{"fr":"Les fausses nouvelles circulent plus vite que les vraies.","tgt":"झूठी ख़बरें सच्ची ख़बरों से तेज़ फैलती हैं।","ro":"Jhūṭhī khabreṃ sachchī khabroṃ se tez phailtī haiṃ."},{"fr":"Je me suis fixé une règle : aucun écran une heure avant de dormir.","tgt":"मैंने एक नियम बनाया है: सोने से एक घंटा पहले कोई स्क्रीन नहीं।","ro":"Maiṃne ek niyam banāyā hai: sone se ek ghanṭā pahle koī skrīn nahīṃ."},{"fr":"Mon grand-père a appris à envoyer des messages vocaux à quatre-vingts ans.","tgt":"मेरे दादाजी ने अस्सी साल की उम्र में वॉइस मैसेज भेजना सीखा।","ro":"Mere dādājī ne assī sāl kī umr meṃ vois maisej bhejnā sīkhā."},{"fr":"On se parle beaucoup, mais on se voit peu.","tgt":"हम बातें तो बहुत करते हैं, पर मिलते कम हैं।","ro":"Ham bāteṃ to bahut karte haiṃ, par milte kam haiṃ."},{"fr":"Sans téléphone, je serais perdu dans cette grande ville.","tgt":"फ़ोन के बिना मैं इस बड़े शहर में खो जाता।","ro":"Fon ke binā maiṃ is baṛe shahar meṃ kho jātā."},{"fr":"Tout dépend de la manière dont on l'utilise.","tgt":"सब कुछ इस पर निर्भर करता है कि हम इसका इस्तेमाल कैसे करते हैं।","ro":"Sab kuchh is par nirbhar kartā hai ki ham iskā istemāl kaise karte haiṃ."}]},{"title":"Souvenirs de voyage en Inde","phrases":[{"fr":"Je n'oublierai jamais le désert du Rajasthan.","tgt":"राजस्थान का रेगिस्तान मुझे हमेशा याद रहेगा।","ro":"Rājasthān kā registān mujhe hameshā yād rahegā."},{"fr":"Nous avons dormi à la belle étoile, près de Jaisalmer.","tgt":"हम जैसलमेर के पास तारों के नीचे सोए।","ro":"Ham Jaisalmer ke pās tāroṃ ke nīche soe."},{"fr":"Au Kerala, on nous a fait faire le tour des canaux en bateau.","tgt":"केरल में हमें नाव से नहरों की सैर कराई गई।","ro":"Keral meṃ hameṃ nāv se nahroṃ kī sair karāī gaī."},{"fr":"Dans le train de nuit pour Goa, il y avait partout des familles qui bavardaient.","tgt":"गोवा जाने वाली रात की ट्रेन में हर तरफ़ बातें करते परिवार थे।","ro":"Govā jāne vālī rāt kī ṭren meṃ har taraf bāteṃ karte parivār the."},{"fr":"Un inconnu nous a invités à prendre le thé chez lui.","tgt":"एक अनजान आदमी ने हमें अपने घर चाय पर बुलाया।","ro":"Ek anjān ādmī ne hameṃ apne ghar chāy par bulāyā."},{"fr":"C'est là que j'ai compris à quel point les Indiens sont accueillants.","tgt":"वहीं मुझे समझ आया कि भारतीय लोग कितने मेहमाननवाज़ होते हैं।","ro":"Vahīṃ mujhe samajh āyā ki bhāratīya log kitne mehmānnavāz hote haiṃ."},{"fr":"Dans l'Himalaya, il faisait si froid que l'eau gelait.","tgt":"हिमालय में इतनी ठंड थी कि पानी जम जाता था।","ro":"Himālay meṃ itnī ṭhanḍ thī ki pānī jam jātā thā."},{"fr":"À Jaipur, je me suis fait faire une chemise sur mesure.","tgt":"मैंने जयपुर में अपनी नाप की एक कमीज़ सिलवाई।","ro":"Maiṃne Jaipur meṃ apnī nāp kī ek kamīz silvāī."},{"fr":"Se lever tôt pour voir le Taj Mahal à l'aube, ça valait vraiment la peine.","tgt":"सुबह-सुबह ताजमहल देखने के लिए जल्दी उठना बिल्कुल बेकार नहीं गया।","ro":"Subah-subah Tājmahal dekhne ke lie jaldī uṭhnā bilkul bekār nahīṃ gayā."},{"fr":"Chaque État m'a donné l'impression d'être un pays différent.","tgt":"हर राज्य मुझे एक अलग देश जैसा लगा।","ro":"Har rājya mujhe ek alag desh jaisā lagā."}]},{"title":"Plusieurs générations sous un même toit","phrases":[{"fr":"Chez nous, trois générations vivent ensemble.","tgt":"हमारे घर में तीन पीढ़ियाँ एक साथ रहती हैं।","ro":"Hamāre ghar meṃ tīn pīṛhiyāṃ ek sāth rahtī haiṃ."},{"fr":"Mon grand-père se lève le premier et réveille toute la maison.","tgt":"दादाजी सबसे पहले उठते हैं और सबको जगा देते हैं।","ro":"Dādājī sabse pahle uṭhte haiṃ aur sabko jagā dete haiṃ."},{"fr":"Les décisions importantes se prennent autour d'un thé, en demandant l'avis de chacun.","tgt":"ज़रूरी फ़ैसले चाय पीते हुए सबकी सलाह से लिए जाते हैं।","ro":"Zarūrī faisle chāy pīte hue sabkī salāh se lie jāte haiṃ."},{"fr":"Ici, on n'est jamais seul, mais on a peu d'intimité.","tgt":"यहाँ अकेलापन तो नहीं है, पर निजता भी कम है।","ro":"Yahāṃ akelāpan to nahīṃ hai, par nijtā bhī kam hai."},{"fr":"Chaque soir, ma grand-mère raconte des histoires aux enfants.","tgt":"दादी हर शाम बच्चों को कहानियाँ सुनाती हैं।","ro":"Dādī har shām bachchoṃ ko kahāniyāṃ sunātī haiṃ."},{"fr":"Les jeunes apprennent la patience, et les anciens la technologie.","tgt":"युवा धीरज सीखते हैं, और बुज़ुर्ग टेक्नोलॉजी।","ro":"Yuvā dhīraj sīkhte haiṃ, aur buzurg ṭeknolojī."},{"fr":"Parfois, des avis différents créent un peu de tension.","tgt":"कभी-कभी अलग-अलग राय की वजह से थोड़ा तनाव हो जाता है।","ro":"Kabhī-kabhī alag-alag rāy kī vajah se thoṛā tanāv ho jātā hai."},{"fr":"Mes cousins sont comme de vrais frères pour moi.","tgt":"मेरे चचेरे भाई मेरे लिए सगे भाइयों जैसे हैं।","ro":"Mere chachere bhāī mere lie sage bhāiyoṃ jaise haiṃ."},{"fr":"Quand quelqu'un tombe malade, toute la famille s'organise.","tgt":"जब कोई बीमार पड़ता है, तो पूरा परिवार मिलकर सँभाल लेता है।","ro":"Jab koī bīmār paṛtā hai, to pūrā parivār milkar saṃbhāl letā hai."},{"fr":"Je ne sais pas si je pourrais vivre seul après ça.","tgt":"पता नहीं इसके बाद मैं अकेले रह पाऊँगा या नहीं।","ro":"Patā nahīṃ iske bād maiṃ akele rah pāūṃgā yā nahīṃ."}]},{"title":"Un au revoir à des amis","phrases":[{"fr":"Demain, je rentre en France après six mois passés ici.","tgt":"कल मैं यहाँ छह महीने रहने के बाद फ़्रांस लौट रहा हूँ।","ro":"Kal maiṃ yahāṃ chhah mahīne rahne ke bād Frāns lauṭ rahā hūṃ."},{"fr":"Mes amis m'ont organisé une petite fête surprise.","tgt":"मेरे दोस्तों ने मेरे लिए एक छोटी-सी सरप्राइज़ पार्टी रखी।","ro":"Mere dostoṃ ne mere lie ek chhoṭī-sī sarprāiz pārṭī rakhī."},{"fr":"Je ne m'attendais pas à être aussi ému.","tgt":"मुझे उम्मीद नहीं थी कि मैं इतना भावुक हो जाऊँगा।","ro":"Mujhe ummīd nahīṃ thī ki maiṃ itnā bhāvuk ho jāūṃgā."},{"fr":"Chacun m'a offert un petit souvenir de la ville.","tgt":"हर किसी ने मुझे शहर की कोई छोटी-सी निशानी दी।","ro":"Har kisī ne mujhe shahar kī koī chhoṭī-sī nishānī dī."},{"fr":"Promettez-moi de venir me voir en France.","tgt":"मुझसे वादा कीजिए कि आप फ़्रांस में मुझसे मिलने आएँगे।","ro":"Mujhse vādā kījie ki āp Frāns meṃ mujhse milne āeṃge."},{"fr":"Pour vous remercier, je vous ai préparé un vrai repas français.","tgt":"शुक्रिया कहने के लिए मैंने आपके लिए असली फ़्रांसीसी खाना बनाया है।","ro":"Shukriyā kahne ke lie maiṃne āpke lie aslī frānsīsī khānā banāyā hai."},{"fr":"Tout ce que j'ai vécu ici restera pour toujours dans mon cœur.","tgt":"जो कुछ मैंने यहाँ जिया है, वह हमेशा मेरे दिल में रहेगा।","ro":"Jo kuchh maiṃne yahāṃ jiyā hai, vah hameshā mere dil meṃ rahegā."},{"fr":"Ne dites pas adieu, dites plutôt qu'on se reverra.","tgt":"अलविदा मत कहिए, कहिए कि फिर मिलेंगे।","ro":"Alvidā mat kahie, kahie ki phir mileṃge."},{"fr":"Nous resterons en contact, la distance n'y changera rien.","tgt":"हम संपर्क में रहेंगे, दूरी से कुछ नहीं बदलेगा।","ro":"Ham sampark meṃ raheṃge, dūrī se kuchh nahīṃ badlegā."},{"fr":"Prenez bien soin de vous, et à très vite.","tgt":"अपना ख़याल रखिए, और जल्द ही मिलते हैं।","ro":"Apnā khayāl rakhie, aur jald hī milte haiṃ."}]},{"title":"Regard en arrière sur mon parcours en hindi","phrases":[{"fr":"Quand j'ai commencé le hindi, je ne savais même pas dire bonjour.","tgt":"जब मैंने हिंदी सीखनी शुरू की, तब मुझे नमस्ते कहना तक नहीं आता था।","ro":"Jab maiṃne hindī sīkhnī shurū kī, tab mujhe namaste kahnā tak nahīṃ ātā thā."},{"fr":"Je pensais que je n'arriverais jamais à bien prononcer certains sons.","tgt":"मुझे लगता था कि कुछ आवाज़ें मैं कभी ठीक से नहीं बोल पाऊँगा।","ro":"Mujhe lagtā thā ki kuchh āvāzeṃ maiṃ kabhī ṭhīk se nahīṃ bol pāūṃgā."},{"fr":"Prendre l'habitude de mettre le verbe à la fin m'a demandé beaucoup d'efforts.","tgt":"वाक्य के आख़िर में क्रिया रखने की आदत डालने में मुझे बहुत मेहनत लगी।","ro":"Vākya ke ākhir meṃ kriyā rakhne kī ādat ḍālne meṃ mujhe bahut mehnat lagī."},{"fr":"Aujourd'hui, je peux parler de cinéma avec un chauffeur de taxi.","tgt":"आज मैं किसी टैक्सी ड्राइवर से फ़िल्मों पर बातचीत कर सकता हूँ।","ro":"Āj maiṃ kisī ṭaiksī ḍrāivar se filmoṃ par bātchīt kar saktā hūṃ."},{"fr":"Quand un étranger parle hindi, les gens sourient toujours.","tgt":"जब कोई विदेशी हिंदी में बात करता है, तो लोग हमेशा मुस्कुरा देते हैं।","ro":"Jab koī videshī hindī meṃ bāt kartā hai, to log hameshā muskurā dete haiṃ."},{"fr":"J'ai fait beaucoup d'erreurs, et on m'a toujours corrigé avec gentillesse.","tgt":"मुझसे बहुत ग़लतियाँ हुईं, और हर बार प्यार से मेरी ग़लती सुधारी गई।","ro":"Mujhse bahut galtiyāṃ huīṃ, aur har bār pyār se merī galtī sudhārī gaī."},{"fr":"Le trajet de chaque jour est devenu mon moment préféré pour m'entraîner.","tgt":"रोज़ का सफ़र अभ्यास करने का मेरा सबसे पसंदीदा समय बन गया।","ro":"Roz kā safar abhyās karne kā merā sabse pasandīdā samay ban gayā."},{"fr":"Il m'arrive de rêver en hindi, et ça m'étonne encore.","tgt":"कभी-कभी मुझे हिंदी में सपने आते हैं, जिस पर मुझे अब भी हैरानी होती है।","ro":"Kabhī-kabhī mujhe hindī meṃ sapne āte haiṃ, jis par mujhe ab bhī hairānī hotī hai."},{"fr":"Cette langue m'a ouvert les portes de nombreuses maisons.","tgt":"इस भाषा ने मेरे लिए कई घरों के दरवाज़े खोल दिए।","ro":"Is bhāshā ne mere lie kaī gharoṃ ke darvāze khol die."},{"fr":"Je suis fier de ce parcours, même s'il me reste beaucoup à apprendre.","tgt":"मुझे अपने इस सफ़र पर गर्व है, भले ही अभी बहुत कुछ सीखना बाकी है।","ro":"Mujhe apne is safar par garv hai, bhale hī abhī bahut kuchh sīkhnā bākī hai."}]},{"title":"Fin du parcours : un dernier bilan","phrases":[{"fr":"Dans ce dernier module, nous avons parlé de culture, d'amitié et de souvenirs.","tgt":"इस आख़िरी मॉड्यूल में हमने संस्कृति, दोस्ती और यादों के बारे में बात की।","ro":"Is ākhirī moḍyūl meṃ hamne sanskriti, dostī aur yādoṃ ke bāre meṃ bāt kī."},{"fr":"Nous savons désormais donner notre avis et expliquer nos contraintes.","tgt":"अब हम अपनी राय देना और अपनी मजबूरियाँ बताना जानते हैं।","ro":"Ab ham apnī rāy denā aur apnī majbūriyāṃ batānā jānte haiṃ."},{"fr":"Quelques expressions imagées rendent maintenant notre hindi plus vivant.","tgt":"कुछ मुहावरे अब हमारी हिंदी को और जानदार बनाते हैं।","ro":"Kuchh muhāvare ab hamārī hindī ko aur jāndār banāte haiṃ."},{"fr":"Depuis les tout premiers mots, nous avons fait un long chemin.","tgt":"पहले शब्दों से लेकर आज तक हमने लंबा सफ़र तय किया है।","ro":"Pahle shabdoṃ se lekar āj tak hamne lambā safar tay kiyā hai."},{"fr":"Les phrases longues et compliquées ne nous font plus peur.","tgt":"लंबे और पेचीदा वाक्य अब हमें नहीं डराते।","ro":"Lambe aur pechīdā vākya ab hameṃ nahīṃ ḍarāte."},{"fr":"Nous pouvons maintenant débattre, plaisanter et réconforter quelqu'un en hindi.","tgt":"अब हम हिंदी में बहस कर सकते हैं, मज़ाक कर सकते हैं और किसी को तसल्ली दे सकते हैं।","ro":"Ab ham hindī meṃ bahas kar sakte haiṃ, mazāk kar sakte haiṃ aur kisī ko tasallī de sakte haiṃ."},{"fr":"Le plus important, c'est d'oser parler, même avec des fautes.","tgt":"सबसे ज़रूरी बात है बोलने की हिम्मत करना, चाहे ग़लतियाँ ही क्यों न हों।","ro":"Sabse zarūrī bāt hai bolne kī himmat karnā, chāhe galtiyāṃ hī kyoṃ na hoṃ."},{"fr":"Continuez à écouter, à répéter et à parler chaque jour.","tgt":"रोज़ सुनते रहिए, दोहराते रहिए और बोलते रहिए।","ro":"Roz sunte rahie, dohrāte rahie aur bolte rahie."},{"fr":"Bravo pour tout ce chemin parcouru en hindi !","tgt":"हिंदी के इस पूरे सफ़र के लिए बहुत-बहुत बधाई।","ro":"Hindī ke is pūre safar ke lie bahut-bahut badhāī."},{"fr":"Le parcours s'achève ici, mais l'histoire de votre hindi ne fait que commencer.","tgt":"सफ़र यहाँ ख़त्म होता है, पर आपकी हिंदी की कहानी तो अभी शुरू हुई है।","ro":"Safar yahāṃ khatm hotā hai, par āpkī hindī kī kahānī to abhī shurū huī hai."}]}]}]}];
